static NSFont *DLDisplayFont(CGFloat size, BOOL bold) {
  CGFloat bump = size <= 14 ? 2.0 : (size <= 20 ? 1.5 : 1.0);
  return [NSFont systemFontOfSize:size + bump weight:bold ? NSFontWeightBold : NSFontWeightSemibold];
}

