@interface DLCircularMenuView : NSView
@property (strong) NSArray<NSDictionary *> *items;
@property (copy) void (^onSegment)(NSInteger index);
@property (copy) void (^onCenter)(BOOL doubleClick);
@property NSInteger hovered;
@end

@implementation DLCircularMenuView
- (instancetype)initWithFrame:(NSRect)frame {
  self = [super initWithFrame:frame];
  if (self) {
    self.hovered = -1;
    self.toolTip = @"单击概览，双击打开控制台";
    NSTrackingArea *ta = [[NSTrackingArea alloc] initWithRect:self.bounds options:(NSTrackingMouseMoved|NSTrackingMouseEnteredAndExited|NSTrackingActiveInKeyWindow|NSTrackingInVisibleRect) owner:self userInfo:nil];
    [self addTrackingArea:ta];
  }
  return self;
}
- (void)updateTrackingAreas {
  [super updateTrackingAreas];
  for (NSTrackingArea *a in self.trackingAreas) [self removeTrackingArea:a];
  NSTrackingArea *ta = [[NSTrackingArea alloc] initWithRect:self.bounds options:(NSTrackingMouseMoved|NSTrackingMouseEnteredAndExited|NSTrackingActiveInKeyWindow|NSTrackingInVisibleRect) owner:self userInfo:nil];
  [self addTrackingArea:ta];
}
- (CGFloat)outerRadius { return MIN(self.bounds.size.width, self.bounds.size.height)/2.0 - 14; }
- (CGFloat)innerRadius { return [self outerRadius] * 0.58; }
- (CGFloat)centerRadius { return 56; }
- (NSPoint)center { return NSMakePoint(NSMidX(self.bounds), NSMidY(self.bounds)); }
- (NSInteger)segmentAtPoint:(NSPoint)p {
  CGFloat dx = p.x - self.center.x, dy = p.y - self.center.y;
  CGFloat dist = sqrt(dx*dx + dy*dy);
  if (dist < [self centerRadius] + 2) return -2;
  if (dist > [self outerRadius] + 4) return -1;
  CGFloat ang = atan2(dy, dx) * 180.0 / M_PI;
  ang += 90.0; if (ang < 0) ang += 360.0;
  NSInteger count = MAX(1, (NSInteger)self.items.count);
  CGFloat span = 360.0 / count;
  NSInteger idx = (NSInteger)floor(ang / span);
  if (idx < 0) idx = 0;
  if (idx >= count) idx = count - 1;
  return idx;
}
- (void)mouseMoved:(NSEvent *)e {
  NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
  NSInteger idx = [self segmentAtPoint:p];
  if (idx != self.hovered) { self.hovered = idx; [self setNeedsDisplay:YES]; }
}
- (void)mouseExited:(NSEvent *)e { self.hovered = -1; [self setNeedsDisplay:YES]; }
- (void)mouseDown:(NSEvent *)e {
  NSPoint p = [self convertPoint:e.locationInWindow fromView:nil];
  NSInteger idx = [self segmentAtPoint:p];
  if (idx == -2) { if (self.onCenter) self.onCenter(e.clickCount >= 2); }
  else if (idx >= 0 && self.onSegment) self.onSegment(idx);
}
- (void)drawRect:(NSRect)dirtyRect {
  [super drawRect:dirtyRect];
  NSColor *bg = [NSColor windowBackgroundColor];
  [bg setFill];
  NSBezierPath *bgPath = [NSBezierPath bezierPathWithRoundedRect:self.bounds xRadius:26 yRadius:26];
  [bgPath fill];
  NSInteger count = MAX(1, (NSInteger)self.items.count);
  CGFloat span = 360.0 / count;
  CGPoint c = self.center;
  CGFloat inner = [self innerRadius], outer = [self outerRadius];
  NSArray *colors = @[[NSColor systemTealColor], [NSColor systemBlueColor], [NSColor systemPurpleColor], [NSColor systemOrangeColor], [NSColor systemIndigoColor], [NSColor systemGreenColor], [NSColor systemPinkColor], [NSColor systemYellowColor]];
  for (NSInteger i = 0; i < count; i++) {
    CGFloat start = -90.0 + i * span + 2.0;
    CGFloat end = -90.0 + (i + 1) * span - 2.0;
    NSBezierPath *path = [NSBezierPath bezierPath];
    [path appendBezierPathWithArcWithCenter:c radius:outer startAngle:start endAngle:end clockwise:NO];
    [path appendBezierPathWithArcWithCenter:c radius:inner startAngle:end endAngle:start clockwise:YES];
    [path closePath];
    NSColor *base = colors[i % colors.count];
    [[base colorWithAlphaComponent:(self.hovered == i ? 0.85 : 0.24)] setFill];
    [path fill];
    if (self.hovered == i) { [[NSColor whiteColor] setStroke]; path.lineWidth = 2; [path stroke]; }
    NSDictionary *item = self.items[i];
    CGFloat mid = (start + end) / 2.0;
    CGFloat r = (inner + outer) / 2.0 + 2;
    NSPoint ip = NSMakePoint(c.x + cos(mid * M_PI / 180.0) * r, c.y + sin(mid * M_PI / 180.0) * r);
    NSImage *icon = [NSImage imageWithSystemSymbolName:item[@"symbol"] ?: @"circle" accessibilityDescription:nil];
    icon = [icon imageWithSymbolConfiguration:[NSImageSymbolConfiguration configurationWithPointSize:18 weight:NSFontWeightSemibold]];
    NSRect ir = NSMakeRect(ip.x - 9, ip.y - 16, 18, 18);
    [icon drawInRect:ir];
    NSString *title = item[@"title"] ?: @"";
    NSMutableParagraphStyle *ps = [[NSMutableParagraphStyle alloc] init]; ps.alignment = NSTextAlignmentCenter;
    NSDictionary *attrs = @{NSFontAttributeName:[NSFont systemFontOfSize:9.5 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:(self.hovered == i ? [NSColor whiteColor] : [NSColor labelColor]), NSParagraphStyleAttributeName:ps};
    [title drawInRect:NSMakeRect(ip.x - 30, ip.y - 30, 60, 14) withAttributes:attrs];
  }
  CGFloat cr = [self centerRadius];
  NSBezierPath *centerPath = [NSBezierPath bezierPathWithOvalInRect:NSMakeRect(c.x-cr, c.y-cr, cr*2, cr*2)];
  [[NSColor controlAccentColor] setFill]; [centerPath fill];
  NSImage *appIcon = [NSApp applicationIconImage];
  if (appIcon) [appIcon drawInRect:NSMakeRect(c.x-26, c.y-26, 52, 52) fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1.0];
}
@end

@interface DLDropScrollView : NSScrollView
@property (copy) void (^onPaths)(NSArray<NSString *> *paths);
@property (strong) NSSet<NSString *> *allowedExtensions;
@end
@implementation DLDropScrollView
- (instancetype)initWithFrame:(NSRect)frame {
  self = [super initWithFrame:frame];
  if (self) [self registerForDraggedTypes:@[NSPasteboardTypeFileURL, NSFilenamesPboardType]];
  return self;
}
- (NSArray<NSString *> *)dropPaths:(id<NSDraggingInfo>)info {
  NSMutableArray *out = [NSMutableArray array];
  NSArray *urls = [[info draggingPasteboard] readObjectsForClasses:@[[NSURL class]] options:@{NSPasteboardURLReadingFileURLsOnlyKey: @YES}];
  for (NSURL *u in urls) if (u.path.length) [out addObject:u.path];
  if (!out.count) {
    NSArray *names = [[info draggingPasteboard] propertyListForType:NSFilenamesPboardType];
    if ([names isKindOfClass:[NSArray class]]) for (id n in names) if ([n isKindOfClass:[NSString class]]) [out addObject:n];
  }
  return out;
}
- (BOOL)hasAllowedPath:(id<NSDraggingInfo>)info {
  for (NSString *p in [self dropPaths:info]) {
    BOOL isDir = NO;
    if ([[NSFileManager defaultManager] fileExistsAtPath:p isDirectory:&isDir] && isDir) return YES;
    if ([self.allowedExtensions containsObject:p.pathExtension.lowercaseString]) return YES;
  }
  return NO;
}
- (NSDragOperation)draggingEntered:(id<NSDraggingInfo>)info { return [self hasAllowedPath:info] ? NSDragOperationCopy : NSDragOperationNone; }
- (NSDragOperation)draggingUpdated:(id<NSDraggingInfo>)info { return [self hasAllowedPath:info] ? NSDragOperationCopy : NSDragOperationNone; }
- (BOOL)prepareForDragOperation:(id<NSDraggingInfo>)info { return [self hasAllowedPath:info]; }
- (BOOL)performDragOperation:(id<NSDraggingInfo>)info {
  NSArray *paths = [self dropPaths:info];
  if (!paths.count) return NO;
  if (self.onPaths) self.onPaths(paths);
  return YES;
}
@end

@interface DLDropImageView : NSImageView
@property (copy) void (^onPath)(NSString *path);
@end
@implementation DLDropImageView
- (instancetype)initWithFrame:(NSRect)frame {
  self = [super initWithFrame:frame];
  if (self) [self registerForDraggedTypes:@[NSPasteboardTypeFileURL, NSFilenamesPboardType]];
  return self;
}
- (NSString *)firstPath:(id<NSDraggingInfo>)info {
  NSArray *urls=[[info draggingPasteboard] readObjectsForClasses:@[[NSURL class]] options:@{NSPasteboardURLReadingFileURLsOnlyKey:@YES}];
  for(NSURL *u in urls) if(u.path.length)return u.path;
  NSArray *names=[[info draggingPasteboard] propertyListForType:NSFilenamesPboardType];
  if([names isKindOfClass:[NSArray class]])for(id n in names)if([n isKindOfClass:[NSString class]])return n;
  return nil;
}
- (NSDragOperation)draggingEntered:(id<NSDraggingInfo>)info {
  self.layer.borderColor=[NSColor controlAccentColor].CGColor;
  return [self firstPath:info].length?NSDragOperationCopy:NSDragOperationNone;
}
- (BOOL)performDragOperation:(id<NSDraggingInfo>)info {
  NSString *path=[self firstPath:info];
  if(!path.length)return NO;
  if(self.onPath)self.onPath(path);
  return YES;
}
@end

@interface DLFileTextView : NSTextView
@property (copy) void (^onPaths)(NSArray<NSString *> *paths);
@end
@implementation DLFileTextView
- (instancetype)initWithFrame:(NSRect)frame {
  self=[super initWithFrame:frame];
  if(self)[self registerForDraggedTypes:@[NSPasteboardTypeFileURL, NSFilenamesPboardType]];
  return self;
}
- (NSArray<NSString *> *)filePaths:(id<NSDraggingInfo>)info {
  NSMutableArray *out=[NSMutableArray array];
  NSArray *urls=[[info draggingPasteboard] readObjectsForClasses:@[[NSURL class]] options:@{NSPasteboardURLReadingFileURLsOnlyKey:@YES}];
  for(NSURL *u in urls)if(u.path.length)[out addObject:u.path];
  if(!out.count){
    NSArray *names=[[info draggingPasteboard] propertyListForType:NSFilenamesPboardType];
    if([names isKindOfClass:[NSArray class]])for(id n in names)if([n isKindOfClass:[NSString class]])[out addObject:n];
  }
  return out;
}
- (NSDragOperation)draggingEntered:(id<NSDraggingInfo>)info {
  if([self filePaths:info].count)return NSDragOperationCopy;
  return [super draggingEntered:info];
}
- (NSDragOperation)draggingUpdated:(id<NSDraggingInfo>)info {
  if([self filePaths:info].count)return NSDragOperationCopy;
  return [super draggingUpdated:info];
}
- (BOOL)performDragOperation:(id<NSDraggingInfo>)info {
  NSArray *paths=[self filePaths:info];
  if(paths.count){if(self.onPaths)self.onPaths(paths);return YES;}
  return [super performDragOperation:info];
}
@end

@interface DLRegionSelectView : NSView
@property NSPoint startPoint;
@property NSRect selection;
@property (copy) void (^onComplete)(NSRect rect);
@property (copy) void (^onCancel)(void);
@end
@implementation DLRegionSelectView
- (BOOL)acceptsFirstResponder { return YES; }
- (void)mouseDown:(NSEvent *)event {
  self.startPoint = [self convertPoint:event.locationInWindow fromView:nil];
  self.selection = NSZeroRect;
  [self setNeedsDisplay:YES];
}
- (void)mouseDragged:(NSEvent *)event {
  NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
  self.selection = NSMakeRect(MIN(self.startPoint.x, p.x), MIN(self.startPoint.y, p.y), fabs(p.x - self.startPoint.x), fabs(p.y - self.startPoint.y));
  [self setNeedsDisplay:YES];
}
- (void)mouseUp:(NSEvent *)event {
  if (self.selection.size.width < 12 || self.selection.size.height < 12) {
    if (self.onCancel) self.onCancel();
    return;
  }
  NSRect screenRect = [self.window convertRectToScreen:self.selection];
  if (self.onComplete) self.onComplete(screenRect);
}
- (void)drawRect:(NSRect)dirtyRect {
  [[NSColor colorWithCalibratedWhite:0 alpha:0.22] setFill];
  NSBezierPath *all = [NSBezierPath bezierPathWithRect:self.bounds];
  if (self.selection.size.width > 0 && self.selection.size.height > 0) {
    [all appendBezierPathWithRect:self.selection];
    all.windingRule = NSWindingRuleEvenOdd;
  }
  [all fill];
  if (self.selection.size.width > 0) {
    [[NSColor whiteColor] setStroke];
    NSBezierPath *border = [NSBezierPath bezierPathWithRect:self.selection];
    border.lineWidth = 2; [border stroke];
    NSString *tip = @"拖动选择录屏区域，松开开始";
    [tip drawAtPoint:NSMakePoint(self.selection.origin.x, self.selection.origin.y + self.selection.size.height + 8) withAttributes:@{NSFontAttributeName:[NSFont systemFontOfSize:12 weight:NSFontWeightSemibold], NSForegroundColorAttributeName:[NSColor whiteColor]}];
  }
}
@end

typedef NS_ENUM(NSInteger, DLRecordScene) { DLRecordSceneFull = 0, DLRecordSceneWindow = 1, DLRecordSceneApplication = 2, DLRecordSceneRegion = 3 };

@interface DLLiveAnnotationView : NSView
@property NSInteger tool; // 0 pen, 1 arrow
@property (strong) NSMutableArray<NSDictionary *> *items;
@property (strong) NSMutableArray<NSValue *> *currentPoints;
@property NSPoint startPoint;
@property (strong) NSColor *color;
@property CGFloat lineWidth;
@property (copy) void (^onEscape)(void);
@end
@implementation DLLiveAnnotationView
- (BOOL)acceptsFirstResponder { return YES; }
- (void)keyDown:(NSEvent *)event { if (event.keyCode == 53) { if (self.onEscape) self.onEscape(); return; } [super keyDown:event]; }
- (BOOL)isOpaque { return NO; }
- (BOOL)isFlipped { return NO; }
- (void)drawRect:(NSRect)dirtyRect {
  NSColor *c = self.color ?: [NSColor systemRedColor];
  [c setStroke];
  for (NSDictionary *it in self.items) {
    NSInteger t = [it[@"tool"] integerValue];
    if (t == 0) {
      NSArray *pts = it[@"points"];
      if (pts.count > 1) {
        NSBezierPath *p = [NSBezierPath bezierPath];
        p.lineWidth = self.lineWidth; p.lineCapStyle = NSLineCapStyleRound; p.lineJoinStyle = NSLineJoinStyleRound;
        [p moveToPoint:[pts[0] pointValue]];
        for (NSInteger i=1;i<(NSInteger)pts.count;i++) [p lineToPoint:[pts[i] pointValue]];
        [p stroke];
      }
    } else {
      NSPoint a=[it[@"start"] pointValue], b=[it[@"end"] pointValue];
      NSBezierPath *p=[NSBezierPath bezierPath]; p.lineWidth=self.lineWidth;
      [p moveToPoint:a]; [p lineToPoint:b]; [p stroke];
      CGFloat ang=atan2(b.y-a.y,b.x-a.x), len=MAX(14,self.lineWidth*4);
      NSBezierPath *h=[NSBezierPath bezierPath];
      [h moveToPoint:b]; [h lineToPoint:NSMakePoint(b.x-len*cos(ang-0.45),b.y-len*sin(ang-0.45))];
      [h moveToPoint:b]; [h lineToPoint:NSMakePoint(b.x-len*cos(ang+0.45),b.y-len*sin(ang+0.45))];
      [h stroke];
    }
  }
  if (self.currentPoints.count > 1 && self.tool == 0) {
    NSBezierPath *p=[NSBezierPath bezierPath]; p.lineWidth=self.lineWidth; p.lineCapStyle=NSLineCapStyleRound;
    [p moveToPoint:[self.currentPoints[0] pointValue]];
    for (NSInteger i=1;i<(NSInteger)self.currentPoints.count;i++) [p lineToPoint:[self.currentPoints[i] pointValue]];
    [p stroke];
  }
}
- (void)mouseDown:(NSEvent *)event {
  self.startPoint=[self convertPoint:event.locationInWindow fromView:nil];
  self.currentPoints=[NSMutableArray arrayWithObject:[NSValue valueWithPoint:self.startPoint]];
}
- (void)mouseDragged:(NSEvent *)event {
  NSPoint p=[self convertPoint:event.locationInWindow fromView:nil];
  if (self.tool==0) { [self.currentPoints addObject:[NSValue valueWithPoint:p]]; [self setNeedsDisplay:YES]; }
  else { [self setNeedsDisplay:YES]; }
}
- (void)mouseUp:(NSEvent *)event {
  NSPoint p=[self convertPoint:event.locationInWindow fromView:nil];
  if (self.tool==0) {
    if (self.currentPoints.count>1) [self.items addObject:@{@"tool":@0,@"points":[self.currentPoints copy]}];
  } else {
    if (hypot(p.x-self.startPoint.x,p.y-self.startPoint.y)>10) [self.items addObject:@{@"tool":@1,@"start":[NSValue valueWithPoint:self.startPoint],@"end":[NSValue valueWithPoint:p]}];
  }
  self.currentPoints=nil; [self setNeedsDisplay:YES];
}
@end

@interface DLAnnotateView : NSView
@property (strong) NSImage *image;
@property (strong) NSMutableArray<NSDictionary *> *items;
@property (strong) NSColor *strokeColor;
@property CGFloat strokeWidth;
@property NSInteger tool; // 0 pen, 1 rect, 2 arrow, 3 mosaic, 4 text
@property NSPoint startPoint;
@property (strong) NSMutableArray<NSValue *> *penPoints;
@property (strong) NSImage *mosaicCache;
@end
@implementation DLAnnotateView
- (BOOL)isFlipped { return NO; }
- (void)setImage:(NSImage *)image { _image = image; self.mosaicCache = nil; [self setNeedsDisplay:YES]; }
- (NSImage *)mosaicImage {
  if (self.mosaicCache) return self.mosaicCache;
  NSRect proposed = NSMakeRect(0, 0, self.image.size.width, self.image.size.height);
  CGImageRef cg = [self.image CGImageForProposedRect:&proposed context:nil hints:nil];
  if (!cg) return self.image;
  CIImage *ci = [CIImage imageWithCGImage:cg];
  CIFilter *f = [CIFilter filterWithName:@"CIPixellate"];
  [f setValue:ci forKey:kCIInputImageKey];
  [f setValue:@(MAX(8, ci.extent.size.width / 70.0)) forKey:kCIInputScaleKey];
  CIImage *out = f.outputImage;
  CGImageRef outCG = [[CIContext contextWithOptions:nil] createCGImage:out fromRect:ci.extent];
  NSImage *img = outCG ? [[NSImage alloc] initWithCGImage:outCG size:self.image.size] : self.image;
  if (outCG) CGImageRelease(outCG);
  self.mosaicCache = img;
  return img;
}
- (void)drawRect:(NSRect)dirtyRect {
  [self.image drawInRect:self.bounds];
  for (NSDictionary *it in self.items) {
    NSColor *c = it[@"color"] ?: [NSColor systemRedColor];
    [c setStroke];
    CGFloat w = [it[@"width"] doubleValue] > 0 ? [it[@"width"] doubleValue] : 4;
    NSInteger t = [it[@"tool"] integerValue];
    if (t == 0) {
      NSArray *pts = it[@"points"];
      if (pts.count > 1) {
        NSBezierPath *path = [NSBezierPath bezierPath];
        path.lineWidth = w; path.lineCapStyle = NSLineCapStyleRound; path.lineJoinStyle = NSLineJoinStyleRound;
        [path moveToPoint:[pts[0] pointValue]];
        for (NSInteger i = 1; i < (NSInteger)pts.count; i++) [path lineToPoint:[pts[i] pointValue]];
        [path stroke];
      }
    } else if (t == 3) {
      NSPoint a = [it[@"start"] pointValue], b = [it[@"end"] pointValue];
      NSRect r = NSMakeRect(MIN(a.x,b.x), MIN(a.y,b.y), fabs(b.x-a.x), fabs(b.y-a.y));
      [[self mosaicImage] drawInRect:r fromRect:r operation:NSCompositingOperationCopy fraction:1.0];
    } else if (t == 4) {
      NSString *text = it[@"text"] ?: @"";
      if (text.length) {
        NSFont *font = [NSFont boldSystemFontOfSize:MAX(16, w * 4.5)];
        NSDictionary *attrs = @{NSFontAttributeName: font, NSForegroundColorAttributeName: c};
        NSPoint p = [it[@"start"] pointValue];
        [text drawAtPoint:p withAttributes:attrs];
      }
    } else {
      NSPoint a = [it[@"start"] pointValue], b = [it[@"end"] pointValue];
      if (t == 1) {
        NSBezierPath *p = [NSBezierPath bezierPathWithRect:NSMakeRect(MIN(a.x,b.x), MIN(a.y,b.y), fabs(b.x-a.x), fabs(b.y-a.y))];
        p.lineWidth = w; [p stroke];
      } else {
        NSBezierPath *p = [NSBezierPath bezierPath];
        p.lineWidth = w; [p moveToPoint:a]; [p lineToPoint:b]; [p stroke];
        CGFloat angle = atan2(b.y-a.y, b.x-a.x);
        CGFloat len = MAX(12, w * 3.5);
        NSPoint p1 = NSMakePoint(b.x - len * cos(angle - 0.45), b.y - len * sin(angle - 0.45));
        NSPoint p2 = NSMakePoint(b.x - len * cos(angle + 0.45), b.y - len * sin(angle + 0.45));
        NSBezierPath *head = [NSBezierPath bezierPath];
        [head moveToPoint:b]; [head lineToPoint:p1]; [head moveToPoint:b]; [head lineToPoint:p2];
        [head stroke];
      }
    }
  }
}
- (void)mouseDown:(NSEvent *)event {
  self.startPoint = [self convertPoint:event.locationInWindow fromView:nil];
  self.penPoints = [NSMutableArray arrayWithObject:[NSValue valueWithPoint:self.startPoint]];
}
- (void)mouseDragged:(NSEvent *)event {
  NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
  if (self.tool == 0) {
    [self.penPoints addObject:[NSValue valueWithPoint:p]];
    [self setNeedsDisplay:YES];
  } else {
    [self setNeedsDisplay:YES];
  }
}
- (void)mouseUp:(NSEvent *)event {
  NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
  NSColor *c = self.strokeColor ?: [NSColor systemRedColor];
  if (self.tool == 0) {
    if (self.penPoints.count > 1) [self.items addObject:@{@"tool":@0, @"points":[self.penPoints copy], @"color":c, @"width":@(self.strokeWidth)}];
  } else if (self.tool == 1) {
    if (fabs(p.x-self.startPoint.x) > 4 && fabs(p.y-self.startPoint.y) > 4) [self.items addObject:@{@"tool":@1, @"start":[NSValue valueWithPoint:self.startPoint], @"end":[NSValue valueWithPoint:p], @"color":c, @"width":@(self.strokeWidth)}];
  } else if (self.tool == 2) {
    if (hypot(p.x-self.startPoint.x, p.y-self.startPoint.y) > 8) [self.items addObject:@{@"tool":@2, @"start":[NSValue valueWithPoint:self.startPoint], @"end":[NSValue valueWithPoint:p], @"color":c, @"width":@(self.strokeWidth)}];
  } else if (self.tool == 3) {
    if (fabs(p.x-self.startPoint.x) > 4 && fabs(p.y-self.startPoint.y) > 4) [self.items addObject:@{@"tool":@3, @"start":[NSValue valueWithPoint:self.startPoint], @"end":[NSValue valueWithPoint:p], @"width":@(self.strokeWidth)}];
  } else if (self.tool == 4) {
    NSAlert *a = [[NSAlert alloc] init];
    a.messageText = @"添加文字";
    a.informativeText = @"输入要显示在截图上的文字";
    NSTextField *tf = [[NSTextField alloc] initWithFrame:NSMakeRect(0,0,260,24)];
    a.accessoryView = tf;
    [a addButtonWithTitle:@"添加"]; [a addButtonWithTitle:@"取消"];
    if ([a runModal] == NSAlertFirstButtonReturn && tf.stringValue.length) {
      [self.items addObject:@{@"tool":@4, @"start":[NSValue valueWithPoint:self.startPoint], @"text":tf.stringValue, @"color":c, @"width":@(self.strokeWidth)}];
    }
  }
  self.penPoints = nil;
  [self setNeedsDisplay:YES];
}
- (void)undo { if (self.items.count) { [self.items removeLastObject]; [self setNeedsDisplay:YES]; } }
- (NSData *)pngData {
  CGFloat scale = 1.0;
  for (NSImageRep *ir in self.image.representations) {
    if (ir.pixelsWide > 0 && self.image.size.width > 0) scale = MAX(scale, ir.pixelsWide / self.image.size.width);
  }
  NSInteger w = MAX(1, (NSInteger)llround(self.bounds.size.width * scale));
  NSInteger h = MAX(1, (NSInteger)llround(self.bounds.size.height * scale));
  NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:w pixelsHigh:h bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
  if (!rep) return nil;
  NSGraphicsContext *ctx = [NSGraphicsContext graphicsContextWithBitmapImageRep:rep];
  [NSGraphicsContext saveGraphicsState];
  [NSGraphicsContext setCurrentContext:ctx];
  CGContextScaleCTM(ctx.CGContext, scale, scale);
  [self drawRect:self.bounds];
  [ctx flushGraphics];
  [NSGraphicsContext restoreGraphicsState];
  return [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
}
@end

@interface DLImageRegionView : NSView
@property (strong) NSImage *image;
@property NSRect selectedRect;
@property NSPoint dragStart;
@property BOOL dragging;
- (NSRect)imageDrawRect;
- (NSRect)selectionInImagePixels;
@end
@implementation DLImageRegionView
- (BOOL)isFlipped { return NO; }
- (void)setImage:(NSImage *)image { _image = image; self.selectedRect = NSZeroRect; [self setNeedsDisplay:YES]; }
- (NSRect)imageDrawRect {
  if (!self.image) return NSZeroRect;
  NSSize is = self.image.size, bs = self.bounds.size;
  if (is.width <= 0 || is.height <= 0 || bs.width <= 0 || bs.height <= 0) return NSZeroRect;
  CGFloat scale = MIN(bs.width / is.width, bs.height / is.height);
  CGFloat w = is.width * scale, h = is.height * scale;
  return NSMakeRect((bs.width - w)/2, (bs.height - h)/2, w, h);
}
- (void)drawRect:(NSRect)dirtyRect {
  [[NSColor colorWithWhite:0.12 alpha:1] setFill];
  NSRectFill(self.bounds);
  NSRect ir = [self imageDrawRect];
  [self.image drawInRect:ir fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1];
  NSRect sel = self.selectedRect;
  if (sel.size.width > 1 && sel.size.height > 1) {
    [[NSColor colorWithWhite:0 alpha:0.5] setFill];
    NSRectFill(NSMakeRect(ir.origin.x, ir.origin.y, ir.size.width, sel.origin.y - ir.origin.y));
    NSRectFill(NSMakeRect(ir.origin.x, NSMaxY(sel), ir.size.width, NSMaxY(ir) - NSMaxY(sel)));
    NSRectFill(NSMakeRect(ir.origin.x, sel.origin.y, sel.origin.x - ir.origin.x, sel.size.height));
    NSRectFill(NSMakeRect(NSMaxX(sel), sel.origin.y, NSMaxX(ir) - NSMaxX(sel), sel.size.height));
    [[NSColor systemBlueColor] setStroke];
    NSBezierPath *p = [NSBezierPath bezierPathWithRect:sel];
    p.lineWidth = 2; [p stroke];
  }
}
- (void)mouseDown:(NSEvent *)event {
  NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
  NSRect ir = [self imageDrawRect];
  if (!NSPointInRect(p, ir)) return;
  self.dragStart = p; self.dragging = YES; self.selectedRect = NSZeroRect; [self setNeedsDisplay:YES];
}
- (void)mouseDragged:(NSEvent *)event {
  if (!self.dragging) return;
  NSPoint p = [self convertPoint:event.locationInWindow fromView:nil];
  NSRect ir = [self imageDrawRect];
  p.x = MIN(MAX(p.x, ir.origin.x), NSMaxX(ir));
  p.y = MIN(MAX(p.y, ir.origin.y), NSMaxY(ir));
  CGFloat x = MIN(self.dragStart.x, p.x), y = MIN(self.dragStart.y, p.y);
  self.selectedRect = NSMakeRect(x, y, fabs(p.x-self.dragStart.x), fabs(p.y-self.dragStart.y));
  [self setNeedsDisplay:YES];
}
- (void)mouseUp:(NSEvent *)event { self.dragging = NO; [self setNeedsDisplay:YES]; }
- (NSRect)selectionInImagePixels {
  if (!self.image) return NSZeroRect;
  NSRect ir = [self imageDrawRect], sel = self.selectedRect;
  if (ir.size.width <= 0 || ir.size.height <= 0 || sel.size.width <= 1 || sel.size.height <= 1) return NSZeroRect;
  CGFloat sx = self.image.size.width / ir.size.width, sy = self.image.size.height / ir.size.height;
  return NSMakeRect((sel.origin.x - ir.origin.x) * sx, (sel.origin.y - ir.origin.y) * sy, sel.size.width * sx, sel.size.height * sy);
}
@end

@interface DLScreenRecorder : NSObject <SCStreamDelegate, SCRecordingOutputDelegate, SCContentSharingPickerObserver>
@property (strong) SCStream *stream;
@property (strong) SCRecordingOutput *recordingOutput;
@property (strong) NSURL *outputURL;
@property (strong) NSURL *finalOutputURL;
@property (strong) NSMutableArray<NSURL *> *segmentURLs;
@property (strong) SCContentFilter *savedFilter;
@property (strong) SCStreamConfiguration *savedConfig;
@property (strong) SCContentSharingPicker *picker;
@property (copy) void (^onStarted)(void);
@property (copy) void (^onPaused)(void);
@property (copy) void (^onFinished)(NSURL *url, NSError *error);
@property NSInteger scene;
@property NSInteger seconds;
@property NSRect region;
@property NSInteger segmentIndex;
@property BOOL paused, stopping, finishing, finished;
@property (strong) dispatch_block_t stopWork;
- (void)startWithScene:(NSInteger)scene seconds:(NSInteger)seconds region:(NSRect)region url:(NSURL *)url;
- (void)pause;
- (void)resume;
- (void)stop;
@end
@implementation DLScreenRecorder
- (SCStreamConfiguration *)streamConfigurationForPicker {
  SCStreamConfiguration *config = [[SCStreamConfiguration alloc] init];
  id sysAudioObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureSystemAudio"];
  BOOL sysAudio = !sysAudioObj || [sysAudioObj boolValue];
  BOOL micAudio = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerCaptureMicrophone"];
  config.capturesAudio = sysAudio;
  config.captureMicrophone = micAudio;
  config.sampleRate = 48000;
  config.channelCount = 2;
  id curObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowCursor"];
  id clickObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowClicks"];
  config.showsCursor = (!curObj || [curObj boolValue]);
  config.showMouseClicks = (!clickObj || [clickObj boolValue]);
  if (config.showMouseClicks) config.pixelFormat = kCVPixelFormatType_32BGRA;
  NSInteger fps = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureFPS"];
  if (fps <= 0) fps = 30;
  config.minimumFrameInterval = CMTimeMake(1, (int32_t)fps);
  NSInteger targetH = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureQuality"];
  if (targetH <= 0) targetH = 1440;
  config.height = (size_t)targetH;
  config.width = MIN(3840, MAX(640, (size_t)llround((CGFloat)targetH * 16.0 / 9.0)));
  return config;
}

- (void)rememberFilter:(SCContentFilter *)filter scene:(NSInteger)scene {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  if (scene == DLRecordSceneWindow && filter.includedWindows.count) {
    SCWindow *w = filter.includedWindows.firstObject;
    [ud setObject:@{@"windowID": @(w.windowID), @"title": w.title ?: @"", @"bundle": w.owningApplication.bundleIdentifier ?: @""} forKey:@"centerCaptureLastWindow"];
  } else if (scene == DLRecordSceneApplication && filter.includedApplications.count) {
    NSMutableArray *ids = [NSMutableArray array];
    for (SCRunningApplication *a in filter.includedApplications) if (a.bundleIdentifier.length) [ids addObject:a.bundleIdentifier];
    [ud setObject:ids forKey:@"centerCaptureLastApps"];
  }
  [ud synchronize];
}

- (BOOL)tryRestoreRememberedSourceForScene:(NSInteger)scene {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  id saved = scene == DLRecordSceneWindow ? [ud objectForKey:@"centerCaptureLastWindow"] : [ud objectForKey:@"centerCaptureLastApps"];
  if (!saved) return NO;
  [SCShareableContent getShareableContentWithCompletionHandler:^(SCShareableContent *content, NSError *error) {
    if (error || !content.displays.count) {
      dispatch_async(dispatch_get_main_queue(), ^{ [self presentPickerForScene:scene]; });
      return;
    }
    SCDisplay *display = content.displays.firstObject;
    SCContentFilter *filter = nil;
    if (scene == DLRecordSceneWindow) {
      NSDictionary *d = saved;
      SCWindow *match = nil;
      for (SCWindow *w in content.windows) {
        if (w.windowID == [d[@"windowID"] unsignedIntValue]) { match = w; break; }
      }
      if (!match) for (SCWindow *w in content.windows) {
        if ([w.title isEqualToString:d[@"title"]] && [w.owningApplication.bundleIdentifier isEqualToString:d[@"bundle"]]) { match = w; break; }
      }
      if (match) filter = [[SCContentFilter alloc] initWithDesktopIndependentWindow:match];
    } else {
      NSMutableArray *apps = [NSMutableArray array];
      for (SCRunningApplication *a in content.applications) if ([saved containsObject:a.bundleIdentifier]) [apps addObject:a];
      if (apps.count) filter = [[SCContentFilter alloc] initWithDisplay:display includingApplications:apps exceptingWindows:@[]];
    }
    if (filter) {
      dispatch_async(dispatch_get_main_queue(), ^{ [self startStreamWithFilter:filter configuration:[self streamConfigurationForPicker]]; });
    } else {
      dispatch_async(dispatch_get_main_queue(), ^{ [self presentPickerForScene:scene]; });
    }
  }];
  return YES;
}

- (void)presentPickerForScene:(NSInteger)scene {
  self.picker = [SCContentSharingPicker sharedPicker];
  SCContentSharingPickerConfiguration *cfg = [[SCContentSharingPickerConfiguration alloc] init];
  cfg.allowedPickerModes = scene == DLRecordSceneWindow ? SCContentSharingPickerModeSingleWindow : SCContentSharingPickerModeSingleApplication;
  cfg.allowsChangingSelectedContent = NO;
  self.picker.defaultConfiguration = cfg;
  self.picker.active = YES;
  [self.picker addObserver:self];
  [self.picker presentPickerUsingContentStyle:(scene == DLRecordSceneWindow ? SCShareableContentStyleWindow : SCShareableContentStyleApplication)];
}

- (void)startWithScene:(NSInteger)scene seconds:(NSInteger)seconds region:(NSRect)region url:(NSURL *)url {
  self.scene = scene; self.seconds = seconds; self.region = region;
  self.finalOutputURL = url; self.segmentURLs = [NSMutableArray array];
  self.segmentIndex = 0; self.paused = NO; self.stopping = NO; self.finishing = NO; self.finished = NO;
  if (scene == DLRecordSceneWindow || scene == DLRecordSceneApplication) {
    if ([self tryRestoreRememberedSourceForScene:scene]) return;
    [self presentPickerForScene:scene];
    return;
  }
  [SCShareableContent getShareableContentWithCompletionHandler:^(SCShareableContent *content, NSError *error) {
    if (error || !content.displays.count) { [self finishWithError:error ?: [NSError errorWithDomain:@"DockLaunchers" code:1 userInfo:@{NSLocalizedDescriptionKey:@"无法访问屏幕内容，请允许屏幕录制权限"}]]; return; }
    NSInteger wantedDisplay = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureDisplayID"];
    SCDisplay *display = nil;
    if (scene == DLRecordSceneRegion && region.size.width > 1) {
      NSPoint center = NSMakePoint(NSMidX(region), NSMidY(region));
      for (SCDisplay *d in content.displays) if (NSPointInRect(center, d.frame)) { display = d; break; }
    }
    if (!display) for (SCDisplay *d in content.displays) if ((NSInteger)d.displayID == wantedDisplay) { display = d; break; }
    if (!display) display = content.displays.firstObject;
    SCContentFilter *filter = [[SCContentFilter alloc] initWithDisplay:display excludingWindows:@[]];
    SCStreamConfiguration *config = [[SCStreamConfiguration alloc] init];
    config.showsCursor = YES;
    config.minimumFrameInterval = CMTimeMake(1, 30);
    id sysAudioObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureSystemAudio"];
    BOOL sysAudio = !sysAudioObj || [sysAudioObj boolValue];
    BOOL micAudio = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerCaptureMicrophone"];
    config.capturesAudio = sysAudio;
    config.captureMicrophone = micAudio;
    config.sampleRate = 48000;
    config.channelCount = 2;
    id curObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowCursor"];
    id clickObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowClicks"];
    config.showsCursor = (!curObj || [curObj boolValue]);
    config.showMouseClicks = (!clickObj || [clickObj boolValue]);
    if (config.showMouseClicks) config.pixelFormat = kCVPixelFormatType_32BGRA;
    NSInteger fps = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureFPS"];
    if (fps <= 0) fps = 30;
    config.minimumFrameInterval = CMTimeMake(1, (int32_t)fps);
    NSInteger targetH = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureQuality"];
    if (targetH <= 0) targetH = 1440;
    if (scene == DLRecordSceneRegion && region.size.width > 1) {
      config.sourceRect = CGRectMake(region.origin.x - display.frame.origin.x, display.frame.size.height - (region.origin.y - display.frame.origin.y + region.size.height), region.size.width, region.size.height);
      CGFloat scale = MIN(1.0, MIN(3840.0 / MAX(1.0, region.size.width), (CGFloat)targetH / MAX(1.0, region.size.height)));
      config.width = MAX(2, (size_t)llround(region.size.width * scale));
      config.height = MAX(2, (size_t)llround(region.size.height * scale));
    } else {
      CGFloat aspect = display.frame.size.height > 0 ? display.frame.size.width / display.frame.size.height : 16.0/9.0;
      config.height = (size_t)targetH;
      config.width = MIN(3840, MAX(640, (size_t)llround((CGFloat)targetH * aspect)));
    }
    [self startStreamWithFilter:filter configuration:config];
  }];
}

- (NSURL *)nextSegmentURL {
  NSString *base = [self.finalOutputURL.lastPathComponent stringByDeletingPathExtension];
  NSString *part = [NSString stringWithFormat:@"%@-part%ld.mp4", base, (long)self.segmentIndex];
  return [[self.finalOutputURL URLByDeletingLastPathComponent] URLByAppendingPathComponent:part];
}

- (void)startStreamWithFilter:(SCContentFilter *)filter configuration:(SCStreamConfiguration *)config {
  self.savedFilter = filter;
  self.savedConfig = config;
  NSURL *segmentURL = [self nextSegmentURL];
  [[NSFileManager defaultManager] removeItemAtURL:segmentURL error:NULL];
  self.outputURL = segmentURL;
  SCRecordingOutputConfiguration *rc = [[SCRecordingOutputConfiguration alloc] init];
  rc.outputURL = segmentURL;
  rc.videoCodecType = [rc.availableVideoCodecTypes containsObject:AVVideoCodecTypeHEVC] ? AVVideoCodecTypeHEVC : AVVideoCodecTypeH264;
  rc.outputFileType = AVFileTypeMPEG4;
  rc.mixesAudioWithMicrophone = NO;
  self.recordingOutput = [[SCRecordingOutput alloc] initWithConfiguration:rc delegate:self];
  NSError *err = nil;
  SCStream *stream = [[SCStream alloc] initWithFilter:filter configuration:config delegate:self];
  if (![stream addRecordingOutput:self.recordingOutput error:&err]) { [self finishWithError:err]; return; }
  self.stream = stream;
  __weak typeof(self) weakSelf = self;
  __block BOOL startSettled = NO;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(10.0 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    if (startSettled || self.finished) return;
    [self.stream stopCaptureWithCompletionHandler:nil];
    [self finishWithError:[NSError errorWithDomain:@"DockLaunchers" code:5 userInfo:@{NSLocalizedDescriptionKey:@"屏幕录制启动超时，请检查屏幕录制权限后重试"}]];
  });
  [stream startCaptureWithCompletionHandler:^(NSError *error) {
    startSettled = YES;
    if (error) { [weakSelf finishWithError:error]; return; }
    dispatch_async(dispatch_get_main_queue(), ^{
      if (weakSelf.onStarted) weakSelf.onStarted();
      if (weakSelf.seconds > 0 && !weakSelf.stopWork) {
        weakSelf.stopWork = dispatch_block_create(0, ^{ [weakSelf stop]; });
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(weakSelf.seconds * NSEC_PER_SEC)), dispatch_get_main_queue(), weakSelf.stopWork);
      }
    });
  }];
}

- (void)pause {
  if (self.paused || !self.stream) return;
  self.paused = YES;
  if (self.stopWork) { dispatch_block_cancel(self.stopWork); self.stopWork = nil; }
  [self.stream stopCaptureWithCompletionHandler:nil];
}

- (void)resume {
  if (!self.paused || self.stopping) return;
  self.paused = NO;
  self.segmentIndex++;
  self.seconds = 0;
  [self startStreamWithFilter:self.savedFilter configuration:self.savedConfig];
}

- (void)stop {
  self.stopping = YES;
  if (self.stopWork) { dispatch_block_cancel(self.stopWork); self.stopWork = nil; }
  if (self.paused || !self.stream) { [self mergeAndFinish]; return; }
  [self.stream stopCaptureWithCompletionHandler:nil];
}

- (void)finishWithError:(NSError *)error {
  if (self.finished) return;
  self.finished = YES;
  if (self.stopWork) { dispatch_block_cancel(self.stopWork); self.stopWork = nil; }
  if (self.onFinished) self.onFinished(self.finalOutputURL, error);
}

- (void)mergeAndFinish {
  if (self.finishing) return;
  self.finishing = YES;
  NSMutableArray *valid = [NSMutableArray array];
  for (NSURL *u in self.segmentURLs) if ([[NSFileManager defaultManager] fileExistsAtPath:u.path]) [valid addObject:u];
  if (!valid.count) { [self finishWithError:[NSError errorWithDomain:@"DockLaunchers" code:3 userInfo:@{NSLocalizedDescriptionKey:@"没有可保存的录屏数据"}]]; return; }
  if (valid.count == 1) {
    NSURL *src = valid.firstObject;
    [[NSFileManager defaultManager] removeItemAtURL:self.finalOutputURL error:NULL];
    [[NSFileManager defaultManager] moveItemAtURL:src toURL:self.finalOutputURL error:NULL];
    [self finishWithError:nil];
    return;
  }
  AVMutableComposition *comp = [AVMutableComposition composition];
  AVMutableCompositionTrack *videoTrack = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
  NSMutableArray<AVMutableCompositionTrack *> *audioTracks = [NSMutableArray array];
  CMTime cursor = kCMTimeZero;
  for (NSURL *u in valid) {
    AVURLAsset *asset = [AVURLAsset URLAssetWithURL:u options:nil];
    AVAssetTrack *v = [asset tracksWithMediaType:AVMediaTypeVideo].firstObject;
    NSArray *audios = [asset tracksWithMediaType:AVMediaTypeAudio];
    if (v) [videoTrack insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:v atTime:cursor error:NULL];
    for (NSInteger i = 0; i < (NSInteger)audios.count && i < 2; i++) {
      while ((NSInteger)audioTracks.count <= i) {
        AVMutableCompositionTrack *at = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
        [audioTracks addObject:at];
      }
      [audioTracks[i] insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:audios[i] atTime:cursor error:NULL];
    }
    cursor = CMTimeAdd(cursor, asset.duration);
  }
  [[NSFileManager defaultManager] removeItemAtURL:self.finalOutputURL error:NULL];
  AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPresetHEVCHighestQuality];
  ex.outputURL = self.finalOutputURL;
  ex.outputFileType = AVFileTypeMPEG4;
  ex.shouldOptimizeForNetworkUse = YES;
  __weak typeof(self) weakSelf = self;
  [ex exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      NSDictionary *outAttrs = [[NSFileManager defaultManager] attributesOfItemAtPath:self.finalOutputURL.path error:NULL];
      BOOL exported = (ex.status == AVAssetExportSessionStatusCompleted) || (outAttrs && [outAttrs[NSFileSize] longLongValue] > 0);
      if (exported) {
        for (NSURL *u in valid) [[NSFileManager defaultManager] removeItemAtURL:u error:NULL];
        [weakSelf finishWithError:nil];
      } else {
        [weakSelf finishWithError:ex.error ?: [NSError errorWithDomain:@"DockLaunchers" code:4 userInfo:@{NSLocalizedDescriptionKey:@"录屏合并失败"}]];
      }
    });
  }];
}

- (void)recordingOutputDidStartRecording:(SCRecordingOutput *)recordingOutput {}
- (void)recordingOutputDidFinishRecording:(SCRecordingOutput *)recordingOutput {
  if (self.outputURL && [[NSFileManager defaultManager] fileExistsAtPath:self.outputURL.path]) [self.segmentURLs addObject:self.outputURL];
  if (self.paused) { self.stream = nil; if (self.onPaused) self.onPaused(); return; }
  if (self.stopping) { self.stream = nil; [self mergeAndFinish]; return; }
  [self finishWithError:nil];
}
- (void)recordingOutput:(SCRecordingOutput *)recordingOutput didFailWithError:(NSError *)error { [self finishWithError:error]; }
- (void)stream:(SCStream *)stream didStopWithError:(NSError *)error { if (error) [self finishWithError:error]; }
- (void)contentSharingPicker:(SCContentSharingPicker *)picker didUpdateWithFilter:(SCContentFilter *)filter forStream:(SCStream *)stream {
  [picker removeObserver:self];
  [self rememberFilter:filter scene:self.scene];
  [self startStreamWithFilter:filter configuration:[self streamConfigurationForPicker]];
}
- (void)contentSharingPicker:(SCContentSharingPicker *)picker didCancelForStream:(SCStream *)stream {
  [picker removeObserver:self];
  [self finishWithError:[NSError errorWithDomain:@"DockLaunchers" code:2 userInfo:@{NSLocalizedDescriptionKey:@"已取消选择录制内容"}]];
}
- (void)contentSharingPickerStartDidFailWithError:(NSError *)error { [self finishWithError:error]; }
@end

@interface DLPinnedImageView : NSImageView
@property NSPoint dragMouse;
@property NSPoint dragOrigin;
@end
@implementation DLPinnedImageView
- (BOOL)acceptsFirstMouse:(NSEvent *)event { return YES; }
- (void)mouseDown:(NSEvent *)event {
  self.dragMouse = [NSEvent mouseLocation];
  self.dragOrigin = self.window.frame.origin;
}
- (void)mouseDragged:(NSEvent *)event {
  NSPoint p = [NSEvent mouseLocation];
  NSPoint origin = NSMakePoint(self.dragOrigin.x + (p.x - self.dragMouse.x), self.dragOrigin.y + (p.y - self.dragMouse.y));
  [self.window setFrameOrigin:origin];
}
@end

@interface DLShelfDropView : NSView
@property (copy) void (^onDrop)(NSArray<NSURL *> *urls);
@end
@implementation DLShelfDropView
- (instancetype)initWithFrame:(NSRect)frameRect {
  self = [super initWithFrame:frameRect];
  if (self) {
    [self registerForDraggedTypes:@[NSPasteboardTypeFileURL]];
    self.wantsLayer = YES;
    self.layer.borderWidth = 1.5;
    self.layer.borderColor = [NSColor controlAccentColor].CGColor;
    self.layer.cornerRadius = 12;
  }
  return self;
}
- (NSDragOperation)draggingEntered:(id<NSDraggingInfo>)sender {
  NSPasteboard *pb = sender.draggingPasteboard;
  return [pb readObjectsForClasses:@[NSURL.class] options:@{NSPasteboardURLReadingFileURLsOnlyKey: @YES}].count ? NSDragOperationCopy : NSDragOperationNone;
}
- (BOOL)performDragOperation:(id<NSDraggingInfo>)sender {
  NSPasteboard *pb = sender.draggingPasteboard;
  NSArray *urls = [pb readObjectsForClasses:@[NSURL.class] options:@{NSPasteboardURLReadingFileURLsOnlyKey: @YES}];
  if (urls.count && self.onDrop) self.onDrop(urls);
  return urls.count > 0;
}
@end

