@interface QuickPanelController : NSObject <NSTableViewDataSource, NSTableViewDelegate, NSSearchFieldDelegate>
@property (strong) NSWindow *window;
@property (strong) NSSearchField *search;
@property (strong) NSTableView *table;
@property (strong) NSArray<NSDictionary *> *items;
@property (strong) NSArray<NSDictionary *> *filtered;
@property (copy) NSArray<NSDictionary *> *(^dataProvider)(void);
@property (copy) void (^openHandler)(NSDictionary *item);
@property (strong) NSPopUpButton *categoryPopup;
@property (strong) NSPopUpButton *groupPopup;
@property (strong) NSTextField *groupLabel;
@property NSInteger category;
@property (copy) NSString *selectedGroup;
@property (strong) id keyMonitor;
- (void)showPanel;
- (void)hidePanel;
@end

@implementation QuickPanelController
- (void)buildWindow {
  self.window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,560,520) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
  self.window.title = @"快速面板";
  self.window.releasedWhenClosed = NO;
  self.window.restorable = NO;
  self.window.level = NSStatusWindowLevel;
  self.window.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  self.window.backgroundColor = [NSColor colorWithCalibratedWhite:0.98 alpha:1.0];
  NSView *cv = self.window.contentView;
  self.search = [[NSSearchField alloc] initWithFrame:NSMakeRect(16, 470, 528, 34)];
  self.search.placeholderString = @"搜索分组、应用、页面、AI 服务、工具…";
  self.search.delegate = self;
  self.search.target = self; self.search.action = @selector(searchChanged:);
  self.search.sendsSearchStringImmediately = YES;
  [cv addSubview:self.search];
  NSTextField *catLabel = [[NSTextField alloc] initWithFrame:NSMakeRect(16, 434, 38, 18)];
  catLabel.stringValue = @"分类"; catLabel.editable = NO; catLabel.bordered = NO; catLabel.drawsBackground = NO;
  catLabel.font = [NSFont systemFontOfSize:10.5 weight:NSFontWeightSemibold];
  catLabel.textColor = [NSColor secondaryLabelColor];
  [cv addSubview:catLabel];
  self.categoryPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(58, 428, 132, 26) pullsDown:NO];
  [self.categoryPopup addItemsWithTitles:@[@"全部", @"分组 Dock", @"分组应用", @"控制台", @"快捷设置", @"系统", @"工具"]];
  self.categoryPopup.target = self;
  self.categoryPopup.action = @selector(categoryChanged:);
  [cv addSubview:self.categoryPopup];
  self.groupLabel = [[NSTextField alloc] initWithFrame:NSMakeRect(204, 434, 60, 18)];
  self.groupLabel.stringValue = @"分组"; self.groupLabel.editable = NO; self.groupLabel.bordered = NO; self.groupLabel.drawsBackground = NO;
  self.groupLabel.font = [NSFont systemFontOfSize:10.5 weight:NSFontWeightSemibold];
  self.groupLabel.textColor = [NSColor secondaryLabelColor];
  [cv addSubview:self.groupLabel];
  self.groupPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(264, 428, 200, 26) pullsDown:NO];
  self.groupPopup.target = self;
  self.groupPopup.action = @selector(groupChanged:);
  [cv addSubview:self.groupPopup];
  self.groupLabel.hidden = YES;
  self.groupPopup.hidden = YES;
  NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 16, 528, 398)];
  sv.hasVerticalScroller = YES;
  sv.borderType = NSNoBorder;
  sv.drawsBackground = YES;
  sv.backgroundColor = [NSColor whiteColor];
  self.table = [[NSTableView alloc] initWithFrame:sv.contentView.bounds];
  NSTableColumn *col = [[NSTableColumn alloc] initWithIdentifier:@"main"];
  col.width = 510;
  [self.table addTableColumn:col];
  self.table.headerView = nil;
  self.table.rowHeight = 54;
  self.table.intercellSpacing = NSMakeSize(0, 2);
  self.table.dataSource = self;
  self.table.delegate = self;
  self.table.selectionHighlightStyle = NSTableViewSelectionHighlightStyleRegular;
  sv.documentView = self.table;
  [cv addSubview:sv];
  [self.window center];
}

- (void)showPanel {
  if (!self.window) [self buildWindow];
  if (!self.keyMonitor) {
    __weak typeof(self) weakSelf = self;
    self.keyMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e) {
      if (!weakSelf.window.isVisible || e.window != weakSelf.window) return e;
      if (e.keyCode == 53) { [weakSelf hidePanel]; return nil; }
      if (e.keyCode == 36 || e.keyCode == 76) { [weakSelf openSelected]; return nil; }
      if (e.keyCode == 125 || e.keyCode == 126) {
        NSInteger row = weakSelf.table.selectedRow;
        row = (e.keyCode == 125) ? MIN((NSInteger)weakSelf.filtered.count - 1, row + 1) : MAX(0, row - 1);
        if (row < 0) row = 0;
        if (weakSelf.filtered.count) {
          [weakSelf.table selectRowIndexes:[NSIndexSet indexSetWithIndex:row] byExtendingSelection:NO];
          [weakSelf.table scrollRowToVisible:row];
        }
        return nil;
      }
      return e;
    }];
  }
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  self.category = [ud integerForKey:@"centerQuickPanelCategory"];
  if (self.category < 0 || self.category > 6) self.category = 0;
  [self.categoryPopup selectItemAtIndex:self.category];
  self.selectedGroup = [ud stringForKey:@"centerQuickPanelGroup"] ?: @"";
  BOOL showGroup = (self.category == 2);
  self.groupLabel.hidden = !showGroup;
  self.groupPopup.hidden = !showGroup;
  if (self.dataProvider) self.items = self.dataProvider() ?: @[];
  self.search.stringValue = @"";
  [self rebuildGroupPopup];
  [self filterWithQuery:@""];
  [NSApp activateIgnoringOtherApps:YES];
  [self.window makeKeyAndOrderFront:nil];
  [self.window orderFrontRegardless];
  [self.window makeFirstResponder:self.search];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.15 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    [self.window orderFrontRegardless];
    [self.window makeKeyWindow];
  });
}
- (void)hidePanel { [self.window orderOut:nil]; }

- (void)rebuildGroupPopup {
  [self.groupPopup removeAllItems];
  NSMutableArray *groups = [NSMutableArray array];
  for (NSDictionary *it in self.items) {
    if ([it[@"category"] integerValue] != 2) continue;
    NSString *g = it[@"group"] ?: @"";
    if (g.length && ![groups containsObject:g]) [groups addObject:g];
  }
  [groups sortUsingSelector:@selector(localizedCompare:)];
  [self.groupPopup addItemWithTitle:@"全部分组"];
  for (NSString *g in groups) [self.groupPopup addItemWithTitle:g];
  if (self.selectedGroup.length && [groups containsObject:self.selectedGroup]) [self.groupPopup selectItemWithTitle:self.selectedGroup];
  else if (groups.count) { self.selectedGroup = groups.firstObject; [self.groupPopup selectItemWithTitle:self.selectedGroup]; }
  else { self.selectedGroup = @""; [self.groupPopup selectItemAtIndex:0]; }
}

- (void)categoryChanged:(id)sender {
  self.category = self.categoryPopup.indexOfSelectedItem;
  [[NSUserDefaults standardUserDefaults] setInteger:self.category forKey:@"centerQuickPanelCategory"];
  BOOL showGroup = (self.category == 2);
  self.groupLabel.hidden = !showGroup;
  self.groupPopup.hidden = !showGroup;
  [self filterWithQuery:self.search.stringValue];
}

- (void)groupChanged:(id)sender {
  self.selectedGroup = self.groupPopup.indexOfSelectedItem > 0 ? self.groupPopup.titleOfSelectedItem : @"";
  if (self.selectedGroup.length) [[NSUserDefaults standardUserDefaults] setObject:self.selectedGroup forKey:@"centerQuickPanelGroup"];
  [self filterWithQuery:self.search.stringValue];
}

- (void)searchChanged:(id)sender { [self filterWithQuery:self.search.stringValue]; }

- (void)filterWithQuery:(NSString *)q {
  NSString *needle = [q stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]].lowercaseString;
  NSMutableArray *base = [NSMutableArray array];
  for (NSDictionary *it in self.items ?: @[]) {
    if (self.category > 0 && [it[@"category"] integerValue] != self.category) continue;
    if (self.category == 2 && self.selectedGroup.length && ![it[@"group"] isEqualToString:self.selectedGroup]) continue;
    [base addObject:it];
  }
  if (!needle.length) {
    self.filtered = base;
  } else {
    NSMutableArray *out = [NSMutableArray array];
    for (NSDictionary *it in base) {
      NSString *hay = [NSString stringWithFormat:@"%@ %@ %@", it[@"title"] ?: @"", it[@"subtitle"] ?: @"", it[@"type"] ?: @""].lowercaseString;
      if ([hay containsString:needle]) [out addObject:it];
    }
    [out sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
      BOOL ap = [[(a[@"title"] ?: @"") lowercaseString] hasPrefix:needle];
      BOOL bp = [[(b[@"title"] ?: @"") lowercaseString] hasPrefix:needle];
      if (ap != bp) return ap ? NSOrderedAscending : NSOrderedDescending;
      return [a[@"title"] compare:b[@"title"]];
    }];
    self.filtered = out;
  }
  [self.table reloadData];
  if (self.filtered.count) {
    [self.table selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];
    [self.table scrollRowToVisible:0];
  }
}

- (NSInteger)numberOfRowsInTableView:(NSTableView *)tableView { return self.filtered.count; }

- (NSView *)tableView:(NSTableView *)tableView viewForTableColumn:(NSTableColumn *)tableColumn row:(NSInteger)row {
  if (row < 0 || row >= (NSInteger)self.filtered.count) return nil;
  NSDictionary *it = self.filtered[row];
  NSTableCellView *cell = [tableView makeViewWithIdentifier:@"quick" owner:self];
  if (!cell) {
    cell = [[NSTableCellView alloc] initWithFrame:NSMakeRect(0,0,510,52)];
    cell.identifier = @"quick";
    NSImageView *iv = [[NSImageView alloc] initWithFrame:NSMakeRect(10, 11, 30, 30)];
    iv.imageScaling = NSImageScaleProportionallyUpOrDown;
    iv.tag = 100; [cell addSubview:iv];
    NSTextField *t = [[NSTextField alloc] initWithFrame:NSMakeRect(50, 26, 350, 18)];
    t.editable = NO; t.bordered = NO; t.drawsBackground = NO; t.font = [NSFont systemFontOfSize:13 weight:NSFontWeightSemibold]; t.tag = 101; [cell addSubview:t];
    NSTextField *st = [[NSTextField alloc] initWithFrame:NSMakeRect(50, 8, 380, 14)];
    st.editable = NO; st.bordered = NO; st.drawsBackground = NO; st.font = [NSFont systemFontOfSize:10]; st.textColor = [NSColor secondaryLabelColor]; st.tag = 102; [cell addSubview:st];
    NSTextField *badge = [[NSTextField alloc] initWithFrame:NSMakeRect(455, 18, 45, 16)];
    badge.editable = NO; badge.bordered = NO; badge.drawsBackground = NO; badge.font = [NSFont systemFontOfSize:9 weight:NSFontWeightMedium]; badge.textColor = [NSColor tertiaryLabelColor]; badge.alignment = NSTextAlignmentRight; badge.tag = 103; [cell addSubview:badge];
  }
  NSImageView *iv = [cell viewWithTag:100];
  NSTextField *t = [cell viewWithTag:101];
  NSTextField *st = [cell viewWithTag:102];
  NSTextField *badge = [cell viewWithTag:103];
  t.stringValue = it[@"title"] ?: @"";
  st.stringValue = it[@"subtitle"] ?: @"";
  badge.stringValue = it[@"type"] ?: @"";
  NSImage *icon = it[@"icon"];
  if (!icon) icon = [NSImage imageWithSystemSymbolName:@"circle" accessibilityDescription:nil];
  iv.image = icon;
  return cell;
}

- (void)tableViewSelectionDidChange:(NSNotification *)note {}

- (void)openSelected {
  NSInteger row = self.table.selectedRow;
  if (row < 0 || row >= (NSInteger)self.filtered.count) return;
  NSDictionary *it = self.filtered[row];
  [self.window orderOut:nil];
  if (self.openHandler) self.openHandler(it);
}

- (void)control:(NSControl *)control textView:(NSTextView *)textView doCommandBySelector:(SEL)sel {
  NSInteger row = self.table.selectedRow;
  if (sel == @selector(moveDown:)) {
    row = MIN((NSInteger)self.filtered.count - 1, row + 1); if (row < 0) row = 0;
    [self.table selectRowIndexes:[NSIndexSet indexSetWithIndex:row] byExtendingSelection:NO];
    [self.table scrollRowToVisible:row]; return;
  }
  if (sel == @selector(moveUp:)) {
    row = MAX(0, row - 1);
    [self.table selectRowIndexes:[NSIndexSet indexSetWithIndex:row] byExtendingSelection:NO];
    [self.table scrollRowToVisible:row]; return;
  }
  if (sel == @selector(insertNewline:)) { [self openSelected]; return; }
  if (sel == @selector(cancelOperation:)) { [self hidePanel]; return; }
}
@end

