@implementation Controller

- (NSImage *)characterImage:(CGFloat)size {
  NSString *p = [[NSBundle mainBundle] pathForResource:@"AppIcon2" ofType:@"icns"];
  NSImage *img = p ? [[NSImage alloc] initWithContentsOfFile:p] : nil;
  if (!img) img = [NSImage imageNamed:NSImageNameApplicationIcon];
  if (!img) img = [NSImage imageNamed:NSImageNameApplicationIcon];
  img.size = NSMakeSize(size, size);
  img.template = NO;
  return img;
}

- (NSTextField *)label:(NSString *)s size:(CGFloat)sz bold:(BOOL)b color:(NSColor *)c {
  NSTextField *l = [NSTextField labelWithString:s];
  l.font = DLDisplayFont(sz, b);
  if (c) l.textColor = c;
  return l;
}

- (void)addLocalAIServiceAccessoryToWindow:(NSWindow *)window {
  if(!window)return;
  if(objc_getAssociatedObject(window, "DLLocalAIButton")) return;
  NSButton *close=[window standardWindowButton:NSWindowCloseButton];
  NSView *titlebar=close.superview ?: window.contentView.superview;
  if(!titlebar) return;
  NSButton *b=[NSButton buttonWithTitle:@"本地 AI 服务" target:self action:@selector(openLocalAIServices:)];
  b.bezelStyle=NSBezelStyleRounded;
  b.controlSize=NSControlSizeSmall;
  b.font=[NSFont systemFontOfSize:10 weight:NSFontWeightMedium];
  b.image=[NSImage imageWithSystemSymbolName:@"server.rack" accessibilityDescription:@"本地 AI 服务"];
  b.imagePosition=NSImageLeft;
  CGFloat w=142, h=24, rightGap=52;
  CGFloat x=MAX(4,titlebar.bounds.size.width-w-rightGap);
  CGFloat y=close ? close.frame.origin.y + (close.frame.size.height-h)/2.0 : MAX(2,titlebar.bounds.size.height-h-2);
  b.frame=NSMakeRect(x,y,w,h);
  b.autoresizingMask=NSViewMinXMargin|NSViewMinYMargin;
  b.toolTip=@"打开本地 AI 服务：Ollama / ComfyUI / Whisper";
  [titlebar addSubview:b];
  objc_setAssociatedObject(window, "DLLocalAIButton", @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
}

- (void)runSelfTest {
  __block int failed = 0;
  void (^check)(BOOL, NSString *) = ^(BOOL ok, NSString *name) {
    fprintf(stderr, "%s %s\n", ok ? "PASS" : "FAIL", name.UTF8String);
    if (!ok) failed = 1;
  };
  for (NSInteger i = 0; i < 6; i++) check([self viewForSection:i] != nil, [NSString stringWithFormat:@"section %ld", (long)i]);
  [self refreshGroups];
  check(self.groups.count >= 7, @"groups loaded");
  self.groupsSearch.stringValue = @"工具";
  [self groupsSearchChanged:nil];
  check(self.groupsFiltered.count == 1, @"exact group search");
  self.groupsSearch.stringValue = @"";
  self.groupsFilter = nil;
  [self refreshGroups];
  NSDictionary *preset = [self aiPresetForName:@"Anthropic Claude"];
  check([preset[@"url"] containsString:@"anthropic"], @"AI preset exact name");
  preset = [self aiPresetForName:@"千问"];
  check([preset[@"name"] containsString:@"通义千问"], @"AI preset alias");
  [self rebuildAIDisplay];
  check(self.aiVisibleEntries.count <= 8, @"AI rows per page");
  check([self isProtectedUserPath:[NSHomeDirectory() stringByAppendingPathComponent:@"Documents"]], @"protected path filter");
  check([[self aiCategoryForEntry:@{@"name": @"Kling", @"note": @"视频生成"}] isEqualToString:@"视频"], @"AI category inference");
  fprintf(stderr, failed ? "SELFTEST FAILED\n" : "SELFTEST OK\n");
  exit(failed);
}

- (NSString *)runOsascript:(NSString *)script {
  NSTask *task = [[NSTask alloc] init];
  task.launchPath = @"/usr/bin/osascript";
  task.arguments = @[@"-e", script];
  NSPipe *pipe = [NSPipe pipe];
  task.standardOutput = pipe;
  task.standardError = [NSPipe pipe];
  @try { [task launch]; } @catch (NSException *e) { return nil; }
  NSData *data = [pipe.fileHandleForReading readDataToEndOfFile];
  [task waitUntilExit];
  if (task.terminationStatus != 0) return nil;
  return [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
}

- (NSMenu *)applicationDockMenu:(NSApplication *)sender {
  NSMenu *menu = [[NSMenu alloc] initWithTitle:@"DockLaunchers"];
  [menu addItemWithTitle:@"打开环形菜单" action:@selector(togglePopover:) keyEquivalent:@""].target = self;
  [menu addItemWithTitle:@"打开控制台" action:@selector(showWindow:) keyEquivalent:@""].target = self;
  [menu addItem:[NSMenuItem separatorItem]];
  [menu addItemWithTitle:@"退出 DockLaunchers" action:@selector(quitApp:) keyEquivalent:@""].target = self;
  return menu;
}

- (BOOL)silentStartupEnabled {
  id v = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerSilentStartup"];
  return v ? [v boolValue] : YES;
}

- (void)applicationWillFinishLaunching:(NSNotification *)note {
  if (!getenv("DOCKLAUNCHERS_CENTER_SELFTEST")) {
    [NSApp setActivationPolicy:[self silentStartupEnabled] ? NSApplicationActivationPolicyAccessory : NSApplicationActivationPolicyRegular];
  }
}

