    });
  }
  if (getenv("DOCKLAUNCHERS_CENTER_TEST_BACKUP")) {
    NSString *n = [NSString stringWithUTF8String:getenv("DOCKLAUNCHERS_CENTER_TEST_BACKUP")];
    [self backupGroupNames:@[n]];
    exit(0);
  }
  if (getenv("DOCKLAUNCHERS_CENTER_TEST_RESTORE")) {
    [self restoreGroupsClicked:nil];
    exit(0);
  }
  self.timer = [NSTimer scheduledTimerWithTimeInterval:self.sampleSeconds target:self selector:@selector(sample) userInfo:nil repeats:YES];
  [self sample];
  id autoSyncVal = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerAutoSync"];
  BOOL autoSync = autoSyncVal ? [autoSyncVal boolValue] : YES;
  if (autoSync) [self startAutoSyncTimer];
  if ([[NSUserDefaults standardUserDefaults] boolForKey:@"centerFileActivity"]) [self startActivityRecorder];
  if ([self silentStartupEnabled]) [NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];
  else [self showWindow:nil];
  if (getenv("DOCKLAUNCHERS_CENTER_SECTION")) {
    [self showSection:atoi(getenv("DOCKLAUNCHERS_CENTER_SECTION"))];
  }
  if (getenv("DOCKLAUNCHERS_CENTER_SEARCH")) {
    [self showSection:4];
    self.uninstallSearch.stringValue = [NSString stringWithUTF8String:getenv("DOCKLAUNCHERS_CENTER_SEARCH")];
    [self reloadUninstallData];
  }
  if (getenv("DOCKLAUNCHERS_CENTER_GROUP")) {
    [self showSection:4];
    self.uninstallScope = 1;
    self.uninstallScopeCtl.selectedSegment = 1;
    [self refreshUninstallGroupPopup];
    NSString *g = [NSString stringWithUTF8String:getenv("DOCKLAUNCHERS_CENTER_GROUP")];
    if ([self.uninstallGroupPopup itemWithTitle:g]) [self.uninstallGroupPopup selectItemWithTitle:g];
    [self reloadUninstallData];
  }
  if (getenv("DOCKLAUNCHERS_CENTER_POPOVER")) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
      [self togglePopover:nil];
    });
  }
}

- (void)toggleSidebar:(id)sender {
  BOOL collapse = !self.sidebarCollapsed;
  self.sidebarCollapsed = collapse;
  __weak typeof(self) weakSelf = self;
  NSArray *nav = @[self.sideLive, self.sideGroups, self.sideAI, self.sideDisk, self.sideUninstall, self.sideSettings];
  NSArray *navTitles = @[@"实时数据", @"Dock 分组", @"AI 管理", @"磁盘分析", @"应用卸载", @"设置"];
  for (NSInteger i = 0; i < nav.count; i++) {
    NSButton *b = nav[i];
    if (collapse) {
      b.title = @"";
      b.imagePosition = NSImageOnly;
      b.alignment = NSTextAlignmentCenter;
      b.frame = NSMakeRect(4, 523 - i * 92.4, 36, 36);
    } else {
      b.title = navTitles[i];
      b.imagePosition = NSImageLeft;
      b.alignment = NSTextAlignmentLeft;
      b.frame = NSMakeRect(14, 521 - i * 92.4, 212, 40);
    }
  }
  if (collapse) {
    self.sidebarToggle.title = @"";
    self.sidebarToggle.image = [NSImage imageWithSystemSymbolName:@"sidebar.right" accessibilityDescription:@"展开侧边栏"];
    self.sidebarToggle.imagePosition = NSImageOnly;
    self.sidebarToggle.alignment = NSTextAlignmentCenter;
    self.sidebarToggle.persistentHighlight = YES;
    [self.sidebarToggle applyColor:[NSColor systemBrownColor] textColor:[NSColor whiteColor]];
  } else {
    for (NSView *v in self.sideView.subviews) v.hidden = NO;
    self.sidebarToggle.title = @"收起侧边栏";
    self.sidebarToggle.image = [NSImage imageWithSystemSymbolName:@"sidebar.left" accessibilityDescription:@"收起侧边栏"];
    self.sidebarToggle.imagePosition = NSImageLeft;
    self.sidebarToggle.alignment = NSTextAlignmentLeft;
    self.sidebarToggle.persistentHighlight = NO;
    [self.sidebarToggle applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
  }
  [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) {
    ctx.duration = 0.22;
    NSRect win = weakSelf.window.contentView.bounds;
    weakSelf.sideView.animator.frame = NSMakeRect(0, 0, collapse ? 44 : 240, win.size.height);
    weakSelf.contentScroll.animator.frame = NSMakeRect(collapse ? 44 : 240, 0, win.size.width - (collapse ? 44 : 240), win.size.height);
    weakSelf.sidebarToggle.animator.frame = collapse ? NSMakeRect(6, 20, 32, 32) : NSMakeRect(14, 20, 212, 36);
  } completionHandler:^{
    if (collapse) {
      for (NSView *v in weakSelf.sideView.subviews) {
        if (![v isKindOfClass:[NSButton class]]) v.hidden = YES;
      }
    }
    [weakSelf layoutPageView:weakSelf.content.subviews.firstObject];
  }];
}

- (void)layoutCenterTitle {
  NSView *frameView = self.window.contentView.superview;
  if (!frameView || !self.centerTitleLabel) return;
  CGFloat w = frameView.bounds.size.width;
  CGFloat h = frameView.bounds.size.height;
  self.centerTitleLabel.frame = NSMakeRect((w - 440)/2.0, h - 30, 440, 24);
}
- (void)layoutPageView:(NSView *)v {
  if (!v) return;
  CGFloat aw = MAX(1, self.contentScroll.contentView.bounds.size.width);
  CGFloat ah = MAX(1, self.contentScroll.contentView.bounds.size.height);
  CGFloat zoom = self.uiZoom > 0 ? self.uiZoom : 1.0;
  // 以窗口宽度为主进行等比缩放：拉宽时整体数据同步放大，拉窄时缩小
  CGFloat scale = (aw / 750.0) * zoom;
  CGFloat w = 750.0 * scale, h = 660.0 * scale;
  CGFloat docW = MAX(aw, w + 24), docH = MAX(ah, h + 24);
  self.content.frame = NSMakeRect(0, 0, docW, docH);
  v.frame = NSMakeRect((docW - w) / 2.0, (docH - h) / 2.0, w, h);
  v.bounds = NSMakeRect(0, 0, 750, 660);
  CGFloat maxY = MAX(0, docH - self.contentScroll.contentView.bounds.size.height);
  [self.contentScroll.contentView scrollToPoint:NSMakePoint(0, maxY)];
  [self.contentScroll reflectScrolledClipView:self.contentScroll.contentView];
}

- (void)applyWindowChrome:(NSWindow *)w {
  if (!w) return;
  if ([w isKindOfClass:[NSWindow class]]) w.tabbingMode = NSWindowTabbingModeDisallowed;
  if ([w isKindOfClass:[NSPanel class]]) return;
  if (w.sheetParent) return;
  if (!(w.styleMask & NSWindowStyleMaskTitled) || !(w.styleMask & NSWindowStyleMaskClosable)) return;
  if (objc_getAssociatedObject(w, "DLCenterChrome")) return;
  objc_setAssociatedObject(w, "DLCenterChrome", @YES, OBJC_ASSOCIATION_RETAIN_NONATOMIC);
  objc_setAssociatedObject(w, "DLCenterBaseLevel", @(w.level), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
  if (!self.pinnedWindows) self.pinnedWindows = [NSMutableSet set];
  NSButton *close = [w standardWindowButton:NSWindowCloseButton];
  NSButton *mini = [w standardWindowButton:NSWindowMiniaturizeButton];
  NSButton *zoom = [w standardWindowButton:NSWindowZoomButton];
  if (mini) mini.hidden = YES;
  if (zoom) zoom.hidden = YES;
  if (close) close.enabled = YES;
  if (!w.delegate) w.delegate = self;
  NSView *titlebar = close.superview ?: w.contentView.superview;
  if (!titlebar) return;
  NSButton *pin = [NSButton buttonWithImage:[NSImage imageWithSystemSymbolName:@"pin.fill" accessibilityDescription:@"钉住"] target:self action:@selector(toggleWindowPin:)];
  pin.bordered = NO;
  pin.imageScaling = NSImageScaleProportionallyDown;
  pin.imagePosition = NSImageOnly;
  pin.contentTintColor = [NSColor systemOrangeColor];
  pin.toolTip = @"钉住窗口";
  pin.wantsLayer = YES;
  pin.layer.cornerRadius = 8;
  pin.layer.backgroundColor = [[NSColor systemOrangeColor] colorWithAlphaComponent:0.16].CGColor;
  pin.layer.borderWidth = 1;
  pin.layer.borderColor = [[NSColor systemOrangeColor] colorWithAlphaComponent:0.65].CGColor;
  pin.layer.shadowColor = [NSColor systemOrangeColor].CGColor;
  pin.layer.shadowOpacity = 0.28;
  pin.layer.shadowRadius = 4;
  pin.layer.shadowOffset = CGSizeMake(0, -1);
  CGFloat pinSize = 30;
  CGFloat px = titlebar.bounds.size.width - pinSize - 12;
  CGFloat py = close ? close.frame.origin.y - (pinSize - close.frame.size.height)/2.0 : MAX(4, titlebar.bounds.size.height - pinSize - 2);
  pin.frame = NSMakeRect(px, py, pinSize, pinSize);
  pin.autoresizingMask = NSViewMinXMargin | NSViewMinYMargin;
  [titlebar addSubview:pin];
}

- (void)toggleWindowPin:(NSButton *)sender {
  NSWindow *w = sender.window;
  if (!w) return;
  if (!self.pinnedWindows) self.pinnedWindows = [NSMutableSet set];
  NSValue *key = [NSValue valueWithNonretainedObject:w];
  BOOL pinned = [self.pinnedWindows containsObject:key];
  BOOL nowPinned = !pinned;
  if (nowPinned) {
    [self.pinnedWindows addObject:key];
    w.level = NSNormalWindowLevel;
    NSButton *cl0 = [w standardWindowButton:NSWindowCloseButton];
    if (cl0) { cl0.hidden = NO; cl0.enabled = YES; }
    sender.image = [NSImage imageWithSystemSymbolName:@"pin.fill" accessibilityDescription:@"已钉住"];
    sender.contentTintColor = [NSColor whiteColor];
    sender.layer.backgroundColor = [NSColor systemOrangeColor].CGColor;
    sender.layer.borderColor = [NSColor systemOrangeColor].CGColor;
    sender.layer.shadowOpacity = 0.5;
    sender.toolTip = @"已钉在桌面（不置顶），点击取消";
  } else {
    [self.pinnedWindows removeObject:key];
    NSInteger base = [objc_getAssociatedObject(w, "DLCenterBaseLevel") integerValue];
    w.level = base;
    sender.image = [NSImage imageWithSystemSymbolName:@"pin.fill" accessibilityDescription:@"钉住"];
    sender.contentTintColor = [NSColor systemOrangeColor];
    sender.layer.backgroundColor = [[NSColor systemOrangeColor] colorWithAlphaComponent:0.16].CGColor;
    sender.layer.borderColor = [[NSColor systemOrangeColor] colorWithAlphaComponent:0.65].CGColor;
    sender.layer.shadowOpacity = 0.28;
    sender.toolTip = @"钉住窗口";
  }
  NSButton *close = [w standardWindowButton:NSWindowCloseButton];
  if (close) { close.hidden = NO; close.enabled = YES; }
  [self showToast:(nowPinned ? @"窗口已钉在桌面，不置顶，可正常关闭" : @"窗口已取消钉住")];
}

- (BOOL)windowShouldClose:(NSWindow *)sender {
  if (sender == self.shelfWindow) {
    [self.shelfPruneTimer invalidate]; self.shelfPruneTimer = nil;
    return YES;
  }
  if (sender == self.window) {
    [sender orderOut:nil];
    return NO;
  }
  return YES;
}

- (void)dlWindowBecameKey:(NSNotification *)note {
  if ([note.object isKindOfClass:[NSWindow class]]) [self applyWindowChrome:note.object];
  if (note.object == self.aiAssistantWindow && self.aiAssistantWindow.isVisible) [self reloadAIAssistantServices];
  if (note.object == self.translationWindow && self.translationWindow.isVisible) [self reloadTranslationProviders];
}

- (void)windowDidMove:(NSNotification *)notification {
  if (notification.object == self.captureCameraWindow) {
    [[NSUserDefaults standardUserDefaults] setObject:NSStringFromPoint(self.captureCameraWindow.frame.origin) forKey:@"centerCaptureCameraOrigin"];
    return;
  }
  NSWindow *w = self.window;
  if (!w || w.isZoomed) return;
  NSRect vis = w.screen.visibleFrame;
  NSRect f = w.frame;
  CGFloat maxTop = NSMaxY(vis) - 2;
  if (NSMaxY(f) > maxTop) {
    f.origin.y = maxTop - f.size.height;
    if (f.origin.y < NSMinY(vis)) f.origin.y = NSMinY(vis);
    [w setFrame:f display:YES];
  }
}

- (void)windowDidResize:(NSNotification *)notification {
  if (notification.object == self.shelfWindow) { [self layoutShelfWindow]; return; }
  [self layoutCenterTitle];
  [self layoutPageView:self.content.subviews.firstObject];
  [self updateDiskGalleryLayout];
}

static OSStatus TranslationHotKeyHandler(EventHandlerCallRef nextHandler, EventRef event, void *userData) {
  Controller *c = (__bridge Controller *)userData;
  EventHotKeyID hk = {0, 0};
  GetEventParameter(event, kEventParamDirectObject, typeEventHotKeyID, NULL, sizeof(hk), NULL, &hk);
  if (hk.id == 1) {
    [c beginScreenshotTranslation];
  } else if (hk.id == 2) [c translateSelectedText];
  else if (hk.id == 3) [c translateCurrentText];
  else if (hk.id == 4) [c showQuickPanel];
  else if (hk.id == 5) [c showAppSearch:nil];
  else if (hk.id == 6) [c showClipboardWindow:nil];
  else if (hk.id == 7) { [c showWindow:nil]; [c showSection:0]; }
  else if (hk.id == 8) [c quickScreenshot:nil];
  else if (hk.id == 9) [c quickRecord:nil];
  else if (hk.id >= 3000) [c performAllGlobalActionID:hk.id];
  else if (hk.id >= 100) [c openGroupByHotkeyID:hk.id];
  return noErr;
}

- (BOOL)registerHotKeyForAction:(NSInteger)action code:(UInt32)code modifiers:(UInt32)mods display:(NSString *)display {
  EventHotKeyRef old = action == 0 ? self.translationHotKey : (action == 1 ? self.selectionHotKey : (action == 2 ? self.translateHotKey : (action == 3 ? self.appSearchHotKey : (action == 4 ? self.quickPanelHotKey : (action == 5 ? self.clipboardHotKey : (action == 6 ? self.consoleHotKey : (action == 7 ? self.screenshotHotKey : self.recordHotKey)))))));
  if (old) UnregisterEventHotKey(old);
  NSArray *hotIDs = @[@1,@2,@3,@5,@4,@6,@7,@8,@9];
  if (action < 0 || action >= (NSInteger)hotIDs.count) return NO;
  EventHotKeyID hid = {'DLTR', (UInt32)[hotIDs[action] unsignedIntValue]};
  EventHotKeyRef ref = NULL;
  OSStatus st = RegisterEventHotKey(code, mods, hid, GetApplicationEventTarget(), 0, &ref);
  if (st != noErr) return NO;
  if (action == 0) { self.translationHotKey = ref; self.shotKeyCode = code; self.shotModifiers = mods; self.shotShortcutDisplay = display; }
  else if (action == 1) { self.selectionHotKey = ref; self.selectionKeyCode = code; self.selectionModifiers = mods; self.selectionShortcutDisplay = display; }
  else if (action == 2) { self.translateHotKey = ref; self.translateKeyCode = code; self.translateModifiers = mods; self.translateShortcutDisplay = display; }
  else if (action == 3) { self.appSearchHotKey = ref; self.appSearchKeyCode = code; self.appSearchModifiers = mods; self.appSearchShortcutDisplay = display; }
  else if (action == 4) { self.quickPanelHotKey = ref; self.quickPanelKeyCode = code; self.quickPanelModifiers = mods; self.quickPanelShortcutDisplay = display; }
  else if (action == 5) { self.clipboardHotKey = ref; self.clipboardKeyCode = code; self.clipboardModifiers = mods; self.clipboardShortcutDisplay = display; }
  else if (action == 6) { self.consoleHotKey = ref; self.consoleKeyCode = code; self.consoleModifiers = mods; self.consoleShortcutDisplay = display; }
  else if (action == 7) { self.screenshotHotKey = ref; self.screenshotKeyCode = code; self.screenshotModifiers = mods; self.screenshotShortcutDisplay = display; }
  else { self.recordHotKey = ref; self.recordKeyCode = code; self.recordModifiers = mods; self.recordShortcutDisplay = display; }
  NSArray *kc = @[@"centerShotKeyCode", @"centerSelectKeyCode", @"centerTranslateKeyCode", @"centerAppSearchKeyCode", @"centerQuickPanelKeyCode", @"centerClipboardKeyCode", @"centerConsoleKeyCode", @"centerScreenshotKeyCode", @"centerRecordKeyCode"];
  NSArray *km = @[@"centerShotModifiers", @"centerSelectModifiers", @"centerTranslateModifiers", @"centerAppSearchModifiers", @"centerQuickPanelModifiers", @"centerClipboardModifiers", @"centerConsoleModifiers", @"centerScreenshotModifiers", @"centerRecordModifiers"];
  NSArray *kd = @[@"centerShotKeyDisplay", @"centerSelectKeyDisplay", @"centerTranslateKeyDisplay", @"centerAppSearchKeyDisplay", @"centerQuickPanelKeyDisplay", @"centerClipboardKeyDisplay", @"centerConsoleKeyDisplay", @"centerScreenshotKeyDisplay", @"centerRecordKeyDisplay"];
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  [ud setInteger:code forKey:kc[action]];
  [ud setInteger:mods forKey:km[action]];
  [ud setObject:display forKey:kd[action]];
  [self refreshShortcutButtons];
  return YES;
}

- (void)installTranslationHotKey {
  EventTypeSpec es = {kEventClassKeyboard, kEventHotKeyPressed};
  InstallEventHandler(GetApplicationEventTarget(), TranslationHotKeyHandler, 1, &es, (__bridge void *)self, &_translationHotKeyHandler);
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  self.shotKeyCode = (UInt32)[ud integerForKey:@"centerShotKeyCode"];
  self.shotModifiers = (UInt32)[ud integerForKey:@"centerShotModifiers"];
  self.shotShortcutDisplay = [ud stringForKey:@"centerShotKeyDisplay"];
  if (!self.shotShortcutDisplay.length) { self.shotKeyCode = kVK_ANSI_T; self.shotModifiers = controlKey | optionKey; self.shotShortcutDisplay = @"⌃⌥T"; }
  self.selectionKeyCode = (UInt32)[ud integerForKey:@"centerSelectKeyCode"];
  self.selectionModifiers = (UInt32)[ud integerForKey:@"centerSelectModifiers"];
  self.selectionShortcutDisplay = [ud stringForKey:@"centerSelectKeyDisplay"];
  if (!self.selectionShortcutDisplay.length) { self.selectionKeyCode = kVK_ANSI_D; self.selectionModifiers = controlKey | optionKey; self.selectionShortcutDisplay = @"⌃⌥D"; }
  self.translateKeyCode = (UInt32)[ud integerForKey:@"centerTranslateKeyCode"];
  self.translateModifiers = (UInt32)[ud integerForKey:@"centerTranslateModifiers"];
  self.translateShortcutDisplay = [ud stringForKey:@"centerTranslateKeyDisplay"];
  if (!self.translateShortcutDisplay.length) { self.translateKeyCode = kVK_Return; self.translateModifiers = controlKey | optionKey; self.translateShortcutDisplay = @"⌃⌥↩"; }
  if(![self.shotShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:0 code:self.shotKeyCode modifiers:self.shotModifiers display:self.shotShortcutDisplay];
  if(![self.selectionShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:1 code:self.selectionKeyCode modifiers:self.selectionModifiers display:self.selectionShortcutDisplay];
  if(![self.translateShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:2 code:self.translateKeyCode modifiers:self.translateModifiers display:self.translateShortcutDisplay];
  self.appSearchKeyCode = (UInt32)[ud integerForKey:@"centerAppSearchKeyCode"];
  self.appSearchModifiers = (UInt32)[ud integerForKey:@"centerAppSearchModifiers"];
  self.appSearchShortcutDisplay = [ud stringForKey:@"centerAppSearchKeyDisplay"];
  if (!self.appSearchShortcutDisplay.length) { self.appSearchKeyCode = kVK_Space; self.appSearchModifiers = controlKey | optionKey; self.appSearchShortcutDisplay = @"⌃⌥Space"; }
  if(![self.appSearchShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:3 code:self.appSearchKeyCode modifiers:self.appSearchModifiers display:self.appSearchShortcutDisplay];
  self.quickPanelKeyCode = (UInt32)[ud integerForKey:@"centerQuickPanelKeyCode"];
  self.quickPanelModifiers = (UInt32)[ud integerForKey:@"centerQuickPanelModifiers"];
  self.quickPanelShortcutDisplay = [ud stringForKey:@"centerQuickPanelKeyDisplay"];
  if (!self.quickPanelShortcutDisplay.length) { self.quickPanelKeyCode = kVK_ANSI_K; self.quickPanelModifiers = cmdKey; self.quickPanelShortcutDisplay = @"⌘K"; }
  if(![self.quickPanelShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:4 code:self.quickPanelKeyCode modifiers:self.quickPanelModifiers display:self.quickPanelShortcutDisplay];
  self.clipboardKeyCode = (UInt32)[ud integerForKey:@"centerClipboardKeyCode"];
  self.clipboardModifiers = (UInt32)[ud integerForKey:@"centerClipboardModifiers"];
  self.clipboardShortcutDisplay = [ud stringForKey:@"centerClipboardKeyDisplay"];
  if (!self.clipboardShortcutDisplay.length) { self.clipboardKeyCode = kVK_ANSI_V; self.clipboardModifiers = controlKey | optionKey; self.clipboardShortcutDisplay = @"⌃⌥V"; }
  if(![self.clipboardShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:5 code:self.clipboardKeyCode modifiers:self.clipboardModifiers display:self.clipboardShortcutDisplay];
  self.consoleKeyCode = (UInt32)[ud integerForKey:@"centerConsoleKeyCode"];
  self.consoleModifiers = (UInt32)[ud integerForKey:@"centerConsoleModifiers"];
  self.consoleShortcutDisplay = [ud stringForKey:@"centerConsoleKeyDisplay"];
  if (!self.consoleShortcutDisplay.length) { self.consoleKeyCode = kVK_ANSI_C; self.consoleModifiers = controlKey | optionKey; self.consoleShortcutDisplay = @"⌃⌥C"; }
  if(![self.consoleShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:6 code:self.consoleKeyCode modifiers:self.consoleModifiers display:self.consoleShortcutDisplay];
  self.screenshotKeyCode = (UInt32)[ud integerForKey:@"centerScreenshotKeyCode"];
  self.screenshotModifiers = (UInt32)[ud integerForKey:@"centerScreenshotModifiers"];
  self.screenshotShortcutDisplay = [ud stringForKey:@"centerScreenshotKeyDisplay"];
  if (!self.screenshotShortcutDisplay.length) { self.screenshotKeyCode = kVK_ANSI_S; self.screenshotModifiers = controlKey | optionKey; self.screenshotShortcutDisplay = @"⌃⌥S"; }
  if(![self.screenshotShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:7 code:self.screenshotKeyCode modifiers:self.screenshotModifiers display:self.screenshotShortcutDisplay];
  self.recordKeyCode = (UInt32)[ud integerForKey:@"centerRecordKeyCode"];
  self.recordModifiers = (UInt32)[ud integerForKey:@"centerRecordModifiers"];
  self.recordShortcutDisplay = [ud stringForKey:@"centerRecordKeyDisplay"];
  if (!self.recordShortcutDisplay.length) { self.recordKeyCode = kVK_ANSI_R; self.recordModifiers = controlKey | optionKey; self.recordShortcutDisplay = @"⌃⌥R"; }
  if(![self.recordShortcutDisplay isEqualToString:@"未设置"]) [self registerHotKeyForAction:8 code:self.recordKeyCode modifiers:self.recordModifiers display:self.recordShortcutDisplay];
}

- (NSString *)shortcutDisplayForAction:(NSInteger)action {
  if (action == 0) return self.shotShortcutDisplay;
  if (action == 1) return self.selectionShortcutDisplay;
  if (action == 2) return self.translateShortcutDisplay;
  if (action == 3) return self.appSearchShortcutDisplay;
  if (action == 4) return self.quickPanelShortcutDisplay;
  if (action == 5) return self.clipboardShortcutDisplay;
  if (action == 6) return self.consoleShortcutDisplay;
  if (action == 7) return self.screenshotShortcutDisplay;
  return self.recordShortcutDisplay;
}

- (void)refreshShortcutButtons {
  for (ColorHoverButton *b in self.shortcutButtons) {
    if (b.tag >= 0 && b.tag <= 8) b.title = [self shortcutDisplayForAction:b.tag];
  }
}

- (void)setupMainMenu {
  NSMenu *mainMenu = [[NSMenu alloc] initWithTitle:@"Main"];
  NSMenuItem *appItem = [[NSMenuItem alloc] initWithTitle:@"DockLaunchers" action:nil keyEquivalent:@""];
  NSMenu *appMenu = [[NSMenu alloc] initWithTitle:@"DockLaunchers"];
  [appMenu addItemWithTitle:@"检查更新…" action:@selector(checkForUpdates:) keyEquivalent:@""].target = self;
  [appMenu addItem:[NSMenuItem separatorItem]];
  [appMenu addItemWithTitle:@"退出 DockLaunchers" action:@selector(quitApp:) keyEquivalent:@"q"];
  appItem.submenu = appMenu;
  [mainMenu addItem:appItem];
  NSMenuItem *editItem = [[NSMenuItem alloc] initWithTitle:@"编辑" action:nil keyEquivalent:@""];
  NSMenu *editMenu = [[NSMenu alloc] initWithTitle:@"编辑"];
  [editMenu addItemWithTitle:@"撤销" action:@selector(undo:) keyEquivalent:@"z"];
  [editMenu addItem:[NSMenuItem separatorItem]];
  [editMenu addItemWithTitle:@"剪切" action:@selector(cut:) keyEquivalent:@"x"];
  [editMenu addItemWithTitle:@"复制" action:@selector(copy:) keyEquivalent:@"c"];
  [editMenu addItemWithTitle:@"粘贴" action:@selector(paste:) keyEquivalent:@"v"];
  [editMenu addItemWithTitle:@"全选" action:@selector(selectAll:) keyEquivalent:@"a"];
  editItem.submenu = editMenu;
  [mainMenu addItem:editItem];
  NSApp.mainMenu = mainMenu;
}

- (void)buildWindow {
  self.window = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,990,660)
                                            styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskMiniaturizable|NSWindowStyleMaskResizable)
                                              backing:NSBackingStoreBuffered defer:NO];
  self.window.title = @"DockLaunchers 控制台";
  self.window.titleVisibility = NSWindowTitleHidden;
  self.window.delegate = self;
  self.window.collectionBehavior = NSWindowCollectionBehaviorFullScreenNone;
  self.centerTitleLabel = [self label:[NSString stringWithFormat:@"DockLaunchers 控制台  v%@", [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"] ?: @"1.0"] size:16 bold:YES color:[NSColor systemOrangeColor]];
  self.centerTitleLabel.alignment = NSTextAlignmentCenter;
  [self.window.contentView.superview addSubview:self.centerTitleLabel];
  [self layoutCenterTitle];
  self.window.styleMask &= ~NSWindowStyleMaskResizable;
  self.window.contentMinSize = NSMakeSize(990, 660);
  self.window.contentMaxSize = NSMakeSize(990, 660);
