// ---------------- Dock 条目 ----------------
- (void)repairDockEntriesClicked:(id)sender {
  [self ensureGroupDockEntries];
  self.dockPersistentDirty=YES;
  [self killDock];
  [self refreshGroups];
  [self showToast:@"已重新写入分组 Dock 图标"];
}

- (void)ensureGroupDockEntries {
  NSString *dir = GroupDir();
  NSFileManager *fm = [NSFileManager defaultManager];
  NSArray *files = [fm contentsOfDirectoryAtPath:dir error:NULL] ?: @[];
  for (NSString *f in files) {
    if (![f hasSuffix:@".app"]) continue;
    NSString *path = [dir stringByAppendingPathComponent:f];
    if (![fm fileExistsAtPath:[path stringByAppendingPathComponent:@"Contents/Info.plist"]]) continue;
    NSDictionary *info = [NSDictionary dictionaryWithContentsOfFile:[path stringByAppendingPathComponent:@"Contents/Info.plist"]] ?: @{};
    NSString *bid = info[@"CFBundleIdentifier"] ?: @"";
    if (![bid hasPrefix:@"com.docklaunchers."]) continue;
    if ([bid isEqualToString:@"com.docklaunchers.center"]) continue;
    NSString *label = info[@"CFBundleDisplayName"] ?: info[@"CFBundleName"] ?: [[f stringByDeletingPathExtension] stringByReplacingOccurrencesOfString:@"DockLaunchers" withString:@""];
    [self addDockEntry:path label:label];
  }
}

- (void)repairGroupDockIconsIfNeeded {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSInteger version = 2;
  if ([ud integerForKey:@"centerGroupIconsRepairVersion"] >= version) return;
  NSDictionary *map = @{@"工具": @"工具组", @"工作": @"工作组", @"聊天": @"聊天组", @"外网": @"外网组", @"影音": @"影音组", @"Ai": @"Ai组", @"AI": @"Ai组", @"Docker": @"Docker组"};
  NSString *dir = [GroupDir() stringByAppendingPathComponent:@"DockLaunchers"];
  NSFileManager *fm = [NSFileManager defaultManager];
  NSArray *files = [fm contentsOfDirectoryAtPath:dir error:NULL] ?: @[];
  BOOL changed = NO;
  for (NSString *f in files) {
    if (![f hasSuffix:@".app"]) continue;
    NSString *app = [dir stringByAppendingPathComponent:f];
    NSString *plist = [app stringByAppendingPathComponent:@"Contents/Info.plist"];
    NSMutableDictionary *info = [[NSDictionary dictionaryWithContentsOfFile:plist] mutableCopy];
    if (!info) continue;
    NSString *label = info[@"CFBundleDisplayName"] ?: info[@"CFBundleName"] ?: [f stringByDeletingPathExtension];
    NSString *iconName = map[label];
    if (!iconName) continue;
    NSString *src = [[NSBundle mainBundle] pathForResource:iconName ofType:@"icns" inDirectory:@"GroupIcons"];
    if (!src) continue;
    NSString *res = [app stringByAppendingPathComponent:@"Contents/Resources"];
    [fm createDirectoryAtPath:res withIntermediateDirectories:YES attributes:nil error:NULL];
    NSString *dst = [res stringByAppendingPathComponent:@"AppIcon.icns"];
    NSData *want = [NSData dataWithContentsOfFile:src];
    NSData *have = [NSData dataWithContentsOfFile:dst];
    if (!want || [want isEqualToData:have]) continue;
    [fm removeItemAtPath:dst error:NULL];
    if (![fm copyItemAtPath:src toPath:dst error:NULL]) continue;
    info[@"CFBundleIconFile"] = @"AppIcon";
    [info writeToFile:plist atomically:YES];
    NSTask *sign = [[NSTask alloc] init];
    sign.launchPath = @"/usr/bin/codesign";
    sign.arguments = @[@"--force", @"--deep", @"--sign", @"-", app];
    @try { [sign launch]; [sign waitUntilExit]; } @catch (NSException *e) {}
    NSTask *reg = [[NSTask alloc] init];
    reg.launchPath = @"/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister";
    reg.arguments = @[@"-f", app];
    @try { [reg launch]; [reg waitUntilExit]; } @catch (NSException *e) {}
    changed = YES;
  }
  [ud setInteger:version forKey:@"centerGroupIconsRepairVersion"];
  [ud synchronize];
  if (changed) [self hardRestartDock];
}

- (void)logDockState:(NSString *)tag path:(NSString *)path {
  CFArrayRef raw = CFPreferencesCopyAppValue(CFSTR("persistent-apps"), CFSTR("com.apple.dock"));
  NSArray *apps = raw ? CFBridgingRelease(raw) : @[];
  BOOL found = NO;
  for (id item in apps) { NSString *u = nil; @try { u = item[@"tile-data"][@"file-data"][@"_CFURLString"]; } @catch (NSException *e) {} if (u && [DockEntryPath(u) isEqualToString:[path stringByStandardizingPath]]) { found = YES; break; } }
  NSString *line = [NSString stringWithFormat:@"%@ %@ count=%ld found=%d %@\n", [NSDate date], tag, (long)apps.count, found, path ?: @""];
  NSFileHandle *fh = [NSFileHandle fileHandleForWritingAtPath:@"/tmp/docklaunchers_dock_debug.log"];
  if (!fh) { [[NSFileManager defaultManager] createFileAtPath:@"/tmp/docklaunchers_dock_debug.log" contents:nil attributes:nil]; fh = [NSFileHandle fileHandleForWritingAtPath:@"/tmp/docklaunchers_dock_debug.log"]; }
  [fh seekToEndOfFile]; [fh writeData:[line dataUsingEncoding:NSUTF8StringEncoding]]; [fh closeFile];
}

- (void)addDockEntry:(NSString *)path label:(NSString *)label {
  @try {
    NSDictionary *info = [NSDictionary dictionaryWithContentsOfFile:[path stringByAppendingPathComponent:@"Contents/Info.plist"]];
    NSString *bid = info[@"CFBundleIdentifier"] ?: label;
    NSString *enc = [[path stringByAppendingString:@"/"] stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLPathAllowedCharacterSet]];
    NSString *url = [NSString stringWithFormat:@"file://%@", enc];
    CFArrayRef raw = CFPreferencesCopyAppValue(CFSTR("persistent-apps"), CFSTR("com.apple.dock"));
    NSMutableArray *apps = raw ? [CFBridgingRelease(raw) mutableCopy] : [NSMutableArray array];
    for (id item in apps) {
      NSString *u = nil; @try { u = item[@"tile-data"][@"file-data"][@"_CFURLString"]; } @catch (NSException *e) {}
      if (u && [DockEntryPath(u) isEqualToString:[path stringByStandardizingPath]]) return;
    }
    [apps addObject:@{@"tile-data": @{@"file-data": @{@"_CFURLString": url, @"_CFURLStringType": @15},
                                      @"file-label": label, @"file-type": @41,
                                      @"bundle-identifier": bid, @"dock-extra": @NO},
                      @"tile-type": @"file-tile"}];
    CFPreferencesSetAppValue(CFSTR("persistent-apps"), (__bridge CFPropertyListRef)apps, CFSTR("com.apple.dock"));
    CFPreferencesAppSynchronize(CFSTR("com.apple.dock"));
    self.dockPersistentDirty=YES;
    [self logDockState:@"add" path:path];
  } @catch (NSException *e) {}
}

- (void)removeDockEntry:(NSString *)path {
  @try {
    NSString *enc = [[path stringByAppendingString:@"/"] stringByAddingPercentEncodingWithAllowedCharacters:[NSCharacterSet URLPathAllowedCharacterSet]];
    CFArrayRef raw = CFPreferencesCopyAppValue(CFSTR("persistent-apps"), CFSTR("com.apple.dock"));
    if (!raw) return;
    NSArray *apps = CFBridgingRelease(raw);
    NSMutableArray *keep = [NSMutableArray array];
    for (id item in apps) {
      NSString *u = nil; @try { u = item[@"tile-data"][@"file-data"][@"_CFURLString"]; } @catch (NSException *e) {}
      if (u && [DockEntryPath(u) isEqualToString:[path stringByStandardizingPath]]) continue;
      [keep addObject:item];
    }
    CFPreferencesSetAppValue(CFSTR("persistent-apps"), (__bridge CFPropertyListRef)keep, CFSTR("com.apple.dock"));
    CFPreferencesAppSynchronize(CFSTR("com.apple.dock"));
    self.dockPersistentDirty=YES;
    [self logDockState:@"remove" path:path];
  } @catch (NSException *e) {}
}

- (void)reloadDockPreferences {
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    notify_post("com.apple.dock.prefchanged");
  });
}

- (void)hardRestartDock {
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    NSTask *ic = [[NSTask alloc] init];
    ic.launchPath = @"/usr/bin/killall";
    ic.arguments = @[@"iconservicesagent"];
    @try { [ic launch]; } @catch (NSException *e) {}
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/usr/bin/killall";
    t.arguments = @[@"-KILL", @"Dock"];
    @try { [t launch]; } @catch (NSException *e) {}
  });
}

// 默认软刷新；持久化 Dock 条目变更后必须硬重启 Dock 才能可靠生效
- (void)killDock {
  if (self.dockPersistentDirty) {
    self.dockPersistentDirty = NO;
    [self hardRestartDock];
    return;
  }
  [self reloadDockPreferences];
}

// ---------------- 应用卸载 ----------------
- (NSArray<NSDictionary *> *)diskMountList {
  NSMutableArray *out = [NSMutableArray array];
  struct statfs *mounts = NULL;
  int n = getmntinfo(&mounts, MNT_NOWAIT);
  for (int i = 0; i < n; i++) {
    struct statfs *m = &mounts[i];
    if (!(m->f_flags & MNT_LOCAL)) continue;
    NSString *mp = [NSString stringWithUTF8String:m->f_mntonname];
    if (![mp isEqualToString:@"/"] && ![mp hasPrefix:@"/Volumes/"]) continue;
    unsigned long long total = (unsigned long long)m->f_blocks * m->f_bsize;
    unsigned long long freeB = (unsigned long long)m->f_bavail * m->f_bsize;
    if (total == 0) continue;
    NSString *name = [mp isEqualToString:@"/"] ? @"内置磁盘" : mp.lastPathComponent;
    [out addObject:@{@"mount": mp, @"name": name, @"total": @(total), @"free": @(freeB)}];
  }
  [out sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
    if ([a[@"mount"] isEqualToString:@"/"]) return NSOrderedAscending;
    if ([b[@"mount"] isEqualToString:@"/"]) return NSOrderedDescending;
    return [a[@"name"] compare:b[@"name"]];
  }];
  return out;
}

- (unsigned long long)diskSizeOfPaths:(NSArray<NSString *> *)paths {
  NSFileManager *fm = [NSFileManager defaultManager];
  unsigned long long total = 0;
  for (NSString *path in paths) {
    BOOL isDir = NO;
    if (![fm fileExistsAtPath:path isDirectory:&isDir]) continue;
    if (!isDir) {
      NSDictionary *attr = [fm attributesOfItemAtPath:path error:NULL];
      if (attr) total += [attr[NSFileSize] unsignedLongLongValue];
      continue;
    }
    NSURL *url = [NSURL fileURLWithPath:path];
    NSDirectoryEnumerator *en = [fm enumeratorAtURL:url includingPropertiesForKeys:@[NSURLFileAllocatedSizeKey, NSURLIsRegularFileKey] options:NSDirectoryEnumerationSkipsHiddenFiles errorHandler:^BOOL(NSURL *u, NSError *e) { return YES; }];
    for (NSURL *u in en) {
      id v = nil;
      if ([u getResourceValue:&v forKey:NSURLFileAllocatedSizeKey error:NULL] && [v isKindOfClass:[NSNumber class]]) total += [v unsignedLongLongValue];
    }
  }
  return total;
}

- (NSString *)aiStorePath {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"ai_entries.json"];
}
- (void)hydrateAIKeys {
  if (!self.aiEntries) return;
  for (NSInteger i = 0; i < (NSInteger)self.aiEntries.count; i++) {
    if (![self.aiEntries[i] isKindOfClass:[NSDictionary class]]) continue;
    NSMutableDictionary *e = [self.aiEntries[i] mutableCopy];
    NSString *kid = e[@"kid"];
    if (kid.length && ![e[@"api"] length]) {
      NSString *stored = AIKeychainGet(kid);
      if (stored.length) {
        e[@"api"] = stored;
        AIKeychainSet(kid, stored);
      }
    }
    self.aiEntries[i] = e;
  }
}

- (void)loadAIEntries {
  NSData *d = [NSData dataWithContentsOfFile:[self aiStorePath]];
  id parsed = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  self.aiEntries = [parsed isKindOfClass:[NSArray class]] ? [parsed mutableCopy] : [NSMutableArray array];
  BOOL migrated = NO;
  for (NSInteger i = 0; i < (NSInteger)self.aiEntries.count; i++) {
    if (![self.aiEntries[i] isKindOfClass:[NSDictionary class]]) continue;
    NSMutableDictionary *e = [self.aiEntries[i] mutableCopy];
    NSString *kid = e[@"kid"];
    if (!kid.length) { kid = [[NSUUID UUID] UUIDString]; e[@"kid"] = kid; migrated = YES; }
    NSString *plain = e[@"api"] ?: @"";
    if (plain.length) {
      AIKeychainSet(kid, plain);
      migrated = YES;
    }
    self.aiEntries[i] = e;
  }
  if (!self.aiSelected) self.aiSelected = [NSMutableSet set];
  if (!self.aiRevealedNames) self.aiRevealedNames = [NSMutableSet set];
  if (!self.aiRevealedQuotas) self.aiRevealedQuotas = [NSMutableSet set];
  [self hydrateAIKeys];
  if (migrated) [self saveAIEntries];
  else if (self.aiEntries.count) [self recordAIHistorySnapshot];
}

- (void)saveAIEntries {
  NSMutableArray *stored = [NSMutableArray array];
  for (NSDictionary *e in self.aiEntries) {
    if (![e isKindOfClass:[NSDictionary class]]) continue;
    NSMutableDictionary *m = [e mutableCopy];
    NSString *key = m[@"api"] ?: @"";
    NSString *kid = m[@"kid"];
    if (!kid.length) { kid = [[NSUUID UUID] UUIDString]; m[@"kid"] = kid; }
    if (key.length) AIKeychainSet(kid, key);
    [m removeObjectForKey:@"api"];
    [stored addObject:m];
  }
  NSMutableSet *liveKids = [NSMutableSet set];
  for (NSDictionary *e in stored) if ([e[@"kid"] isKindOfClass:[NSString class]]) [liveKids addObject:e[@"kid"]];
  for (NSString *acct in AIKeychainAccounts()) if (![liveKids containsObject:acct]) AIKeychainDelete(acct);
  NSData *d = [NSJSONSerialization dataWithJSONObject:stored options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:[self aiStorePath] atomically:YES];
  [self recordAIHistorySnapshot];
}
- (NSString *)clipboardStorePath {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"clipboard.json"];
}

