- (NSString *)quickReplyStorePath {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"quick_replies.json"];
}

- (void)loadQuickReplies {
  NSData *d = [NSData dataWithContentsOfFile:[self quickReplyStorePath]];
  NSArray *arr = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  NSMutableArray *out = [NSMutableArray array];
  if ([arr isKindOfClass:[NSArray class]]) {
    for (NSDictionary *raw in arr) {
      if (![raw isKindOfClass:[NSDictionary class]]) continue;
      NSString *text = raw[@"text"] ?: @"";
      if (!text.length) continue;
      [out addObject:@{@"quick": @YES, @"title": raw[@"title"] ?: @"快捷回复", @"text": text, @"date": [NSDate date], @"favorite": @NO}];
    }
  }
  self.quickReplyItems = out;
}

- (void)saveQuickReplies {
  NSMutableArray *out = [NSMutableArray array];
  for (NSDictionary *it in self.quickReplyItems) [out addObject:@{@"title": it[@"title"] ?: @"快捷回复", @"text": it[@"text"] ?: @""}];
  NSData *d = [NSJSONSerialization dataWithJSONObject:out options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:[self quickReplyStorePath] atomically:YES];
}

- (void)updateClipboardTabButtons {
  BOOL quick = self.clipboardFilter == 4;
  self.clipboardPauseBtn.hidden = quick;
  self.clipboardFavBtn.hidden = quick;
  self.clipboardAddQuickBtn.hidden = !quick;
  self.clipboardEditQuickBtn.hidden = !quick;
}

- (void)loadClipboardHistory {
  self.clipboardItems = [NSMutableArray array];
  NSData *d = [NSData dataWithContentsOfFile:[self clipboardStorePath]];
  id arr = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  if (![arr isKindOfClass:[NSArray class]]) return;
  for (id raw in arr) {
    if (![raw isKindOfClass:[NSDictionary class]]) continue;
    NSTimeInterval ts = [raw[@"date"] doubleValue];
    NSDate *date = ts > 0 ? [NSDate dateWithTimeIntervalSince1970:ts] : [NSDate date];
    NSString *kind = raw[@"kind"] ?: @"text";
    if ([kind isEqualToString:@"image"]) {
      NSString *file = raw[@"file"] ?: @"";
      NSString *path = [[self clipboardImagesDir] stringByAppendingPathComponent:file];
      if (!file.length || ![[NSFileManager defaultManager] fileExistsAtPath:path]) continue;
      [self.clipboardItems addObject:@{@"kind": @"image", @"file": file, @"date": date, @"favorite": @([raw[@"favorite"] boolValue]), @"width": raw[@"width"] ?: @0, @"height": raw[@"height"] ?: @0}];
      continue;
    }
    NSString *text = raw[@"text"];
    if (!text.length) continue;
    [self.clipboardItems addObject:@{@"text": text, @"date": date, @"favorite": @([raw[@"favorite"] boolValue])}];
  }
  [self pruneClipboardHistory];
}

- (void)saveClipboardHistory {
  NSMutableArray *out = [NSMutableArray array];
  for (NSDictionary *it in self.clipboardItems) {
    NSDate *date = it[@"date"] ?: [NSDate date];
    if ([it[@"kind"] isEqualToString:@"image"]) {
      NSString *file = it[@"file"] ?: @"";
      if (!file.length) continue;
      [out addObject:@{@"kind": @"image", @"file": file, @"date": @([date timeIntervalSince1970]), @"favorite": @([it[@"favorite"] boolValue]), @"width": it[@"width"] ?: @0, @"height": it[@"height"] ?: @0}];
      continue;
    }
    NSString *text = it[@"text"] ?: @"";
    if (!text.length) continue;
    [out addObject:@{@"text": text, @"date": @([date timeIntervalSince1970]), @"favorite": @([it[@"favorite"] boolValue])}];
  }
  NSData *d = [NSJSONSerialization dataWithJSONObject:out options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:[self clipboardStorePath] atomically:YES];
}

- (void)reloadClipboardVisibleItems {
  if (!self.clipboardVisibleItems) self.clipboardVisibleItems = [NSMutableArray array];
  [self.clipboardVisibleItems removeAllObjects];
  NSString *q = [self.clipboardSearch.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]].lowercaseString;
  NSInteger filter = self.clipboardFilter;
  if (filter == 4) {
    if (!self.quickReplyItems) [self loadQuickReplies];
    for (NSDictionary *it in self.quickReplyItems) {
      if (q.length) {
        NSString *hay = [NSString stringWithFormat:@"%@ %@", it[@"title"] ?: @"", it[@"text"] ?: @""].lowercaseString;
        if ([hay rangeOfString:q].location == NSNotFound) continue;
      }
      [self.clipboardVisibleItems addObject:it];
    }
    [self.clipboardTable reloadData];
    [self updateClipboardSelectAllState];
    return;
  }
  for (NSDictionary *it in self.clipboardItems) {
    BOOL img = [it[@"kind"] isEqualToString:@"image"];
    if ((filter == 3 || self.clipboardFavoritesOnly) && ![it[@"favorite"] boolValue]) continue;
    if (filter == 1 && img) continue;
    if (filter == 2 && !img) continue;
    if (q.length) {
      if ([it[@"kind"] isEqualToString:@"image"]) continue;
      if ([(it[@"text"] ?: @"") rangeOfString:q options:NSCaseInsensitiveSearch].location == NSNotFound) continue;
    }
    [self.clipboardVisibleItems addObject:it];
  }
  [self.clipboardTable reloadData];
  [self updateClipboardSelectAllState];
}

- (NSDictionary *)clipboardSelectedItem {
  NSInteger row = self.clipboardTable.clickedRow;
  if (row < 0) row = self.clipboardTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) return nil;
  return self.clipboardVisibleItems[row];
}

- (void)copyClipboardRow:(id)sender {
  NSDictionary *it = [self clipboardSelectedItem];
  if (!it) return;
  NSPasteboard *pb = [NSPasteboard generalPasteboard];
  [pb clearContents];
  if ([it[@"kind"] isEqualToString:@"image"]) {
    NSString *path = [[self clipboardImagesDir] stringByAppendingPathComponent:it[@"file"] ?: @""];
    NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
    if (img) [pb writeObjects:@[img]];
  } else {
    [pb setString:it[@"text"] ?: @"" forType:NSPasteboardTypeString];
  }
  [self showToast:@"已复制到剪贴板"];
}

