    save.target = self; save.action = @selector(performClipboardSave:);
    [save applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:save];
    ColorHoverButton *cancel = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(392, 30, 84, 32)];
    cancel.title = @"取消"; cancel.hoverColor = [NSColor systemGrayColor];
    cancel.target = self; cancel.action = @selector(cancelClipboardSave:);
    [cancel applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:cancel];
    [self.clipboardSaveWindow center];
  }
  NSString *defaultName = isImage ? (it[@"file"] ?: @"剪贴板图片.png") : @"剪贴板文本.txt";
  self.clipboardSaveNameField.stringValue = defaultName;
  NSString *downloads = [NSHomeDirectory() stringByAppendingPathComponent:@"Downloads"];
  self.clipboardSaveDirField.stringValue = downloads;
  [NSApp activateIgnoringOtherApps:YES];
  [self.clipboardSaveWindow makeKeyAndOrderFront:nil];
}

- (void)cancelClipboardSave:(id)sender {
  [self.clipboardSaveWindow orderOut:nil];
  self.clipboardSaveItem = nil;
}

- (void)performClipboardSave:(id)sender {
  NSDictionary *it = self.clipboardSaveItem;
  if (!it) return;
  BOOL isImage = [it[@"kind"] isEqualToString:@"image"];
  NSString *name = [self.clipboardSaveNameField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!name.length) { [self showToast:@"请填写文件名"]; return; }
  name = name.lastPathComponent;
  NSString *ext = isImage ? @"png" : @"txt";
  if (![name.pathExtension.lowercaseString isEqualToString:ext]) name = [name stringByAppendingPathExtension:ext];
  NSString *dir = [self.clipboardSaveDirField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!dir.length) dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Downloads"];
  if ([dir hasPrefix:@"~"]) dir = [dir stringByExpandingTildeInPath];
  BOOL isDir = NO;
  if (![[NSFileManager defaultManager] fileExistsAtPath:dir isDirectory:&isDir] || !isDir) { [self showToast:@"文件夹不存在"]; return; }
  NSString *path = [dir stringByAppendingPathComponent:name];
  if (isImage) {
    NSString *src = [[self clipboardImagesDir] stringByAppendingPathComponent:(it[@"file"] ?: @"")];
    NSData *data = [NSData dataWithContentsOfFile:src];
    if (!data) { [self showToast:@"图片文件不存在"]; return; }
    NSBitmapImageRep *rep = [NSBitmapImageRep imageRepWithData:data];
    NSData *png = rep ? [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] : data;
    if (![png writeToFile:path atomically:YES]) { [self showToast:@"保存失败"]; return; }
  } else {
    NSString *text = it[@"text"] ?: @"";
    if (![text writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:NULL]) { [self showToast:@"保存失败"]; return; }
  }
  [self.clipboardSaveWindow orderOut:nil];
  self.clipboardSaveItem = nil;
  [self showToast:@"已保存"];
  [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:path]]];
}

- (void)clearAllClipboardHistory:(id)sender {
  NSInteger count = self.clipboardItems.count;
  if (!count) { [self showToast:@"暂无剪贴板历史"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = [NSString stringWithFormat:@"清空全部 %ld 条剪贴板历史？", (long)count];
  a.informativeText = @"图片缓存也会删除，此操作不可恢复；当前剪贴板内容不受影响。";
  [a addButtonWithTitle:@"清空"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  for (NSDictionary *it in self.clipboardItems) if ([it[@"kind"] isEqualToString:@"image"]) [self deleteClipboardImageForItem:it];
  self.clipboardItems = [NSMutableArray array];
  [self saveClipboardHistory];
  [self reloadClipboardVisibleItems];
  [self showToast:@"剪贴板历史已清空"];
}

- (void)pasteClipboardToPreviousApp:(id)sender {
  NSDictionary *it = [self clipboardSelectedItem];
  if (!it) return;
  [self copyClipboardRow:nil];
  NSRunningApplication *target = self.clipboardPreviousApp;
  [self.clipboardWindow orderOut:nil];
  if (!target || target.terminated) {
    [self showToast:@"已复制，请到目标应用按 ⌘V"];
    return;
  }
  [target activateWithOptions:NSApplicationActivateIgnoringOtherApps];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.25 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    if (!AXIsProcessTrusted()) { [self showToast:@"已复制；粘贴需要开启设备控制权限"]; return; }
    CGEventSourceRef src = CGEventSourceCreate(kCGEventSourceStateHIDSystemState);
    CGEventRef down = CGEventCreateKeyboardEvent(src, (CGKeyCode)9, true);
    CGEventRef up = CGEventCreateKeyboardEvent(src, (CGKeyCode)9, false);
    CGEventSetFlags(down, kCGEventFlagMaskCommand);
    CGEventSetFlags(up, kCGEventFlagMaskCommand);
    CGEventPost(kCGHIDEventTap, down);
    CGEventPost(kCGHIDEventTap, up);
    if (down) CFRelease(down);
    if (up) CFRelease(up);
    if (src) CFRelease(src);
  });
}

- (void)clearClipboardHistory:(id)sender { [self clearAllClipboardHistory:nil]; }
- (void)toggleClipboardPause:(id)sender { self.clipboardPaused = !self.clipboardPaused; self.clipboardPauseBtn.title = self.clipboardPaused ? @"继续监听" : @"暂停监听"; [self showToast:self.clipboardPaused ? @"已暂停剪贴板记录" : @"已恢复剪贴板记录"]; }
- (void)toggleClipboardFavorite:(id)sender { [self toggleClipboardFavoriteAtRow:self.clipboardTable.selectedRow]; }
- (void)toggleClipboardFavoriteAtRow:(NSInteger)row {
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) { [self showToast:@"请先选择一条记录"]; return; }
  NSDictionary *vis=self.clipboardVisibleItems[row];
  for (NSInteger i=0;i<(NSInteger)self.clipboardItems.count;i++) {
    NSDictionary *it=self.clipboardItems[i];
    if ((vis[@"text"] && [it[@"text"] isEqual:vis[@"text"]]) || (vis[@"file"] && [it[@"file"] isEqual:vis[@"file"]])) {
      NSMutableDictionary *m=[it mutableCopy]; m[@"favorite"]=@(![it[@"favorite"] boolValue]); self.clipboardItems[i]=m; break;
    }
  }
  [self saveClipboardHistory]; [self reloadClipboardVisibleItems];
}
- (void)clipboardSearchChanged:(id)sender { [self reloadClipboardVisibleItems]; }

- (NSInteger)clipboardRetentionDays {
  if (![[NSUserDefaults standardUserDefaults] objectForKey:@"centerClipboardDays"]) return 30;
  return [[NSUserDefaults standardUserDefaults] integerForKey:@"centerClipboardDays"];
}

- (void)pruneClipboardHistory {
  NSInteger days = [self clipboardRetentionDays];
  if (days <= 0 || !self.clipboardItems.count) return;
  NSDate *cutoff = [NSDate dateWithTimeIntervalSinceNow:-days * 86400.0];
  NSMutableArray *keep = [NSMutableArray array];
  for (NSDictionary *it in self.clipboardItems) {
    NSDate *date = [it[@"date"] isKindOfClass:[NSDate class]] ? it[@"date"] : [NSDate date];
    if ([date compare:cutoff] != NSOrderedAscending) [keep addObject:it];
  }
  if (keep.count != self.clipboardItems.count) {
    for (NSDictionary *it in self.clipboardItems) if (![keep containsObject:it] && [it[@"kind"] isEqualToString:@"image"]) [self deleteClipboardImageForItem:it];
    self.clipboardItems = keep;
    [self saveClipboardHistory];
  }
}

- (void)clipboardRetentionChanged:(NSPopUpButton *)popup {
  NSInteger days = [popup.selectedItem.representedObject integerValue];
  [[NSUserDefaults standardUserDefaults] setInteger:days forKey:@"centerClipboardDays"];
  [self pruneClipboardHistory];
  if (self.clipboardWindow.isVisible) [self reloadClipboardVisibleItems];
  [self showToast:days > 0 ? [NSString stringWithFormat:@"剪贴板将保留 %ld 天", (long)days] : @"剪贴板历史将永久保留"];
}

- (void)startClipboardMonitor {
  if (self.clipboardTimer) return;
  [self loadClipboardHistory];
  self.clipboardLastChange = [NSPasteboard generalPasteboard].changeCount;
  self.clipboardLastText = [[NSPasteboard generalPasteboard] stringForType:NSPasteboardTypeString] ?: @"";
  self.clipboardTimer = [NSTimer scheduledTimerWithTimeInterval:1.0 repeats:YES block:^(NSTimer *t) {
    NSPasteboard *pb = [NSPasteboard generalPasteboard];
    NSInteger cc = pb.changeCount;
    if (cc == self.clipboardLastChange) return;
    self.clipboardLastChange = cc;
    if (self.clipboardPaused) return;
    NSData *imgData = [pb dataForType:NSPasteboardTypePNG];
    if (!imgData.length) {
      NSData *tiff = [pb dataForType:NSPasteboardTypeTIFF];
      if (tiff.length) {
        NSBitmapImageRep *rep = [NSBitmapImageRep imageRepWithData:tiff];
        imgData = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
      }
    }
    if (imgData.length) {
      NSString *file = [[[NSUUID UUID] UUIDString] stringByAppendingString:@".png"];
      NSString *path = [[self clipboardImagesDir] stringByAppendingPathComponent:file];
      if (![imgData writeToFile:path atomically:YES]) return;
      NSImage *img = [[NSImage alloc] initWithData:imgData];
      [self.clipboardItems insertObject:@{@"kind": @"image", @"file": file, @"date": [NSDate date], @"favorite": @NO, @"width": @(img.size.width), @"height": @(img.size.height)} atIndex:0];
      self.clipboardLastText = @"";
      while (self.clipboardItems.count > 200) {
        NSDictionary *last = self.clipboardItems.lastObject;
        if ([last[@"kind"] isEqualToString:@"image"]) [self deleteClipboardImageForItem:last];
        [self.clipboardItems removeLastObject];
      }
      [self pruneClipboardHistory];
      [self saveClipboardHistory];
      if (self.clipboardWindow.isVisible) [self reloadClipboardVisibleItems];
      return;
    }
    NSString *text = [pb stringForType:NSPasteboardTypeString];
    if (!text.length || [text isEqualToString:self.clipboardLastText]) return;
    self.clipboardLastText = text;
    [self.clipboardItems insertObject:@{@"text": text, @"date": [NSDate date], @"favorite": @NO} atIndex:0];
    while (self.clipboardItems.count > 200) [self.clipboardItems removeLastObject];
    [self pruneClipboardHistory];
    [self saveClipboardHistory];
    if (self.clipboardWindow.isVisible) [self reloadClipboardVisibleItems];
  }];
}

