  }
  [self loadQuickReplies];
  [self.clipboardTabs setSelectedSegment:self.clipboardFilter];
  [self updateClipboardTabButtons];
  [self reloadClipboardVisibleItems];
  [NSApp activateIgnoringOtherApps:YES];
  [self.clipboardWindow makeKeyAndOrderFront:nil];
  [self.clipboardWindow orderFrontRegardless];
  [self installClipboardHoverMonitor];
}

- (void)clipboardTabsChanged:(NSSegmentedControl *)sender {
  self.clipboardFilter = sender.selectedSegment;
  [self hideClipboardPreview];
  [self updateClipboardTabButtons];
  [self reloadClipboardVisibleItems];
}

- (void)deleteClipboardRow:(NSButton *)sender {
  NSInteger row = sender.tag;
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) return;
  NSDictionary *it = self.clipboardVisibleItems[row];
  if ([it[@"quick"] boolValue]) {
    [self.quickReplyItems removeObject:it];
    [self saveQuickReplies];
  } else {
    if ([it[@"kind"] isEqualToString:@"image"]) [self deleteClipboardImageForItem:it];
    [self.clipboardItems removeObject:it];
    [self saveClipboardHistory];
  }
  [self reloadClipboardVisibleItems];
}

- (NSString *)clipboardKeyForItem:(NSDictionary *)it {
  NSDate *d = it[@"date"] ?: [NSDate date];
  return [NSString stringWithFormat:@"%.3f|%@|%@|%@", [d timeIntervalSince1970], it[@"kind"] ?: @"text", it[@"file"] ?: @"", [it[@"text"] ?: @"" substringToIndex:MIN(60, [it[@"text"] ?: @"" length])]];
}

- (void)updateClipboardSelectAllState {
  if (!self.clipboardSelectAll) return;
  BOOL all = self.clipboardVisibleItems.count > 0;
  for (NSDictionary *it in self.clipboardVisibleItems) {
    if (![self.clipboardSelected containsObject:[self clipboardKeyForItem:it]]) { all = NO; break; }
  }
  self.clipboardSelectAll.state = all ? NSControlStateValueOn : NSControlStateValueOff;
}

- (void)clipboardToggleSelect:(NSButton *)sender {
  NSInteger row = sender.tag;
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) return;
  if (!self.clipboardSelected) self.clipboardSelected = [NSMutableSet set];
  NSString *key = [self clipboardKeyForItem:self.clipboardVisibleItems[row]];
  if (sender.state == NSControlStateValueOn) [self.clipboardSelected addObject:key];
  else [self.clipboardSelected removeObject:key];
  [self updateClipboardSelectAllState];
}

- (void)toggleClipboardSelectAll:(NSButton *)sender {
  if (!self.clipboardSelected) self.clipboardSelected = [NSMutableSet set];
  if (sender.state == NSControlStateValueOn) {
    for (NSDictionary *it in self.clipboardVisibleItems) [self.clipboardSelected addObject:[self clipboardKeyForItem:it]];
  } else {
    for (NSDictionary *it in self.clipboardVisibleItems) [self.clipboardSelected removeObject:[self clipboardKeyForItem:it]];
  }
  [self.clipboardTable reloadData];
  [self updateClipboardSelectAllState];
}

- (void)deleteClipboardSelected:(id)sender {
  BOOL quickMode = self.clipboardFilter == 4;
  NSMutableArray *targets = [NSMutableArray array];
  NSArray *source = quickMode ? (self.quickReplyItems ?: @[]) : self.clipboardItems;
  for (NSDictionary *it in source) if ([self.clipboardSelected containsObject:[self clipboardKeyForItem:it]]) [targets addObject:it];
  if (!targets.count) { [self showToast:@"请先勾选要删除的记录"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = [NSString stringWithFormat:@"删除 %ld 条剪贴板记录？", (long)targets.count];
  [a addButtonWithTitle:@"删除"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  for (NSDictionary *it in targets) {
    if ([it[@"quick"] boolValue]) {
      [self.quickReplyItems removeObject:it];
    } else {
      if ([it[@"kind"] isEqualToString:@"image"]) [self deleteClipboardImageForItem:it];
      [self.clipboardItems removeObject:it];
    }
    [self.clipboardSelected removeObject:[self clipboardKeyForItem:it]];
  }
  if (quickMode) [self saveQuickReplies]; else [self saveClipboardHistory];
  [self reloadClipboardVisibleItems];
  [self showToast:[NSString stringWithFormat:@"已删除 %ld 条记录", (long)targets.count]];
}

- (void)showQuickReplyEditorAtIndex:(NSInteger)idx {
  BOOL editing = idx >= 0 && idx < (NSInteger)self.quickReplyItems.count;
  NSDictionary *old = editing ? self.quickReplyItems[idx] : @{};
  NSView *av = [[NSView alloc] initWithFrame:NSMakeRect(0,0,520,240)];
  NSTextField *tl = [self label:@"标题" size:10.5 bold:YES color:[NSColor secondaryLabelColor]];
  tl.frame = NSMakeRect(4, 212, 60, 16); [av addSubview:tl];
  NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(70, 206, 440, 26)];
  titleField.stringValue = old[@"title"] ?: @""; [av addSubview:titleField];
  NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(4, 8, 506, 188)];
  sv.hasVerticalScroller = YES; sv.borderType = NSBezelBorder;
  NSTextView *tv = [[NSTextView alloc] initWithFrame:sv.contentView.bounds];
  tv.font = [NSFont systemFontOfSize:12];
  tv.string = old[@"text"] ?: @"";
  sv.documentView = tv; [av addSubview:sv];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = editing ? @"编辑快捷回复" : @"新增快捷回复";
  a.accessoryView = av;
  [a addButtonWithTitle:@"保存"];
  [a addButtonWithTitle:@"取消"];
  a.window.level = NSStatusWindowLevel + 2;
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSString *text = [tv.string stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!text.length) { [self showToast:@"快捷回复内容不能为空"]; return; }
  NSString *title = [titleField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!title.length) title = @"快捷回复";
  NSDictionary *item = @{@"quick": @YES, @"title": title, @"text": text, @"date": [NSDate date], @"favorite": @NO};
  if (!self.quickReplyItems) self.quickReplyItems = [NSMutableArray array];
  if (editing) [(NSMutableArray *)self.quickReplyItems replaceObjectAtIndex:idx withObject:item];
  else [(NSMutableArray *)self.quickReplyItems insertObject:item atIndex:0];
  [self saveQuickReplies];
  self.clipboardFilter = 4;
  [self.clipboardTabs setSelectedSegment:4];
  [self updateClipboardTabButtons];
  [self reloadClipboardVisibleItems];
  [self showToast:editing ? @"快捷回复已更新" : @"快捷回复已添加"];
}

- (void)addQuickReply:(id)sender {
  [self loadQuickReplies];
  [self showQuickReplyEditorAtIndex:-1];
}

- (void)editQuickReply:(id)sender {
  [self loadQuickReplies];
  NSInteger row = self.clipboardTable.selectedRow;
  if (row < 0) row = self.clipboardTable.clickedRow;
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) { [self showToast:@"请先选择一条快捷回复"]; return; }
  NSDictionary *sel = self.clipboardVisibleItems[row];
  NSInteger idx = [self.quickReplyItems indexOfObjectPassingTest:^BOOL(NSDictionary *it, NSUInteger i, BOOL *stop) { return [it[@"text"] isEqual:sel[@"text"]] && [it[@"title"] isEqual:sel[@"title"]]; }];
  if (idx != NSNotFound) [self showQuickReplyEditorAtIndex:idx];
}

- (void)buildClipboardPreviewPanel {
  if (self.clipboardPreviewPanel) return;
  self.clipboardPreviewPanel = [[NSPanel alloc] initWithContentRect:NSMakeRect(0,0,400,300) styleMask:(NSWindowStyleMaskBorderless|NSWindowStyleMaskNonactivatingPanel) backing:NSBackingStoreBuffered defer:NO];
  self.clipboardPreviewPanel.level = NSFloatingWindowLevel + 2;
  self.clipboardPreviewPanel.opaque = NO;
  self.clipboardPreviewPanel.backgroundColor = [NSColor clearColor];
  self.clipboardPreviewPanel.hasShadow = YES;
  NSView *card = [[NSView alloc] initWithFrame:NSMakeRect(0,0,400,300)];
  card.wantsLayer = YES;
  card.layer.backgroundColor = [NSColor windowBackgroundColor].CGColor;
  card.layer.cornerRadius = 14;
  card.layer.borderWidth = 1;
  card.layer.borderColor = [[NSColor separatorColor] colorWithAlphaComponent:0.6].CGColor;
  card.layer.masksToBounds = YES;
  self.clipboardPreviewPanel.contentView = card;
  self.clipboardPreviewImageView = [[NSImageView alloc] initWithFrame:card.bounds];
  self.clipboardPreviewImageView.imageScaling = NSImageScaleProportionallyUpOrDown;
  self.clipboardPreviewImageView.autoresizingMask = NSViewWidthSizable|NSViewHeightSizable;
  [card addSubview:self.clipboardPreviewImageView];
  self.clipboardPreviewScroll = [[NSScrollView alloc] initWithFrame:NSInsetRect(card.bounds, 14, 14)];
  self.clipboardPreviewScroll.hasVerticalScroller = YES;
  self.clipboardPreviewScroll.drawsBackground = NO;
  self.clipboardPreviewScroll.autoresizingMask = NSViewWidthSizable|NSViewHeightSizable;
  self.clipboardPreviewTextView = [[NSTextView alloc] initWithFrame:self.clipboardPreviewScroll.contentView.bounds];
  self.clipboardPreviewTextView.editable = NO;
  self.clipboardPreviewTextView.selectable = YES;
  self.clipboardPreviewTextView.font = [NSFont systemFontOfSize:13];
  self.clipboardPreviewTextView.textContainerInset = NSMakeSize(4, 4);
  self.clipboardPreviewScroll.documentView = self.clipboardPreviewTextView;
  [card addSubview:self.clipboardPreviewScroll];
  self.clipboardPreviewImageView.hidden = YES;
  self.clipboardPreviewScroll.hidden = YES;
}

- (void)showClipboardOCRText:(NSString *)text {
  if (!self.clipboardOCRWindow) {
    self.clipboardOCRWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,540,400) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable) backing:NSBackingStoreBuffered defer:NO];
    self.clipboardOCRWindow.title = @"图片文字识别";
    self.clipboardOCRWindow.releasedWhenClosed = NO;
    self.clipboardOCRWindow.level = NSFloatingWindowLevel;
    NSView *cv = self.clipboardOCRWindow.contentView;
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 64, 508, 310)];
    sv.hasVerticalScroller = YES; sv.borderType = NSBezelBorder;
    self.clipboardOCRTextView = [[NSTextView alloc] initWithFrame:sv.contentView.bounds];
    self.clipboardOCRTextView.editable = NO;
    self.clipboardOCRTextView.selectable = YES;
    self.clipboardOCRTextView.font = [NSFont systemFontOfSize:13];
    sv.documentView = self.clipboardOCRTextView;
    [cv addSubview:sv];
    ColorHoverButton *copy = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(16, 20, 110, 32)];
    copy.title = @"复制文字"; copy.hoverColor = [NSColor systemGreenColor];
    copy.target = self; copy.action = @selector(copyClipboardOCRText:);
    [copy applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:copy];
    ColorHoverButton *close = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(424, 20, 100, 32)];
    close.title = @"关闭"; close.hoverColor = [NSColor systemGrayColor];
    close.target = self; close.action = @selector(closeClipboardOCR:);
    [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:close];
    [self.clipboardOCRWindow center];
  }
  self.clipboardOCRTextView.string = text ?: @"";
  [NSApp activateIgnoringOtherApps:YES];
  [self.clipboardOCRWindow makeKeyAndOrderFront:nil];
  [self.clipboardOCRWindow orderFrontRegardless];
}

- (void)ocrClipboardRow:(NSButton *)sender {
  NSInteger row = sender.tag;
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) return;
  NSDictionary *it = self.clipboardVisibleItems[row];
  if (![it[@"kind"] isEqualToString:@"image"]) { [self showToast:@"请选择图片记录"]; return; }
  NSString *path = [[self clipboardImagesDir] stringByAppendingPathComponent:it[@"file"] ?: @""];
  if (![[NSFileManager defaultManager] fileExistsAtPath:path]) { [self showToast:@"图片文件不存在"]; return; }
  [self showToast:@"正在识别图片文字…"];
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
    if (!img) { dispatch_async(dispatch_get_main_queue(), ^{ [self showToast:@"图片读取失败"]; }); return; }
    CGImageRef cg = [img CGImageForProposedRect:NULL context:nil hints:nil];
    if (!cg) { dispatch_async(dispatch_get_main_queue(), ^{ [self showToast:@"图片读取失败"]; }); return; }
    NSMutableString *out = [NSMutableString string];
    VNRecognizeTextRequest *req = [[VNRecognizeTextRequest alloc] init];
    req.recognitionLevel = VNRequestTextRecognitionLevelAccurate;
    req.recognitionLanguages = @[@"zh-Hans", @"en-US"];
    req.usesLanguageCorrection = YES;
    VNImageRequestHandler *h = [[VNImageRequestHandler alloc] initWithCGImage:cg options:@{}];
    NSError *err = nil;
    [h performRequests:@[req] error:&err];
    for (VNRecognizedTextObservation *o in req.results) {
      VNRecognizedText *t = [[o topCandidates:1] firstObject];
      if (t.string.length) [out appendFormat:@"%@\n", t.string];
    }
    img = nil;
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!out.length) { [self showToast:@"没有识别到文字"]; return; }
      [self showClipboardOCRText:out];
    });
  });
}

- (void)copyClipboardOCRText:(id)sender {
  NSString *text = self.clipboardOCRTextView.string;
  if (!text.length) return;
  [[NSPasteboard generalPasteboard] clearContents];
  [[NSPasteboard generalPasteboard] setString:text forType:NSPasteboardTypeString];
  [self showToast:@"识别文字已复制"];
}

- (void)closeClipboardOCR:(id)sender { [self.clipboardOCRWindow orderOut:nil]; }

- (void)showClipboardPreviewForRow:(NSInteger)row {
  if (row < 0 || row >= (NSInteger)self.clipboardVisibleItems.count) return;
  if (!self.clipboardWindow.isVisible) return;
  [self buildClipboardPreviewPanel];
  NSDictionary *it = self.clipboardVisibleItems[row];
  BOOL isImage = [it[@"kind"] isEqualToString:@"image"];
  CGFloat pw = 380, ph = 300;
  if (isImage) {
    NSImage *img = [[NSImage alloc] initWithContentsOfFile:[[self clipboardImagesDir] stringByAppendingPathComponent:it[@"file"] ?: @""]];
    if (!img) return;
    CGFloat ratio = MIN(440.0 / MAX(1, img.size.width), 340.0 / MAX(1, img.size.height));
    pw = MAX(180, img.size.width * ratio);
    ph = MAX(140, img.size.height * ratio);
    self.clipboardPreviewImageView.image = img;
    self.clipboardPreviewImageView.hidden = NO;
    self.clipboardPreviewScroll.hidden = YES;
  } else {
    self.clipboardPreviewTextView.string = it[@"text"] ?: @"";
    self.clipboardPreviewImageView.hidden = YES;
    self.clipboardPreviewScroll.hidden = NO;
  }
  NSRect wf = self.clipboardWindow.frame;
  CGFloat x = wf.origin.x - pw - 12;
  CGFloat y = wf.origin.y + wf.size.height - ph;
  NSScreen *screen = self.clipboardWindow.screen ?: [NSScreen mainScreen];
  NSRect vis = screen.visibleFrame;
  if (x < vis.origin.x + 8) x = wf.origin.x + wf.size.width + 12;
  if (x + pw > vis.origin.x + vis.size.width - 8) x = vis.origin.x + vis.size.width - pw - 8;
  if (y < vis.origin.y + 8) y = vis.origin.y + 8;
  if (y + ph > vis.origin.y + vis.size.height - 8) y = vis.origin.y + vis.size.height - ph - 8;
  [self.clipboardPreviewPanel setFrame:NSMakeRect(x, y, pw, ph) display:YES];
  self.clipboardPreviewImageView.frame = NSMakeRect(0,0,pw,ph);
  self.clipboardPreviewScroll.frame = NSInsetRect(NSMakeRect(0,0,pw,ph), 14, 14);
  [self.clipboardPreviewPanel orderFrontRegardless];
}

- (void)hideClipboardPreview {
  self.clipboardPreviewRow = -1;
  [self.clipboardPreviewPanel orderOut:nil];
}

- (void)installClipboardHoverMonitor {
  if (self.clipboardHoverMonitor) return;
  __weak typeof(self) weakSelf = self;
  self.clipboardHoverMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskMouseMoved handler:^NSEvent *(NSEvent *e) {
    if (!weakSelf.clipboardWindow.isVisible) { [weakSelf hideClipboardPreview]; return e; }
    NSPoint screen = [NSEvent mouseLocation];
    NSPoint winPt = [weakSelf.clipboardWindow convertPointFromScreen:screen];
    NSPoint tblPt = [weakSelf.clipboardTable convertPoint:winPt fromView:nil];
    NSInteger row = [weakSelf.clipboardTable rowAtPoint:tblPt];
    if (row >= 0 && row != weakSelf.clipboardPreviewRow) {
      weakSelf.clipboardPreviewRow = row;
      [weakSelf showClipboardPreviewForRow:row];
    } else if (row < 0 && weakSelf.clipboardPreviewRow >= 0) {
      weakSelf.clipboardPreviewRow = -1;
      [weakSelf hideClipboardPreview];
    }
    return e;
  }];
}

- (void)closeClipboardWindow:(id)sender { [self.clipboardWindow orderOut:nil]; }

- (NSString *)aiHistoryDir {
  NSString *dir = [[self backupBaseDir] stringByAppendingPathComponent:@"ai-history"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return dir;
}

- (void)recordAIHistorySnapshot { [self recordAIHistorySnapshotForce:NO]; }

- (void)recordAIHistorySnapshotForce:(BOOL)force {
  static NSTimeInterval lastSnapshot = 0;
  NSTimeInterval now = [NSDate timeIntervalSinceReferenceDate];
  if (!force && lastSnapshot > 0 && now - lastSnapshot < 300) return;
  if (!self.aiEntries.count) return;
  lastSnapshot = now;
  NSMutableArray *sanitized = [NSMutableArray array];
  for (NSDictionary *e in self.aiEntries) {
    NSMutableDictionary *m = [e mutableCopy];
    [m removeObjectForKey:@"api"];
    if (![m[@"kid"] length]) m[@"kid"] = [[NSUUID UUID] UUIDString];
    [sanitized addObject:m];
  }
  NSDateFormatter *df = [[NSDateFormatter alloc] init];
  df.dateFormat = @"yyyyMMdd-HHmmss";
  NSString *name = [[df stringFromDate:[NSDate date]] stringByAppendingString:@".json"];
  NSString *path = [[self aiHistoryDir] stringByAppendingPathComponent:name];
  NSData *d = [NSJSONSerialization dataWithJSONObject:sanitized options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:path atomically:YES];
  [self pruneAIHistory];
}

- (NSInteger)aiHistoryRetentionDays {
  if (![[NSUserDefaults standardUserDefaults] objectForKey:@"centerAIHistoryDays"]) return 30;
  return [[NSUserDefaults standardUserDefaults] integerForKey:@"centerAIHistoryDays"];
}

- (void)pruneAIHistory {
  NSFileManager *fm = [NSFileManager defaultManager];
  NSString *dir = [self aiHistoryDir];
  NSArray *files = [[fm contentsOfDirectoryAtPath:dir error:NULL] ?: @[] sortedArrayUsingSelector:@selector(compare:)];
  NSInteger days = [self aiHistoryRetentionDays];
  NSDate *cutoff = days > 0 ? [NSDate dateWithTimeIntervalSinceNow:-days * 86400.0] : nil;
  NSDateFormatter *fmt = [[NSDateFormatter alloc] init];
  fmt.dateFormat = @"yyyyMMdd-HHmmss";
  for (NSString *f in files) {
    if (![f.pathExtension.lowercaseString isEqualToString:@"json"]) continue;
    NSDate *date = [fmt dateFromString:f.stringByDeletingPathExtension];
    if (cutoff && date && [date compare:cutoff] == NSOrderedAscending) {
      [fm removeItemAtPath:[dir stringByAppendingPathComponent:f] error:NULL];
    }
  }
  files = [[fm contentsOfDirectoryAtPath:dir error:NULL] ?: @[] sortedArrayUsingSelector:@selector(compare:)];
  if (files.count > 20) {
    for (NSUInteger i = 0; i + 20 < files.count; i++) {
      [fm removeItemAtPath:[dir stringByAppendingPathComponent:files[i]] error:NULL];
    }
  }
}

- (void)deleteAllAIHistory:(id)sender {
  NSFileManager *fm = [NSFileManager defaultManager];
  NSString *dir = [self aiHistoryDir];
  NSArray *files = [fm contentsOfDirectoryAtPath:dir error:NULL] ?: @[];
  NSInteger count = 0;
  for (NSString *f in files) if ([f.pathExtension.lowercaseString isEqualToString:@"json"]) count++;
  if (!count) { [self showToast:@"暂无历史版本"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = [NSString stringWithFormat:@"删除全部 %ld 个历史版本？", (long)count];
  a.informativeText = @"此操作不可恢复；当前 AI 服务数据不会被删除。";
  [a addButtonWithTitle:@"删除全部"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSInteger ok = 0;
  for (NSString *f in files) {
    if (![f.pathExtension.lowercaseString isEqualToString:@"json"]) continue;
    if ([fm removeItemAtPath:[dir stringByAppendingPathComponent:f] error:NULL]) ok++;
  }
  [self showToast:[NSString stringWithFormat:@"已删除 %ld 个历史版本", (long)ok]];
}

- (void)saveAIHistoryNow:(id)sender {
  [self recordAIHistorySnapshotForce:YES];
  [self showToast:@"已保存当前 AI 数据版本"];
}

- (void)showAIHistory:(id)sender {
  [self pruneAIHistory];
  NSFileManager *fm = [NSFileManager defaultManager];
  NSString *dir = [self aiHistoryDir];
  NSArray *files = [[fm contentsOfDirectoryAtPath:dir error:NULL] sortedArrayUsingSelector:@selector(compare:)] ?: @[];
  if (!files.count) { [self showToast:@"暂无历史版本，修改 AI 数据后会自动生成"]; return; }

  NSView *accessory = [[NSView alloc] initWithFrame:NSMakeRect(0,0,520,82)];
  NSTextField *versionLabel = [self label:@"历史版本" size:10.5 bold:YES color:[NSColor secondaryLabelColor]];
  versionLabel.frame = NSMakeRect(0, 62, 80, 18); [accessory addSubview:versionLabel];
  NSPopUpButton *popup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0, 34, 340, 28) pullsDown:NO];
  NSDateFormatter *inFmt = [[NSDateFormatter alloc] init]; inFmt.dateFormat = @"yyyyMMdd-HHmmss";
  NSDateFormatter *outFmt = [[NSDateFormatter alloc] init]; outFmt.dateFormat = @"yyyy-MM-dd HH:mm:ss";
  for (NSString *f in [files reverseObjectEnumerator]) {
    NSString *stamp = [f stringByDeletingPathExtension];
    NSDate *date = [inFmt dateFromString:stamp];
    NSString *label = date ? [outFmt stringFromDate:date] : stamp;
    [popup addItemWithTitle:label];
    popup.lastItem.representedObject = f;
  }
  [accessory addSubview:popup];
  NSTextField *retLabel = [self label:@"自动清除" size:10.5 bold:YES color:[NSColor secondaryLabelColor]];
  retLabel.frame = NSMakeRect(0, 6, 75, 18); [accessory addSubview:retLabel];
  NSPopUpButton *retPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(78, 0, 180, 26) pullsDown:NO];
  NSArray *retTitles = @[@"7 天", @"30 天", @"90 天", @"永久"];
  NSArray *retDays = @[@7, @30, @90, @0];
  for (NSInteger i = 0; i < retTitles.count; i++) {
    [retPopup addItemWithTitle:retTitles[i]];
    retPopup.lastItem.representedObject = retDays[i];
  }
  NSInteger curDays = [self aiHistoryRetentionDays];
  for (NSMenuItem *mi in retPopup.itemArray) if ([mi.representedObject integerValue] == curDays) { [retPopup selectItem:mi]; break; }
  [accessory addSubview:retPopup];
  ColorHoverButton *saveNow = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(268, 0, 120, 26)];
  saveNow.title = @"立即保存版本"; saveNow.hoverColor = [NSColor systemGreenColor];
  saveNow.target = self; saveNow.action = @selector(saveAIHistoryNow:);
  [saveNow applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
  [accessory addSubview:saveNow];
  ColorHoverButton *deleteAll = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(396, 0, 116, 26)];
  deleteAll.title = @"删除全部"; deleteAll.hoverColor = [NSColor systemRedColor];
  deleteAll.target = self; deleteAll.action = @selector(deleteAllAIHistory:);
  [deleteAll applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
  [accessory addSubview:deleteAll];

  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"AI 数据历史版本";
  a.informativeText = @"恢复会覆盖当前 AI 服务列表，恢复前会自动保存当前版本；API Key 单独保存，按条目标识保留。";
  a.accessoryView = accessory;
  [a addButtonWithTitle:@"恢复此版本"];
  [a addButtonWithTitle:@"删除此版本"];
  [a addButtonWithTitle:@"取消"];
  a.window.level = NSStatusWindowLevel + 2;
  [NSApp activateIgnoringOtherApps:YES];
  NSModalResponse resp = [a runModal];

  NSInteger selectedDays = [retPopup.selectedItem.representedObject integerValue];
  [[NSUserDefaults standardUserDefaults] setInteger:selectedDays forKey:@"centerAIHistoryDays"];

  if (resp == NSAlertThirdButtonReturn) return;
  NSString *selected = popup.selectedItem.representedObject;
  NSString *path = [dir stringByAppendingPathComponent:selected ?: @""];
  if (resp == NSAlertSecondButtonReturn) {
    [fm removeItemAtPath:path error:NULL];
    [self showToast:@"已删除该历史版本"];
    return;
  }
  NSData *d = [NSData dataWithContentsOfFile:path];
  if (!d.length) { [self showToast:@"历史版本读取失败"]; return; }
  [self recordAIHistorySnapshotForce:YES];
  [d writeToFile:[self aiStorePath] atomically:YES];
  self.aiEntries = nil;
  [self loadAIEntries];
  for (NSInteger i = 0; i < (NSInteger)self.aiEntries.count; i++) {
    if (![self.aiEntries[i] isKindOfClass:[NSDictionary class]]) continue;
    NSMutableDictionary *e = [self.aiEntries[i] mutableCopy];
    NSString *kid = e[@"kid"];
    if (kid.length && ![e[@"api"] length]) {
      NSString *stored = AIKeychainGet(kid);
      if (stored.length) e[@"api"] = stored;
    }
    self.aiEntries[i] = e;
  }
  [self rebuildAIDisplay];
  [self showToast:@"已恢复 AI 数据历史版本，恢复前状态已自动保存"];
}

- (NSString *)runLocalTool:(NSString *)tool args:(NSArray *)args {
  NSTask *t=[[NSTask alloc] init]; t.launchPath=tool; t.arguments=args;
  NSPipe *pipe=[NSPipe pipe]; t.standardOutput=pipe; t.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[t launch];}@catch(NSException *e){return @"";}
  NSData *d=[pipe.fileHandleForReading readDataToEndOfFile]; [t waitUntilExit];
  return [[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding] ?: @"";
}

