- (void)ollamaMarketReload:(id)sender {
  NSMutableArray *all=[NSMutableArray array];
  for(NSDictionary *x in [self ollamaCuratedModels])[all addObject:[x mutableCopy]];
  NSSet *baseNames=[NSSet setWithArray:[all valueForKey:@"name"]];
  for(NSDictionary *x in [self cachedMarketEntriesNamed:@"ollama"]) if(x[@"name"] && ![baseNames containsObject:x[@"name"]])[all addObject:[x mutableCopy]];
  self.ollamaMarketModels=all; [self ollamaMarketFilterChanged:nil];
  self.ollamaMarketStatus.stringValue=[NSString stringWithFormat:@"已显示 %ld 个（含缓存），正在后台更新…",(long)all.count];
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{
    NSMutableArray *working=[all mutableCopy];
    NSMutableSet *known=[NSMutableSet set];
    for(NSDictionary *m in working)[known addObject:m[@"name"]];
    double memGB=[NSProcessInfo processInfo].physicalMemory/1073741824.0;
    NSString *installedOut=[self runLocalTool:@"/opt/homebrew/bin/ollama" args:@[@"list"]];
    NSMutableSet *installed=[NSMutableSet set];
    for(NSString *line in [installedOut componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]){
      NSString *x=[line stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
      if(!x.length||[x hasPrefix:@"NAME "])continue;
      NSString *n=[x componentsSeparatedByCharactersInSet:NSCharacterSet.whitespaceCharacterSet].firstObject;
      if(n.length)[installed addObject:n];
    }
    NSString *html=[NSString stringWithContentsOfURL:[NSURL URLWithString:@"https://ollama.com/library"] encoding:NSUTF8StringEncoding error:NULL];
    if(html.length){
      NSRegularExpression *re=[NSRegularExpression regularExpressionWithPattern:@"href=\"/library/([^\"#?]+)\"" options:0 error:NULL];
      for(NSTextCheckingResult *r in [re matchesInString:html options:0 range:NSMakeRange(0,html.length)]){
        NSString *name=[html substringWithRange:[r rangeAtIndex:1]];
        if(!name.length||[known containsObject:name])continue;
        [known addObject:name];
        [working addObject:[@{@"name":name,@"category":[self ollamaCategoryForName:name],@"size":@"未知",@"desc":@"Ollama 官方模型库",@"recommended":@NO} mutableCopy]];
      }
    }
    for(NSMutableDictionary *m in working){
      if([installed containsObject:m[@"name"]])m[@"installed"]=@YES;
      NSString *sz=m[@"size"] ?: @"";
      double g=0;
      if([sz hasSuffix:@"GB"])g=[sz doubleValue];
      else if([sz hasSuffix:@"MB"])g=[sz doubleValue]/1024.0;
      BOOL rec=NO;
      if(g>0){
        if(memGB<12)rec=(g<=2.5);
        else if(memGB<20)rec=(g<=6.0);
        else rec=(g<=12.0);
      }
      m[@"recommended"]=@(rec);
    }
    [self saveMarketEntries:working named:@"ollama"];
    dispatch_async(dispatch_get_main_queue(),^{
      self.ollamaMarketModels=working;
      [self ollamaMarketFilterChanged:nil];
      self.ollamaMarketStatus.stringValue=[NSString stringWithFormat:@"共 %ld 个模型，已安装 %ld 个",(long)working.count,(long)installed.count];
    });
  });
}

- (void)ollamaMarketFilterChanged:(id)sender {
  NSString *q=[self.ollamaMarketSearch.stringValue lowercaseString] ?: @"";
  NSString *cat=self.ollamaMarketCategory.titleOfSelectedItem ?: @"全部";
  NSMutableArray *out=[NSMutableArray array];
  for(NSDictionary *m in self.ollamaMarketModels){
    if(q.length && ![[(m[@"name"] ?: @"") lowercaseString] containsString:q])continue;
    if([cat isEqualToString:@"推荐"] && ![m[@"recommended"] boolValue])continue;
    if(![cat isEqualToString:@"全部"] && ![cat isEqualToString:@"推荐"] && !([m[@"category"] isEqualToString:cat]))continue;
    [out addObject:m];
  }
  self.ollamaMarketFiltered=out;
  [self.ollamaMarketTable reloadData];
}

- (void)cancelOllamaPull:(id)sender {
  if(!self.ollamaPullTask){self.ollamaMarketStatus.stringValue=@"没有正在进行的下载";return;}
  [self.ollamaPullTask terminate]; self.ollamaPullTask=nil;
  self.ollamaMarketStatus.stringValue=@"已取消下载";
}

- (void)ollamaMarketInstall:(id)sender {
  NSInteger row=self.ollamaMarketTable.selectedRow;
  if(row<0||row>=(NSInteger)self.ollamaMarketFiltered.count){self.ollamaMarketStatus.stringValue=@"请先选择模型";return;}
  NSDictionary *m=self.ollamaMarketFiltered[row];
  if([m[@"installed"] boolValue]){self.ollamaMarketStatus.stringValue=@"该模型已安装";return;}
  NSString *name=m[@"name"] ?: @""; if(!name.length)return;
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=[NSString stringWithFormat:@"下载 %@？",name];
  a.informativeText=@"从 Ollama 官方模型库下载；支持取消。";
  [a addButtonWithTitle:@"下载"]; [a addButtonWithTitle:@"取消"];
  if([a runModal]!=NSAlertFirstButtonReturn)return;
  if(self.ollamaPullTask || self.marketDownloadTask || self.videoDownloadTask){self.ollamaMarketStatus.stringValue=@"已有下载任务在进行，请等待或取消";return;}
  self.ollamaMarketStatus.stringValue=[NSString stringWithFormat:@"正在拉取 %@…",name];
  NSTask *t=[[NSTask alloc] init]; t.launchPath=@"/opt/homebrew/bin/ollama"; t.arguments=@[@"pull",name];
  NSPipe *err=[NSPipe pipe]; t.standardError=err; t.standardOutput=[NSFileHandle fileHandleWithNullDevice];
  __weak typeof(self) weakSelf=self;
  err.fileHandleForReading.readabilityHandler=^(NSFileHandle *h){
    NSData *d=h.availableData; if(!d.length)return;
    NSString *s=[[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding] ?: @"";
    NSRange pct=[s rangeOfString:@"%" options:NSBackwardsSearch];
    if(pct.location!=NSNotFound){
      NSInteger st=MAX(0,(NSInteger)pct.location-4);
      NSString *num=[s substringWithRange:NSMakeRange(st,pct.location-st)];
      num=[num stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
      dispatch_async(dispatch_get_main_queue(),^{weakSelf.ollamaMarketStatus.stringValue=[NSString stringWithFormat:@"正在拉取 %@ · %@%%",name,num];});
    }
  };
  t.terminationHandler=^(NSTask *task){
    err.fileHandleForReading.readabilityHandler=nil;
    dispatch_async(dispatch_get_main_queue(),^{
      weakSelf.ollamaPullTask=nil;
      weakSelf.ollamaMarketStatus.stringValue=(task.terminationStatus==0)?[NSString stringWithFormat:@"%@ 下载完成",name]:@"下载失败/已取消";
      [weakSelf ollamaMarketReload:nil];
    });
  };
  @try{[t launch];self.ollamaPullTask=t;}@catch(NSException *e){self.ollamaPullTask=nil;self.ollamaMarketStatus.stringValue=@"启动失败";}
}

