}

- (NSArray *)videoBackendCatalog {
  double mem=[NSProcessInfo processInfo].physicalMemory/1073741824.0;
  BOOL svd=mem>=16, hunyuan=mem>=24, ltx=mem>=12;
  NSMutableArray *a=[NSMutableArray array];
  for(NSDictionary *x in @[
    @{@"name":@"AnimateDiff + SD1.5",@"file":@"mm_sd_v15_v2.ckpt",@"category":@"AnimateDiff",@"size":@"3.8 GB",@"desc":@"文生视频/图生视频，8GB 唯一稳定方案",@"recommended":@YES,@"installed":@YES},
    @{@"name":@"mm_sd_v15_v2.ckpt",@"file":@"mm_sd_v15_v2.ckpt",@"category":@"AnimateDiff",@"size":@"1.7 GB",@"desc":@"已安装的运动模块",@"recommended":@YES,@"installed":@YES},
    @{@"name":@"Realistic Vision V6.0（写实）",@"file":@"Realistic_Vision_V6.0_NV_B1.safetensors",@"repo":@"SG161222/Realistic_Vision_V6.0_B1_noVAE",@"category":@"SD1.5 写实",@"size":@"约 2.0 GB",@"desc":@"写实猫/人像，SD1.5 + AnimateDiff 可用",@"recommended":@YES,@"target":@"checkpoints",@"format":@"SD1.5 写实底模",@"platform":@"ComfyUI / A1111 / Forge"},
    @{@"name":@"Anything V5（动漫）",@"file":@"AnythingV5V3_v5PrtRE.safetensors",@"repo":@"ckpt/anything-v5.0",@"category":@"SD1.5 动漫",@"size":@"约 2.0 GB",@"desc":@"动漫赛璐璐风格，SD1.5 + AnimateDiff 可用",@"recommended":@YES,@"target":@"checkpoints",@"format":@"SD1.5 动漫底模",@"platform":@"ComfyUI / A1111 / Forge"},
    @{@"name":@"Stable Video Diffusion",@"file":@"svd.safetensors",@"repo":@"stabilityai/stable-video-diffusion-img2vid",@"category":@"Stable Video Diffusion",@"size":@"9.5 GB",@"desc":@"图片转视频，建议 16GB 以上",@"recommended":@(svd)},
    @{@"name":@"SVD-XT",@"file":@"svd_xt.safetensors",@"repo":@"stabilityai/stable-video-diffusion-img2vid-xt",@"category":@"Stable Video Diffusion",@"size":@"9.5 GB",@"desc":@"更长帧数图生视频",@"recommended":@(svd)},
    @{@"name":@"HunyuanVideo BF16",@"file":@"hunyuan_video_t2v_720p_bf16.safetensors",@"repo":@"tencent/HunyuanVideo",@"category":@"HunyuanVideo",@"size":@"约 25 GB",@"desc":@"高质量文生视频，建议 24GB 以上",@"recommended":@(hunyuan)},
    @{@"name":@"HunyuanVideo FP8",@"file":@"hunyuan_video_t2v_720p_fp8_e4m3fn.safetensors",@"repo":@"tencent/HunyuanVideo",@"category":@"HunyuanVideo",@"size":@"约 15 GB",@"desc":@"HunyuanVideo 量化版，24GB 以上",@"recommended":@(hunyuan)},
    @{@"name":@"LTX-Video 2B",@"file":@"ltx-video-2b-v0.9.5.safetensors",@"repo":@"Lightricks/LTX-Video",@"category":@"LTX-Video",@"size":@"约 4.5 GB",@"desc":@"快速文生视频，建议 12GB 以上",@"recommended":@(ltx)}
  ]) [a addObject:[x mutableCopy]];
  NSString *dir=[self videoMarketDirectory];
  for(NSMutableDictionary *m in a){
    if([m[@"installed"] boolValue])continue;
    NSString *catDir=m[@"category"] ?: @"其他"; NSString *fname=m[@"file"] ?: @"";
    NSString *p;
    if([m[@"target"] isEqualToString:@"checkpoints"])p=[[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/models/checkpoints"] stringByAppendingPathComponent:fname];
    else p=[dir stringByAppendingPathComponent:[catDir stringByAppendingPathComponent:fname]];
    if([[NSFileManager defaultManager] fileExistsAtPath:p])m[@"installed"]=@YES;
    if(m[@"repo"] && !m[@"url"])m[@"url"]=[NSString stringWithFormat:@"https://hf-mirror.com/%@/resolve/main/%@",m[@"repo"],m[@"file"]];
    NSString *cat=m[@"category"] ?: @"";
    if([cat isEqualToString:@"AnimateDiff"]){
      if([m[@"file"] hasSuffix:@"mm_sd_v15_v2.ckpt"]){m[@"format"]=@"运动模块";m[@"platform"]=@"ComfyUI / A1111 扩展";}
      else {m[@"format"]=@"SD1.5 底模";m[@"platform"]=@"通用：ComfyUI / A1111 / Forge";}
    } else if([cat isEqualToString:@"Stable Video Diffusion"]){m[@"format"]=@"SVD 专用模型";m[@"platform"]=@"仅 ComfyUI / Diffusers 工作流";}
    else if([cat isEqualToString:@"HunyuanVideo"]){m[@"format"]=@"Hunyuan 专用模型";m[@"platform"]=@"仅 ComfyUI / Diffusers 工作流";}
    else if([cat isEqualToString:@"LTX-Video"]){m[@"format"]=@"LTX 专用模型";m[@"platform"]=@"仅 ComfyUI / Diffusers 工作流";}
    if(!m[@"format"])m[@"format"]=@"视频模型";
    if(!m[@"platform"])m[@"platform"]=@"需确认";
  }
  return a;
}

- (NSString *)videoMarketCachePath {
  NSString *dir=[NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"video_market_latest.json"];
}

- (NSArray *)videoMarketCachedLatest {
  NSData *d=[NSData dataWithContentsOfFile:[self videoMarketCachePath]];
  id o=d?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
  return [o isKindOfClass:[NSArray class]]?o:@[];
}

- (void)saveVideoMarketLatest:(NSArray *)latest {
  NSData *d=[NSJSONSerialization dataWithJSONObject:latest options:0 error:NULL];
  [d writeToFile:[self videoMarketCachePath] atomically:YES];
}

- (void)videoModelMarketRefreshLatest:(id)sender {
  NSArray *cached=[self videoMarketCachedLatest];
  NSMutableArray *immediate=[[self videoBackendCatalog] mutableCopy];
  NSSet *baseRepos=[NSSet setWithArray:[immediate valueForKey:@"repo"]];
  for(NSDictionary *m in cached) if(m[@"repo"] && ![baseRepos containsObject:m[@"repo"]])[immediate addObject:m];
  self.videoModelMarketModels=immediate;
  [self videoModelMarketFilterChanged:nil];
  self.videoModelMarketStatus.stringValue=[NSString stringWithFormat:@"已显示 %ld 个（含缓存），正在后台检查更新…",(long)immediate.count];
  __weak typeof(self) weakSelf=self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{
    NSURLSessionConfiguration *cfg=[NSURLSessionConfiguration ephemeralSessionConfiguration];
    cfg.timeoutIntervalForRequest=6; cfg.timeoutIntervalForResource=8;
    NSURLSession *session=[NSURLSession sessionWithConfiguration:cfg];
    dispatch_group_t group=dispatch_group_create();
    NSMutableArray *fresh=[NSMutableArray array];
    for(NSString *tag in @[@"text-to-video",@"image-to-video"]){
      NSString *url=[NSString stringWithFormat:@"https://huggingface.co/api/models?search=%@&sort=lastModified&direction=-1&limit=6",tag];
      dispatch_group_enter(group);
      [[session dataTaskWithURL:[NSURL URLWithString:url] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
        id arr=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
        if([arr isKindOfClass:[NSArray class]]){
          @synchronized(fresh){
            for(NSDictionary *x in arr){
              NSString *rid=x[@"id"]; if(!rid.length)continue;
              [fresh addObject:@{@"name":rid,@"repo":rid,@"file":@"",@"category":@"最新",@"size":@"未知",@"desc":[NSString stringWithFormat:@"Hugging Face 最新视频模型（%@，实验）",tag],@"recommended":@NO,@"format":@"Hugging Face 模型",@"platform":@"需确认，可能不兼容 ComfyUI"}];
            }
          }
        }
        dispatch_group_leave(group);
      }] resume];
    }
    dispatch_group_wait(group,dispatch_time(DISPATCH_TIME_NOW,(int64_t)(10*NSEC_PER_SEC)));
    dispatch_async(dispatch_get_main_queue(),^{
      NSMutableArray *all=[[weakSelf videoBackendCatalog] mutableCopy];
      NSMutableSet *known=[NSMutableSet set];
      for(NSDictionary *m in all) if(m[@"repo"])[known addObject:m[@"repo"]];
      for(NSDictionary *m in fresh) if(m[@"repo"] && ![known containsObject:m[@"repo"]]){[known addObject:m[@"repo"]];[all addObject:m];}
      if(fresh.count)[weakSelf saveVideoMarketLatest:fresh];
      weakSelf.videoModelMarketModels=all;
      [weakSelf videoModelMarketFilterChanged:nil];
      weakSelf.videoModelMarketStatus.stringValue=fresh.count?[NSString stringWithFormat:@"已更新：%ld 个视频模型",(long)all.count]:@"网络暂不可用，已使用内置/缓存列表";
    });
  });
}

- (void)videoModelMarketDownload:(id)sender {
  if(self.videoDownloadTask || self.marketDownloadTask || self.ollamaPullTask){self.videoModelMarketStatus.stringValue=@"已有下载任务在进行，请等待或取消";return;}
  NSInteger row=self.videoModelMarketTable.selectedRow;
  if(row<0||row>=(NSInteger)self.videoModelMarketFiltered.count){self.videoModelMarketStatus.stringValue=@"请先选择模型";return;}
  NSDictionary *m=self.videoModelMarketFiltered[row];
  if([m[@"installed"] boolValue]){self.videoModelMarketStatus.stringValue=@"该模型已下载";return;}
  NSString *url=m[@"url"] ?: @"";
  if(!url.length && m[@"repo"]){
    NSString *api=[NSString stringWithFormat:@"https://huggingface.co/api/models/%@?blobs=true",m[@"repo"]];
    NSData *d=[NSData dataWithContentsOfURL:[NSURL URLWithString:api]];
    id o=d?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
    NSArray *sib=[o isKindOfClass:[NSDictionary class]]?o[@"siblings"]:nil;
    for(NSDictionary *x in sib){NSString *fn=x[@"rfilename"];if([fn.pathExtension.lowercaseString isEqualToString:@"safetensors"]){url=[NSString stringWithFormat:@"https://hf-mirror.com/%@/resolve/main/%@",m[@"repo"],fn];break;}}
  }
  if(!url.length){self.videoModelMarketStatus.stringValue=@"未找到可下载的 safetensors 文件";return;}
  NSString *name=m[@"file"]; if(!name.length)name=url.lastPathComponent;
  NSString *dir;
  if([m[@"target"] isEqualToString:@"checkpoints"])dir=[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/models/checkpoints"];
  else dir=[[self videoMarketDirectory] stringByAppendingPathComponent:m[@"category"] ?: @"其他"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  NSString *dst=[dir stringByAppendingPathComponent:name];
  NSDictionary *fs=[[NSFileManager defaultManager] attributesOfFileSystemForPath:dir error:NULL];
  unsigned long long free=[fs[NSFileSystemFreeSize] unsignedLongLongValue];
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=[NSString stringWithFormat:@"下载 %@？",name];
  a.informativeText=[NSString stringWithFormat:@"大小约 %@，剩余磁盘约 %.1f GB，保存到：\n%@",m[@"size"] ?: @"未知",free/1073741824.0,dir];
  [a addButtonWithTitle:@"下载"]; [a addButtonWithTitle:@"取消"];
  if([a runModal]!=NSAlertFirstButtonReturn)return;
  if(free<2ULL*1024*1024*1024){self.videoModelMarketStatus.stringValue=@"磁盘剩余空间不足 2GB";return;}
  self.videoDownloadName=name; self.videoDownloadDest=dst; self.videoDownloadStart=[NSDate date];
  self.videoModelMarketStatus.stringValue=[NSString stringWithFormat:@"正在下载 %@…",name];
  NSURLSessionConfiguration *cfg=[NSURLSessionConfiguration defaultSessionConfiguration];
  self.videoDownloadSession=[NSURLSession sessionWithConfiguration:cfg delegate:self delegateQueue:[NSOperationQueue mainQueue]];
  self.videoDownloadTask=[self.videoDownloadSession downloadTaskWithURL:[NSURL URLWithString:url]];
  [self.videoDownloadTask resume];
}

- (void)cancelVideoModelDownload:(id)sender {
  if(!self.videoDownloadTask){self.videoModelMarketStatus.stringValue=@"没有正在进行的下载";return;}
  [self.videoDownloadTask cancel]; self.videoDownloadTask=nil;
  [self.videoDownloadSession invalidateAndCancel]; self.videoDownloadSession=nil;
  self.videoModelMarketStatus.stringValue=@"已取消下载";
}

- (void)URLSession:(NSURLSession *)session downloadTask:(NSURLSessionDownloadTask *)downloadTask didWriteData:(int64_t)bytesWritten totalBytesWritten:(int64_t)totalBytesWritten totalBytesExpectedToWrite:(int64_t)totalBytesExpectedToWrite {
  if(downloadTask!=self.videoDownloadTask)return;
  if(totalBytesExpectedToWrite>0){
    double p=100.0*totalBytesWritten/totalBytesExpectedToWrite;
    double elapsed=MAX(0.1,[[NSDate date] timeIntervalSinceDate:self.videoDownloadStart ?: [NSDate date]]);
    double speed=totalBytesWritten/elapsed; double remain=speed>1?(totalBytesExpectedToWrite-totalBytesWritten)/speed:-1;
    NSString *eta=remain>=0?[NSString stringWithFormat:@" · 剩余约 %ld:%02ld",(long)((NSInteger)remain/60),(long)((NSInteger)remain%60)]:@"";
    self.videoModelMarketStatus.stringValue=[NSString stringWithFormat:@"正在下载 %@ · %.1f%% · %.1f MB/s%@（%.2f/%.2f GB）",self.videoDownloadName,p,speed/1048576.0,eta,totalBytesWritten/1073741824.0,totalBytesExpectedToWrite/1073741824.0];
  } else self.videoModelMarketStatus.stringValue=[NSString stringWithFormat:@"正在下载 %@ · %.2f GB",self.videoDownloadName,totalBytesWritten/1073741824.0];
}

- (void)URLSession:(NSURLSession *)session downloadTask:(NSURLSessionDownloadTask *)downloadTask didFinishDownloadingToURL:(NSURL *)location {
  if(downloadTask!=self.videoDownloadTask){return;}
  NSString *dst=self.videoDownloadDest;
  [[NSFileManager defaultManager] removeItemAtPath:dst error:NULL];
  NSError *mv=nil; BOOL ok=[[NSFileManager defaultManager] moveItemAtURL:location toURL:[NSURL fileURLWithPath:dst] error:&mv];
  self.videoDownloadTask=nil; [self.videoDownloadSession finishTasksAndInvalidate]; self.videoDownloadSession=nil;
  self.videoModelMarketStatus.stringValue=ok?[NSString stringWithFormat:@"%@ 下载完成",self.videoDownloadName]:[NSString stringWithFormat:@"保存失败：%@",mv.localizedDescription ?: @""];
  if(ok){[self videoModelMarketReload];[self refreshVideoGenModels];}
}

- (void)URLSession:(NSURLSession *)session task:(NSURLSessionTask *)task didCompleteWithError:(NSError *)error {
  if(task!=self.videoDownloadTask)return;
  self.videoDownloadTask=nil; [self.videoDownloadSession finishTasksAndInvalidate]; self.videoDownloadSession=nil;
  if(error) self.videoModelMarketStatus.stringValue=[NSString stringWithFormat:@"下载失败：%@",error.localizedDescription ?: @"已取消"];
}

- (void)showVideoModelMarket:(id)sender {
  if(!self.videoModelMarketWindow){
    self.videoModelMarketWindow=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,860,540) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.videoModelMarketWindow.title=@"视频模型市场"; self.videoModelMarketWindow.releasedWhenClosed=NO;
    NSView *cv=self.videoModelMarketWindow.contentView;
    NSTextField *t=[self label:@"视频模型市场" size:20 bold:YES color:nil]; t.frame=NSMakeRect(24,490,300,28); [cv addSubview:t];
    double gb=[NSProcessInfo processInfo].physicalMemory/1073741824.0;
    NSTextField *h=[self label:[NSString stringWithFormat:@"当前内存约 %.0f GB；这里只展示兼容性和性能建议，不会自动下载模型",gb] size:10 bold:NO color:[NSColor secondaryLabelColor]]; h.frame=NSMakeRect(24,466,720,18); [cv addSubview:h];
