- (NSString *)videoCheckpointStyleLabel:(NSString *)file {
  NSString *n=file.lowercaseString;
  if([n containsString:@"anything"]||[n containsString:@"anime"]||[n containsString:@"counterfeit"]||[n containsString:@"meina"])return @"动漫";
  if([n containsString:@"realistic"]||[n containsString:@"epicrealism"]||[n containsString:@"majicmix"])return @"写实";
  if([n containsString:@"v1-5"]||[n containsString:@"pruned"])return @"通用";
  return @"底模";
}

- (void)videoGenCheckpointChanged:(id)sender {
  NSMenuItem *item=self.videoGenCheckpointPopup.selectedItem;
  NSString *raw=item.representedObject ?: (self.videoGenCheckpointPopup.titleOfSelectedItem ?: @"");
  self.videoGenLastCheckpoint=raw;
  NSString *n=raw.lowercaseString;
  NSString *neg;
  if([n containsString:@"anything"]||[n containsString:@"anime"]||[n containsString:@"counterfeit"]||[n containsString:@"meina"]){
    neg=@"blurry, low quality, distorted, watermark, extra paws, extra tails, extra heads, malformed paws, extra legs, malformed ears, bad hands, extra fingers, missing fingers, fused fingers, ugly, deformed, photo, realistic, photorealistic, 3d, cgi, live action, worst quality, jpeg artifacts, noise, bad anatomy, bad proportions, extra limbs, fused limbs, missing limbs, poorly drawn face, poorly drawn paws, text, logo, cropped, flicker, ghosting, inconsistent motion";
  } else if([n containsString:@"realistic"]||[n containsString:@"epicrealism"]||[n containsString:@"majicmix"]){
    neg=@"blurry, low quality, distorted, watermark, extra paws, extra tails, extra heads, malformed paws, extra legs, malformed ears, bad hands, extra fingers, missing fingers, fused fingers, ugly, deformed, anime, cartoon, illustration, 3d render, cgi, painting, worst quality, out of focus, jpeg artifacts, noise, oversaturated, bad anatomy, bad proportions, extra limbs, fused limbs, missing limbs, poorly drawn face, poorly drawn paws, text, logo, cropped, flicker, ghosting, inconsistent motion";
  } else {
    neg=@"blurry, low quality, distorted, watermark, extra paws, extra tails, extra heads, malformed paws, extra legs, malformed ears, bad hands, extra fingers, missing fingers, fused fingers, ugly, deformed, worst quality, out of focus, jpeg artifacts, noise, grainy, oversaturated, bad anatomy, bad proportions, extra limbs, fused limbs, missing limbs, poorly drawn face, poorly drawn paws, text, logo, cropped, flicker, ghosting, inconsistent motion";
  }
  self.videoGenNegativeField.stringValue=neg;
  self.videoGenStatus.stringValue=[NSString stringWithFormat:@"已套用%@负面提示词",([n containsString:@"anything"]||[n containsString:@"anime"])?@"动漫":([n containsString:@"realistic"]?@"写实":@"通用")];
}

- (void)refreshVideoGenModels {
  NSString *ckptDir=[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/models/checkpoints"];
  NSArray *ckpts=[[NSFileManager defaultManager] contentsOfDirectoryAtPath:ckptDir error:NULL] ?: @[];
  [self.videoGenCheckpointPopup removeAllItems];
  for(NSString *f in ckpts) if([f.pathExtension.lowercaseString isEqualToString:@"safetensors"]||[f.pathExtension.lowercaseString isEqualToString:@"ckpt"]){
    NSString *label=[NSString stringWithFormat:@"%@ · %@",[f stringByDeletingPathExtension],[self videoCheckpointStyleLabel:f]];
    [self.videoGenCheckpointPopup addItemWithTitle:label];
    self.videoGenCheckpointPopup.lastItem.representedObject=f;
  }
  NSString *mmDir=[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/models/animatediff_models"];
  NSArray *mms=[[NSFileManager defaultManager] contentsOfDirectoryAtPath:mmDir error:NULL] ?: @[];
  [self.videoGenMotionPopup removeAllItems];
  for(NSString *f in mms) if([@[@"ckpt",@"safetensors"] containsObject:f.pathExtension.lowercaseString]) [self.videoGenMotionPopup addItemWithTitle:f];
  NSString *selected=self.videoGenCheckpointPopup.selectedItem.representedObject ?: @"";
  if(selected.length && ![selected isEqualToString:self.videoGenLastCheckpoint ?: @""])[self videoGenCheckpointChanged:nil];
  if(!ckpts.count) self.videoGenStatus.stringValue=@"未找到底模";
  else if(ckpts.count==1) self.videoGenStatus.stringValue=@"只有基础底模；可到「视频模型市场」下载写实/动漫底模";
  else if(!mms.count) self.videoGenStatus.stringValue=@"未找到 AnimateDiff 运动模块";
}

- (NSString *)videoGenSaveDirectory {
  NSString *p=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerVideoOutputPath"] ?: @"";
  if(!p.length)p=[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/output"];
  p=[p stringByExpandingTildeInPath];
  [[NSFileManager defaultManager] createDirectoryAtPath:p withIntermediateDirectories:YES attributes:nil error:NULL];
  return p;
}

- (void)videoGenSavePathChanged:(id)sender {
  NSString *p=[self.videoGenSavePathField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if(!p.length)p=[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/output"];
  p=[p stringByExpandingTildeInPath];
  [[NSUserDefaults standardUserDefaults] setObject:p forKey:@"centerVideoOutputPath"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [[NSFileManager defaultManager] createDirectoryAtPath:p withIntermediateDirectories:YES attributes:nil error:NULL];
  self.videoGenSavePathField.stringValue=p;
  self.videoGenStatus.stringValue=[NSString stringWithFormat:@"视频将保存到：%@",p];
}

- (void)chooseVideoGenSavePath:(id)sender {
  NSOpenPanel *p=[NSOpenPanel openPanel]; p.canChooseFiles=NO; p.canChooseDirectories=YES; p.allowsMultipleSelection=NO; p.prompt=@"选择保存目录"; p.directoryURL=[NSURL fileURLWithPath:[self videoGenSaveDirectory]];
  [p beginSheetModalForWindow:self.videoGenWindow completionHandler:^(NSModalResponse r){
    if(r!=NSModalResponseOK)return;
    self.videoGenSavePathField.stringValue=p.URL.path;
    [self videoGenSavePathChanged:nil];
  }];
}

- (void)openVideoGenOutput:(id)sender {
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:[self videoGenSaveDirectory]]];
}

- (void)checkComfyVideoReady:(void (^)(BOOL ready))completion {
  [[[NSURLSession sharedSession] dataTaskWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/system_stats"] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    completion(!e && [(NSHTTPURLResponse *)r statusCode]==200);
  }] resume];
}

- (void)ensureComfyUIForVideo {
  self.videoGenStatus.stringValue=@"正在检查 ComfyUI 服务…";
  __weak typeof(self) weakSelf=self;
  [self checkComfyVideoReady:^(BOOL ready){
    dispatch_async(dispatch_get_main_queue(),^{
      if(ready){ [weakSelf submitVideoGeneration:nil]; return; }
      weakSelf.videoGenAutoStartedComfy=YES;
      weakSelf.localComfyWanted=YES;
      weakSelf.localComfyStartAt=[[NSDate date] timeIntervalSince1970];
      [weakSelf startLocalComfyAuto];
      weakSelf.videoGenComfyPollAttempts=0;
      weakSelf.videoGenStatus.stringValue=@"ComfyUI 未运行，正在自动启动（首次约 10–30 秒）…";
      [weakSelf.videoGenComfyPollTimer invalidate];
      weakSelf.videoGenComfyPollTimer=[NSTimer scheduledTimerWithTimeInterval:2 repeats:YES block:^(NSTimer *t){
        weakSelf.videoGenComfyPollAttempts++;
        if(weakSelf.videoGenComfyPollAttempts>60){
          [t invalidate]; weakSelf.videoGenComfyPollTimer=nil;
          weakSelf.videoGenStatus.stringValue=@"ComfyUI 启动超时，请到本地服务页查看";
          return;
        }
        [weakSelf checkComfyVideoReady:^(BOOL ok){
          dispatch_async(dispatch_get_main_queue(),^{
            if(!ok)return;
            [weakSelf.videoGenComfyPollTimer invalidate]; weakSelf.videoGenComfyPollTimer=nil;
            [weakSelf submitVideoGeneration:nil];
          });
        }];
      }];
    });
  }];
}

- (void)stopComfyAfterVideoAuto {
  self.localComfyWanted=NO;
  self.localComfyAutoStarting=NO;
  if(self.localComfyTask.isRunning)[self.localComfyTask terminate];
  self.localComfyTask=nil;
  NSTask *k=[[NSTask alloc] init]; k.launchPath=@"/usr/bin/pkill"; k.arguments=@[@"-f",@"main.py --listen 127.0.0.1 --port 8188"];
  k.standardOutput=[NSFileHandle fileHandleWithNullDevice]; k.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[k launch];}@catch(NSException *e){}
  self.localAISwitchUpdating=YES; self.localComfySwitch.state=NSControlStateValueOff; self.localAISwitchUpdating=NO;
}

- (NSString *)translateVideoPromptWithOllama:(NSString *)text {
  NSString *prompt=[NSString stringWithFormat:@"Translate this Chinese video prompt into concise English. Output only the English prompt, no quotes, no explanation, keep visual details:\n%@",text];
  NSDictionary *body=@{@"model":@"qwen2.5:3b",@"prompt":prompt,@"stream":@NO,@"options":@{@"temperature":@0.1}};
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:11434/api/generate"]];
  req.HTTPMethod=@"POST"; [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"]; req.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:NULL]; req.timeoutInterval=90;
  __block NSString *out=nil; dispatch_semaphore_t sem=dispatch_semaphore_create(0);
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
    if([o isKindOfClass:[NSDictionary class]])out=o[@"response"];
    dispatch_semaphore_signal(sem);
  }] resume];
  dispatch_semaphore_wait(sem,dispatch_time(DISPATCH_TIME_NOW,(int64_t)(95*NSEC_PER_SEC)));
  if(!out.length)return nil;
  out=[out stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
  out=[out stringByTrimmingCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"\"“”'"]];
  return out.length?out:nil;
}

- (void)populateVideoTranslateProviders {
  if(!self.aiEntries)[self loadAIEntries];
  if(!self.videoGenTranslateProviderPopup)return;
  NSInteger saved=[[NSUserDefaults standardUserDefaults] integerForKey:@"centerVideoTranslateProvider"];
  [self.videoGenTranslateProviderPopup removeAllItems];
  [self.videoGenTranslateProviderPopup addItemWithTitle:@"本地 Ollama"]; self.videoGenTranslateProviderPopup.lastItem.representedObject=@(-1);
  for(NSInteger i=0;i<(NSInteger)self.aiEntries.count;i++){
    NSDictionary *e=self.aiEntries[i];
    if([e[@"localOnly"] boolValue])continue;
    if(![[self aiModelCategoryKey:e] isEqualToString:@"text"])continue;
    NSString *name=e[@"name"] ?: @"";
    if(!name.length)continue;
    NSString *shortName=[name componentsSeparatedByCharactersInSet:[NSCharacterSet whitespaceCharacterSet]].firstObject ?: name;
    [self.videoGenTranslateProviderPopup addItemWithTitle:[NSString stringWithFormat:@"API：%@",shortName]];
    self.videoGenTranslateProviderPopup.lastItem.representedObject=@(i);
  }
  NSInteger target=0;
  for(NSInteger i=0;i<self.videoGenTranslateProviderPopup.numberOfItems;i++){
    if([[self.videoGenTranslateProviderPopup itemAtIndex:i].representedObject integerValue]==saved){target=i;break;}
  }
  [self.videoGenTranslateProviderPopup selectItemAtIndex:target];
}

- (void)videoGenTranslateProviderChanged:(id)sender {
  NSInteger idx=[self.videoGenTranslateProviderPopup.selectedItem.representedObject integerValue];
  [[NSUserDefaults standardUserDefaults] setInteger:idx forKey:@"centerVideoTranslateProvider"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  self.videoGenStatus.stringValue=idx<0?@"翻译服务：本地 Ollama":@"翻译服务：云端 API";
}

- (void)translateVideoPromptWithAPIEntry:(NSDictionary *)e original:(NSString *)text {
  NSString *base=e[@"apiBase"] ?: @"", *key=e[@"api"] ?: @"", *model=e[@"model"] ?: @"";
  if([base hasSuffix:@"/chat/completions"])base=[base substringToIndex:base.length-17];
  while([base hasSuffix:@"/"])base=[base substringToIndex:base.length-1];
  if(!base.length||!key.length){self.videoGenStatus.stringValue=@"该 API 服务缺少地址或 Key";return;}
  if(!model.length)model=@"gpt-4o-mini";
  NSString *prompt=[NSString stringWithFormat:@"Translate this Chinese video prompt into concise English. Output only the English prompt, no quotes, no explanation, keep visual details:\n%@",text];
  self.videoGenStatus.stringValue=@"正在调用 API 翻译…";
  __weak typeof(self) weakSelf=self;
  [self aiFileAPICall:prompt model:model url:[base stringByAppendingString:@"/chat/completions"] key:key completion:^(NSString *answer,NSString *error){
    if(answer.length){weakSelf.videoGenPromptField.stringValue=[answer stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];weakSelf.videoGenStatus.stringValue=@"API 翻译完成，请检查后生成";}
    else weakSelf.videoGenStatus.stringValue=[NSString stringWithFormat:@"API 翻译失败：%@",error ?: @"无返回"];
  }];
}

- (void)translateVideoPromptClicked:(id)sender {
  NSString *text=[self.videoGenPromptField.stringValue stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
  if(!text.length){self.videoGenStatus.stringValue=@"请先填写提示词";return;}
  if(!ContainsChineseText(text)){self.videoGenStatus.stringValue=@"提示词已经是英文";return;}
  NSInteger provider=[self.videoGenTranslateProviderPopup.selectedItem.representedObject integerValue];
  if(provider>=0 && provider<(NSInteger)self.aiEntries.count){
    [self translateVideoPromptWithAPIEntry:self.aiEntries[provider] original:text];
    return;
  }
  self.videoGenStatus.stringValue=@"正在启动 Ollama 翻译…";
  self.localOllamaWanted=YES; self.localOllamaStartAt=[[NSDate date] timeIntervalSince1970];
  [self startLocalOllamaAuto];
  __weak typeof(self) weakSelf=self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{
    __block BOOL ready=NO;
    for(NSInteger i=0;i<45;i++){
      dispatch_semaphore_t s=dispatch_semaphore_create(0);
      __block BOOL ok=NO;
      [[[NSURLSession sharedSession] dataTaskWithURL:[NSURL URLWithString:@"http://127.0.0.1:11434/api/version"] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
        ok = (!e && [r isKindOfClass:[NSHTTPURLResponse class]] && [(NSHTTPURLResponse *)r statusCode]==200);
        dispatch_semaphore_signal(s);
      }] resume];
      dispatch_semaphore_wait(s,dispatch_time(DISPATCH_TIME_NOW,(int64_t)(2*NSEC_PER_SEC)));
      if(ok){ready=YES;break;}
      [NSThread sleepForTimeInterval:0.5];
    }
    if(!ready){dispatch_async(dispatch_get_main_queue(),^{weakSelf.videoGenStatus.stringValue=@"Ollama 未就绪，无法翻译";});return;}
    dispatch_async(dispatch_get_main_queue(),^{ weakSelf.localOllamaRunning=YES; });
    NSString *en=[weakSelf translateVideoPromptWithOllama:text];
    dispatch_async(dispatch_get_main_queue(),^{
      if(en.length){weakSelf.videoGenPromptField.stringValue=en;weakSelf.videoGenStatus.stringValue=@"已翻译成英文，请检查后生成";}
      else weakSelf.videoGenStatus.stringValue=@"翻译失败，请手动输入英文";
    });
  });
}

- (void)cancelVideoGeneration:(id)sender {
  if(!self.videoGenPromptID.length && !self.videoGenPollTimer){
    self.videoGenStatus.stringValue=@"当前没有正在生成的视频";
    return;
  }
  self.videoGenCancelled=YES;
  NSString *pid=self.videoGenPromptID ?: @"";
  self.videoGenPromptID=nil;
  [self.videoGenPollTimer invalidate]; self.videoGenPollTimer=nil;
  [self.videoGenElapsedTimer invalidate]; self.videoGenElapsedTimer=nil;
  [self.videoGenComfyPollTimer invalidate]; self.videoGenComfyPollTimer=nil;
  NSMutableURLRequest *ir=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/interrupt"]];
  ir.HTTPMethod=@"POST"; ir.HTTPBody=[@"{}" dataUsingEncoding:NSUTF8StringEncoding];
  [[[NSURLSession sharedSession] dataTaskWithRequest:ir] resume];
  if(pid.length){
    NSMutableURLRequest *qr=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/queue"]];
    qr.HTTPMethod=@"POST"; [qr setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
    qr.HTTPBody=[NSJSONSerialization dataWithJSONObject:@{@"delete":@[pid]} options:0 error:NULL];
    [[[NSURLSession sharedSession] dataTaskWithRequest:qr] resume];
  }
  if(self.videoGenAutoStartedComfy){[self stopComfyAfterVideoAuto];self.videoGenAutoStartedComfy=NO;}
  self.videoGenStatus.stringValue=@"已取消生成";
}

- (void)generateVideo:(id)sender {
  if(self.videoGenSavePathField.stringValue.length)[self videoGenSavePathChanged:nil];
  if(self.videoGenPromptID.length){self.videoGenStatus.stringValue=@"已有生成任务在进行";return;}
  if(self.videoGenBackendPopup.indexOfSelectedItem != 0){
    NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"该视频后端尚未安装";
    a.informativeText=@"Stable Video Diffusion 和 HunyuanVideo 只提供模型市场信息和性能建议，不会自动下载到本机。当前可执行的是 AnimateDiff。";
    [a addButtonWithTitle:@"好"]; [a runModal]; return;
  }
  [self ensureComfyUIForVideo];
}

- (void)submitVideoGeneration:(id)sender {
  self.videoGenCancelled=NO;
  if(self.videoGenSavePathField.stringValue.length)[self videoGenSavePathChanged:nil];
  if(self.videoGenPromptID.length){self.videoGenStatus.stringValue=@"已有生成任务在进行";return;}
  if(self.videoGenBackendPopup.indexOfSelectedItem != 0){
    NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"该视频后端尚未安装";
    a.informativeText=@"Stable Video Diffusion 和 HunyuanVideo 只提供模型市场信息和性能建议，不会自动下载到本机。当前可执行的是 AnimateDiff。";
    [a addButtonWithTitle:@"好"]; [a runModal]; return;
  }
  NSString *ckpt=self.videoGenCheckpointPopup.selectedItem.representedObject ?: (self.videoGenCheckpointPopup.titleOfSelectedItem ?: @"");
  NSString *mm=self.videoGenMotionPopup.titleOfSelectedItem ?: @"";
  if(!ckpt.length||!mm.length){self.videoGenStatus.stringValue=@"请先选择底模和运动模块";return;}
  if(self.localOllamaRunning||self.localOllamaSwitch.state==NSControlStateValueOn){
    [self stopLocalOllamaForExclusive];
    [self showToast:@"已停止 Ollama，为视频生成释放内存"];
  }
  NSInteger width=MAX(256,self.videoGenWidthField.integerValue);
  double memGB=[NSProcessInfo processInfo].physicalMemory/1073741824.0;
  if(memGB<12 && (width>320 || self.videoGenHeightField.integerValue>320 || self.videoGenFramesField.integerValue>10)){
    NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"8GB 内存可能不足";
    a.informativeText=@"建议降到 256×256、8 帧；继续使用更高参数可能生成失败或系统卡顿。";
    [a addButtonWithTitle:@"继续"]; [a addButtonWithTitle:@"取消"];
    if([a runModal]!=NSAlertFirstButtonReturn)return;
  }
  NSInteger height=MAX(256,self.videoGenHeightField.integerValue);
  NSInteger frames=MAX(4,MIN(32,self.videoGenFramesField.integerValue));
  NSInteger steps=MAX(2,MIN(30,self.videoGenStepsField.integerValue));
  NSInteger fps=MAX(1,MIN(30,self.videoGenFpsField.integerValue));
  NSInteger seed=self.videoGenSeedField.integerValue;
  self.videoGenTargetSeconds=MAX(1.0,MIN(30.0,self.videoGenDurationField.doubleValue));
  self.videoGenBaseSeconds=(fps>0)?((double)frames/(double)fps):1.0;
  NSString *pos=[(self.videoGenPromptField.stringValue ?: @"") stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
  NSString *neg=self.videoGenNegativeField.stringValue ?: @"";
  if(!pos.length){self.videoGenStatus.stringValue=@"请先填写英文提示词";return;}
  if(ContainsChineseText(pos)){
    NSAlert *a=[[NSAlert alloc] init];
    a.messageText=@"提示词需要英文";
    a.informativeText=@"AnimateDiff 使用的 SD1.5 文本编码器不支持中文，中文提示词会生成彩色噪声。\n\n请改成英文，例如：\na cute cat licking its fur, close-up, soft light, detailed fur\n\n步数建议至少 8 步。";
    [a addButtonWithTitle:@"好"]; [a runModal];
    self.videoGenStatus.stringValue=@"提示词需要英文，已停止生成";
    return;
  }
  NSDictionary *w=@{
    @"1":@{@"class_type":@"CheckpointLoaderSimple",@"inputs":@{@"ckpt_name":ckpt}},
    @"2":@{@"class_type":@"CLIPTextEncode",@"inputs":@{@"text":pos,@"clip":@[@"1",@1]}},
    @"3":@{@"class_type":@"CLIPTextEncode",@"inputs":@{@"text":neg,@"clip":@[@"1",@1]}},
    @"4":@{@"class_type":@"ADE_AnimateDiffLoaderGen1",@"inputs":@{@"model":@[@"1",@0],@"model_name":mm,@"beta_schedule":@"autoselect"}},
    @"5":@{@"class_type":@"EmptyLatentImage",@"inputs":@{@"width":@(width),@"height":@(height),@"batch_size":@(frames)}},
    @"6":@{@"class_type":@"KSampler",@"inputs":@{@"model":@[@"4",@0],@"seed":@(seed),@"steps":@(steps),@"cfg":@7,@"sampler_name":@"euler",@"scheduler":@"normal",@"positive":@[@"2",@0],@"negative":@[@"3",@0],@"latent_image":@[@"5",@0],@"denoise":@1}},
    @"7":@{@"class_type":@"VAEDecode",@"inputs":@{@"samples":@[@"6",@0],@"vae":@[@"1",@2]}},
    @"8":@{@"class_type":@"VHS_VideoCombine",@"inputs":@{@"images":@[@"7",@0],@"frame_rate":@(fps),@"loop_count":@0,@"filename_prefix":@"DockLaunchers/localvideo",@"format":@"video/h264-mp4",@"pingpong":@NO,@"save_output":@YES}}
  };
  NSData *body=[NSJSONSerialization dataWithJSONObject:@{@"prompt":w,@"client_id":@"docklaunchers"} options:0 error:NULL];
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/prompt"]];
  req.HTTPMethod=@"POST"; [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"]; req.HTTPBody=body;
  self.videoGenStatus.stringValue=@"正在提交任务…";
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    dispatch_async(dispatch_get_main_queue(),^{
      if(weakSelf.videoGenCancelled)return;
      id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
      NSString *pid=[o isKindOfClass:[NSDictionary class]]?o[@"prompt_id"]:nil;
      if(!pid.length){weakSelf.videoGenStatus.stringValue=[NSString stringWithFormat:@"提交失败：%@",e.localizedDescription ?: @"请确认 ComfyUI 已启动"]; if(weakSelf.videoGenAutoStartedComfy){[weakSelf stopComfyAfterVideoAuto];weakSelf.videoGenAutoStartedComfy=NO;} return;}
      weakSelf.videoGenPromptID=pid; weakSelf.videoGenStart=[[NSDate date] timeIntervalSince1970];
      weakSelf.videoGenStatus.stringValue=@"正在生成视频…";
      weakSelf.videoGenElapsedTimer=[NSTimer scheduledTimerWithTimeInterval:1 repeats:YES block:^(NSTimer *t){
        NSInteger sec=(NSInteger)([[NSDate date] timeIntervalSince1970]-weakSelf.videoGenStart);
        weakSelf.videoGenStatus.stringValue=[NSString stringWithFormat:@"正在生成视频… %ld 秒（8GB 可能需要几分钟）",(long)sec];
      }];
      weakSelf.videoGenPollTimer=[NSTimer scheduledTimerWithTimeInterval:3 repeats:YES block:^(NSTimer *t){[weakSelf pollVideoGeneration];}];
    });
  }] resume];
}

- (void)pollVideoGeneration {
  if(!self.videoGenPromptID.length)return;
  NSString *url=[NSString stringWithFormat:@"http://127.0.0.1:8188/history/%@",self.videoGenPromptID];
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithURL:[NSURL URLWithString:url] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
    if(![o isKindOfClass:[NSDictionary class]]||![o[weakSelf.videoGenPromptID] isKindOfClass:[NSDictionary class]])return;
    NSDictionary *hist=o[weakSelf.videoGenPromptID]; NSDictionary *outputs=hist[@"outputs"];
    NSString *found=nil;
    for(NSDictionary *node in outputs.allValues){ if(![node isKindOfClass:[NSDictionary class]])continue; for(NSString *key in @[@"gifs",@"images",@"videos"]){ NSArray *arr=node[key]; if(![arr isKindOfClass:[NSArray class]]||!arr.count)continue; NSDictionary *f=arr.firstObject; if(![f isKindOfClass:[NSDictionary class]])continue; NSString *fn=f[@"filename"]; if(fn.length){NSString *sub=f[@"subfolder"] ?: @""; found=[[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/output"] stringByAppendingPathComponent:[sub stringByAppendingPathComponent:fn]];break;} } if(found)break; }
    NSString *saved=found;
    if(found.length){
      NSString *dir=[weakSelf videoGenSaveDirectory];
      NSString *srcDir=[found stringByDeletingLastPathComponent];
      if(![srcDir isEqualToString:dir]){
        NSString *dest=[dir stringByAppendingPathComponent:found.lastPathComponent];
        if([[NSFileManager defaultManager] fileExistsAtPath:dest]){
          NSString *base=found.lastPathComponent.stringByDeletingPathExtension;
          NSString *ext=found.pathExtension;
          dest=[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"%@-%ld.%@",base,(long)[[NSDate date] timeIntervalSince1970],ext]];
        }
        if([[NSFileManager defaultManager] copyItemAtPath:found toPath:dest error:NULL])saved=dest;
      }
      double target=weakSelf.videoGenTargetSeconds, base=weakSelf.videoGenBaseSeconds;
      if(target>base+0.25 && saved.length){
        NSString *ff=[[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/venv/lib/python3.11/site-packages/imageio_ffmpeg/binaries"] stringByAppendingPathComponent:@"ffmpeg-macos-aarch64-v9.0"];
        if([[NSFileManager defaultManager] isExecutableFileAtPath:ff]){
          NSString *out=[[saved stringByDeletingPathExtension] stringByAppendingFormat:@"-%lds.mp4",(long)target];
          NSInteger loops=(NSInteger)ceil(target/base);
          NSTask *t=[[NSTask alloc] init]; t.launchPath=ff;
          t.arguments=@[@"-y",@"-stream_loop",[@(loops) stringValue],@"-i",saved,@"-t",[@(target) stringValue],@"-c",@"copy",out];
          t.standardOutput=[NSFileHandle fileHandleWithNullDevice]; t.standardError=[NSFileHandle fileHandleWithNullDevice];
          @try{[t launch];[t waitUntilExit];}@catch(NSException *e){}
          if([[NSFileManager defaultManager] fileExistsAtPath:out])saved=out;
        }
      }
    }
    if(!weakSelf.videoGenPromptID.length)return;
    dispatch_async(dispatch_get_main_queue(),^{
      if(!weakSelf.videoGenPromptID.length)return;
      [weakSelf.videoGenPollTimer invalidate]; weakSelf.videoGenPollTimer=nil;
      [weakSelf.videoGenElapsedTimer invalidate]; weakSelf.videoGenElapsedTimer=nil;
      weakSelf.videoGenPromptID=nil;
      if(saved.length){weakSelf.videoGenStatus.stringValue=[NSString stringWithFormat:@"已保存：%@",saved]; [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:saved]];}
      else weakSelf.videoGenStatus.stringValue=@"生成完成，但未找到输出文件";
      if(weakSelf.videoGenAutoStartedComfy){[weakSelf stopComfyAfterVideoAuto];weakSelf.videoGenAutoStartedComfy=NO;weakSelf.videoGenStatus.stringValue=[weakSelf.videoGenStatus.stringValue stringByAppendingString:@" · 已释放 ComfyUI 内存"];}
    });
  }] resume];
}

- (void)openLocalAIServices:(id)sender {
  if (!self.localAIWindow) {
    self.localAIWindow=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,620,520) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.localAIWindow.title=@"本地 AI 服务"; self.localAIWindow.releasedWhenClosed=NO;
    NSView *cv=self.localAIWindow.contentView;
    NSTextField *t=[self label:@"本地 AI 服务" size:20 bold:YES color:nil]; t.frame=NSMakeRect(24,472,300,28); [cv addSubview:t];
    NSTextField *h=[self label:@"打开开关启动服务，关闭开关停止；不加入 AI 服务列表" size:10 bold:NO color:[NSColor secondaryLabelColor]]; h.frame=NSMakeRect(24,450,300,18); [cv addSubview:h];
    ColorHoverButton *videoBtn=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(470,470,126,30)];
    videoBtn.title=@"视频生成…"; videoBtn.hoverColor=[NSColor systemPinkColor]; videoBtn.font=[NSFont systemFontOfSize:10];
    videoBtn.target=self; videoBtn.action=@selector(showVideoGeneration:);
    videoBtn.toolTip=@"AnimateDiff 本地视频生成";
    [videoBtn applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:videoBtn];
    ColorHoverButton *policy=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(336,470,126,30)];
    policy.title=@"运行策略…"; policy.hoverColor=[NSColor systemPurpleColor]; policy.font=[NSFont systemFontOfSize:10];
    policy.target=self; policy.action=@selector(showLocalAIRunPolicy:);
    policy.toolTip=@"选择只允许单开，或按电脑性能允许双开";
    [policy applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:policy];
    NSArray *titles=@[@"Ollama",@"ComfyUI",@"Whisper.cpp"];
    NSArray *subs=@[@"本地对话模型服务",@"本地 SD1.5 生图服务",@"语音转文字 / 会议助手 / AI 文件音视频"];
    for(NSInteger i=0;i<3;i++){
      NSBox *card=[[NSBox alloc] initWithFrame:NSMakeRect(24,330-i*104,572,88)];
      card.boxType=NSBoxCustom; card.cornerRadius=10; card.borderWidth=1; card.borderColor=[NSColor separatorColor]; card.fillColor=DLButtonBackground();
      [cv addSubview:card];
      NSTextField *tl=[self label:titles[i] size:14 bold:YES color:nil]; tl.frame=NSMakeRect(18,50,200,20); [card addSubview:tl];
      NSTextField *sl=[self label:subs[i] size:10 bold:NO color:[NSColor secondaryLabelColor]]; sl.frame=NSMakeRect(18,30,300,16); [card addSubview:sl];
      NSTextField *st=[self label:@"检查中…" size:10 bold:NO color:[NSColor secondaryLabelColor]]; st.frame=NSMakeRect(18,8,440,16); [card addSubview:st];
      NSSwitch *sw=[[NSSwitch alloc] initWithFrame:NSMakeRect(500,32,44,26)];
      sw.target=self;
      if(i==0){sw.action=@selector(localAIToggleOllama:);self.localOllamaStatus=st;self.localOllamaSwitch=sw;}
      else if(i==1){sw.action=@selector(localAIToggleComfy:);self.localComfyStatus=st;self.localComfySwitch=sw;}
      else {sw.action=@selector(localAIToggleWhisper:);self.localWhisperStatus=st;self.localWhisperSwitch=sw;}
      [card addSubview:sw];
      ColorHoverButton *manage=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(382,48,94,26)];
      manage.title=@"管理…"; manage.hoverColor=[NSColor systemPurpleColor]; manage.font=[NSFont systemFontOfSize:10];
      manage.target=self;
      manage.action=i==0?@selector(manageOllamaModels:):(i==1?@selector(manageComfyModels:):@selector(manageWhisperModels:));
      [manage applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [card addSubview:manage];
    }
    ColorHoverButton *refresh=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(24,40,100,32)];
    refresh.title=@"刷新状态"; refresh.hoverColor=[NSColor systemBlueColor]; refresh.target=self; refresh.action=@selector(refreshLocalAIServices:);
    [refresh applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:refresh];
    ColorHoverButton *log=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(132,40,120,32)];
    log.title=@"打开 ComfyUI 日志"; log.hoverColor=[NSColor systemTealColor]; log.font=[NSFont systemFontOfSize:10]; log.target=self; log.action=@selector(openLocalAIComfyLog:);
    [log applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:log];
    ColorHoverButton *quitOllamaUI=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(260,40,140,32)];
    quitOllamaUI.title=@"关闭 Ollama 界面"; quitOllamaUI.hoverColor=[NSColor systemRedColor]; quitOllamaUI.font=[NSFont systemFontOfSize:10];
    quitOllamaUI.target=self; quitOllamaUI.action=@selector(forceCloseOllamaUI:);
    quitOllamaUI.toolTip=@"如果 Ollama 窗口卡住或停在欢迎页，强制关闭界面（不影响后台服务开关）";
    [quitOllamaUI applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:quitOllamaUI];
    ColorHoverButton *freeMem=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(400,40,92,32)];
    freeMem.title=@"释放内存"; freeMem.hoverColor=[NSColor systemOrangeColor]; freeMem.font=[NSFont systemFontOfSize:10];
    freeMem.target=self; freeMem.action=@selector(releaseLocalAIMemory:);
    [freeMem applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:freeMem];
    ColorHoverButton *close=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(500,40,96,32)];
    close.title=@"关闭"; close.hoverColor=[NSColor systemGrayColor]; close.target=self; close.action=@selector(closeLocalAIServices:);
    [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:close];
    [self.localAIWindow center];
  }
  [self refreshLocalAIServices:nil];
  if(!self.localAITimer) self.localAITimer=[NSTimer scheduledTimerWithTimeInterval:3.0 repeats:YES block:^(NSTimer *t){ [self refreshLocalAIServicesSilent]; }];
  [self bringAuxiliaryWindowToFront:self.localAIWindow];
}

- (void)closeLocalAIServices:(id)sender { [self.localAITimer invalidate]; self.localAITimer=nil; [self.localAIWindow orderOut:nil]; }

- (void)releaseLocalAIMemory:(id)sender {
  self.localOllamaStatus.stringValue=@"正在释放模型内存…";
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{
    NSString *out=[self runLocalTool:@"/opt/homebrew/bin/ollama" args:@[@"ps"]];
    NSMutableArray *names=[NSMutableArray array];
    for(NSString *line in [out componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]){
      NSString *t=[line stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
      if(!t.length||[t hasPrefix:@"NAME "])continue;
      NSString *n=[t componentsSeparatedByCharactersInSet:NSCharacterSet.whitespaceCharacterSet].firstObject;
      if(n.length)[names addObject:n];
    }
    for(NSString *n in names)[self runLocalTool:@"/opt/homebrew/bin/ollama" args:@[@"stop",n]];
    NSURLSessionDataTask *task=[[NSURLSession sharedSession] dataTaskWithRequest:[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/free"]] completionHandler:nil];
    (void)task;
    NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/free"]];
    req.HTTPMethod=@"POST"; [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
    req.HTTPBody=[NSJSONSerialization dataWithJSONObject:@{@"unload_models":@YES,@"free_memory":@YES} options:0 error:NULL];
    [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:nil] resume];
    dispatch_async(dispatch_get_main_queue(),^{
      self.localOllamaStatus.stringValue=names.count?[NSString stringWithFormat:@"已释放 Ollama 模型：%@",[names componentsJoinedByString:@", "]]:@"Ollama 当前没有加载模型";
      [self refreshLocalAIServices:nil];
    });
  });
}

- (void)forceCloseOllamaUI:(id)sender {
  NSTask *t=[[NSTask alloc] init]; t.launchPath=@"/usr/bin/osascript"; t.arguments=@[@"-e",@"tell application \"Ollama\" to quit"];
  t.standardOutput=[NSFileHandle fileHandleWithNullDevice]; t.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[t launch];[t waitUntilExit];}@catch(NSException *e){}
  NSTask *k=[[NSTask alloc] init]; k.launchPath=@"/usr/bin/pkill"; k.arguments=@[@"-f",@"Ollama.app/Contents/MacOS/Ollama"];
  k.standardOutput=[NSFileHandle fileHandleWithNullDevice]; k.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[k launch];}@catch(NSException *e){}
  self.localOllamaStatus.stringValue=@"已关闭 Ollama 界面";
  [self showToast:@"已关闭 Ollama 界面"];
}

- (void)stopLocalOllamaForExclusive {
  self.localOllamaWanted=NO;
  if([[NSFileManager defaultManager] isExecutableFileAtPath:@"/opt/homebrew/bin/brew"]){
    NSTask *bt=[[NSTask alloc] init]; bt.launchPath=@"/opt/homebrew/bin/brew"; bt.arguments=@[@"services",@"stop",@"ollama"];
    bt.standardOutput=[NSFileHandle fileHandleWithNullDevice]; bt.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[bt launch];}@catch(NSException *e){}
  }
  if(self.localOllamaTask.isRunning)[self.localOllamaTask terminate];
  self.localOllamaTask=nil;
  NSTask *k=[[NSTask alloc] init]; k.launchPath=@"/usr/bin/pkill"; k.arguments=@[@"-f",@"Ollama.app/Contents/Resources/ollama serve"];
  k.standardOutput=[NSFileHandle fileHandleWithNullDevice]; k.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[k launch];}@catch(NSException *e){}
  self.localAISwitchUpdating=YES; self.localOllamaSwitch.state=NSControlStateValueOff; self.localAISwitchUpdating=NO;
  self.localOllamaStatus.stringValue=@"已停止 · 为另一个本地服务释放内存";
}

- (void)stopLocalComfyForExclusive {
  self.localComfyWanted=NO;
  if(self.localComfyTask.isRunning)[self.localComfyTask terminate];
  self.localComfyTask=nil;
  NSTask *k=[[NSTask alloc] init]; k.launchPath=@"/usr/bin/pkill"; k.arguments=@[@"-f",@"main.py --listen 127.0.0.1 --port 8188"];
  k.standardOutput=[NSFileHandle fileHandleWithNullDevice]; k.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[k launch];}@catch(NSException *e){}
  self.localAISwitchUpdating=YES; self.localComfySwitch.state=NSControlStateValueOff; self.localAISwitchUpdating=NO;
  self.localComfyStatus.stringValue=@"已停止 · 为另一个本地服务释放内存";
}

- (void)showLocalAIExclusiveAlertForOllama:(BOOL)ollama {
  if(self.localAIExclusiveAlertShown)return;
  self.localAIExclusiveAlertShown=YES;
  NSAlert *a=[[NSAlert alloc] init];
  a.messageText=@"内存不足，只能运行一个本地 AI 服务";
  a.informativeText=ollama?@"已自动关闭 ComfyUI。8GB 内存同时运行会导致系统卡顿。" : @"已自动关闭 Ollama。8GB 内存同时运行会导致系统卡顿。";
  [a addButtonWithTitle:@"好"];
  [a runModal];
}

- (void)enforceLocalAIExclusive {
  if([self localAIDualAllowed]){self.localAIExclusiveAlertShown=NO;return;}
  if(!(self.localOllamaRunning&&self.localComfyRunning)){self.localAIExclusiveAlertShown=NO;return;}
  if(self.localAIRunningOwner==2){[self stopLocalOllamaForExclusive];[self showLocalAIExclusiveAlertForOllama:NO];}
  else {[self stopLocalComfyForExclusive];[self showLocalAIExclusiveAlertForOllama:YES];}
  self.localAIRunningOwner=0;
}

- (void)startLocalOllamaAuto {
  NSString *cli=@"/opt/homebrew/bin/ollama";
  if([[NSFileManager defaultManager] isExecutableFileAtPath:@"/opt/homebrew/bin/brew"] && [[NSFileManager defaultManager] isExecutableFileAtPath:cli]){
    NSTask *bt=[[NSTask alloc] init]; bt.launchPath=@"/opt/homebrew/bin/brew"; bt.arguments=@[@"services",@"start",@"ollama"];
    bt.standardOutput=[NSFileHandle fileHandleWithNullDevice]; bt.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[bt launch];}@catch(NSException *e){}
    return;
  }
  if(![[NSFileManager defaultManager] isExecutableFileAtPath:cli])return;
  NSTask *t=[[NSTask alloc] init]; t.launchPath=cli; t.arguments=@[@"serve"];
  NSString *log=[NSTemporaryDirectory() stringByAppendingPathComponent:@"docklaunchers-ollama.log"];
  [[NSFileManager defaultManager] createFileAtPath:log contents:nil attributes:nil];
  NSFileHandle *fh=[NSFileHandle fileHandleForWritingAtPath:log];[fh seekToEndOfFile];
  t.standardOutput=fh;t.standardError=fh;
  @try{[t launch];self.localOllamaTask=t;}@catch(NSException *e){}
}

