  NSString *py=[dir stringByAppendingPathComponent:@"venv/bin/python"];
  NSString *main=[dir stringByAppendingPathComponent:@"main.py"];
  if(![[NSFileManager defaultManager] isExecutableFileAtPath:py]||![[NSFileManager defaultManager] fileExistsAtPath:main])return;
  NSTask *t=[[NSTask alloc] init]; t.launchPath=py; t.arguments=@[main,@"--listen",@"127.0.0.1",@"--port",@"8188",@"--lowvram"]; t.currentDirectoryURL=[NSURL fileURLWithPath:dir];
  NSString *log=[NSTemporaryDirectory() stringByAppendingPathComponent:@"docklaunchers-comfyui.log"];
  [[NSFileManager defaultManager] createFileAtPath:log contents:nil attributes:nil];
  NSFileHandle *fh=[NSFileHandle fileHandleForWritingAtPath:log];[fh seekToEndOfFile];
  t.standardOutput=fh;t.standardError=fh;
  @try{[t launch];self.localComfyTask=t;}@catch(NSException *e){}
}

- (void)refreshLocalAIServicesSilent { [self refreshLocalAIServices:nil]; }

- (void)refreshLocalAIServices:(id)sender {
  NSURLSession *session=[NSURLSession sharedSession];
  [[session dataTaskWithURL:[NSURL URLWithString:@"http://127.0.0.1:11434/api/version"] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    dispatch_async(dispatch_get_main_queue(),^{
      BOOL on=!e && [(NSHTTPURLResponse *)r statusCode]==200;
      self.localOllamaRunning=on;
      if(on&&self.localAIRunningOwner==0)self.localAIRunningOwner=1;
      if(on)[self enforceLocalAIExclusive];
      NSTimeInterval now=[[NSDate date] timeIntervalSince1970];
      BOOL starting=!on&&self.localOllamaWanted&&(now-self.localOllamaStartAt<90);
      self.localAISwitchUpdating=YES;
      self.localOllamaSwitch.state=(on||starting)?NSControlStateValueOn:NSControlStateValueOff;
      self.localAISwitchUpdating=NO;
      self.localOllamaStatus.stringValue=on?@"运行中 · http://127.0.0.1:11434":(starting?@"正在启动，首次约 10–20 秒…":@"已停止");
      if(!on && self.localOllamaWanted && !starting && !self.localOllamaAutoStarting && now-self.localOllamaLastAutoStart>8){
        self.localOllamaAutoStarting=YES; self.localOllamaLastAutoStart=now; self.localOllamaStartAt=now;
        [self startLocalOllamaAuto];
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(6*NSEC_PER_SEC)),dispatch_get_main_queue(),^{self.localOllamaAutoStarting=NO;});
      }
      if(on){
        [[session dataTaskWithURL:[NSURL URLWithString:@"http://127.0.0.1:11434/api/ps"] completionHandler:^(NSData *pd,NSURLResponse *pr,NSError *pe){
          id po=pd.length?[NSJSONSerialization JSONObjectWithData:pd options:0 error:NULL]:nil;
          NSArray *ms=[po isKindOfClass:[NSDictionary class]]?po[@"models"]:nil;
          NSMutableArray *names=[NSMutableArray array];
          if([ms isKindOfClass:[NSArray class]])for(NSDictionary *m in ms){if([m isKindOfClass:[NSDictionary class]]&&[m[@"name"] length])[names addObject:m[@"name"]];}
          dispatch_async(dispatch_get_main_queue(),^{
            self.localOllamaStatus.stringValue=names.count?[NSString stringWithFormat:@"运行中 · 已加载 %@",[names componentsJoinedByString:@", "]]:@"运行中 · 空闲";
          });
        }] resume];
      }
    });
  }] resume];
  [[session dataTaskWithURL:[NSURL URLWithString:@"http://127.0.0.1:8188/system_stats"] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    dispatch_async(dispatch_get_main_queue(),^{
      BOOL on=!e && [(NSHTTPURLResponse *)r statusCode]==200;
      self.localComfyRunning=on;
      if(on&&self.localAIRunningOwner==0)self.localAIRunningOwner=2;
      if(on)[self enforceLocalAIExclusive];
      NSTimeInterval now=[[NSDate date] timeIntervalSince1970];
      BOOL starting=!on&&self.localComfyWanted&&(now-self.localComfyStartAt<120);
      self.localAISwitchUpdating=YES;
      self.localComfySwitch.state=(on||starting)?NSControlStateValueOn:NSControlStateValueOff;
      self.localAISwitchUpdating=NO;
      self.localComfyStatus.stringValue=on?@"运行中 · http://127.0.0.1:8188":(starting?@"正在启动，首次约 10–30 秒…":@"已停止");
      if(!on && self.localComfyWanted && !starting && !self.localComfyAutoStarting && now-self.localComfyLastAutoStart>10){
        self.localComfyAutoStarting=YES; self.localComfyLastAutoStart=now; self.localComfyStartAt=now;
        [self startLocalComfyAuto];
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(8*NSEC_PER_SEC)),dispatch_get_main_queue(),^{self.localComfyAutoStarting=NO;});
      }
    });
  }] resume];
  NSString *exe=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerWhisperExe"] ?: @"/opt/homebrew/bin/whisper-cli";
  NSString *model=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerWhisperModel"] ?: @"";
  BOOL ready=[[NSFileManager defaultManager] isExecutableFileAtPath:exe] && [[NSFileManager defaultManager] isReadableFileAtPath:model];
  BOOL enabled=[[NSUserDefaults standardUserDefaults] integerForKey:@"centerSTTEngine"]==2;
  self.localAISwitchUpdating=YES;
  self.localWhisperSwitch.state=enabled?NSControlStateValueOn:NSControlStateValueOff;
  self.localAISwitchUpdating=NO;
  self.localWhisperStatus.stringValue=ready?(enabled?@"已启用 · 按需运行，不常驻":@"已安装 · 当前未启用"):@"未安装或模型路径未配置";
}

- (void)localAIToggleOllama:(NSSwitch *)sender {
  if(self.localAISwitchUpdating) return;
  if(sender.state==NSControlStateValueOn && self.localOllamaWanted && ([[NSDate date] timeIntervalSince1970]-self.localOllamaStartAt<30)){
    self.localOllamaStatus.stringValue=@"正在启动，请稍候…";
    self.localAISwitchUpdating=YES; sender.state=NSControlStateValueOn; self.localAISwitchUpdating=NO;
    return;
  }
  if(sender.state==NSControlStateValueOn){
    self.localOllamaWanted=YES;
    self.localOllamaStartAt=[[NSDate date] timeIntervalSince1970];
    self.localAIRunningOwner=1;
    if(![self localAIDualAllowed] && (self.localComfyRunning||self.localComfySwitch.state==NSControlStateValueOn)){
      [self stopLocalComfyForExclusive];
      [self showLocalAIExclusiveAlertForOllama:YES];
    }
    self.localOllamaStatus.stringValue=@"正在启动…";
    if([[NSFileManager defaultManager] isExecutableFileAtPath:@"/opt/homebrew/bin/brew"] && [[NSFileManager defaultManager] isExecutableFileAtPath:@"/opt/homebrew/bin/ollama"]){
      NSTask *bt=[[NSTask alloc] init]; bt.launchPath=@"/opt/homebrew/bin/brew"; bt.arguments=@[@"services",@"start",@"ollama"];
      bt.standardOutput=[NSFileHandle fileHandleWithNullDevice]; bt.standardError=[NSFileHandle fileHandleWithNullDevice];
      @try{[bt launch];[bt waitUntilExit];self.localOllamaStatus.stringValue=@"Homebrew 服务已启动";}@catch(NSException *e){self.localOllamaStatus.stringValue=@"brew 启动失败";}
      dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(2.0*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self refreshLocalAIServices:nil];});
      return;
    }
    NSString *cli=@"/Applications/Ollama.app/Contents/Resources/ollama";
    if(![[NSFileManager defaultManager] isExecutableFileAtPath:cli]) cli=@"/opt/homebrew/bin/ollama";
    if(![[NSFileManager defaultManager] isExecutableFileAtPath:cli]) { self.localOllamaStatus.stringValue=@"未安装 Ollama"; sender.state=NSControlStateValueOff; return; }
    // 直接启动后台 serve，不打开 Ollama GUI/欢迎页
    NSTask *t=[[NSTask alloc] init]; t.launchPath=cli; t.arguments=@[@"serve"];
    NSString *log=[NSTemporaryDirectory() stringByAppendingPathComponent:@"docklaunchers-ollama.log"];
    [[NSFileManager defaultManager] createFileAtPath:log contents:nil attributes:nil];
    NSFileHandle *fh=[NSFileHandle fileHandleForWritingAtPath:log]; [fh seekToEndOfFile];
    t.standardOutput=fh; t.standardError=fh;
    @try{[t launch];self.localOllamaTask=t;self.localOllamaStatus.stringValue=@"正在启动后台服务…";}
    @catch(NSException *e){self.localOllamaStatus.stringValue=@"启动失败";sender.state=NSControlStateValueOff;}
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(2.0*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self refreshLocalAIServices:nil];});
  } else {
    self.localOllamaWanted=NO;
    self.localOllamaStatus.stringValue=@"正在停止…";
    if([[NSFileManager defaultManager] isExecutableFileAtPath:@"/opt/homebrew/bin/brew"]){
      NSTask *bt=[[NSTask alloc] init]; bt.launchPath=@"/opt/homebrew/bin/brew"; bt.arguments=@[@"services",@"stop",@"ollama"];
      bt.standardOutput=[NSFileHandle fileHandleWithNullDevice]; bt.standardError=[NSFileHandle fileHandleWithNullDevice];
      @try{[bt launch];[bt waitUntilExit];self.localOllamaStatus.stringValue=@"Homebrew 服务已停止";}@catch(NSException *e){}
    }
    if(self.localOllamaTask.isRunning)[self.localOllamaTask terminate];
    self.localOllamaTask=nil;
    NSTask *t=[[NSTask alloc] init]; t.launchPath=@"/usr/bin/pkill"; t.arguments=@[@"-f",@"Ollama.app/Contents/Resources/ollama serve"];
    t.standardOutput=[NSFileHandle fileHandleWithNullDevice];t.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[t launch];}@catch(NSException *e){}
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(1.5*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self refreshLocalAIServices:nil];});
  }
}

- (void)localAIToggleComfy:(NSSwitch *)sender {
  if(self.localAISwitchUpdating) return;
  if(sender.state==NSControlStateValueOn && self.localComfyWanted && (self.localComfyTask.isRunning || [[NSDate date] timeIntervalSince1970]-self.localComfyStartAt<120)){
    self.localComfyStatus.stringValue=@"正在启动，请稍候…";
    self.localAISwitchUpdating=YES; sender.state=NSControlStateValueOn; self.localAISwitchUpdating=NO;
    return;
  }
  if(sender.state==NSControlStateValueOn){
    self.localComfyWanted=YES;
    self.localComfyStartAt=[[NSDate date] timeIntervalSince1970];
    self.localAIRunningOwner=2;
    if(![self localAIDualAllowed] && (self.localOllamaRunning||self.localOllamaSwitch.state==NSControlStateValueOn)){
      [self stopLocalOllamaForExclusive];
      [self showLocalAIExclusiveAlertForOllama:NO];
    }
    NSString *dir=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerComfyUIPath"] ?: [NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI"];
    NSString *py=[dir stringByAppendingPathComponent:@"venv/bin/python"];
    NSString *main=[dir stringByAppendingPathComponent:@"main.py"];
    if(![[NSFileManager defaultManager] isExecutableFileAtPath:py] || ![[NSFileManager defaultManager] fileExistsAtPath:main]){ self.localComfyStatus.stringValue=@"未找到 ~/ComfyUI"; sender.state=NSControlStateValueOff; return; }
    NSTask *t=[[NSTask alloc] init]; t.launchPath=py; t.arguments=@[main,@"--listen",@"127.0.0.1",@"--port",@"8188",@"--lowvram"]; t.currentDirectoryURL=[NSURL fileURLWithPath:dir];
    NSString *log=[NSTemporaryDirectory() stringByAppendingPathComponent:@"docklaunchers-comfyui.log"];
    [[NSFileManager defaultManager] createFileAtPath:log contents:nil attributes:nil];
    NSFileHandle *fh=[NSFileHandle fileHandleForWritingAtPath:log]; [fh seekToEndOfFile];
    t.standardOutput=fh; t.standardError=fh;
    @try{[t launch];self.localComfyTask=t;self.localComfyStatus.stringValue=@"正在启动…";}@catch(NSException *e){self.localComfyStatus.stringValue=@"启动失败";sender.state=NSControlStateValueOff;}
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(4.0*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self refreshLocalAIServices:nil];});
  } else {
    self.localComfyWanted=NO;
    self.localComfyStatus.stringValue=@"正在停止…";
    if(self.localComfyTask.isRunning)[self.localComfyTask terminate];
    self.localComfyTask=nil;
    NSTask *t=[[NSTask alloc] init]; t.launchPath=@"/usr/bin/pkill"; t.arguments=@[@"-f",@"main.py --listen 127.0.0.1 --port 8188"];
    t.standardOutput=[NSFileHandle fileHandleWithNullDevice];t.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[t launch];}@catch(NSException *e){}
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(2.0*NSEC_PER_SEC)),dispatch_get_main_queue(),^{[self refreshLocalAIServices:nil];});
  }
}

- (void)localAIToggleWhisper:(NSSwitch *)sender {
  if(self.localAISwitchUpdating) return;
  if(sender.state==NSControlStateValueOn){
    NSString *exe=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerWhisperExe"] ?: @"/opt/homebrew/bin/whisper-cli";
    NSString *model=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerWhisperModel"] ?: @"";
    if(![[NSFileManager defaultManager] isExecutableFileAtPath:exe] || ![[NSFileManager defaultManager] isReadableFileAtPath:model]){
      self.localWhisperStatus.stringValue=@"未安装或模型缺失"; sender.state=NSControlStateValueOff; return;
    }
    [[NSUserDefaults standardUserDefaults] setInteger:2 forKey:@"centerSTTEngine"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    self.localWhisperStatus.stringValue=@"已启用 · 按需运行，不常驻";
  } else {
    [[NSUserDefaults standardUserDefaults] setInteger:0 forKey:@"centerSTTEngine"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    self.localWhisperStatus.stringValue=@"已停用 · 使用 Apple Speech";
  }
}

- (void)openLocalAIComfyLog:(id)sender {
  NSString *log=[NSTemporaryDirectory() stringByAppendingPathComponent:@"docklaunchers-comfyui.log"];
  if([[NSFileManager defaultManager] fileExistsAtPath:log]) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:log]];
  else [self showToast:@"还没有 ComfyUI 日志"];
}

- (void)showAIKeyFilePicker:(id)sender {
  [self loadAIEntries];
  if (!self.aiEntries.count) { [self showToast:@"暂无 AI 服务"]; return; }
  NSPopUpButton *popup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0,0,320,28) pullsDown:NO];
  for (NSDictionary *e in self.aiEntries) [popup addItemWithTitle:e[@"name"] ?: @"未命名"];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"定位 API Key 文件";
  a.informativeText = @"选择 AI 服务，验证应用密码后在 Finder 中显示本地 ai_keys.json。";
  a.accessoryView = popup;
  [a addButtonWithTitle:@"继续"];
  [a addButtonWithTitle:@"取消"];
  a.window.level = NSStatusWindowLevel + 2;
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSInteger idx = popup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.aiEntries.count) return;
  NSDictionary *entry = self.aiEntries[idx];
  NSString *kid = entry[@"kid"] ?: @"";
  if (!kid.length || !AIKeychainGet(kid).length) { [self showToast:@"该服务没有保存 API Key"]; return; }
  if (![self requestAdminAuthentication]) return;
  NSString *path = AIKeysFilePath();
  if (![[NSFileManager defaultManager] fileExistsAtPath:path]) { [self showToast:@"密钥文件不存在"]; return; }
  [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:path]]];
  [self showToast:@"已在 Finder 中定位密钥文件"];
}

- (void)buildAIView {
  AIDropView *v = [[AIDropView alloc] initWithFrame:NSMakeRect(0,0,750,660)];
  v.dropTarget = self;
  v.dropAction = @selector(aiHandleDroppedFiles:);
  NSTextField *h = [self label:@"AI 管理" size:24 bold:YES color:nil];
  h.frame = NSMakeRect(24, 606, 300, 30); [v addSubview:h];
  NSTextField *sub = [self label:@"集中管理 AI 服务、API 地址与密钥；敏感操作使用应用密码" size:11 bold:NO color:[NSColor secondaryLabelColor]];
  sub.frame = NSMakeRect(24, 584, 500, 18); [v addSubview:sub];
  ColorHoverButton *keyFileBtn = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(600, 598, 126, 28)];
  keyFileBtn.title = @"历史 Key…"; keyFileBtn.hoverColor = [NSColor systemTealColor];
  keyFileBtn.target = self; keyFileBtn.action = @selector(showAIKeyFilePicker:);
  keyFileBtn.toolTip = @"选择 AI 服务，验证应用密码后定位本地密钥文件";
  [keyFileBtn applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
  [v addSubview:keyFileBtn];
  ColorHoverButton *aiFileBtn = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(324,598,124,28)];
  aiFileBtn.title=@"AI 文件…"; aiFileBtn.hoverColor=[NSColor systemPinkColor];
  aiFileBtn.target=self; aiFileBtn.action=@selector(openAIFileAnalyzer:);
  aiFileBtn.toolTip=@"导入文件、云文档并用 AI 分析";
