    self.appPasswordWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,470,340) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
