- (NSDictionary *)aiPresetForName:(NSString *)raw {
  NSString *n = [[raw lowercaseString] stringByReplacingOccurrencesOfString:@" " withString:@""];
  if (n.length < 2) return nil;
  NSDictionary *best = nil; NSUInteger bestLen = 0;
  for (NSDictionary *p in [self aiPresets]) {
    for (NSString *alias in p[@"aliases"]) {
      if ([n containsString:alias] && alias.length > bestLen) { best = p; bestLen = alias.length; }
    }
  }
  return best;
}

- (NSDictionary *)aiDefaultBaseAndModelForName:(NSString *)raw {
  NSString *name = [(raw ?: @"") lowercaseString];
  NSString *base = nil, *model = nil;
  if ([name containsString:@"comfy"]) { base = @"http://127.0.0.1:8188"; model = @"v1-5-pruned-emaonly.safetensors"; }
  else if ([name containsString:@"ollama"] || [name containsString:@"本地模型"]) { base = @"http://127.0.0.1:11434/v1"; model = @"llama3.2"; }
  else if ([name containsString:@"deepseek"] || [name containsString:@"深度求索"] || [name containsString:@"深度探索"]) { base = @"https://api.deepseek.com/v1"; model = @"deepseek-chat"; }
  else if ([name containsString:@"openai"] || [name containsString:@"chatgpt"]) { base = @"https://api.openai.com/v1"; model = @"gpt-4o-mini"; }
  else if ([name containsString:@"claude"] || [name containsString:@"anthropic"]) { base = @"https://api.anthropic.com/v1"; model = @"claude-3-5-sonnet-latest"; }
  else if ([name containsString:@"gemini"] || [name containsString:@"谷歌"]) { base = @"https://generativelanguage.googleapis.com/v1beta/openai"; model = @"gemini-1.5-flash"; }
  else if ([name containsString:@"grok"] || [name containsString:@"xai"]) { base = @"https://api.x.ai/v1"; model = @"grok-2-latest"; }
  else if ([name containsString:@"mistral"]) { base = @"https://api.mistral.ai/v1"; model = @"mistral-small-latest"; }
  else if ([name containsString:@"kimi"] || [name containsString:@"moonshot"] || [name containsString:@"月之暗面"]) { base = @"https://api.moonshot.cn/v1"; model = @"moonshot-v1-8k"; }
  else if ([name containsString:@"智谱"] || [name containsString:@"glm"]) { base = @"https://open.bigmodel.cn/api/paas/v4"; model = @"glm-4-flash"; }
  else if ([name containsString:@"千问"] || [name containsString:@"qwen"] || [name containsString:@"通义"] || [name containsString:@"百炼"]) { base = @"https://dashscope.aliyuncs.com/compatible-mode/v1"; model = @"qwen-plus"; }
  else if ([name containsString:@"文心"] || [name containsString:@"千帆"] || [name containsString:@"ernie"]) { base = @"https://qianfan.baidubce.com/v2"; model = @"ernie-4.0-8k"; }
  else if ([name containsString:@"豆包"] || [name containsString:@"方舟"] || [name containsString:@"doubao"] || [name containsString:@"volcengine"]) { base = @"https://ark.cn-beijing.volces.com/api/v3"; model = @"doubao-pro-32k"; }
  else if ([name containsString:@"混元"] || [name containsString:@"hunyuan"]) { base = @"https://api.hunyuan.cloud.tencent.com/v1"; model = @"hunyuan-lite"; }
  else if ([name containsString:@"minimax"] || [name containsString:@"海螺"]) { base = @"https://api.minimaxi.com/v1"; model = @"abab6.5s-chat"; }
  else if ([name containsString:@"百川"] || [name containsString:@"baichuan"]) { base = @"https://api.baichuan-ai.com/v1"; model = @"Baichuan4"; }
  else if ([name containsString:@"零一"] || [name containsString:@"lingyiwanwu"] || [name isEqualToString:@"yi"]) { base = @"https://api.lingyiwanwu.com/v1"; model = @"yi-lightning"; }
  else if ([name containsString:@"阶跃"] || [name containsString:@"stepfun"]) { base = @"https://api.stepfun.com/v1"; model = @"step-1-8k"; }
  else if ([name containsString:@"硅基流动"] || [name containsString:@"siliconflow"]) { base = @"https://api.siliconflow.cn/v1"; model = @"Qwen/Qwen2.5-7B-Instruct"; }
  else if ([name containsString:@"openrouter"]) { base = @"https://openrouter.ai/api/v1"; model = @"openai/gpt-4o-mini"; }
  else if ([name containsString:@"groq"]) { base = @"https://api.groq.com/openai/v1"; model = @"llama-3.1-8b-instant"; }
  else if ([name containsString:@"together"]) { base = @"https://api.together.xyz/v1"; model = @"meta-llama/Llama-3.1-8B-Instruct-Turbo"; }
  else if ([name containsString:@"fireworks"]) { base = @"https://api.fireworks.ai/inference/v1"; model = @"accounts/fireworks/models/llama-v3p1-8b-instruct"; }
  return base.length ? @{@"base": base, @"model": model ?: @""} : nil;
}

- (void)applyAIPresetAutofill {
  if (!self.dialogAIName) return;
  NSString *name = self.dialogAIName.stringValue ?: @"";
  NSDictionary *preset = nil;
  for (NSDictionary *p in [self aiPresets]) {
    if ([p[@"name"] isEqualToString:name]) { preset = p; break; }
  }
  if (!preset) preset = [self aiPresetForName:name];
  if (!preset) { self.dialogAIStatus.stringValue = @"未识别到预设服务，可手动填写地址"; return; }
  self.dialogAIEndpoint.stringValue = preset[@"url"] ?: @"";
  if (!self.dialogAINote.stringValue.length) self.dialogAINote.stringValue = preset[@"type"] ?: @"";
  NSDictionary *def = [self aiDefaultBaseAndModelForName:name];
  if (def) {
    BOOL hasSavedBase = self.dialogAIEditing && self.dialogAIBase.stringValue.length;
    BOOL hasSavedModel = self.dialogAIEditing && self.dialogAIModel.stringValue.length;
    if (!hasSavedBase) self.dialogAIBase.stringValue = def[@"base"] ?: @"";
    if (!hasSavedModel) self.dialogAIModel.stringValue = def[@"model"] ?: @"";
  }
  self.dialogAIStatus.stringValue = [NSString stringWithFormat:@"已识别：%@ · 已自动填写地址和默认模型", preset[@"name"]];
}

- (void)controlTextDidChange:(NSNotification *)note {
  if (note.object == self.batchFindField || note.object == self.batchReplaceField || note.object == self.batchPrefixField || note.object == self.batchSuffixField) {
    [self reloadBatchRenamePreview];
    return;
  }
  if (note.object != self.dialogAIName) return;
  [self applyAIPresetAutofill];
}

- (void)comboBoxSelectionDidChange:(NSNotification *)note {
  if (note.object != self.dialogAIName) return;
  NSComboBox *cb = note.object;
  NSInteger idx = cb.indexOfSelectedItem;
  if (idx >= 0 && idx < cb.numberOfItems) {
    cb.stringValue = [cb itemObjectValueAtIndex:idx];
  }
  [self applyAIPresetAutofill];
}

- (void)aiAddEntry:(id)sender { [self aiShowEntryDialogForIndex:-1]; }

- (void)fetchAIModelsForDialog:(id)sender {
  NSString *base = [self.dialogAIBase.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
  NSString *key = [self.dialogAIApi.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
  if (!base.length) { self.dialogAIStatus.stringValue = @"请先填写 API 基础地址"; return; }
  BOOL localBase = [base containsString:@"127.0.0.1"] || [base containsString:@"localhost"] || [base containsString:@"ollama"] || [base containsString:@"8188"];
  if (!key.length && localBase) key = @"ollama-local";
  if (!key.length) { self.dialogAIStatus.stringValue = @"请先填写 API Key"; return; }
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length - @"/chat/completions".length];
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length - 1];
  self.dialogAIStatus.stringValue = @"正在获取模型列表…";
  NSURL *url = [NSURL URLWithString:[base stringByAppendingString:@"/models"]];
  if (!url) { self.dialogAIStatus.stringValue = @"API 地址无效"; return; }
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:url];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.timeoutInterval = 20;
  __weak typeof(self) weakSelf = self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    NSMutableArray *models = [NSMutableArray array];
    if (data.length) {
      id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
      id list = [obj isKindOfClass:[NSDictionary class]] ? obj[@"data"] : nil;
      if ([list isKindOfClass:[NSArray class]]) for (id m in list) {
        NSString *mid = [m isKindOfClass:[NSDictionary class]] ? m[@"id"] : nil;
        if (!mid.length) continue;
        NSString *low=[mid lowercaseString];
        if([low containsString:@"embed"]||[low containsString:@"nomic"]||[low containsString:@"bge"]||[low containsString:@"mxbai"])continue;
        [models addObject:mid];
      }
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!models.count) { weakSelf.dialogAIStatus.stringValue = err.localizedDescription ?: @"未获取到模型，可手动输入"; return; }
      [models sortUsingSelector:@selector(localizedStandardCompare:)];
      NSComboBox *cb = weakSelf.dialogAIModelCombo;
      NSString *current = cb.stringValue;
      [cb removeAllItems];
      [cb addItemsWithObjectValues:models];
      if (current.length && [models containsObject:current]) cb.stringValue = current;
      else cb.stringValue = models.firstObject;
      weakSelf.dialogAIStatus.stringValue = [NSString stringWithFormat:@"已获取 %ld 个模型", (long)models.count];
    });
  }] resume];
}

- (void)aiShowEntryDialogForIndex:(NSInteger)idx {
  BOOL editing = idx >= 0 && idx < (NSInteger)self.aiEntries.count;
  self.dialogAIEditing = editing;
  NSDictionary *old = editing ? self.aiEntries[idx] : @{};
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = editing ? @"编辑 AI 服务" : @"新增 AI 服务";
  a.informativeText = @"输入 AI 名称即可自动识别并填写 API Key 获取地址；支持官方名和常用别名，例如千问 / Qwen / 通义千问。";
  [a addButtonWithTitle:@"保存"];
  [a addButtonWithTitle:@"取消"];
  NSView *av = [[NSView alloc] initWithFrame:NSMakeRect(0, 0, 500, 368)];
  NSArray *labels = @[@"名称", @"余量", @"Key 获取页", @"API Key", @"备注", @"API 基础地址", @"模型"];
  NSArray *keys = @[@"name", @"quota", @"endpoint", @"api", @"note", @"apiBase", @"model"];
  NSMutableArray *fields = [NSMutableArray array];
  for (NSInteger i = 0; i < labels.count; i++) {
    NSTextField *lab = [self label:labels[i] size:11.5 bold:NO color:[NSColor secondaryLabelColor]];
    lab.frame = NSMakeRect(8, 294 - i*38, 100, 18); [av addSubview:lab];
    NSTextField *tf;
    if (i == 0) {
      NSComboBox *cb = [[NSComboBox alloc] initWithFrame:NSMakeRect(112, 288 - i*38, 370, 26)];
      for (NSDictionary *p in [self aiPresets]) [cb addItemWithObjectValue:p[@"name"]];
      cb.editable = YES; cb.completes = YES; cb.delegate = self;
      tf = cb; self.dialogAIName = cb;
    } else if (i == 6) {
      NSComboBox *cb = [[NSComboBox alloc] initWithFrame:NSMakeRect(112, 288 - i*38, 280, 26)];
      cb.editable = YES; cb.completes = YES;
      cb.stringValue = old[keys[i]] ?: @"";
      tf = cb; self.dialogAIModelCombo = cb; self.dialogAIModel = cb;
      ColorHoverButton *fetch = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(400, 288 - i*38 + 1, 82, 24)];
      fetch.title = @"获取模型"; fetch.hoverColor = [NSColor systemTealColor];
      fetch.target = self; fetch.action = @selector(fetchAIModelsForDialog:);
      [fetch applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
      [av addSubview:fetch];
    } else {
      tf = [[NSTextField alloc] initWithFrame:NSMakeRect(112, 288 - i*38, 370, 26)];
      if (i == 1) self.dialogAIQuota = tf;
      if (i == 2) self.dialogAIEndpoint = tf;
      if (i == 3) self.dialogAIApi = tf;
      if (i == 4) self.dialogAINote = tf;
      if (i == 5) self.dialogAIBase = tf;
    }
    tf.stringValue = old[keys[i]] ?: @"";
    [av addSubview:tf]; [fields addObject:tf];
  }
  NSTextField *catLabel = [self label:@"模型分类" size:11.5 bold:NO color:[NSColor secondaryLabelColor]];
  catLabel.frame = NSMakeRect(8, 34, 100, 18); [av addSubview:catLabel];
  self.dialogAIModelCategoryPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(112, 28, 370, 26) pullsDown:NO];
  NSArray *catKeys = @[@"text", @"image", @"video", @"vision", @"edit", @"speech"];
  for (NSString *k in catKeys) {
    [self.dialogAIModelCategoryPopup addItemWithTitle:[self aiModelCategoryTitle:k]];
    self.dialogAIModelCategoryPopup.lastItem.representedObject = k;
  }
  NSString *oldCat = [self aiModelCategoryKey:old];
  for (NSMenuItem *mi in self.dialogAIModelCategoryPopup.itemArray) if ([[mi representedObject] isEqualToString:oldCat]) [self.dialogAIModelCategoryPopup selectItem:mi];
  [av addSubview:self.dialogAIModelCategoryPopup];
  self.dialogAIStatus = [self label:@"" size:10.5 bold:NO color:[NSColor systemGreenColor]];
  self.dialogAIStatus.frame = NSMakeRect(8, 4, 480, 16);
  [av addSubview:self.dialogAIStatus];
  a.accessoryView = av;
  if (editing && self.dialogAIBase.stringValue.length && self.dialogAIApi.stringValue.length) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.25 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{ [self fetchAIModelsForDialog:nil]; });
  }
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSMutableDictionary *entry = editing ? [old mutableCopy] : [NSMutableDictionary dictionary];
  for (NSInteger i = 0; i < keys.count; i++) entry[keys[i]] = ((NSTextField *)fields[i]).stringValue ?: @"";
  entry[@"modelCategory"] = self.dialogAIModelCategoryPopup.selectedItem.representedObject ?: @"text";
  NSString *entryBase = entry[@"apiBase"] ?: @"";
  if (![entry[@"api"] length] && ([entryBase containsString:@"127.0.0.1"] || [entryBase containsString:@"localhost"] || [entryBase containsString:@"ollama"] || [entryBase containsString:@"8188"])) entry[@"api"] = @"local";
  if (![entry[@"name"] length]) { [self showToast:@"名称不能为空"]; return; }
  if (![entry[@"endpoint"] length]) {
    NSDictionary *preset = [self aiPresetForName:entry[@"name"]];
    if (preset) {
      entry[@"endpoint"] = preset[@"url"] ?: @"";
      if (![entry[@"note"] length]) entry[@"note"] = preset[@"type"] ?: @"";
    }
  }
  if (editing) {
    if (![entry[@"kid"] length] && [old[@"kid"] length]) entry[@"kid"] = old[@"kid"];
    if (![entry[@"kid"] length]) entry[@"kid"] = [[NSUUID UUID] UUIDString];
    self.aiEntries[idx] = entry;
  } else {
    entry[@"kid"] = [[NSUUID UUID] UUIDString];
    [self.aiEntries addObject:entry];
  }
  [self saveAIEntries];
  self.aiPage = 0;
  [self rebuildAIDisplay];
  [self showToast:editing ? @"AI 服务已更新" : @"AI 服务已添加"];
  if ([entry[@"api"] length]) {
    [self performSelector:@selector(refreshAIQuotas:) withObject:nil afterDelay:0.4];
  }
}

- (void)aiEditVisibleRow:(id)sender {
  NSInteger row = self.aiTable.clickedRow;
  if (row < 0) row = self.aiTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.aiVisibleEntries.count) return;
  NSDictionary *target = self.aiVisibleEntries[row];
  for (NSInteger i = 0; i < (NSInteger)self.aiEntries.count; i++) {
    if ([[self aiEntryIdentity:self.aiEntries[i]] isEqualToString:[self aiEntryIdentity:target]]) { [self aiShowEntryDialogForIndex:i]; return; }
  }
}

- (void)aiEditRow:(NSButton *)b {
  NSInteger row = b.tag;
  if (row < 0 || row >= (NSInteger)self.aiVisibleEntries.count) return;
  NSDictionary *target = self.aiVisibleEntries[row];
  NSInteger idx = NSNotFound;
  for (NSInteger i = 0; i < (NSInteger)self.aiEntries.count; i++) {
    if ([[self aiEntryIdentity:self.aiEntries[i]] isEqualToString:[self aiEntryIdentity:target]]) { idx = i; break; }
  }
  if (idx != NSNotFound) [self aiShowEntryDialogForIndex:idx];
}

- (void)aiBackupRow:(NSButton *)b {
  NSInteger row = b.tag;
  if (row < 0 || row >= (NSInteger)self.aiVisibleEntries.count) return;
  NSDictionary *entry = self.aiVisibleEntries[row];
  NSString *name = entry[@"name"] ?: @"AI备份";
  [self runAIBackupForEntries:@[entry] singleName:name];
}

- (void)aiDeleteSelected:(id)sender {
  NSMutableArray *targets = [NSMutableArray array];
  NSMutableArray *names = [NSMutableArray array];
  for (NSDictionary *e in self.aiEntries) {
    NSString *ident = [self aiEntryIdentity:e];
    if ([self.aiSelected containsObject:ident]) {
      [targets addObject:ident];
      [names addObject:e[@"name"] ?: e[@"name"] ?: @"未命名"];
    }
  }
  if (!targets.count) { [self showToast:@"请先勾选要删除的服务"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = [NSString stringWithFormat:@"删除 %ld 条 AI 服务？", (long)targets.count];
  a.informativeText = [names componentsJoinedByString:@"、"];
  [a addButtonWithTitle:@"删除"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  if (![self requestAdminAuthentication]) {
    [self showToast:@"管理员验证失败，已取消删除"];
    return;
  }
  for (NSString *ident in targets) {
    for (NSInteger i = (NSInteger)self.aiEntries.count - 1; i >= 0; i--) {
      if ([[self aiEntryIdentity:self.aiEntries[i]] isEqualToString:ident]) [self.aiEntries removeObjectAtIndex:i];
    }
  }
  [self.aiSelected removeAllObjects];
  [self saveAIEntries];
  self.aiPage = 0;
  [self rebuildAIDisplay];
  [self showToast:@"已删除所选数据与本地备份"];
}

- (void)aiReload:(id)sender {
  [self loadAIEntries];
  [self.aiSelected removeAllObjects];
  [self.aiRevealedNames removeAllObjects];
  self.aiPage = 0;
  [self rebuildAIDisplay];
  [self showToast:@"已刷新 AI 服务数据"];
}

- (void)aiBackupAll:(id)sender {
  [self runAIBackupForEntries:self.aiEntries singleName:nil];
}

- (void)removeAIBackupsForName:(NSString *)name {
  if (!name.length) return;
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers/backup/ai"];
  NSArray *files = [[NSFileManager defaultManager] contentsOfDirectoryAtPath:dir error:NULL] ?: @[];
  for (NSString *f in files) {
    if ([f hasPrefix:[name stringByAppendingString:@"-"]]) {
      [[NSFileManager defaultManager] removeItemAtPath:[dir stringByAppendingPathComponent:f] error:NULL];
    }
  }
}

- (void)aiDeleteRow:(NSButton *)b {
  NSInteger row = b.tag;
  if (row < 0 || row >= (NSInteger)self.aiVisibleEntries.count) return;
  NSDictionary *targetEntry = self.aiVisibleEntries[row];
  NSString *name = targetEntry[@"name"] ?: @"";
  NSString *ident = [self aiEntryIdentity:targetEntry];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"删除该 AI 服务？";
  a.informativeText = [NSString stringWithFormat:@"将删除控制台中的数据，并清理本地备份：%@（%@）", name, [self aiModelCategoryTitle:[self aiModelCategoryKey:targetEntry]]];
  [a addButtonWithTitle:@"删除"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  if (![self requestAdminAuthentication]) {
    [self showToast:@"管理员验证失败，已取消删除"];
    return;
  }
  for (NSInteger i = (NSInteger)self.aiEntries.count - 1; i >= 0; i--) {
    if ([[self aiEntryIdentity:self.aiEntries[i]] isEqualToString:ident]) [self.aiEntries removeObjectAtIndex:i];
  }
  [self.aiSelected removeObject:ident];
  [self saveAIEntries];
  [self removeAIBackupsForName:name];
  [self rebuildAIDisplay];
  [self showToast:@"已删除数据与本地备份"];
}

