  [cv addSubview:self.sceneSpaceButton];

  self.sceneAutoCheck = [NSButton checkboxWithTitle:@"按时间自动切换（工作日 9:00-18:00 工作，其余下班）" target:self action:@selector(sceneAutoChanged:)];
  self.sceneAutoCheck.state = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerSceneAuto"] ? NSControlStateValueOn : NSControlStateValueOff;
  self.sceneAutoCheck.frame = NSMakeRect(20, 416, 460, 22);
  [cv addSubview:self.sceneAutoCheck];

  NSTextField *hint = [self label:@"勾选该场景要显示的分组" size:10.5 bold:YES color:[NSColor tertiaryLabelColor]];
  hint.frame = NSMakeRect(20, 392, 300, 18); [cv addSubview:hint];

  self.sceneScroll = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 74, 468, 310)];
  self.sceneScroll.hasVerticalScroller = YES; self.sceneScroll.borderType = NSBezelBorder;
  self.sceneScroll.drawsBackground = YES; self.sceneScroll.backgroundColor = [NSColor controlBackgroundColor];
  [cv addSubview:self.sceneScroll];

  ColorHoverButton *apply = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(240, 24, 120, 34)];
  apply.title = @"应用此场景"; apply.hoverColor = [NSColor systemIndigoColor];
  apply.target = self; apply.action = @selector(applyCurrentScene:);
  [apply applyColor:[NSColor systemIndigoColor] textColor:[NSColor whiteColor]];
  [cv addSubview:apply];
  ColorHoverButton *close = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(370, 24, 100, 34)];
  close.title = @"关闭"; close.hoverColor = [NSColor systemGrayColor];
  close.target = self; close.action = @selector(closeSceneSettings:);
  [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
  [cv addSubview:close];

  self.sceneChecks = [NSMutableArray array];
  [self reloadSceneChecks];
  [self sceneAutoChanged:self.sceneAutoCheck];
  [NSApp activateIgnoringOtherApps:YES];
  [self.sceneWindow center];
  [self.sceneWindow makeKeyAndOrderFront:nil];
  [self.sceneWindow orderFrontRegardless];
}

- (NSArray<NSString *> *)dockGroupNames {
  NSMutableArray *names = [NSMutableArray array];
  CFPreferencesAppSynchronize(CFSTR("com.apple.dock"));
  CFArrayRef raw = CFPreferencesCopyAppValue(CFSTR("persistent-apps"), CFSTR("com.apple.dock"));
  NSArray *apps = raw ? CFBridgingRelease(raw) : @[];
  NSString *groupDir = [GroupDir() stringByStandardizingPath];
  for (id item in apps) {
    if (![item isKindOfClass:[NSDictionary class]]) continue;
    NSString *u = item[@"tile-data"][@"file-data"][@"_CFURLString"];
    if (!u.length) continue;
    NSURL *url = [NSURL URLWithString:u];
    NSString *path = url.path.stringByStandardizingPath;
    if (![path hasPrefix:[groupDir stringByAppendingString:@"/"]]) continue;
    NSString *name = path.lastPathComponent.stringByDeletingPathExtension;
    if (name.length && ![names containsObject:name]) [names addObject:name];
  }
  return names;
}

- (void)reloadSceneChecks {
  NSInteger idx = self.scenePopup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSDictionary *scene = self.scenes[idx];
  NSString *bound = scene[@"layout"] ?: @"";
  if (self.sceneLayoutButton) self.sceneLayoutButton.title = bound.length ? [NSString stringWithFormat:@"布局：%@", bound] : @"窗口布局：无";
  if (self.sceneSpaceButton) {
    NSString *sid = scene[@"spaceID"] ?: @"";
    NSNumber *sidx = scene[@"spaceIndex"];
    self.sceneSpaceButton.title = sid.length ? [NSString stringWithFormat:@"桌面：%@", sidx ?: @""] : @"桌面：未绑定";
  }
  NSArray *sceneGroups = scene[@"groups"] ?: @[];
  BOOL all = [self sceneIsAll:scene];
  NSArray *installed = [self installedGroupNames];
  NSView *doc = [[FlippedView alloc] initWithFrame:NSMakeRect(0,0,450,MAX(310,installed.count*34))];
  [self.sceneChecks removeAllObjects];
  for (NSInteger i = 0; i < (NSInteger)installed.count; i++) {
    NSString *name = installed[i];
    NSButton *cb = [NSButton checkboxWithTitle:name target:self action:@selector(sceneCheckChanged:)];
    cb.frame = NSMakeRect(12, i*34+5, 420, 24);
    cb.tag = i;
    cb.state = (all || [sceneGroups containsObject:name]) ? NSControlStateValueOn : NSControlStateValueOff;
    [doc addSubview:cb];
    [self.sceneChecks addObject:cb];
  }
  self.sceneScroll.documentView = doc;
}

- (void)sceneLayoutChanged:(id)sender {
  [self loadScenes];
  [self loadWindowLayouts];
  NSInteger idx = self.scenePopup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSArray *names = [[self.savedLayouts allKeys] sortedArrayUsingSelector:@selector(localizedCompare:)];
  NSPopUpButton *popup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(0,0,300,28) pullsDown:NO];
  [popup addItemWithTitle:@"不绑定窗口布局"];
  for (NSString *n in names) [popup addItemWithTitle:n];
  NSString *cur = self.scenes[idx][@"layout"] ?: @"";
  if (cur.length && [names containsObject:cur]) [popup selectItemWithTitle:cur];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"绑定窗口布局";
  a.informativeText = @"应用这个场景时，同时恢复对应的窗口布局。";
  a.accessoryView = popup;
  [a addButtonWithTitle:@"保存"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSMutableDictionary *scene = [self.scenes[idx] mutableCopy];
  if (popup.indexOfSelectedItem <= 0) [scene removeObjectForKey:@"layout"];
  else scene[@"layout"] = popup.titleOfSelectedItem;
  self.scenes[idx] = scene;
  [self saveScenes];
  [self reloadSceneChecks];
}

- (void)scenePopupChanged:(id)sender { [self reloadSceneChecks]; }

- (void)sceneCheckChanged:(id)sender {
  NSInteger idx = self.scenePopup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSArray *installed = [self installedGroupNames];
  NSMutableArray *checked = [NSMutableArray array];
  for (NSButton *cb in self.sceneChecks) {
    NSInteger tag = cb.tag;
    if (tag >= 0 && tag < (NSInteger)installed.count && cb.state == NSControlStateValueOn) [checked addObject:installed[tag]];
  }
  NSMutableDictionary *scene = [self.scenes[idx] mutableCopy];
  if (checked.count == installed.count) {
    scene[@"all"] = @YES; scene[@"groups"] = @[];
  } else {
    scene[@"all"] = @NO; scene[@"groups"] = checked;
  }
  self.scenes[idx] = scene;
  [self saveScenes];
}

- (void)startSceneAutoIfNeeded {
  if (![[NSUserDefaults standardUserDefaults] boolForKey:@"centerSceneAuto"]) return;
  [self loadScenes];
  self.sceneTimer = [NSTimer scheduledTimerWithTimeInterval:60 target:self selector:@selector(sceneAutoTick:) userInfo:nil repeats:YES];
  [self sceneAutoTick:nil];
}

- (void)sceneAutoChanged:(id)sender {
  BOOL on = self.sceneAutoCheck.state == NSControlStateValueOn;
  [[NSUserDefaults standardUserDefaults] setBool:on forKey:@"centerSceneAuto"];
  [self.sceneTimer invalidate]; self.sceneTimer = nil;
  if (!on) return;
  self.sceneTimer = [NSTimer scheduledTimerWithTimeInterval:60 target:self selector:@selector(sceneAutoTick:) userInfo:nil repeats:YES];
  [self sceneAutoTick:nil];
}

- (void)sceneAutoTick:(NSTimer *)timer {
  if ([[NSUserDefaults standardUserDefaults] boolForKey:@"centerScenePerSpaceEnabled"]) return;
  NSDate *now = [NSDate date];
  NSCalendar *cal = [NSCalendar currentCalendar];
  NSInteger weekday = [cal component:NSCalendarUnitWeekday fromDate:now];
  NSInteger hour = [cal component:NSCalendarUnitHour fromDate:now];
  BOOL workday = (weekday >= 2 && weekday <= 6);
  BOOL workTime = workday && hour >= 9 && hour < 18;
  NSString *target = workTime ? @"工作" : @"下班";
  if ([self.lastAppliedScene isEqualToString:target]) return;
  for (NSDictionary *sc in self.scenes) {
    if ([sc[@"name"] isEqualToString:target]) { [self applySceneNamed:target silent:YES]; return; }
  }
}

- (void)sceneSpaceButtonClicked:(id)sender {
  NSInteger idx = self.scenePopup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSMutableDictionary *scene = [self.scenes[idx] mutableCopy];
  NSDictionary *space = DLActiveSpaceInfo();
  if (!space) { [self showToast:@"当前 macOS 不支持桌面识别"]; return; }
  if (((NSString *)(scene[@"spaceID"] ?: @"")).length) {
    NSAlert *a = [[NSAlert alloc] init];
    a.messageText = @"解除桌面绑定？";
    a.informativeText = @"解除后，这个场景不再随桌面自动切换。";
    [a addButtonWithTitle:@"解除"];
    [a addButtonWithTitle:@"取消"];
    if ([a runModal] != NSAlertFirstButtonReturn) return;
    [scene removeObjectForKey:@"spaceID"];
    [scene removeObjectForKey:@"spaceIndex"];
    [scene removeObjectForKey:@"spaceDisplay"];
    self.scenes[idx] = scene;
    [self saveScenes];
    BOOL any = NO;
    for (NSDictionary *sc in self.scenes) if (((NSString *)(sc[@"spaceID"] ?: @"")).length) { any = YES; break; }
    [[NSUserDefaults standardUserDefaults] setBool:any forKey:@"centerScenePerSpaceEnabled"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    [self reloadSceneChecks];
    self.lastAppliedSpaceKey = nil;
    if (any) [self applySceneForCurrentSpace]; else self.lastAppliedScene = @"";
    [self showToast:@"已解除桌面绑定"];
    return;
  }
  NSString *key = space[@"id"] ?: @"";
  for (NSInteger i = 0; i < (NSInteger)self.scenes.count; i++) {
    if (i == idx) continue;
    NSMutableDictionary *other = [self.scenes[i] mutableCopy];
    if ([[other[@"spaceID"] description] isEqualToString:key]) {
      [other removeObjectForKey:@"spaceID"];
      [other removeObjectForKey:@"spaceIndex"];
      self.scenes[i] = other;
    }
  }
  scene[@"spaceID"] = key;
  scene[@"spaceIndex"] = space[@"index"] ?: @0;
  scene[@"spaceDisplay"] = space[@"display"] ?: @"";
  self.scenes[idx] = scene;
  [self saveScenes];
  [[NSUserDefaults standardUserDefaults] setBool:YES forKey:@"centerScenePerSpaceEnabled"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self reloadSceneChecks];
  self.lastAppliedSpaceKey = nil;
  [self applySceneForCurrentSpace];
  [self showToast:[NSString stringWithFormat:@"已绑定到桌面 %@", space[@"index"] ?: @""]];
}

- (void)activeSpaceChanged:(NSNotification *)note {
  NSDictionary *space = DLActiveSpaceInfo();
  NSString *key = space[@"id"] ?: @"";
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    if (self.scenePromptOpen) return;
    NSDictionary *now = DLActiveSpaceInfo();
    if (key.length && ![[now[@"id"] description] isEqualToString:key]) return;
    [self applySceneForCurrentSpace];
    NSDictionary *sp = DLActiveSpaceInfo();
    [self evaluateAutomationTrigger:@"space" value:[sp[@"index"] description] ?: @""];
  });
}

- (void)clearGroupDockEntries {
  NSArray *installed = [self installedGroupNames];
  BOOL changed = NO;
  NSSet *current = [NSSet setWithArray:[self dockGroupNames]];
  if (current.count) changed = YES;
  for (NSString *group in installed) {
    NSString *path = [[GroupDir() stringByAppendingPathComponent:group] stringByAppendingPathExtension:@"app"];
    if ([[NSFileManager defaultManager] fileExistsAtPath:path]) [self removeDockEntry:path];
  }
  if (changed) [self killDock];
}

- (void)applySceneForCurrentSpace {
  if (self.scenePromptOpen) return;
  if (![[NSUserDefaults standardUserDefaults] boolForKey:@"centerScenePerSpaceEnabled"]) return;
  NSDictionary *space = DLActiveSpaceInfo();
  NSString *key = space[@"id"] ?: @"";
  if (!key.length) return;
  if ([self.lastAppliedSpaceKey isEqualToString:key]) return;
  self.lastAppliedSpaceKey = key;
  [self loadScenes];
  NSDictionary *match = nil;
  for (NSDictionary *sc in self.scenes) if ([[sc[@"spaceID"] description] isEqualToString:key]) { match = sc; break; }
  if (!match) {
    for (NSDictionary *sc in self.scenes) {
      if ([sc[@"spaceIndex"] integerValue] != [space[@"index"] integerValue]) continue;
      NSString *d1 = sc[@"spaceDisplay"] ?: @"";
      NSString *d2 = space[@"display"] ?: @"";
      if (!d1.length || [d1 isEqualToString:d2]) { match = sc; break; }
    }
  }
  if (match) {
    [self applySceneNamed:match[@"name"] ?: @"" silent:YES];
  } else {
    // 新建/空桌面切换时 Dock 重启可能打断 Mission Control，延迟清理
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(2.0 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
      if (self.scenePromptOpen) return;
      NSDictionary *now = DLActiveSpaceInfo();
      if (![[now[@"id"] description] isEqualToString:key]) return;
      [self clearGroupDockEntries];
      self.lastAppliedScene = @"";
    });
  }
}

- (void)applyCurrentScene:(id)sender {
  [self promptApplySceneAtIndex:self.scenePopup.indexOfSelectedItem];
}

- (void)reloadScenePopups {
  if (self.scenePopup) {
    NSString *cur = self.scenePopup.titleOfSelectedItem;
    [self.scenePopup removeAllItems];
    for (NSDictionary *sc in self.scenes) [self.scenePopup addItemWithTitle:sc[@"name"] ?: @""];
    if (cur.length) [self.scenePopup selectItemWithTitle:cur];
  }
  if (self.quickScenePopup) {
    NSString *cur = self.quickScenePopup.titleOfSelectedItem;
    [self.quickScenePopup removeAllItems];
    for (NSDictionary *sc in self.scenes) [self.quickScenePopup addItemWithTitle:sc[@"name"] ?: @""];
    if (cur.length) [self.quickScenePopup selectItemWithTitle:cur];
  }
}

- (BOOL)promptApplySceneAtIndex:(NSInteger)idx {
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return NO;
  [self loadScenes];
  if (idx >= (NSInteger)self.scenes.count) return NO;
  NSDictionary *scene = self.scenes[idx];
  NSArray *installed = [self installedGroupNames];
  if (!installed.count) { [self showToast:@"没有已安装的分组"]; return NO; }
  NSMutableArray *checks = [NSMutableArray array];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"自定义场景并应用";
  NSDictionary *space = DLActiveSpaceInfo();
  a.informativeText = [NSString stringWithFormat:@"当前桌面：%@\n输入场景名称、勾选要显示的分组；确认后会保存为独立场景并绑定到当前桌面。",
                       space ? [NSString stringWithFormat:@"桌面 %@", space[@"index"] ?: @""] : @"当前桌面"];
  [a addButtonWithTitle:@"保存并应用"];
  [a addButtonWithTitle:@"取消"];
  CGFloat contentH = installed.count * 32 + 50;
  NSView *box = [[NSView alloc] initWithFrame:NSMakeRect(0,0,460,contentH)];
  NSTextField *nameLabel = [self label:@"场景名称" size:11 bold:YES color:nil];
  nameLabel.frame = NSMakeRect(10, contentH - 25, 60, 18); [box addSubview:nameLabel];
  NSTextField *nameField = [[NSTextField alloc] initWithFrame:NSMakeRect(76, contentH - 31, 370, 26)];
  nameField.placeholderString = @"例如：聊天、工作、游戏";
  nameField.stringValue = scene[@"name"] ?: @"";
  [box addSubview:nameField];
  BOOL all = [self sceneIsAll:scene];
  NSArray *selected = scene[@"groups"] ?: @[];
  for (NSInteger i = 0; i < (NSInteger)installed.count; i++) {
    NSString *name = installed[i];
    NSButton *cb = [NSButton checkboxWithTitle:name target:nil action:nil];
    cb.frame = NSMakeRect(10, contentH - 82 - i*32, 430, 24);
    cb.state = (all || [selected containsObject:name]) ? NSControlStateValueOn : NSControlStateValueOff;
    cb.tag = i;
    [box addSubview:cb];
    [checks addObject:cb];
  }
  a.accessoryView = box;
  self.scenePromptOpen = YES;
  if (a.window) {
    a.window.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  }
  NSModalResponse promptResult = [a runModal];
  self.scenePromptOpen = NO;
  if (promptResult != NSAlertFirstButtonReturn) return NO;
  NSString *newName = [nameField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!newName.length) {
    [self showToast:@"场景名称不能为空"];
    return NO;
  }
  NSMutableArray *chosen = [NSMutableArray array];
  for (NSButton *cb in checks) if (cb.state == NSControlStateValueOn && cb.tag >= 0 && cb.tag < (NSInteger)installed.count) [chosen addObject:installed[cb.tag]];
  NSMutableDictionary *updated = [scene mutableCopy];
  updated[@"name"] = newName;
  if (chosen.count == installed.count) { updated[@"all"] = @YES; updated[@"groups"] = @[]; }
  else { updated[@"all"] = @NO; updated[@"groups"] = chosen; }
  NSInteger targetIdx = idx;
  NSString *oldName = scene[@"name"] ?: @"";
  if (![newName isEqualToString:oldName]) {
    NSInteger existing = NSNotFound;
    for (NSInteger i = 0; i < (NSInteger)self.scenes.count; i++) if ([self.scenes[i][@"name"] ?: @"" isEqualToString:newName]) { existing = i; break; }
    if (existing != NSNotFound) targetIdx = existing;
    else targetIdx = self.scenes.count;
    // 清除旧场景的桌面绑定，避免同一个桌面残留两个场景
    NSMutableDictionary *oldScene = [self.scenes[idx] mutableCopy];
    [oldScene removeObjectForKey:@"spaceID"];
    [oldScene removeObjectForKey:@"spaceIndex"];
    [oldScene removeObjectForKey:@"spaceDisplay"];
    self.scenes[idx] = oldScene;
    if (existing != NSNotFound) self.scenes[targetIdx] = updated;
    else [self.scenes addObject:updated];
  } else {
    self.scenes[idx] = updated;
  }
  [self saveScenes];
  [self reloadScenePopups];
  if (self.scenePopup) [self.scenePopup selectItemAtIndex:targetIdx];
  if (self.quickScenePopup) [self.quickScenePopup selectItemAtIndex:targetIdx];
  [self applySceneAtIndex:targetIdx];
  [self reloadSceneChecks];
  return YES;
}

- (void)applySceneAtIndex:(NSInteger)idx {
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSDictionary *space = DLActiveSpaceInfo();
  NSMutableDictionary *scene = [self.scenes[idx] mutableCopy];
  if (space) {
    NSString *key = space[@"id"] ?: @"";
    for (NSInteger i = 0; i < (NSInteger)self.scenes.count; i++) {
      if (i == idx) continue;
      NSMutableDictionary *other = [self.scenes[i] mutableCopy];
      if ([[other[@"spaceID"] description] isEqualToString:key]) {
        [other removeObjectForKey:@"spaceID"];
        [other removeObjectForKey:@"spaceIndex"];
        [other removeObjectForKey:@"spaceDisplay"];
        self.scenes[i] = other;
      }
    }
    scene[@"spaceID"] = key;
    scene[@"spaceIndex"] = space[@"index"] ?: @0;
    scene[@"spaceDisplay"] = space[@"display"] ?: @"";
    self.scenes[idx] = scene;
    [self saveScenes];
    [[NSUserDefaults standardUserDefaults] setBool:YES forKey:@"centerScenePerSpaceEnabled"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    self.lastAppliedSpaceKey = key;
  }
  [self applySceneNamed:self.scenes[idx][@"name"] silent:NO];
  [self reloadSceneChecks];
  if (space) [self showToast:[NSString stringWithFormat:@"已应用「%@」并绑定到桌面 %@", self.scenes[idx][@"name"] ?: @"", space[@"index"] ?: @""]];
}

- (void)applySceneNamed:(NSString *)name silent:(BOOL)silent {
  NSDictionary *scene = nil;
  for (NSDictionary *sc in self.scenes) if ([sc[@"name"] isEqualToString:name]) { scene = sc; break; }
  if (!scene) return;
  NSArray *sceneGroups = scene[@"groups"] ?: @[];
  BOOL all = [self sceneIsAll:scene];
  NSArray *installed = [self installedGroupNames];
  for (NSString *group in installed) {
    NSString *path = [[GroupDir() stringByAppendingPathComponent:group] stringByAppendingPathExtension:@"app"];
    if (![[NSFileManager defaultManager] fileExistsAtPath:path]) continue;
    if (all || [sceneGroups containsObject:group]) [self addDockEntry:path label:group];
    else [self removeDockEntry:path];
  }
  [self killDock];
  self.lastAppliedScene = name;
  NSString *layoutName = scene[@"layout"] ?: @"";
  if (layoutName.length) {
    BOOL autoLaunch = !self.layoutAutoLaunchCheck || self.layoutAutoLaunchCheck.state == NSControlStateValueOn;
    [self restoreWindowLayoutNamed:layoutName autoLaunch:autoLaunch];
  }
  if (!silent) [self showToast:[NSString stringWithFormat:@"已切换到「%@」场景", name]];
}

- (void)closeSceneSettings:(id)sender { [self.sceneWindow orderOut:nil]; }

- (NSString *)usageStorePath {
  return [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers/usage.json"];
}

- (NSDictionary<NSString *, NSString *> *)groupByAppPath {
  NSMutableDictionary *map = [NSMutableDictionary dictionary];
  NSString *lists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  for (NSString *f in [[NSFileManager defaultManager] contentsOfDirectoryAtPath:lists error:NULL] ?: @[]) {
    if (![f.pathExtension.lowercaseString isEqualToString:@"txt"]) continue;
    NSString *group = f.stringByDeletingPathExtension;
    NSString *body = [NSString stringWithContentsOfFile:[lists stringByAppendingPathComponent:f] encoding:NSUTF8StringEncoding error:NULL] ?: @"";
    for (NSString *line in [body componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]]) {
      NSString *t = [line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
      if (!t.length || [t hasPrefix:@"#"]) continue;
      NSRange r = [t rangeOfString:@"|"];
      if (r.location != NSNotFound) t = [[t substringFromIndex:r.location+1] stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
      NSString *path = ResolveAppPath(t);
      if (path.length) map[path] = group;
    }
  }
  return map;
}

- (void)showUsageStats:(id)sender {
  NSData *d = [NSData dataWithContentsOfFile:[self usageStorePath]];
  id parsed = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  NSDictionary *all = [parsed isKindOfClass:[NSDictionary class]] ? parsed : @{};
  NSDictionary *groups = [self groupByAppPath];
  NSMutableArray *rows = [NSMutableArray array];
  for (NSString *path in all) {
    NSDictionary *u = all[path];
    if (![u isKindOfClass:[NSDictionary class]]) continue;
    [rows addObject:@{@"path": path, @"label": u[@"label"] ?: path.lastPathComponent, @"count": u[@"count"] ?: @0, @"last": u[@"last"] ?: @0, @"group": groups[path] ?: @""}];
  }
  [rows sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) {
    NSComparisonResult r = [b[@"count"] compare:a[@"count"]];
    if (r != NSOrderedSame) return r;
    return [b[@"last"] compare:a[@"last"]];
  }];
  self.usageRows = rows;
  if (!self.usageWindow) {
    self.usageWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,640,520) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.usageWindow.title = @"使用统计与推荐";
    self.usageWindow.releasedWhenClosed = NO;
    self.usageWindow.level = NSNormalWindowLevel;
    NSView *cv = self.usageWindow.contentView;
    NSTextField *title = [self label:@"使用统计与推荐" size:20 bold:YES color:nil];
    title.frame = NSMakeRect(20, 470, 300, 28); [cv addSubview:title];
    NSTextField *sub = [self label:@"统计从分组启动器的应用启动次数，优先推荐高频但未分组的应用" size:10 bold:NO color:[NSColor secondaryLabelColor]];
    sub.frame = NSMakeRect(20, 448, 590, 18); [cv addSubview:sub];
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 76, 608, 360)];
    sv.hasVerticalScroller = YES; sv.borderType = NSBezelBorder;
    self.usageTable = [[NSTableView alloc] initWithFrame:sv.contentView.bounds];
    NSArray *cols = @[@[@"app", @"应用", @300.0], @[@"count", @"启动次数", @80.0], @[@"last", @"最近使用", @130.0], @[@"group", @"所在分组", @90.0]];
    for (NSArray *c in cols) {
      NSTableColumn *col = [[NSTableColumn alloc] initWithIdentifier:c[0]];
      col.title = c[1]; col.width = [c[2] doubleValue];
      [self.usageTable addTableColumn:col];
    }
    self.usageTable.rowHeight = 40;
    self.usageTable.dataSource = self; self.usageTable.delegate = self;
    sv.documentView = self.usageTable;
    [cv addSubview:sv];
    NSTextField *hint = [self label:@"" size:10.5 bold:NO color:[NSColor tertiaryLabelColor]];
    hint.frame = NSMakeRect(18, 48, 610, 18); hint.identifier = @"usageHint"; [cv addSubview:hint];
    ColorHoverButton *exportCSV = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(402, 14, 108, 30)];
    exportCSV.title = @"导出 CSV"; exportCSV.hoverColor = [NSColor systemGreenColor];
    exportCSV.target = self; exportCSV.action = @selector(exportUsageCSV:);
    [exportCSV applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
    [cv addSubview:exportCSV];
    ColorHoverButton *close = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(520, 14, 100, 30)];
    close.title = @"关闭"; close.hoverColor = [NSColor systemGrayColor];
    close.target = self; close.action = @selector(closeUsageStats:);
    [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
    [cv addSubview:close];
    [self.usageWindow center];
  }
  [self.usageTable reloadData];
  NSTextField *hint = [self.usageWindow.contentView viewWithTag:0];
  for (NSView *v in self.usageWindow.contentView.subviews) if ([v.identifier isEqualToString:@"usageHint"]) { hint = (NSTextField *)v; break; }
  NSMutableArray *recs = [NSMutableArray array];
  for (NSDictionary *r in rows) if (![r[@"group"] length] && [r[@"count"] integerValue] >= 2) [recs addObject:r[@"label"]];
  hint.stringValue = recs.count ? [NSString stringWithFormat:@"推荐加入分组：%@", [[recs subarrayWithRange:NSMakeRange(0, MIN(5, recs.count))] componentsJoinedByString:@"、"]] : @"暂无未分组的高频应用";
  [NSApp activateIgnoringOtherApps:YES];
  [self.usageWindow makeKeyAndOrderFront:nil];
  [self.usageWindow orderFrontRegardless];
}

- (void)exportUsageCSV:(id)sender {
  if (!self.usageRows.count) { [self showToast:@"暂无使用统计数据"]; return; }
  NSSavePanel *sp = [NSSavePanel savePanel];
  sp.nameFieldStringValue = @"DockLaunchers-使用统计.csv";
  sp.allowedFileTypes = @[@"csv"];
  if ([sp runModal] != NSModalResponseOK) return;
  NSDateFormatter *dfDate = [[NSDateFormatter alloc] init];
  dfDate.dateFormat = @"yyyy-MM-dd";
  NSDateFormatter *dfTime = [[NSDateFormatter alloc] init];
  dfTime.dateFormat = @"HH:mm";
  NSMutableString *csv = [NSMutableString stringWithString:@"应用,启动次数,最近使用日期,最近使用时间,所在分组\n"];
  for (NSDictionary *r in self.usageRows) {
    NSNumber *last = r[@"last"];
    NSString *dateText = @"";
    NSString *timeText = @"";
    if ([last doubleValue] > 0) {
      NSDate *d = [NSDate dateWithTimeIntervalSince1970:last.doubleValue];
      dateText = [dfDate stringFromDate:d];
      timeText = [dfTime stringFromDate:d];
    }
    NSString *name = [r[@"label"] stringByReplacingOccurrencesOfString:@"," withString:@"，"];
    NSString *group = [(r[@"group"] ?: @"") stringByReplacingOccurrencesOfString:@"," withString:@"，"];
    [csv appendFormat:@"%@,%@,%@,%@,%@\n", name, r[@"count"] ?: @0, dateText, timeText, group];
  }
  NSMutableData *data = [NSMutableData dataWithData:[@"\uFEFF" dataUsingEncoding:NSUTF8StringEncoding]];
  [data appendData:[csv dataUsingEncoding:NSUTF8StringEncoding]];
  if (![data writeToURL:sp.URL atomically:YES]) { [self showToast:@"导出失败"]; return; }
  [self showToast:@"使用统计已导出"];
  [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[sp.URL]];
}

