- (void)scanLargeFiles:(id)sender {
  if (self.largeFileScanning) return;
  self.largeFileScanning = YES;
  self.largeFileScanButton.enabled = NO;
  self.largeFileStatus.stringValue = @"正在扫描…";
  NSString *scope = self.largeFileScopePopup.selectedItem.representedObject ?: NSHomeDirectory();
  BOOL videosOnly = [scope isEqualToString:@"__videos__"];
  NSString *root = videosOnly ? NSHomeDirectory() : scope;
  unsigned long long threshold = (unsigned long long)[self.largeFileThresholdPopup.selectedItem.representedObject integerValue] * 1024ULL * 1024ULL;
  BOOL homeScan = videosOnly || [root isEqualToString:NSHomeDirectory()];
  NSSet *videoExts = [NSSet setWithArray:@[@"mp4", @"mov", @"mkv", @"avi", @"m4v", @"webm", @"flv", @"wmv", @"ts", @"mts", @"m2ts"]];
  __weak typeof(self) weakSelf = self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY, 0), ^{
    NSMutableArray *files = [NSMutableArray array];
    NSFileManager *fm = [NSFileManager defaultManager];
    NSURL *rootURL = [NSURL fileURLWithPath:root];
    NSDirectoryEnumerator *en = [fm enumeratorAtURL:rootURL includingPropertiesForKeys:@[NSURLFileSizeKey, NSURLContentModificationDateKey, NSURLIsRegularFileKey, NSURLIsSymbolicLinkKey] options:(NSDirectoryEnumerationSkipsHiddenFiles|NSDirectoryEnumerationSkipsPackageDescendants) errorHandler:nil];
    for (NSURL *u in en) {
      if (files.count >= 400) break;
      @autoreleasepool {
        NSNumber *isReg = nil, *isLink = nil, *size = nil;
        [u getResourceValue:&isReg forKey:NSURLIsRegularFileKey error:NULL];
        [u getResourceValue:&isLink forKey:NSURLIsSymbolicLinkKey error:NULL];
        if (!isReg.boolValue || isLink.boolValue) continue;
        if (homeScan) {
          NSString *rel = u.path;
          if ([rel containsString:@"/Library/"] || [rel containsString:@"/.Trash/"]) continue;
        }
        if (videosOnly && ![videoExts containsObject:u.pathExtension.lowercaseString]) continue;
        [u getResourceValue:&size forKey:NSURLFileSizeKey error:NULL];
        NSNumber *alloc = nil;
        [u getResourceValue:&alloc forKey:NSURLFileAllocatedSizeKey error:NULL];
        unsigned long long logical = size.unsignedLongLongValue;
        unsigned long long actual = alloc.unsignedLongLongValue;
        if (actual == 0) actual = logical;
        if (actual < threshold) continue;
        NSDate *date = nil; [u getResourceValue:&date forKey:NSURLContentModificationDateKey error:NULL];
        NSString *ext = u.path.lowercaseString;
        BOOL virtual = [ext hasSuffix:@".img.raw"] || [ext hasSuffix:@".vmdk"] || [ext hasSuffix:@".qcow2"] || [ext hasSuffix:@".vdi"] || [ext hasSuffix:@".sparseimage"];
        [files addObject:@{@"path": u.path, @"name": u.lastPathComponent ?: u.path, @"size": @(actual), @"logical": @(logical), @"virtual": @(virtual), @"date": date ?: [NSDate date]}];
      }
    }
    [files sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) { return [b[@"size"] compare:a[@"size"]]; }];
    dispatch_async(dispatch_get_main_queue(), ^{
      weakSelf.largeFileAllItems = files;
      weakSelf.largeFileScanning = NO;
      weakSelf.largeFileScanButton.enabled = YES;
      weakSelf.largeFileStatus.stringValue = [NSString stringWithFormat:@"找到 %ld 个大于阈值的文件（最多显示 400 个）", (long)files.count];
      [weakSelf applyLargeFileFilter];
    });
  });
}

- (void)largeFileFilterChanged:(id)sender { [self applyLargeFileFilter]; }

- (void)applyLargeFileFilter {
  NSString *q = [self.largeFileSearch.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]].lowercaseString;
  if (!q.length) {
    self.largeFileItems = self.largeFileAllItems ?: @[];
  } else {
    NSMutableArray *out = [NSMutableArray array];
    for (NSDictionary *it in self.largeFileAllItems ?: @[]) {
      NSString *hay = [NSString stringWithFormat:@"%@ %@", it[@"name"] ?: @"", it[@"path"] ?: @""].lowercaseString;
      if ([hay containsString:q]) [out addObject:it];
    }
    self.largeFileItems = out;
  }
  [self.largeFileTable reloadData];
}

- (void)trashLargeFiles:(id)sender {
  NSIndexSet *sel = self.largeFileTable.selectedRowIndexes;
  if (!sel.count) { [self showToast:@"请先选择要清理的文件"]; return; }
  if (![self requestAdminAuthentication]) return;
  NSMutableArray<NSURL *> *urls = [NSMutableArray array];
  [sel enumerateIndexesUsingBlock:^(NSUInteger idx, BOOL *stop) {
    if (idx < self.largeFileItems.count) [urls addObject:[NSURL fileURLWithPath:self.largeFileItems[idx][@"path"]]];
  }];
  NSAlert *a = [[NSAlert alloc] init];
  BOOL hasVirtual = NO;
  for (NSURL *u in urls) for (NSString *v in @[@".img.raw", @".vmdk", @".qcow2", @".vdi", @".sparseimage"]) if ([u.path.lowercaseString hasSuffix:v]) hasVirtual = YES;
  a.messageText = [NSString stringWithFormat:@"将 %ld 个文件移到废纸篓？", (long)urls.count];
  a.informativeText = hasVirtual ? @"其中包含虚拟机/Docker 磁盘镜像，删除会丢失容器和虚拟机数据；可在废纸篓中恢复。" : @"可在废纸篓中恢复。";
  [a addButtonWithTitle:@"移到废纸篓"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSFileManager *fm = [NSFileManager defaultManager];
  NSInteger ok = 0;
  for (NSURL *u in urls) if ([fm trashItemAtURL:u resultingItemURL:nil error:NULL]) ok++;
  [self showToast:[NSString stringWithFormat:@"已移到废纸篓 %ld 个文件", (long)ok]];
  [self scanLargeFiles:nil];
}

- (void)revealLargeFileAtRow:(NSButton *)sender {
  NSInteger row = sender.tag;
  if (row < 0 || row >= (NSInteger)self.largeFileItems.count) return;
  NSString *path = self.largeFileItems[row][@"path"];
  if (path.length) [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:path]]];
}

- (void)revealLargeFileRow:(id)sender {
  NSInteger row = self.largeFileTable.clickedRow;
  if (row < 0) row = self.largeFileTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.largeFileItems.count) return;
  NSString *path = self.largeFileItems[row][@"path"];
  if (path.length) [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:path]]];
}

- (void)closeLargeFileCleaner:(id)sender { [self.largeFileWindow orderOut:nil]; }

- (NSString *)promptStorePath {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"prompts.json"];
}

- (void)loadPrompts {
  NSData *d = [NSData dataWithContentsOfFile:[self promptStorePath]];
  id arr = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  if ([arr isKindOfClass:[NSArray class]]) self.prompts = [arr mutableCopy];
  if (!self.prompts) {
    self.prompts = [@[
      @{@"title": @"翻译并润色", @"category": @"翻译", @"content": @"请翻译下面的内容并润色，保持原意，输出中文：\n\n"},
      @{@"title": @"总结要点", @"category": @"总结", @"content": @"请总结下面内容的核心要点，用简洁的条目列出：\n\n"},
      @{@"title": @"代码解释", @"category": @"代码", @"content": @"请解释下面代码的作用，指出潜在问题并给出改进建议：\n\n"}
    ] mutableCopy];
    [self savePrompts];
  }
}

- (void)savePrompts {
  NSData *d = [NSJSONSerialization dataWithJSONObject:self.prompts ?: @[] options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:[self promptStorePath] atomically:YES];
}

