- (void)refreshPromptCategories {
  if (!self.promptCategoryPopup) return;
  NSString *cur = self.promptCategoryPopup.titleOfSelectedItem ?: @"全部分类";
  NSMutableArray *cats = [NSMutableArray array];
  for (NSDictionary *p in self.prompts) {
    NSString *c = p[@"category"] ?: @"";
    if (c.length && ![cats containsObject:c]) [cats addObject:c];
  }
  [cats sortUsingSelector:@selector(localizedCompare:)];
  [cats insertObject:@"全部分类" atIndex:0];
  [self.promptCategoryPopup removeAllItems];
  for (NSString *c in cats) [self.promptCategoryPopup addItemWithTitle:c];
  if ([cats containsObject:cur]) [self.promptCategoryPopup selectItemWithTitle:cur];
}

- (void)promptCategoryChanged:(id)sender {
  self.promptPage = 0;
  [self reloadPromptTable];
}

- (void)reloadPromptTable {
  NSString *q = [self.promptSearch.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]].lowercaseString;
  NSString *cat = self.promptCategoryPopup.titleOfSelectedItem ?: @"全部分类";
  NSMutableArray *out = [NSMutableArray array];
  for (NSDictionary *p in self.prompts) {
    if (![cat isEqualToString:@"全部分类"] && ![(p[@"category"] ?: @"") isEqualToString:cat]) continue;
    if (q.length) {
      NSString *hay = [NSString stringWithFormat:@"%@ %@ %@", p[@"title"] ?: @"", p[@"category"] ?: @"", p[@"content"] ?: @""].lowercaseString;
      if ([hay rangeOfString:q].location == NSNotFound) continue;
    }
    [out addObject:p];
  }
  self.promptFiltered = out;
  NSInteger pageSize = 15;
  NSInteger pages = MAX(1, ((NSInteger)out.count + pageSize - 1) / pageSize);
  if (self.promptPage >= pages) self.promptPage = pages - 1;
  if (self.promptPage < 0) self.promptPage = 0;
  NSInteger start = self.promptPage * pageSize;
  NSInteger end = MIN((NSInteger)out.count, start + pageSize);
  self.promptPageItems = end > start ? [out subarrayWithRange:NSMakeRange(start, end - start)] : @[];
  if (self.promptPageLabel) {
    self.promptPageLabel.stringValue = [NSString stringWithFormat:@"第 %ld/%ld 页", (long)(self.promptPage + 1), (long)pages];
    self.promptPrevButton.enabled = self.promptPage > 0;
    self.promptPrevButton.alphaValue = self.promptPrevButton.enabled ? 1.0 : 0.4;
    self.promptNextButton.enabled = self.promptPage < pages - 1;
    self.promptNextButton.alphaValue = self.promptNextButton.enabled ? 1.0 : 0.4;
  }
  [self.promptTable reloadData];
}

- (void)promptSearchChanged:(id)sender { self.promptPage = 0; [self reloadPromptTable]; }

- (void)showPromptEditorAtIndex:(NSInteger)idx {
  BOOL editing = idx >= 0 && idx < (NSInteger)self.prompts.count;
  NSDictionary *old = editing ? self.prompts[idx] : @{};
  NSView *av = [[NSView alloc] initWithFrame:NSMakeRect(0,0,560,300)];
  NSTextField *tl = [self label:@"标题" size:10.5 bold:YES color:[NSColor secondaryLabelColor]];
  tl.frame = NSMakeRect(4, 276, 80, 16); [av addSubview:tl];
  NSTextField *titleField = [[NSTextField alloc] initWithFrame:NSMakeRect(82, 270, 470, 26)];
  titleField.stringValue = old[@"title"] ?: @""; [av addSubview:titleField];
  NSTextField *cl = [self label:@"分类" size:10.5 bold:YES color:[NSColor secondaryLabelColor]];
  cl.frame = NSMakeRect(4, 242, 80, 16); [av addSubview:cl];
  NSTextField *catField = [[NSTextField alloc] initWithFrame:NSMakeRect(82, 236, 200, 26)];
  catField.stringValue = old[@"category"] ?: @""; [av addSubview:catField];
  NSTextField *nl = [self label:@"内容" size:10.5 bold:YES color:[NSColor secondaryLabelColor]];
  nl.frame = NSMakeRect(4, 208, 80, 16); [av addSubview:nl];
  NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(82, 8, 470, 192)];
  sv.hasVerticalScroller = YES; sv.borderType = NSBezelBorder;
  NSTextView *tv = [[NSTextView alloc] initWithFrame:sv.contentView.bounds];
  tv.font = [NSFont systemFontOfSize:12];
  tv.string = old[@"content"] ?: @"";
  sv.documentView = tv; [av addSubview:sv];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = editing ? @"编辑提示词" : @"新增提示词";
  a.accessoryView = av;
  [a addButtonWithTitle:@"保存"];
  [a addButtonWithTitle:@"取消"];
  a.window.level = NSStatusWindowLevel + 2;
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSString *title = titleField.stringValue.length ? titleField.stringValue : @"未命名提示词";
  NSMutableDictionary *p = [@{@"title": title, @"category": catField.stringValue ?: @"", @"content": tv.string ?: @""} mutableCopy];
  if (editing) self.prompts[idx] = p; else [self.prompts addObject:p];
  [self savePrompts];
  [self refreshPromptCategories];
  [self reloadPromptTable];
}

- (void)promptAdd:(id)sender { [self showPromptEditorAtIndex:-1]; }

- (void)promptEditSelected:(id)sender {
  NSInteger row = self.promptTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.promptPageItems.count) return;
  NSDictionary *sel = self.promptPageItems[row];
  NSInteger idx = [self.prompts indexOfObjectPassingTest:^BOOL(NSDictionary *p, NSUInteger i, BOOL *stop) { return [p[@"title"] isEqual:sel[@"title"]] && [p[@"content"] isEqual:sel[@"content"]]; }];
  if (idx != NSNotFound) [self showPromptEditorAtIndex:idx];
}

- (void)promptDeleteSelected:(id)sender {
  NSMutableSet *keys = [NSMutableSet setWithSet:self.promptSelected ?: [NSSet set]];
  if (!keys.count) {
    for (NSNumber *n in self.promptTable.selectedRowIndexes) {
      NSInteger row = n.integerValue;
      if (row >= 0 && row < (NSInteger)self.promptPageItems.count) [keys addObject:[self promptSelectionKeyForDict:self.promptPageItems[row]]];
    }
  }
  if (!keys.count) { [self showToast:@"请先勾选或选中要删除的提示词"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = [NSString stringWithFormat:@"删除 %ld 条提示词？", (long)keys.count];
  a.informativeText = @"删除后不可恢复。";
  [a addButtonWithTitle:@"删除"];
  [a addButtonWithTitle:@"取消"];
  a.window.level = NSStatusWindowLevel + 2;
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSMutableArray *deleteTitles = [NSMutableArray array];
  for (NSInteger i = (NSInteger)self.prompts.count - 1; i >= 0; i--) {
    NSDictionary *p = self.prompts[i];
    if ([keys containsObject:[self promptSelectionKeyForDict:p]]) {
      [deleteTitles addObject:p[@"title"] ?: @"提示词"];
      [self.prompts removeObjectAtIndex:i];
    }
  }
  for (NSString *k in keys) [self.promptSelected removeObject:k];
  [self savePrompts];
  [self refreshPromptCategories];
  [self reloadPromptTable];
  [self showToast:[NSString stringWithFormat:@"已删除 %ld 条提示词", (long)deleteTitles.count]];
}

