}

- (void)promptNextPage:(id)sender {
  NSInteger pageSize = 15;
  NSInteger pages = MAX(1, ((NSInteger)self.promptFiltered.count + pageSize - 1) / pageSize);
  if (self.promptPage >= pages - 1) return;
  self.promptPage++;
  [self reloadPromptTable];
}

