    self.dockMagnifyValue.frame = NSMakeRect(386, 306, 50, 18); [cv addSubview:self.dockMagnifyValue];

    self.dockAutohideCheck = [NSButton checkboxWithTitle:@"启用自动隐藏和展开" target:self action:@selector(dockOptionChanged:)];
    self.dockAutohideCheck.state = [[self dockPrefString:@"autohide"] boolValue] ? NSControlStateValueOn : NSControlStateValueOff;
    self.dockAutohideCheck.frame = NSMakeRect(24, 260, 190, 22); [cv addSubview:self.dockAutohideCheck];
    NSTextField *delayLabel = [self label:@"悬停展开延迟" size:9.5 bold:NO color:[NSColor secondaryLabelColor]];
    delayLabel.frame = NSMakeRect(222, 262, 96, 18); [cv addSubview:delayLabel];
    self.dockAutohideDelayPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(322, 254, 118, 26) pullsDown:NO];
    NSArray *delays = @[@0.0, @0.2, @0.5, @1.0, @2.0];
    for (NSNumber *d in delays) {
      NSString *t = [d doubleValue] == 0 ? @"立即展开" : [NSString stringWithFormat:@"%.1f 秒", [d doubleValue]];
      [self.dockAutohideDelayPopup addItemWithTitle:t];
      self.dockAutohideDelayPopup.lastItem.representedObject = d;
    }
    double curDelay = [[self dockPrefString:@"autohide-delay"] doubleValue];
    NSInteger best = 0;
    for (NSInteger i = 0; i < (NSInteger)delays.count; i++) if (fabs([delays[i] doubleValue] - curDelay) < fabs([delays[best] doubleValue] - curDelay)) best = i;
    [self.dockAutohideDelayPopup selectItemAtIndex:best];
    self.dockAutohideDelayPopup.target = self;
    self.dockAutohideDelayPopup.action = @selector(dockOptionChanged:);
    [cv addSubview:self.dockAutohideDelayPopup];
    self.dockLivePreviewCheck = [NSButton checkboxWithTitle:@"拖动时实时预览 Dock" target:self action:nil];
    self.dockLivePreviewCheck.state = NSControlStateValueOn;
    self.dockLivePreviewCheck.frame = NSMakeRect(24, 184, 220, 22); [cv addSubview:self.dockLivePreviewCheck];

    NSTextField *pl = [self label:@"位置" size:11 bold:YES color:nil];
    pl.frame = NSMakeRect(24, 214, 60, 18); [cv addSubview:pl];
    self.dockPositionPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(90, 208, 140, 26) pullsDown:NO];
    [self.dockPositionPopup addItemsWithTitles:@[@"底部", @"左侧", @"右侧"]];
    NSString *ori = [self dockPrefString:@"orientation"];
    [self.dockPositionPopup selectItemAtIndex:[ori isEqualToString:@"left"] ? 1 : ([ori isEqualToString:@"right"] ? 2 : 0)];
    self.dockPositionPopup.target = self;
    self.dockPositionPopup.action = @selector(dockOptionChanged:);
    [cv addSubview:self.dockPositionPopup];

    ColorHoverButton *apply = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(24, 140, 110, 34)];
    apply.title = @"应用"; apply.hoverColor = [NSColor systemGreenColor];
    apply.target = self; apply.action = @selector(applyDockAppearance:);
    [apply applyColor:[NSColor systemGreenColor] textColor:[NSColor whiteColor]]; [cv addSubview:apply];
    ColorHoverButton *reset = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(144, 140, 110, 34)];
    reset.title = @"恢复默认"; reset.hoverColor = [NSColor systemOrangeColor];
    reset.target = self; reset.action = @selector(resetDockAppearance:);
    [reset applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:reset];
    ColorHoverButton *close = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(376, 140, 84, 34)];
    close.title = @"关闭"; close.hoverColor = [NSColor systemGrayColor];
    close.target = self; close.action = @selector(closeDockAppearance:);
    [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:close];
    NSTextField *note = [self label:@"拖动或应用时会重启 Dock，分组图标会自动恢复" size:9.5 bold:NO color:[NSColor tertiaryLabelColor]];
    note.frame = NSMakeRect(24, 100, 430, 16); [cv addSubview:note];
    [self.dockAppearanceWindow center];
  }
  [NSApp activateIgnoringOtherApps:YES];
  [self.dockAppearanceWindow makeKeyAndOrderFront:nil];
  [self.dockAppearanceWindow orderFrontRegardless];
}

- (void)dockSizeChanged:(NSSlider *)s {
  self.dockSizeValue.stringValue = [NSString stringWithFormat:@"%ld", (long)s.integerValue];
  [self scheduleDockLiveApply];
}

- (void)dockMagnifyChanged:(NSSlider *)s {
  self.dockMagnifyValue.stringValue = [NSString stringWithFormat:@"%ld", (long)s.integerValue];
  [self scheduleDockLiveApply];
}

- (void)dockMagnifyToggled:(NSButton *)b {
  self.dockMagnifySlider.enabled = b.state == NSControlStateValueOn;
  [self scheduleDockLiveApply];
}

- (void)dockOptionChanged:(id)sender {
  [self scheduleDockLiveApply];
}

- (NSString *)dockValuesSignature {
  return [NSString stringWithFormat:@"%ld|%ld|%ld|%ld|%.2f|%ld",
          (long)self.dockSizeSlider.integerValue,
          (long)self.dockMagnifySlider.integerValue,
          (long)self.dockMagnifyCheck.state,
          (long)self.dockAutohideCheck.state,
          [self.dockAutohideDelayPopup.selectedItem.representedObject doubleValue],
          (long)self.dockPositionPopup.indexOfSelectedItem];
}

- (void)writeDockValuesAndRestart:(BOOL)restart {
  NSArray *pairs = @[
    @[@"tilesize", @"-int", [NSString stringWithFormat:@"%ld", (long)self.dockSizeSlider.integerValue]],
    @[@"magnification", @"-bool", self.dockMagnifyCheck.state == NSControlStateValueOn ? @"true" : @"false"],
    @[@"largesize", @"-int", [NSString stringWithFormat:@"%ld", (long)self.dockMagnifySlider.integerValue]],
    @[@"autohide", @"-bool", self.dockAutohideCheck.state == NSControlStateValueOn ? @"true" : @"false"],
    @[@"autohide-delay", @"-float", [NSString stringWithFormat:@"%.2f", [self.dockAutohideDelayPopup.selectedItem.representedObject doubleValue]]]
  ];
  for (NSArray *pair in pairs) {
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/usr/bin/defaults";
    t.arguments = @[@"write", @"com.apple.dock", pair[0], pair[1], pair[2]];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
  }
  NSArray *pos = @[@"bottom", @"left", @"right"];
  NSTask *t2 = [[NSTask alloc] init];
  t2.launchPath = @"/usr/bin/defaults";
  t2.arguments = @[@"write", @"com.apple.dock", @"orientation", @"-string", pos[MAX(0, MIN(2, self.dockPositionPopup.indexOfSelectedItem))]];
  @try { [t2 launch]; [t2 waitUntilExit]; } @catch (NSException *e) {}
  if (restart) [self reloadDockPreferences];
  self.dockLastSignature = [self dockValuesSignature];
}

- (void)scheduleDockLiveApply {
  if (self.dockLivePreviewCheck.state != NSControlStateValueOn) return;
  [self.dockLiveTimer invalidate];
  self.dockLiveTimer = [NSTimer scheduledTimerWithTimeInterval:0.45 target:self selector:@selector(applyDockLiveValues:) userInfo:nil repeats:NO];
}

- (void)applyDockLiveValues:(NSTimer *)timer {
  if (![self dockValuesSignature].length) return;
  if ([[self dockValuesSignature] isEqualToString:self.dockLastSignature ?: @""]) return;
  [self writeDockValuesAndRestart:YES];
}

- (void)applyDockAppearance:(id)sender {
  [self.dockLiveTimer invalidate];
  self.dockLiveTimer = nil;
  [self writeDockValuesAndRestart:YES];
  [self showToast:@"Dock 外观已应用"];
}

- (void)resetDockAppearance:(id)sender {
  self.dockSizeSlider.integerValue = 64;
  self.dockMagnifySlider.integerValue = 96;
  self.dockMagnifyCheck.state = NSControlStateValueOff;
  self.dockAutohideCheck.state = NSControlStateValueOff;
  [self.dockAutohideDelayPopup selectItemAtIndex:2];
  [self.dockPositionPopup selectItemAtIndex:0];
  self.dockSizeValue.stringValue = @"64";
  self.dockMagnifyValue.stringValue = @"96";
  [self showToast:@"已恢复默认值，点应用生效"];
}

- (void)closeDockAppearance:(id)sender { [self.dockAppearanceWindow orderOut:nil]; }

- (NSString *)windowLayoutStorePath {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"window_layouts.json"];
}

- (void)loadWindowLayouts {
  if (self.savedLayouts) return;
  NSData *d = [NSData dataWithContentsOfFile:[self windowLayoutStorePath]];
  id obj = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  self.savedLayouts = [obj isKindOfClass:[NSDictionary class]] ? [obj mutableCopy] : [NSMutableDictionary dictionary];
}

- (void)saveWindowLayouts {
  NSData *d = [NSJSONSerialization dataWithJSONObject:self.savedLayouts ?: @{} options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:[self windowLayoutStorePath] atomically:YES];
}

- (BOOL)ensureAccessibilityPermission {
  if (AXIsProcessTrusted()) return YES;
  static BOOL didPrompt = NO;
  if (!didPrompt) {
    didPrompt = YES;
    NSDictionary *opts = @{(__bridge NSString *)kAXTrustedCheckOptionPrompt: @YES};
    AXIsProcessTrustedWithOptions((__bridge CFDictionaryRef)opts);
  }
  if (AXIsProcessTrusted()) return YES;
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"窗口控制权限未生效";
  a.informativeText = @"请在 系统设置 → 隐私与安全性 → 设备控制和数据访问 中打开 DockLaunchers 控制台（旧版 macOS 叫「辅助功能」）。\n\n切换开关后，请点「重启控制台」让权限生效。";
  [a addButtonWithTitle:@"重试"];
  [a addButtonWithTitle:@"重启控制台"];
  [a addButtonWithTitle:@"打开系统设置"];
  [a addButtonWithTitle:@"取消"];
  NSModalResponse r = [a runModal];
  if (r == NSAlertFirstButtonReturn) return [self ensureAccessibilityPermission];
  if (r == NSAlertSecondButtonReturn) {
    NSString *bundle = [[NSBundle mainBundle] bundlePath];
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/bin/sh";
    t.arguments = @[@"-c", [NSString stringWithFormat:@"sleep 1; open \"%@\"", bundle]];
    @try { [t launch]; } @catch (NSException *e) {}
    [NSApp terminate:nil];
  } else if (r == NSAlertThirdButtonReturn) {
    [[NSWorkspace sharedWorkspace] openURL:[NSURL URLWithString:@"x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"]];
  }
  return NO;
}

- (NSArray<NSDictionary *> *)captureCurrentWindowLayout {
  NSMutableArray *windows = [NSMutableArray array];
  NSArray *infoList = CFBridgingRelease(CGWindowListCopyWindowInfo(kCGWindowListOptionAll | kCGWindowListExcludeDesktopElements, kCGNullWindowID));
  NSMutableDictionary *appsByPID = [NSMutableDictionary dictionary];
  for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) {
    if (app.activationPolicy == NSApplicationActivationPolicyRegular && app.processIdentifier != getpid()) appsByPID[@(app.processIdentifier)] = app;
  }
  for (NSDictionary *info in infoList) {
    NSNumber *layer = info[(__bridge NSString *)kCGWindowLayer];
    if (layer.integerValue != 0) continue;
    NSNumber *pidNum = info[(__bridge NSString *)kCGWindowOwnerPID];
    NSRunningApplication *app = appsByPID[pidNum];
    if (!app) continue;
    NSString *bundle = app.bundleIdentifier ?: @"";
    if (!bundle.length) continue;
    CGRect rect = CGRectZero;
    NSDictionary *bounds = info[(__bridge NSString *)kCGWindowBounds];
    if (!bounds || !CGRectMakeWithDictionaryRepresentation((__bridge CFDictionaryRef)bounds, &rect)) continue;
    if (rect.size.width < 120 || rect.size.height < 80) continue;
    NSString *title = info[(__bridge NSString *)kCGWindowName] ?: @"";
    BOOL onscreen = [info[(__bridge NSString *)kCGWindowIsOnscreen] boolValue];
    NSNumber *winID = info[(__bridge NSString *)kCGWindowNumber] ?: @0;
    [windows addObject:@{@"bundle": bundle, @"app": app.localizedName ?: bundle, @"title": title, @"onscreen": @(onscreen), @"winid": winID, @"x": @(rect.origin.x), @"y": @(rect.origin.y), @"w": @(rect.size.width), @"h": @(rect.size.height)}];
  }
  if (self.layoutSpaceCheck.state == NSControlStateValueOn && DLPrivateSpaceAPIAvailable()) {
    for (NSMutableDictionary *w in windows) {
      NSNumber *wid = w[@"winid"];
      if (!wid) continue;
      NSArray *spaces = [self privateSpacesForWindowID:wid.unsignedIntValue];
      if (spaces.count) w[@"space"] = spaces.firstObject;
    }
  }
  return windows;
}

- (NSArray<NSNumber *> *)privateSpacesForWindowID:(uint32_t)windowID {
  void *h = DLSkyLightHandle();
  if (!h) return @[];
  DL_CGSMainFn mainf = (DL_CGSMainFn)dlsym(h, "CGSMainConnectionID");
  DL_CGSCopySpacesForWindowsFn copyf = (DL_CGSCopySpacesForWindowsFn)dlsym(h, "CGSCopySpacesForWindows");
  if (!mainf || !copyf) return @[];
  CFNumberRef widNum = CFNumberCreate(NULL, kCFNumberSInt32Type, &windowID);
  CFArrayRef ids = CFArrayCreate(NULL, (const void **)&widNum, 1, &kCFTypeArrayCallBacks);
  CFArrayRef spaces = copyf(mainf(), 0x7, ids);
  CFRelease(ids);
  CFRelease(widNum);
  if (!spaces) return @[];
  NSArray *arr = CFBridgingRelease(spaces);
  NSMutableArray *out = [NSMutableArray array];
  for (id obj in arr) {
    if ([obj isKindOfClass:[NSNumber class]]) [out addObject:obj];
  }
  return out;
}

- (BOOL)privateSwitchToSpaceID:(uint64_t)spaceID {
  void *h = DLSkyLightHandle();
  if (!h) return NO;
  DL_CGSMainFn mainf = (DL_CGSMainFn)dlsym(h, "CGSMainConnectionID");
  DL_CGSCopyDisplaySpacesFn copyf = (DL_CGSCopyDisplaySpacesFn)dlsym(h, "CGSCopyManagedDisplaySpaces");
  DL_CGSSetCurrentSpaceFn setf = (DL_CGSSetCurrentSpaceFn)dlsym(h, "CGSManagedDisplaySetCurrentSpace");
  if (!mainf || !copyf || !setf) return NO;
  CFArrayRef displays = copyf(mainf());
  if (!displays) return NO;
  NSArray *displayArr = CFBridgingRelease(displays);
  for (NSDictionary *display in displayArr) {
    NSString *displayID = display[@"Display Identifier"];
    if (!displayID.length) continue;
    for (NSDictionary *space in display[@"Spaces"] ?: @[]) {
      NSNumber *sid = space[@"id64"] ?: space[@"ManagedSpaceID"];
      if (sid.unsignedLongLongValue == spaceID) {
        setf(mainf(), (__bridge CFStringRef)displayID, spaceID);
        return YES;
      }
    }
  }
  return NO;
}

- (uint64_t)spaceIDForLayout:(NSDictionary *)layout {
  for (NSDictionary *w in layout[@"windows"] ?: @[]) {
    NSNumber *space = w[@"space"];
    if (space.unsignedLongLongValue > 0) return space.unsignedLongLongValue;
  }
  return 0;
}

- (NSString *)runAppleScriptSource:(NSString *)source {
  NSAppleScript *script = [[NSAppleScript alloc] initWithSource:source];
  NSDictionary *err = nil;
  NSAppleEventDescriptor *result = [script executeAndReturnError:&err];
  return result ? [result stringValue] : @"";
}

- (NSDictionary<NSString *, NSArray<NSString *> *> *)captureSessionPages {
  NSMutableDictionary *out = [NSMutableDictionary dictionary];
  NSArray *browsers = @[@[@"com.apple.Safari", @"Safari"], @[@"com.google.Chrome", @"Google Chrome"]];
  for (NSArray *pair in browsers) {
    BOOL running = NO;
    for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) if ([app.bundleIdentifier isEqualToString:pair[0]]) { running = YES; break; }
    if (!running) continue;
    NSString *src = [NSString stringWithFormat:@"tell application \"%@\"\nset out to \"\"\nrepeat with w in windows\nrepeat with t in tabs of w\ntry\nset out to out & (URL of t as text) & linefeed\nend try\nend repeat\nend repeat\nreturn out\nend tell", pair[1]];
    NSString *result = [self runAppleScriptSource:src];
    NSMutableArray *urls = [NSMutableArray array];
    for (NSString *line in [result componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]]) {
      NSString *u = [line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
      if ([u hasPrefix:@"http"]) [urls addObject:u];
      if (urls.count >= 30) break;
    }
    if (urls.count) out[pair[0]] = urls;
  }
  BOOL finderRunning = NO;
  for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) if ([app.bundleIdentifier isEqualToString:@"com.apple.finder"]) { finderRunning = YES; break; }
  if (finderRunning) {
    NSString *src = @"tell application \"Finder\"\nset out to \"\"\nrepeat with w in windows\ntry\nset out to out & (POSIX path of (target of w as alias)) & linefeed\nend try\nend repeat\nreturn out\nend tell";
    NSString *result = [self runAppleScriptSource:src];
    NSMutableArray *paths = [NSMutableArray array];
    for (NSString *line in [result componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]]) {
      NSString *p = [line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
      if ([p hasPrefix:@"/"]) [paths addObject:p];
    }
    if (paths.count) out[@"com.apple.finder"] = paths;
  }
  return out;
}

- (BOOL)restoreSessionPages:(NSDictionary *)pages {
  NSMutableSet *opened = [NSMutableSet set];
  NSArray *browsers = @[@[@"com.apple.Safari", @"Safari"], @[@"com.google.Chrome", @"Google Chrome"]];
  for (NSArray *pair in browsers) {
    NSArray *urls = pages[pair[0]];
    if (!urls.count) continue;
    NSMutableArray *quoted = [NSMutableArray array];
    for (NSString *u in urls) [quoted addObject:[NSString stringWithFormat:@"\"%@\"", [u stringByReplacingOccurrencesOfString:@"\"" withString:@"\\\""]]];
    NSString *list = [quoted componentsJoinedByString:@", "];
    NSString *src;
    if ([pair[0] isEqualToString:@"com.apple.Safari"]) {
      src = [NSString stringWithFormat:@"tell application \"Safari\"\nset urls to {%@}\nrepeat with u in urls\nmake new document with properties {URL:u}\nend repeat\nend tell", list];
    } else {
      src = [NSString stringWithFormat:@"tell application \"Google Chrome\"\nset urls to {%@}\nrepeat with u in urls\nmake new window\nset URL of active tab of front window to u\nend repeat\nend tell", list];
    }
    [self runAppleScriptSource:src];
    [opened addObject:pair[0]];
  }
  NSArray *paths = pages[@"com.apple.finder"];
  for (NSString *p in paths) {
    [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:p]];
    [opened addObject:@"com.apple.finder"];
  }
  return opened.count > 0;
}

- (NSArray<NSDictionary *> *)captureCurrentApps {
  NSMutableArray *apps = [NSMutableArray array];
  for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) {
    if (app.activationPolicy != NSApplicationActivationPolicyRegular) continue;
    if (app.processIdentifier == getpid()) continue;
    NSString *bundle = app.bundleIdentifier ?: @"";
    if (!bundle.length) continue;
    [apps addObject:@{@"bundle": bundle, @"app": app.localizedName ?: bundle}];
  }
  return apps;
}

