- (void)addPDFPaths:(NSArray<NSString *> *)paths {
  NSFileManager *fm = [NSFileManager defaultManager];
  NSMutableArray *items = [self.pdfItems mutableCopy] ?: [NSMutableArray array];
  NSInteger added = 0;
  for (NSString *path in paths) {
    BOOL isDir = NO;
    if ([fm fileExistsAtPath:path isDirectory:&isDir] && isDir) {
      NSDirectoryEnumerator *en = [fm enumeratorAtPath:path];
      for (NSString *rel in en) {
        if (![rel.pathExtension.lowercaseString isEqualToString:@"pdf"]) continue;
        NSString *full = [path stringByAppendingPathComponent:rel];
        if (![items containsObject:full]) { [items addObject:full]; added++; }
      }
    } else if ([path.pathExtension.lowercaseString isEqualToString:@"pdf"] && ![items containsObject:path]) {
      [items addObject:path]; added++;
    }
  }
  self.pdfItems = items;
  [self.pdfTable reloadData];
  if (added) [self showToast:[NSString stringWithFormat:@"已添加 %ld 个 PDF", (long)added]];
}

- (void)addImagePaths:(NSArray<NSString *> *)paths {
  NSFileManager *fm = [NSFileManager defaultManager];
  NSSet *exts = [NSSet setWithArray:@[@"jpg", @"jpeg", @"png", @"heic", @"tiff", @"gif"]];
  NSMutableArray *items = [self.imageToolItems mutableCopy] ?: [NSMutableArray array];
  NSInteger added = 0;
  for (NSString *path in paths) {
    BOOL isDir = NO;
    if ([fm fileExistsAtPath:path isDirectory:&isDir] && isDir) {
      NSDirectoryEnumerator *en = [fm enumeratorAtPath:path];
      for (NSString *rel in en) {
        if (![exts containsObject:rel.pathExtension.lowercaseString]) continue;
        NSString *full = [path stringByAppendingPathComponent:rel];
        if (![items containsObject:full]) { [items addObject:full]; added++; }
      }
    } else if ([exts containsObject:path.pathExtension.lowercaseString] && ![items containsObject:path]) {
      [items addObject:path]; added++;
    }
  }
  self.imageToolItems = items;
  [self.imageToolTable reloadData];
  if (added) [self showToast:[NSString stringWithFormat:@"已添加 %ld 张图片", (long)added]];
}

- (void)pdfAddFiles:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = YES; p.canChooseDirectories = NO; p.allowsMultipleSelection = YES;
  p.allowedFileTypes = @[@"pdf"];
  if ([p runModal] != NSModalResponseOK) return;
  NSMutableArray *paths = [self.pdfItems mutableCopy] ?: [NSMutableArray array];
  for (NSURL *u in p.URLs) if (![paths containsObject:u.path]) [paths addObject:u.path];
  self.pdfItems = paths;
  [self.pdfTable reloadData];
}

- (void)pdfClear:(id)sender { self.pdfItems = @[]; [self.pdfTable reloadData]; }

- (void)pdfMerge:(id)sender {
  if (self.pdfItems.count < 2) { [self showToast:@"至少添加两个 PDF"]; return; }
  NSSavePanel *sp = [NSSavePanel savePanel];
  sp.nameFieldStringValue = @"合并.pdf";
  sp.allowedFileTypes = @[@"pdf"];
  if ([sp runModal] != NSModalResponseOK) return;
  NSArray *paths=[self.pdfItems copy]; NSURL *outURL=sp.URL;
  [self.pdfSpinner startAnimation:nil]; self.pdfStatus.stringValue=@"正在合并 PDF…";
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{
    PDFDocument *out = [[PDFDocument alloc] init];
    for (NSString *path in paths) {
      PDFDocument *doc = [[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:path]];
      if (!doc) continue;
      for (NSUInteger i = 0; i < doc.pageCount; i++) { PDFPage *page = [doc pageAtIndex:i]; if (page) [out insertPage:page atIndex:[out pageCount]]; }
    }
    BOOL ok=[out writeToURL:outURL];
    dispatch_async(dispatch_get_main_queue(),^{
      [self.pdfSpinner stopAnimation:nil];
      self.pdfStatus.stringValue=ok?[NSString stringWithFormat:@"已合并 %ld 个 PDF",(long)paths.count]:@"合并失败";
      if(ok){[self showToast:@"PDF 合并完成"];[[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[outURL]];}
    });
  });
}

- (void)pdfSplit:(id)sender {
  if (!self.pdfItems.count) { [self showToast:@"请先添加 PDF"]; return; }
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = NO; p.canChooseDirectories = YES; p.allowsMultipleSelection = NO;
  p.message = @"选择拆分后 PDF 的保存文件夹";
  if ([p runModal] != NSModalResponseOK) return;
  NSArray *paths=[self.pdfItems copy]; NSURL *outDir=p.URL;
  [self.pdfSpinner startAnimation:nil]; self.pdfStatus.stringValue=@"正在拆分 PDF…";
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{
    NSInteger made = 0;
    for (NSString *path in paths) {
      PDFDocument *doc = [[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:path]];
      if (!doc) continue;
      NSString *base = path.lastPathComponent.stringByDeletingPathExtension;
      for (NSUInteger i = 0; i < doc.pageCount; i++) {
        PDFDocument *one = [[PDFDocument alloc] init];
        PDFPage *page = [doc pageAtIndex:i]; if (!page) continue;
        [one insertPage:page atIndex:0];
        NSString *name = [NSString stringWithFormat:@"%@_第%ld页.pdf", base, (long)(i + 1)];
        if ([one writeToURL:[outDir URLByAppendingPathComponent:name]]) made++;
      }
    }
    dispatch_async(dispatch_get_main_queue(),^{
      [self.pdfSpinner stopAnimation:nil]; self.pdfStatus.stringValue=[NSString stringWithFormat:@"已拆分生成 %ld 个 PDF",(long)made];
      if(made>0){[self showToast:@"PDF 拆分完成"];[[NSWorkspace sharedWorkspace] openURL:outDir];}
    });
  });
}

- (id<NSPasteboardWriting>)tableView:(NSTableView *)tableView pasteboardWriterForRow:(NSInteger)row {
  if (tableView == self.shelfTable) {
    if (row < 0 || row >= (NSInteger)self.shelfVisiblePaths.count) return nil;
    NSPasteboardItem *item = [[NSPasteboardItem alloc] init];
    [item setString:[[NSURL fileURLWithPath:self.shelfVisiblePaths[row]] absoluteString] forType:NSPasteboardTypeFileURL];
    return item;
  }
  if (tableView != self.pdfTable) return nil;
  NSPasteboardItem *item = [[NSPasteboardItem alloc] init];
  [item setString:[NSString stringWithFormat:@"%ld", (long)row] forType:@"DockLaunchersPDFRow"];
  return item;
}

- (NSDragOperation)tableView:(NSTableView *)tableView validateDrop:(id<NSDraggingInfo>)info proposedRow:(NSInteger)row proposedDropOperation:(NSTableViewDropOperation)dropOperation {
  if (tableView != self.pdfTable && tableView != self.imageToolTable) return NSDragOperationNone;
  [tableView setDropRow:row dropOperation:NSTableViewDropAbove];
  if ([[info draggingPasteboard] availableTypeFromArray:@[NSPasteboardTypeFileURL, NSFilenamesPboardType]]) return NSDragOperationCopy;
  if (tableView != self.pdfTable) return NSDragOperationNone;
  return NSDragOperationMove;
}

- (BOOL)tableView:(NSTableView *)tableView acceptDrop:(id<NSDraggingInfo>)info row:(NSInteger)row dropOperation:(NSTableViewDropOperation)dropOperation {
  if (tableView != self.pdfTable && tableView != self.imageToolTable) return NO;
  NSPasteboard *pb = [info draggingPasteboard];
  NSMutableArray<NSString *> *incoming = [NSMutableArray array];
  NSArray *urls = [pb readObjectsForClasses:@[[NSURL class]] options:@{NSPasteboardURLReadingFileURLsOnlyKey: @YES}];
  for (NSURL *u in urls) if (u.path.length) [incoming addObject:u.path];
  if (!incoming.count) {
    NSArray *names = [pb propertyListForType:NSFilenamesPboardType];
    if ([names isKindOfClass:[NSArray class]]) for (id n in names) if ([n isKindOfClass:[NSString class]]) [incoming addObject:n];
  }
  if (incoming.count) {
    NSFileManager *fm = [NSFileManager defaultManager];
    NSMutableArray<NSString *> *expanded = [NSMutableArray array];
    for (NSString *path in incoming) {
      BOOL isDir = NO;
      if ([fm fileExistsAtPath:path isDirectory:&isDir] && isDir) {
        NSDirectoryEnumerator *en = [fm enumeratorAtPath:path];
        for (NSString *rel in en) {
          if ((tableView == self.pdfTable) ? [rel.pathExtension.lowercaseString isEqualToString:@"pdf"] : [@[@"jpg", @"jpeg", @"png", @"heic", @"tiff", @"gif"] containsObject:rel.pathExtension.lowercaseString]) [expanded addObject:[path stringByAppendingPathComponent:rel]];
        }
      } else {
        [expanded addObject:path];
      }
    }
    NSInteger added = 0;
    if (tableView == self.pdfTable) {
      NSMutableArray *paths = [self.pdfItems mutableCopy] ?: [NSMutableArray array];
      for (NSString *path in expanded) if ([path.pathExtension.lowercaseString isEqualToString:@"pdf"] && ![paths containsObject:path]) { [paths addObject:path]; added++; }
      self.pdfItems = paths;
      [self.pdfTable reloadData];
    } else {
      NSMutableArray *paths = [self.imageToolItems mutableCopy] ?: [NSMutableArray array];
      NSSet *exts = [NSSet setWithArray:@[@"jpg", @"jpeg", @"png", @"heic", @"tiff", @"gif"]];
      for (NSString *path in expanded) if ([exts containsObject:path.pathExtension.lowercaseString] && ![paths containsObject:path]) { [paths addObject:path]; added++; }
      self.imageToolItems = paths;
      [self.imageToolTable reloadData];
    }
    [self showToast:[NSString stringWithFormat:@"已添加 %ld 个文件", (long)added]];
    return YES;
  }
  if (tableView != self.pdfTable) return NO;
  NSString *value = [[info draggingPasteboard] stringForType:@"DockLaunchersPDFRow"];
  NSInteger from = value.integerValue;
  if (from < 0 || from >= (NSInteger)self.pdfItems.count) return NO;
  NSMutableArray *items = [self.pdfItems mutableCopy];
  id moved = items[from];
  [items removeObjectAtIndex:from];
  NSInteger to = row;
  if (to > from) to--;
  to = MAX(0, MIN(to, (NSInteger)items.count));
  [items insertObject:moved atIndex:to];
  self.pdfItems = items;
  [self.pdfTable reloadData];
  return YES;
}

- (NSDragOperation)tableView:(NSTableView *)tableView draggingSession:(NSDraggingSession *)session sourceOperationMaskForDraggingContext:(NSDraggingContext)context {
  return tableView == self.pdfTable ? NSDragOperationMove : NSDragOperationNone;
}

- (void)pdfMoveSelectedUp:(id)sender {
  NSInteger row = self.pdfTable.selectedRow;
  if (row <= 0 || row >= (NSInteger)self.pdfItems.count) return;
  NSMutableArray *items = [self.pdfItems mutableCopy];
  [items exchangeObjectAtIndex:row withObjectAtIndex:row - 1];
  self.pdfItems = items;
  [self.pdfTable reloadData];
  [self.pdfTable selectRowIndexes:[NSIndexSet indexSetWithIndex:row - 1] byExtendingSelection:NO];
}

- (void)pdfMoveSelectedDown:(id)sender {
  NSInteger row = self.pdfTable.selectedRow;
  if (row < 0 || row + 1 >= (NSInteger)self.pdfItems.count) return;
  NSMutableArray *items = [self.pdfItems mutableCopy];
  [items exchangeObjectAtIndex:row withObjectAtIndex:row + 1];
  self.pdfItems = items;
  [self.pdfTable reloadData];
  [self.pdfTable selectRowIndexes:[NSIndexSet indexSetWithIndex:row + 1] byExtendingSelection:NO];
}

- (void)pdfExportImages:(id)sender {
  if (!self.pdfItems.count) { [self showToast:@"请先添加 PDF"]; return; }
  NSInteger row = self.pdfTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.pdfItems.count) row = 0;
  NSString *path = self.pdfItems[row];
  PDFDocument *doc = [[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:path]];
  if (!doc) { [self showToast:@"PDF 读取失败"]; return; }
  NSInteger total = doc.pageCount;
  NSInteger start = self.pdfStartField.integerValue; if (start <= 0) start = 1;
  NSInteger end = self.pdfEndField.integerValue; if (end <= 0) end = total;
  start = MAX(1, MIN(start, total)); end = MAX(1, MIN(end, total));
  if (start > end) { NSInteger t = start; start = end; end = t; }
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = NO; p.canChooseDirectories = YES; p.allowsMultipleSelection = NO;
  p.message = @"选择图片保存文件夹";
  if ([p runModal] != NSModalResponseOK) return;
  NSString *base = path.lastPathComponent.stringByDeletingPathExtension;
  NSInteger made = 0;
  for (NSInteger i = start - 1; i < end; i++) {
    PDFPage *page = [doc pageAtIndex:i];
    if (!page) continue;
    NSImage *img = [page thumbnailOfSize:NSMakeSize(1600, 2200) forBox:kPDFDisplayBoxMediaBox];
    if (!img) continue;
    NSBitmapImageRep *rep = [NSBitmapImageRep imageRepWithData:[img TIFFRepresentation]];
    NSData *png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    if (!png) continue;
    NSString *name = [NSString stringWithFormat:@"%@_第%ld页.png", base, (long)(i + 1)];
    if ([png writeToFile:[p.URL.path stringByAppendingPathComponent:name] atomically:YES]) made++;
  }
  [self showToast:[NSString stringWithFormat:@"已导出 %ld 张图片", (long)made]];
  if (made > 0) [[NSWorkspace sharedWorkspace] openURL:p.URL];
}

- (void)pdfExtractPages:(id)sender {
  if (!self.pdfItems.count) { [self showToast:@"请先添加 PDF"]; return; }
  NSInteger row = self.pdfTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.pdfItems.count) row = 0;
  NSString *path = self.pdfItems[row];
  PDFDocument *doc = [[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:path]];
  if (!doc) { [self showToast:@"PDF 读取失败"]; return; }
  NSInteger total = doc.pageCount;
  NSInteger start = self.pdfStartField.integerValue;
  NSInteger end = self.pdfEndField.integerValue;
  if (start <= 0) start = 1;
  if (end <= 0) end = total;
  start = MAX(1, MIN(start, total));
  end = MAX(1, MIN(end, total));
  if (start > end) { NSInteger t = start; start = end; end = t; }
  NSSavePanel *sp = [NSSavePanel savePanel];
  NSString *base = path.lastPathComponent.stringByDeletingPathExtension;
  sp.nameFieldStringValue = [NSString stringWithFormat:@"%@_第%ld-%ld页.pdf", base, (long)start, (long)end];
  sp.allowedFileTypes = @[@"pdf"];
  if ([sp runModal] != NSModalResponseOK) return;
  PDFDocument *out = [[PDFDocument alloc] init];
  for (NSInteger i = start - 1; i < end; i++) {
    PDFPage *page = [doc pageAtIndex:i];
    if (page) [out insertPage:page atIndex:[out pageCount]];
  }
  if (![out writeToURL:sp.URL]) { [self showToast:@"提取失败"]; return; }
  [self showToast:[NSString stringWithFormat:@"已提取第 %ld–%ld 页", (long)start, (long)end]];
  [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[sp.URL]];
}

- (NSArray<NSString *> *)finderSelectedPaths {
  NSString *source = @"tell application \"Finder\"\nset sel to selection as alias list\nset out to \"\"\nrepeat with f in sel\nset out to out & (POSIX path of f) & linefeed\nend repeat\nreturn out\nend tell";
  NSAppleScript *script = [[NSAppleScript alloc] initWithSource:source];
  NSDictionary *err = nil;
  NSAppleEventDescriptor *result = [script executeAndReturnError:&err];
  if (!result || err) return @[];
  NSString *out = result.stringValue ?: @"";
  NSMutableArray *paths = [NSMutableArray array];
  for (NSString *line in [out componentsSeparatedByString:@"\n"]) {
    NSString *p = [line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (p.length) [paths addObject:p];
  }
  return paths;
}

