- (void)performRadialAction:(NSString *)action {
  if ([action hasPrefix:@"custom://"]) {
    NSArray *items = [[NSUserDefaults standardUserDefaults] arrayForKey:@"centerRadialCustomItems"] ?: @[];
    for (NSDictionary *it in items) {
      if (![it[@"action"] isEqualToString:action]) continue;
      NSString *type = it[@"customType"] ?: @"url";
      NSString *value = it[@"customValue"] ?: @"";
      if (!value.length) return;
      if ([type isEqualToString:@"shell"]) {
        NSTask *task = [[NSTask alloc] init];
        task.launchPath = @"/bin/sh";
        task.arguments = @[@"-lc", value];
        @try { [task launch]; } @catch (NSException *e) { [self showToast:@"命令启动失败"]; }
      } else {
        NSURL *url = nil;
        if ([type isEqualToString:@"url"]) {
          NSString *u = value;
          if (![u containsString:@"://"]) u = [@"https://" stringByAppendingString:u];
          url = [NSURL URLWithString:u];
        } else {
          url = [NSURL fileURLWithPath:[value stringByExpandingTildeInPath]];
        }
        if (url) [[NSWorkspace sharedWorkspace] openURL:url];
      }
      return;
    }
    return;
  }
  if (!action.length) return;
  if ([action isEqualToString:@"translate"]) [self showTranslationWindow:nil];
  else if ([action isEqualToString:@"screenshottranslate"]) [self beginScreenshotTranslation];
  else if ([action isEqualToString:@"compress"]) [self showCompressWindow:nil];
  else if ([action isEqualToString:@"pdf"]) [self showPDFTools:nil];
  else if ([action isEqualToString:@"image"]) [self showImageTools:nil];
  else if ([action isEqualToString:@"rename"]) [self showBatchRenamer:nil];
  else if ([action isEqualToString:@"clipboard"]) [self showClipboardWindow:nil];
  else if ([action isEqualToString:@"groups"]) [self showGroupPanel:nil];
  else if ([action isEqualToString:@"scene"]) { [self rebuildQuickSceneTab]; [self showDetachedPage:self.quickScenePage title:@"场景模式"]; }
  else if ([action isEqualToString:@"ai"]) { if ([self ensureAIManagementAccess]) { [self rebuildQuickAITab]; [self showDetachedPage:self.quickAIPage title:@"AI 管理"]; } }
  else if ([action isEqualToString:@"aimgmtpage"]) [self openAIManagementFromMenu];
  else if ([action isEqualToString:@"aifile"]) [self openAIFileAnalyzer:nil];
  else if ([action isEqualToString:@"automation"]) [self openAutomationRules:nil];
  else if ([action isEqualToString:@"groupschedule"]) [self openGroupScheduleRules:nil];
  else if ([action isEqualToString:@"layouts"]) [self showWindowLayouts:nil];
  else if ([action isEqualToString:@"largefiles"]) [self showLargeFileCleaner:nil];
  else if ([action isEqualToString:@"duplicates"]) [self showDuplicateFinder:nil];
  else if ([action isEqualToString:@"startup"]) [self showStartupItems:nil];
  else if ([action isEqualToString:@"process"]) [self showProcessManager:nil];
  else if ([action isEqualToString:@"usage"]) [self showUsageStats:nil];
  else if ([action isEqualToString:@"appsearch"]) [self showAppSearch:nil];
  else if ([action isEqualToString:@"quickpanel"]) [self showQuickPanel];
  else if ([action isEqualToString:@"prompts"]) [self showPromptLibrary:nil];
  else if ([action isEqualToString:@"appearance"]) [self showDockAppearance:nil];
  else if ([action isEqualToString:@"password"]) [self showPasswordSettings:nil];
  else if ([action isEqualToString:@"appshortcuts"]) [self showAppShortcutSettings:nil];
  else if ([action isEqualToString:@"globalshortcuts"]) [self openShortcutSettings:nil];
  else if ([action isEqualToString:@"disk"]) [self openDiskAnalysisFromMenu];
  else if ([action isEqualToString:@"capture"]) [self showCaptureTool:nil];
  else if ([action isEqualToString:@"pinshot"]) [self pinScreenshotInteractive:nil];
  else if ([action isEqualToString:@"scrollshot"]) [self startScrollCapture:nil];
  else if ([action isEqualToString:@"fullshot"]) [self captureFullScreen:nil];
  else if ([action isEqualToString:@"recordtoggle"]) [self captureVideo:nil];
  else if ([action isEqualToString:@"recordpause"]) [self pauseCapture:nil];
  else if ([action isEqualToString:@"videopost"]) [self openVideoPostWindow:nil];
  else if ([action isEqualToString:@"colorsampler"]) [self showColorSampler:nil];
  else if ([action isEqualToString:@"filesearch"]) [self showFileSearch:nil];
  else if ([action isEqualToString:@"recordrecent"]) [self openMostRecentRecording];
  else if ([action isEqualToString:@"meeting"]) [self openMeetingAssistant:nil];
  else if ([action isEqualToString:@"voicetext"]) [self openVoiceTextWindow:nil];
  else if ([action isEqualToString:@"tts"]) [self openAITTSWindow:nil];
  else if ([action isEqualToString:@"capturehistory"]) [self showCaptureHistory:nil];
  else if ([action isEqualToString:@"ocr"]) [self ocrLatestScreenshot:nil];
  else if ([action isEqualToString:@"shelf"]) [self openShelfWindow:nil];
  else if ([action isEqualToString:@"aitext"]) [self openAIAssistant:nil];
  else if ([action isEqualToString:@"aiimage"]) [self openAIImagePanel:nil];
  else if ([action isEqualToString:@"aivideo"]) [self openAIVideoPanel:nil];
  else if ([action isEqualToString:@"aivision"]) [self openAIVisionPanel:nil];
  else if ([action isEqualToString:@"aiedit"]) [self openAIEditPanel:nil];
  else if ([action isEqualToString:@"uninstall"]) [self openUninstallFromMenu];
}

- (void)showDetachedPage:(NSView *)page title:(NSString *)title {
  if (!page) return;
  if (!self.detachedPanels) self.detachedPanels = [NSMapTable strongToStrongObjectsMapTable];
  if (!self.detachedScrolls) self.detachedScrolls = [NSMapTable strongToStrongObjectsMapTable];
  NSString *key = [NSString stringWithFormat:@"%@-%p", title, page];
  NSWindow *existing = [self.detachedPanels objectForKey:key];
  if (existing) {
    page.hidden = NO;
    [NSApp activateIgnoringOtherApps:YES];
    [existing makeKeyAndOrderFront:nil];
    [existing orderFrontRegardless];
    return;
  }
  [page removeFromSuperview];
  page.hidden = NO;
  CGFloat pw = MAX(360, page.frame.size.width);
  CGFloat ph = MAX(260, page.frame.size.height);
  NSWindow *w = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,pw+16,ph+56) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable|NSWindowStyleMaskMiniaturizable) backing:NSBackingStoreBuffered defer:NO];
  w.title = title;
  w.releasedWhenClosed = NO;
  w.level = NSNormalWindowLevel;
  NSView *cv = w.contentView;
  NSTextField *tl = [[NSTextField alloc] initWithFrame:NSMakeRect(12, ph+22, 220, 20)];
  tl.editable = NO; tl.bordered = NO; tl.drawsBackground = NO;
  tl.font = [NSFont systemFontOfSize:12 weight:NSFontWeightSemibold];
  tl.stringValue = title;
  [cv addSubview:tl];
  NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(8, 8, pw, ph)];
  sv.hasHorizontalScroller = YES; sv.hasVerticalScroller = YES;
  sv.autohidesScrollers = YES;
  sv.allowsMagnification = YES;
  sv.minMagnification = 0.5;
  sv.maxMagnification = 2.0;
  sv.magnification = 1.0;
  sv.drawsBackground = YES;
  sv.backgroundColor = [NSColor controlBackgroundColor];
  [sv setDocumentView:page];
  [cv addSubview:sv];
  [self.detachedPanels setObject:w forKey:key];
  [self.detachedScrolls setObject:sv forKey:w];
  [self applyWindowChrome:w];
  [w center];
  [NSApp activateIgnoringOtherApps:YES];
  [w makeKeyAndOrderFront:nil];
  [w orderFrontRegardless];
}

- (NSScrollView *)scrollForDetachedWindow:(NSWindow *)w {
  return w ? [self.detachedScrolls objectForKey:w] : nil;
}

- (void)toggleDetachedPin:(ColorHoverButton *)sender {
  NSWindow *w = sender.window;
  if (!w) return;
  BOOL pinned = [objc_getAssociatedObject(w, "DLDetachedPinned") boolValue];
  BOOL nowPinned = !pinned;
  objc_setAssociatedObject(w, "DLDetachedPinned", @(nowPinned), OBJC_ASSOCIATION_RETAIN_NONATOMIC);
  w.level = NSNormalWindowLevel;
  sender.title = nowPinned ? @"浮动" : @"钉住";
  sender.hoverColor = nowPinned ? [NSColor systemOrangeColor] : [NSColor systemGrayColor];
}

- (void)zoomDetachedOut:(id)sender {
  NSScrollView *sv = [self scrollForDetachedWindow:[(NSButton *)sender window]];
  if (!sv) return;
  NSView *doc = sv.documentView;
  NSPoint anchor = NSMakePoint(NSMinX(doc.bounds), NSMaxY(doc.bounds));
  [sv setMagnification:MAX(sv.minMagnification, sv.magnification - 0.15) centeredAtPoint:anchor];
}

- (void)zoomDetachedIn:(id)sender {
  NSScrollView *sv = [self scrollForDetachedWindow:[(NSButton *)sender window]];
  if (!sv) return;
  NSView *doc = sv.documentView;
  NSPoint anchor = NSMakePoint(NSMinX(doc.bounds), NSMaxY(doc.bounds));
  [sv setMagnification:MIN(sv.maxMagnification, sv.magnification + 0.15) centeredAtPoint:anchor];
}

- (void)layoutFilterChanged:(id)sender { [self reloadLayoutVisibleNames]; }

- (void)reloadLayoutVisibleNames {
  NSArray *all = [[self.savedLayouts allKeys] sortedArrayUsingSelector:@selector(localizedCompare:)];
  NSString *q = [self.layoutSearch.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]].lowercaseString;
  if (q.length) {
    NSMutableArray *out = [NSMutableArray array];
    for (NSString *n in all) if ([n.lowercaseString containsString:q]) [out addObject:n];
    self.layoutVisibleNames = out;
  } else {
    self.layoutVisibleNames = all;
  }
  [self.layoutTable reloadData];
  [self.layoutTable deselectAll:nil];
  if (self.layoutTable.numberOfRows > 0) [self.layoutTable selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];
}

- (void)showWindowLayouts:(id)sender {
  [self loadWindowLayouts];
  if (!self.layoutWindow) {
    self.layoutWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,600,480) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable) backing:NSBackingStoreBuffered defer:NO];
    self.layoutWindow.title = @"窗口布局记忆";
    self.layoutWindow.releasedWhenClosed = NO;
    self.layoutWindow.level = NSNormalWindowLevel;
    NSView *cv = self.layoutWindow.contentView;
    NSTextField *title = [self label:@"窗口布局记忆" size:20 bold:YES color:nil];
    title.frame = NSMakeRect(20, 430, 300, 28); [cv addSubview:title];
    NSTextField *sub = [self label:@"单击选中布局，双击恢复；保存不需要权限，恢复需要窗口控制权限" size:10 bold:NO color:[NSColor secondaryLabelColor]];
    sub.frame = NSMakeRect(20, 408, 520, 18); [cv addSubview:sub];
    self.layoutSearch = [[NSSearchField alloc] initWithFrame:NSMakeRect(400, 426, 180, 26)];
    self.layoutSearch.placeholderString = @"搜索布局";
    self.layoutSearch.target = self; self.layoutSearch.action = @selector(layoutFilterChanged:);
    [self.layoutSearch setContinuous:YES];
    [cv addSubview:self.layoutSearch];
    NSPopUpButton *presetPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(300,426,92,26) pullsDown:NO];
    [presetPopup addItemsWithTitles:@[@"快速布局", @"左右分屏", @"上下分屏", @"四宫格"]];
    presetPopup.target = self; presetPopup.action = @selector(applyLayoutPresetFromPopup:);
    [cv addSubview:presetPopup];
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 116, 568, 276)];
    sv.hasVerticalScroller = YES; sv.borderType = NSBezelBorder;
    self.layoutTable = [[NSTableView alloc] initWithFrame:sv.contentView.bounds];
    NSArray *cols = @[@[@"lname", @"布局名称", @220.0], @[@"lcount", @"窗口数", @80.0], @[@"ldate", @"保存时间", @180.0]];
    for (NSArray *c in cols) {
      NSTableColumn *col = [[NSTableColumn alloc] initWithIdentifier:c[0]];
      col.title = c[1]; col.width = [c[2] doubleValue];
      [self.layoutTable addTableColumn:col];
    }
    self.layoutTable.rowHeight = 36;
    self.layoutTable.dataSource = self; self.layoutTable.delegate = self;
    sv.documentView = self.layoutTable; [cv addSubview:sv];
    self.layoutSpaceCheck = [NSButton checkboxWithTitle:@"实验性：按桌面恢复" target:self action:@selector(layoutSpaceToggled:)];
    self.layoutSpaceCheck.state = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerLayoutExperimentalSpace"] ? NSControlStateValueOn : NSControlStateValueOff;
    self.layoutSpaceCheck.frame = NSMakeRect(16, 84, 190, 20);
    self.layoutSpaceCheck.toolTip = @"使用 macOS 私有 API 记录和切换桌面；失败时自动回退";
    [cv addSubview:self.layoutSpaceCheck];
    self.layoutAutoLaunchCheck = [NSButton checkboxWithTitle:@"自动启动缺失应用" target:self action:nil];
    self.layoutAutoLaunchCheck.state = NSControlStateValueOn;
    self.layoutAutoLaunchCheck.frame = NSMakeRect(212, 84, 160, 20); [cv addSubview:self.layoutAutoLaunchCheck];
    self.layoutAXButton = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(392, 84, 170, 20)];
    self.layoutAXButton.title = @"窗口控制权限"; self.layoutAXButton.hoverColor = [NSColor systemOrangeColor];
    self.layoutAXButton.target = self; self.layoutAXButton.action = @selector(requestLayoutAccessibility:);
    [self.layoutAXButton applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
    [cv addSubview:self.layoutAXButton];
    NSArray *actions = @[@[@"保存当前布局", @"saveCurrentWindowLayout:", @16.0, @130.0, [NSColor systemGreenColor]],
                         @[@"恢复选中布局", @"restoreSelectedWindowLayout:", @154.0, @130.0, [NSColor systemBlueColor]],
                         @[@"删除", @"deleteSelectedWindowLayout:", @292.0, @72.0, [NSColor systemRedColor]],
                         @[@"重命名", @"renameSelectedWindowLayout:", @372.0, @90.0, [NSColor systemOrangeColor]],
                         @[@"关闭", @"closeWindowLayouts:", @488.0, @80.0, [NSColor systemGrayColor]]];
    for (NSArray *d in actions) {
      ColorHoverButton *b = [[ColorHoverButton alloc] initWithFrame:NSMakeRect([d[2] doubleValue], 40, [d[3] doubleValue], 32)];
      b.title = d[0]; b.hoverColor = d[4]; b.target = self; b.action = NSSelectorFromString(d[1]);
      [b applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
      [cv addSubview:b];
    }
    [self.layoutWindow center];
  }
  [self reloadLayoutVisibleNames];
  if (self.layoutTable.numberOfRows > 0 && self.layoutTable.selectedRow < 0) {
    [self.layoutTable selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];
  }
  self.layoutTable.target = self;
  self.layoutTable.doubleAction = @selector(restoreSelectedWindowLayout:);
  if (self.layoutAXButton) {
    BOOL trusted = AXIsProcessTrusted();
    self.layoutAXButton.title = trusted ? @"窗口控制：已授权" : @"窗口控制权限";
    [self.layoutAXButton applyColor:trusted ? [NSColor systemGreenColor] : DLButtonBackground() textColor:trusted ? [NSColor whiteColor] : [NSColor labelColor]];
  }
  [NSApp activateIgnoringOtherApps:YES];
  [self.layoutWindow makeKeyAndOrderFront:nil];
  [self.layoutWindow orderFrontRegardless];
}

- (void)layoutSpaceToggled:(NSButton *)sender {
  if (sender.state == NSControlStateValueOn && !DLPrivateSpaceAPIAvailable()) {
    sender.state = NSControlStateValueOff;
    [self showToast:@"当前 macOS 不支持私有桌面接口，已关闭"];
    return;
  }
  if (sender.state == NSControlStateValueOn) {
    NSAlert *a = [[NSAlert alloc] init];
    a.messageText = @"启用实验性桌面恢复？";
    a.informativeText = @"该功能使用 macOS 私有接口记录和切换桌面，可能在系统更新后失效，偶发导致桌面/Dock 异常。失败时会自动回退，不会修改文件。";
    [a addButtonWithTitle:@"启用"];
    [a addButtonWithTitle:@"取消"];
    if ([a runModal] != NSAlertFirstButtonReturn) { sender.state = NSControlStateValueOff; return; }
  }
  [[NSUserDefaults standardUserDefaults] setBool:(sender.state == NSControlStateValueOn) forKey:@"centerLayoutExperimentalSpace"];
}

- (void)requestLayoutAccessibility:(id)sender {
  if (AXIsProcessTrusted()) {
    self.layoutAXButton.title = @"窗口控制：已授权";
    [self.layoutAXButton applyColor:[NSColor systemGreenColor] textColor:[NSColor whiteColor]];
    [self showToast:@"窗口控制权限已生效"];
    return;
  }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"需要开启窗口控制权限";
  a.informativeText = [NSString stringWithFormat:@"macOS 27 的路径是：\n系统设置 → 隐私与安全性 → 设备控制和数据访问\n（旧版 macOS 叫「辅助功能」）\n\n在列表里找到 DockLaunchers控制台.app，打开开关。\n\n当前应用路径：%@\n\n如果没有条目，点列表下方的「+」添加；如果有多条旧记录，先删除再重新添加。开启后请重启控制台。", [[NSBundle mainBundle] bundlePath]];
  [a addButtonWithTitle:@"打开系统设置"];
  [a addButtonWithTitle:@"在 Finder 中显示"];
  [a addButtonWithTitle:@"好"];
  NSModalResponse r = [a runModal];
  if (r == NSAlertFirstButtonReturn) {
    [[NSWorkspace sharedWorkspace] openURL:[NSURL URLWithString:@"x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"]];
  } else if (r == NSAlertSecondButtonReturn) {
    [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:[[NSBundle mainBundle] bundlePath]]]];
  }
}

- (void)applyLayoutPresetFromPopup:(NSPopUpButton *)sender {
  NSInteger idx = sender.indexOfSelectedItem;
  [sender selectItemAtIndex:0];
  if (idx == 1) [self arrangeFrontmostAppWindows:1];
  else if (idx == 2) [self arrangeFrontmostAppWindows:2];
  else if (idx == 3) [self arrangeFrontmostAppWindows:3];
}

- (void)applyLayoutPresetLeftRight:(id)sender { [self arrangeFrontmostAppWindows:1]; }
- (void)applyLayoutPresetTopBottom:(id)sender { [self arrangeFrontmostAppWindows:2]; }
- (void)applyLayoutPresetGrid:(id)sender { [self arrangeFrontmostAppWindows:3]; }

- (void)arrangeFrontmostAppWindows:(NSInteger)preset {
  if (![self ensureAccessibilityPermission]) return;
  NSRunningApplication *front = [[NSWorkspace sharedWorkspace] frontmostApplication];
  if (!front || front.processIdentifier == [[NSProcessInfo processInfo] processIdentifier]) {
    [self showToast:@"请先切换到要排列窗口的应用"];
    return;
  }
  AXUIElementRef app = AXUIElementCreateApplication(front.processIdentifier);
  CFTypeRef raw = NULL;
  NSArray *wins = nil;
  if (AXUIElementCopyAttributeValue(app, kAXWindowsAttribute, &raw) == kAXErrorSuccess && raw) {
    wins = CFBridgingRelease(raw);
  }
  CFRelease(app);
  if (!wins.count) { [self showToast:@"当前应用没有可排列的窗口"]; return; }
  NSScreen *screen = [NSScreen mainScreen];
  NSRect vis = screen.visibleFrame;
  CGFloat gap = 8;
  CGFloat halfW = (vis.size.width - gap * 3) / 2.0;
  CGFloat halfH = (vis.size.height - gap * 3) / 2.0;
  CGFloat screenH = screen.frame.size.height;
  NSInteger n = MIN((NSInteger)wins.count, preset == 3 ? 4 : 2);
  for (NSInteger i = 0; i < n; i++) {
    AXUIElementRef win = (__bridge AXUIElementRef)wins[i];
    NSRect r = vis;
    if (preset == 1) { r = NSMakeRect(i == 0 ? vis.origin.x + gap : vis.origin.x + gap * 2 + halfW, vis.origin.y + gap, halfW, vis.size.height - gap * 2); }
    else if (preset == 2) { r = NSMakeRect(vis.origin.x + gap, i == 0 ? vis.origin.y + gap * 2 + halfH : vis.origin.y + gap, vis.size.width - gap * 2, halfH); }
    else {
      CGFloat x = vis.origin.x + gap + (i % 2) * (halfW + gap);
      CGFloat y = vis.origin.y + gap + (i / 2) * (halfH + gap);
      r = NSMakeRect(x, y, halfW, halfH);
    }
    CGPoint p = CGPointMake(r.origin.x, screenH - (r.origin.y + r.size.height));
    CGSize sz = CGSizeMake(r.size.width, r.size.height);
    AXValueRef posVal = AXValueCreate(kAXValueCGPointType, &p);
    AXValueRef sizeVal = AXValueCreate(kAXValueCGSizeType, &sz);
    AXUIElementSetAttributeValue(win, kAXMinimizedAttribute, kCFBooleanFalse);
    if (posVal) { AXUIElementSetAttributeValue(win, kAXPositionAttribute, posVal); CFRelease(posVal); }
    if (sizeVal) { AXUIElementSetAttributeValue(win, kAXSizeAttribute, sizeVal); CFRelease(sizeVal); }
  }
  [self showToast:preset == 1 ? @"已左右分屏" : (preset == 2 ? @"已上下分屏" : @"已四宫格排列")];
}

- (void)saveCurrentWindowLayout:(id)sender {
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"保存窗口布局";
  a.informativeText = @"输入一个布局名称，例如：工作、下班、剪辑。";
  NSTextField *tf = [[NSTextField alloc] initWithFrame:NSMakeRect(0,0,300,26)];
  tf.placeholderString = @"布局名称";
  a.accessoryView = tf;
  [a addButtonWithTitle:@"保存"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSString *name = [tf.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!name.length) { [self showToast:@"布局名称不能为空"]; return; }
  NSArray *windows = [self captureCurrentWindowLayout];
  NSArray *apps = [self captureCurrentApps];
  NSDictionary *pages = [self captureSessionPages];
  if (!windows.count && !apps.count) { [self showToast:@"没有可保存的窗口或应用"]; return; }
  self.savedLayouts[name] = @{@"date": @([[NSDate date] timeIntervalSince1970]), @"windows": windows, @"apps": apps, @"pages": pages};
  [self saveWindowLayouts];
  [self reloadLayoutVisibleNames];
  NSInteger idx = [self.layoutVisibleNames indexOfObject:name];
  if (idx != NSNotFound) [self.layoutTable selectRowIndexes:[NSIndexSet indexSetWithIndex:idx] byExtendingSelection:NO];
  [self showToast:[NSString stringWithFormat:@"已保存「%@」：%ld 个窗口、%ld 个应用", name, (long)windows.count, (long)apps.count]];
}

- (void)restoreSelectedWindowLayout:(id)sender {
  if (![self ensureAccessibilityPermission]) return;
  NSInteger row = self.layoutTable.selectedRow;
  NSArray *names = self.layoutVisibleNames ?: @[];
  if (row < 0 || row >= (NSInteger)names.count) { [self showToast:@"请先选择一个布局"]; return; }
  BOOL autoLaunch = !self.layoutAutoLaunchCheck || self.layoutAutoLaunchCheck.state == NSControlStateValueOn;
  [self restoreWindowLayoutNamed:names[row] autoLaunch:autoLaunch];
}

- (NSInteger)axWindowCountForPID:(pid_t)pid {
  AXUIElementRef axApp = AXUIElementCreateApplication(pid);
  CFTypeRef raw = NULL;
  NSInteger count = 0;
  if (AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute, &raw) == kAXErrorSuccess && raw) {
    NSArray *wins = CFBridgingRelease(raw);
    count = wins.count;
  }
  CFRelease(axApp);
  return count;
}

- (void)restoreWindowLayoutNamed:(NSString *)name autoLaunch:(BOOL)autoLaunch {
  [self loadWindowLayouts];
  if (![self ensureAccessibilityPermission]) return;
  NSDictionary *layout = self.savedLayouts[name];
  NSArray *windows = layout[@"windows"] ?: @[];
  NSArray *appList = layout[@"apps"] ?: @[];
  if (self.layoutSpaceCheck.state == NSControlStateValueOn && DLPrivateSpaceAPIAvailable()) {
    uint64_t space = [self spaceIDForLayout:layout];
    if (space > 0 && [self privateSwitchToSpaceID:space]) {
      [self showToast:@"正在切换到保存的桌面…"];
      [NSThread sleepForTimeInterval:0.4];
    }
  }
  if (!windows.count && !appList.count) { [self showToast:@"该布局没有记录"]; return; }
  NSDictionary *pages = layout[@"pages"] ?: @{};
  if (autoLaunch && pages.count) {
    BOOL opened = [self restoreSessionPages:pages];
    if (opened) {
      [self showToast:@"正在恢复网页/文件夹并调整窗口…"];
      __weak typeof(self) weakSelf = self;
      dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(3.0 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        [weakSelf applyWindowLayoutNamed:name];
      });
      return;
    }
  }
  NSMutableSet *required = [NSMutableSet set];
  for (NSDictionary *w in windows) if ([w[@"bundle"] length]) [required addObject:w[@"bundle"]];
  for (NSDictionary *a in appList) if ([a[@"bundle"] length]) [required addObject:a[@"bundle"]];
  if (autoLaunch && required.count) {
    NSMutableDictionary *running = [NSMutableDictionary dictionary];
    for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) {
      if (app.activationPolicy == NSApplicationActivationPolicyRegular && app.bundleIdentifier.length) running[app.bundleIdentifier] = app;
    }
    NSInteger launched = 0, reopened = 0;
    for (NSString *bundle in required) {
      NSRunningApplication *app = running[bundle];
      if (!app) {
        NSURL *url = [[NSWorkspace sharedWorkspace] URLForApplicationWithBundleIdentifier:bundle];
        if (!url) continue;
        NSWorkspaceOpenConfiguration *cfg = [NSWorkspaceOpenConfiguration configuration];
        cfg.activates = NO;
        [[NSWorkspace sharedWorkspace] openApplicationAtURL:url configuration:cfg completionHandler:nil];
        launched++;
      } else if ([self axWindowCountForPID:app.processIdentifier] == 0) {
        NSURL *url = [[NSWorkspace sharedWorkspace] URLForApplicationWithBundleIdentifier:bundle];
        if (!url) continue;
        NSWorkspaceOpenConfiguration *cfg = [NSWorkspaceOpenConfiguration configuration];
        cfg.activates = NO;
        [[NSWorkspace sharedWorkspace] openApplicationAtURL:url configuration:cfg completionHandler:nil];
        reopened++;
      }
    }
    if (launched + reopened > 0) {
      [self showToast:[NSString stringWithFormat:@"正在启动 %ld 个应用、重开 %ld 个窗口…", (long)launched, (long)reopened]];
      __weak typeof(self) weakSelf = self;
      dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(2.8 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
        [weakSelf applyWindowLayoutNamed:name];
      });
      return;
    }
  }
  [self applyWindowLayoutNamed:name];
}

- (void)applyWindowLayoutNamed:(NSString *)name {
  NSDictionary *layout = self.savedLayouts[name] ?: @{};
  NSArray *windows = layout[@"windows"] ?: @[];
  NSMutableDictionary *apps = [NSMutableDictionary dictionary];
  for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) {
    if (app.activationPolicy == NSApplicationActivationPolicyRegular && app.bundleIdentifier.length) apps[app.bundleIdentifier] = app;
  }
  NSInteger restored = 0, failed = 0;
  NSMutableDictionary *usedIndexes = [NSMutableDictionary dictionary];
  NSMutableSet *activatedApps = [NSMutableSet set];
  for (NSDictionary *w in windows) {
    NSRunningApplication *app = apps[w[@"bundle"] ?: @""];
    if (!app) continue;
    AXUIElementRef axApp = AXUIElementCreateApplication(app.processIdentifier);
    CFTypeRef raw = NULL;
    if (AXUIElementCopyAttributeValue(axApp, kAXWindowsAttribute, &raw) != kAXErrorSuccess || !raw) { CFRelease(axApp); continue; }
    NSArray *axWindows = CFBridgingRelease(raw);
    NSMutableIndexSet *used = usedIndexes[w[@"bundle"]];
    if (!used) { used = [NSMutableIndexSet indexSet]; usedIndexes[w[@"bundle"]] = used; }
    NSInteger idx = NSNotFound;
    NSString *wantTitle = w[@"title"] ?: @"";
    if (wantTitle.length) {
      for (NSInteger i = 0; i < (NSInteger)axWindows.count; i++) {
        if ([used containsIndex:i]) continue;
        AXUIElementRef win = (__bridge AXUIElementRef)axWindows[i];
        CFTypeRef tr = NULL;
        NSString *t = @"";
        if (AXUIElementCopyAttributeValue(win, kAXTitleAttribute, &tr) == kAXErrorSuccess && tr) t = CFBridgingRelease(tr);
        if ([t isEqualToString:wantTitle]) { idx = i; break; }
      }
    }
    if (idx == NSNotFound) {
      for (NSInteger i = 0; i < (NSInteger)axWindows.count; i++) if (![used containsIndex:i]) { idx = i; break; }
    }
    if (idx == NSNotFound || idx >= (NSInteger)axWindows.count) { CFRelease(axApp); failed++; continue; }
    [used addIndex:idx];
    AXUIElementRef win = (__bridge AXUIElementRef)axWindows[idx];
    AXUIElementSetAttributeValue(win, kAXMinimizedAttribute, kCFBooleanFalse);
    NSString *bundle = w[@"bundle"] ?: @"";
    if (![activatedApps containsObject:bundle]) {
      [activatedApps addObject:bundle];
      [app activateWithOptions:NSApplicationActivateIgnoringOtherApps];
    }
    AXUIElementPerformAction(win, kAXRaiseAction);
    CGPoint p = CGPointMake([w[@"x"] doubleValue], [w[@"y"] doubleValue]);
    CGSize sz = CGSizeMake([w[@"w"] doubleValue], [w[@"h"] doubleValue]);
    AXValueRef posVal = AXValueCreate(kAXValueCGPointType, &p);
    AXValueRef sizeVal = AXValueCreate(kAXValueCGSizeType, &sz);
    BOOL ok = YES;
    AXError pe = posVal ? AXUIElementSetAttributeValue(win, kAXPositionAttribute, posVal) : kAXErrorFailure;
    AXError se = sizeVal ? AXUIElementSetAttributeValue(win, kAXSizeAttribute, sizeVal) : kAXErrorFailure;
    if (pe != kAXErrorSuccess || se != kAXErrorSuccess) ok = NO;
    if (posVal) CFRelease(posVal);
    if (sizeVal) CFRelease(sizeVal);
    if (ok) restored++; else failed++;
    CFRelease(axApp);
  }
  if (restored == 0) [self showToast:[NSString stringWithFormat:@"没有找到可恢复的窗口（失败 %ld 个）；请确认应用已打开并已获得窗口控制权限", (long)failed]];
  else [self showToast:[NSString stringWithFormat:@"已恢复「%@」的 %ld 个窗口%@", name, (long)restored, failed ? [NSString stringWithFormat:@"，%ld 个失败", (long)failed] : @""]];
}

- (void)renameSelectedWindowLayout:(id)sender {
  NSInteger row = self.layoutTable.selectedRow;
  NSArray *names = self.layoutVisibleNames ?: @[];
  if (row < 0 || row >= (NSInteger)names.count) { [self showToast:@"请先选择一个布局"]; return; }
  NSString *oldName = names[row];
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"重命名布局";
  a.informativeText = [NSString stringWithFormat:@"当前名称：%@", oldName];
  NSTextField *tf = [[NSTextField alloc] initWithFrame:NSMakeRect(0,0,300,26)];
  tf.stringValue = oldName;
  a.accessoryView = tf;
  [a addButtonWithTitle:@"重命名"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSString *newName = [tf.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!newName.length) { [self showToast:@"布局名称不能为空"]; return; }
  if ([newName isEqualToString:oldName]) return;
  if (self.savedLayouts[newName]) { [self showToast:@"已存在同名布局"]; return; }
  NSDictionary *info = self.savedLayouts[oldName];
  [self.savedLayouts removeObjectForKey:oldName];
  self.savedLayouts[newName] = info ?: @{};
  [self saveWindowLayouts];
  [self reloadLayoutVisibleNames];
  NSInteger idx = [self.layoutVisibleNames indexOfObject:newName];
  if (idx != NSNotFound) [self.layoutTable selectRowIndexes:[NSIndexSet indexSetWithIndex:idx] byExtendingSelection:NO];
  [self showToast:[NSString stringWithFormat:@"已重命名为「%@」", newName]];
}

- (void)deleteSelectedWindowLayout:(id)sender {
  NSInteger row = self.layoutTable.selectedRow;
  NSArray *names = self.layoutVisibleNames ?: @[];
  if (row < 0 || row >= (NSInteger)names.count) return;
  [self.savedLayouts removeObjectForKey:names[row]];
  [self saveWindowLayouts];
  [self reloadLayoutVisibleNames];
}

- (void)closeWindowLayouts:(id)sender { [self.layoutWindow orderOut:nil]; }

