- (void)applyAppearanceRecursively:(NSView *)view appearance:(NSAppearance *)ap {
  if (!view) return;
  if (!ap) ap = [NSApp effectiveAppearance];
  if ([view.identifier isEqualToString:@"MetricCard"]) {
    view.layer.backgroundColor = CardBackgroundForAppearance(ap).CGColor;
    view.layer.borderColor = CardBorderForAppearance(ap).CGColor;
  }
  if ([view.identifier isEqualToString:@"DLCard"]) {
    view.layer.backgroundColor = CardBackgroundForAppearance(ap).CGColor;
    view.layer.borderColor = CardBorderForAppearance(ap).CGColor;
  }
  view.needsDisplay = YES;
  for (NSView *sub in view.subviews) [self applyAppearanceRecursively:sub appearance:ap];
}

- (void)applyThemeFromDefaults {
  NSInteger tv = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerTheme"];
  NSAppearance *ap = nil;
  if (tv == 1) ap = [NSAppearance appearanceNamed:NSAppearanceNameAqua];
  else if (tv == 2) ap = [NSAppearance appearanceNamed:NSAppearanceNameDarkAqua];
  NSApp.appearance = ap;
  self.window.appearance = ap;
  if (self.popover) {
    NSAppearance *effective = ap ?: [NSApp effectiveAppearance];
    self.popover.appearance = effective;
    if (self.popover.contentViewController.view) {
      self.popover.contentViewController.view.appearance = effective;
      [self applyAppearanceRecursively:self.popover.contentViewController.view appearance:ap];
    }
  }
  [self applyAppearanceRecursively:self.window.contentView appearance:ap];
  [self refreshThemeColors];
  if (self.popover.isShown && self.quickTabs.selectedSegment == 2) [self rebuildQuickAITab];
}

- (void)refreshThemeColors {
  self.window.backgroundColor = PageBackgroundForAppearance(NSApp.effectiveAppearance);
  if (self.contentScroll) self.contentScroll.backgroundColor = PageBackgroundForAppearance(NSApp.effectiveAppearance);
  if (self.content) self.content.layer.backgroundColor = PageBackgroundForAppearance(NSApp.effectiveAppearance).CGColor;
  if (self.sideView) self.sideView.layer.backgroundColor = PageBackgroundForAppearance(NSApp.effectiveAppearance).CGColor;
  if (self.statusItem.button) self.statusItem.button.contentTintColor = [NSColor labelColor];
}

- (void)uiZoomChanged:(NSPopUpButton *)sender {
  NSArray *vals = @[@1.0, @1.1, @1.2, @1.35, @1.5, @1.75];
  NSInteger idx = sender.indexOfSelectedItem;
  self.uiZoom = idx >= 0 && idx < (NSInteger)vals.count ? [vals[idx] doubleValue] : 1.2;
  [self layoutPageView:self.content.subviews.firstObject];
  [self showToast:[NSString stringWithFormat:@"界面缩放：%@", sender.titleOfSelectedItem]];
}

- (void)themeChanged:(id)sender {
  NSInteger tv = self.themePopup.indexOfSelectedItem;
  [[NSUserDefaults standardUserDefaults] setInteger:tv forKey:@"centerTheme"];
  [self applyThemeFromDefaults];
  // 主题切换后销毁旧页面，强制用新外观重建，避免旧控件保留浅色/深色文字
  self.liveView = nil; self.groupsView = nil; self.aiView = nil;
  self.diskView = nil; self.uninstallView = nil; self.settingsView = nil;
  [self.builtSections removeAllObjects];
  if (self.popover) {
    [self.popover performClose:nil];
    self.popover = nil;
    self.quickOverview = nil; self.quickGroupPage = nil; self.quickAIPage = nil; self.quickDetail = nil;
    self.quickToolsPage = nil;
    [self buildPopover];
  }
  [self showSection:self.section];
  NSArray *names = @[@"跟随系统", @"亮色", @"暗色"];
  [self showToast:[NSString stringWithFormat:@"显示主题：%@", names[tv]]];
}

- (void)toggleMenuBarText:(id)sender {
  BOOL on = (self.menuBarCheck.state == NSControlStateValueOn);
  [[NSUserDefaults standardUserDefaults] setBool:on forKey:@"centerMenuText"];
  [self sample];
  [self showToast:on ? @"菜单栏数字已开启" : @"菜单栏数字已隐藏"];
}

- (void)intervalChanged:(id)sender {
  NSArray *secs = @[@1,@2,@5,@10];
  NSInteger s = [secs[self.intervalPopup.indexOfSelectedItem] integerValue];
  self.sampleSeconds = s;
  [[NSUserDefaults standardUserDefaults] setInteger:s forKey:@"centerInterval"];
  [self.timer invalidate];
  self.timer = [NSTimer scheduledTimerWithTimeInterval:s target:self selector:@selector(sample) userInfo:nil repeats:YES];
  [self showToast:[NSString stringWithFormat:@"采样间隔已设为 %ld 秒", (long)s]];
}

- (NSString *)loginPlistPath { return [NSHomeDirectory() stringByAppendingPathComponent:@"Library/LaunchAgents/com.docklaunchers.center.plist"]; }

- (void)unloadLoginAgent {
  NSString *p = [self loginPlistPath];
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/bin/launchctl";
  t.arguments = @[@"unload", p];
  @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
}

- (void)toggleSilentStartup:(NSButton *)sender {
  BOOL on = sender.state == NSControlStateValueOn;
  [[NSUserDefaults standardUserDefaults] setBool:on forKey:@"centerSilentStartup"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self showToast:on ? @"已开启开机静默启动（下次启动生效）" : @"已关闭开机静默启动"];
}

- (void)toggleLoginItem:(id)sender {
  NSString *path = [self loginPlistPath];
  if (self.loginCheck.state == NSControlStateValueOn) {
    [[NSFileManager defaultManager] createDirectoryAtPath:[path stringByDeletingLastPathComponent] withIntermediateDirectories:YES attributes:nil error:NULL];
    NSString *appPath = [[NSBundle mainBundle] bundlePath];
    NSDictionary *pl = @{@"Label": @"com.docklaunchers.center",
                         @"ProgramArguments": @[@"/usr/bin/open", @"-g", @"-a", appPath],
                         @"RunAtLoad": @YES,
                         @"KeepAlive": @NO};
    [pl writeToFile:path atomically:YES];
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/bin/launchctl";
    t.arguments = @[@"load", path];
    @try { [t launch]; } @catch (NSException *e) {}
  } else {
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/bin/launchctl";
    t.arguments = @[@"unload", path];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
    [[NSFileManager defaultManager] removeItemAtPath:path error:NULL];
  }
  [self showToast:(self.loginCheck.state == NSControlStateValueOn ? @"已开启开机自启" : @"已关闭开机自启")];
}

- (void)stopAllLocalAIServicesForExit {
  [self.localAITimer invalidate]; self.localAITimer=nil;
  if(self.localOllamaWanted || self.localOllamaTask.isRunning){
    if([[NSFileManager defaultManager] isExecutableFileAtPath:@"/opt/homebrew/bin/brew"]){
      NSTask *bt=[[NSTask alloc] init]; bt.launchPath=@"/opt/homebrew/bin/brew"; bt.arguments=@[@"services",@"stop",@"ollama"];
      bt.standardOutput=[NSFileHandle fileHandleWithNullDevice]; bt.standardError=[NSFileHandle fileHandleWithNullDevice];
      @try{[bt launch];[bt waitUntilExit];}@catch(NSException *e){}
    }
    if(self.localOllamaTask.isRunning)[self.localOllamaTask terminate];
    self.localOllamaTask=nil;
  }
  if(self.localComfyWanted || self.localComfyTask.isRunning){
    if(self.localComfyTask.isRunning)[self.localComfyTask terminate];
    self.localComfyTask=nil;
    NSTask *k=[[NSTask alloc] init]; k.launchPath=@"/usr/bin/pkill"; k.arguments=@[@"-f",@"main.py --listen 127.0.0.1 --port 8188"];
    k.standardOutput=[NSFileHandle fileHandleWithNullDevice]; k.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[k launch];}@catch(NSException *e){}
  }
}

- (void)quitApp:(id)sender { self.allowTerminate = YES; [self stopAllLocalAIServicesForExit]; [self unloadLoginAgent]; [NSApp terminate:nil]; }

- (void)applyRadialPagePreferences {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSArray *savedOrder = [ud arrayForKey:@"centerRadialPageOrder"];
  NSArray *hidden = [ud arrayForKey:@"centerRadialHiddenPages"];
  NSSet *hiddenSet = [NSSet setWithArray:hidden ?: @[]];
  NSMutableArray *ordered = [NSMutableArray array];
  NSMutableSet *seen = [NSMutableSet set];
  if (savedOrder.count) {
    for (NSNumber *n in savedOrder) {
      NSInteger idx = [n integerValue];
      if (idx >= 0 && idx < (NSInteger)self.radialPages.count && ![seen containsObject:@(idx)]) {
        [seen addObject:@(idx)];
        if (![hiddenSet containsObject:@(idx)]) [ordered addObject:self.radialPages[idx]];
      }
    }
  }
  for (NSInteger i = 0; i < (NSInteger)self.radialPages.count; i++) {
    if ([seen containsObject:@(i)] || [hiddenSet containsObject:@(i)]) continue;
    [ordered addObject:self.radialPages[i]];
  }
  if (ordered.count) self.radialPages = ordered;
  // 应用单个功能项的隐藏与排序
  NSArray *hiddenActions = [ud arrayForKey:@"centerRadialItemHiddenActions"] ?: @[];
  NSSet *itemHiddenSet = [NSSet setWithArray:hiddenActions];
  NSDictionary *orderMap = [ud dictionaryForKey:@"centerRadialItemOrder"] ?: @{};
  NSMutableArray *finalPages = [NSMutableArray array];
  for (NSArray *page in self.radialPages) {
    NSString *pageKey = [self radialPageKeyForItems:page];
    NSArray *savedItemOrder = orderMap[pageKey];
    NSMutableArray *allItems = [NSMutableArray arrayWithArray:page];
    NSArray *customItems = [ud arrayForKey:@"centerRadialCustomItems"] ?: @[];
    for (NSDictionary *ci in customItems) if ([ci[@"pageKey"] isEqualToString:pageKey]) [allItems addObject:ci];
    NSMutableArray *items = [NSMutableArray array];
    if (savedItemOrder.count) {
      for (NSString *action in savedItemOrder) {
        for (NSDictionary *it in allItems) if ([it[@"action"] isEqualToString:action] && ![items containsObject:it]) [items addObject:it];
      }
    }
    for (NSDictionary *it in allItems) if (![items containsObject:it]) [items addObject:it];
    NSMutableArray *shown = [NSMutableArray array];
    for (NSDictionary *it in items) if (![itemHiddenSet containsObject:it[@"action"]]) [shown addObject:it];
    if (!shown.count && items.count) [shown addObject:items.firstObject];
    if (shown.count) [finalPages addObject:shown];
  }
  if (finalPages.count) self.radialPages = finalPages;
}

- (NSString *)radialPageKeyForItems:(NSArray *)items {
  NSMutableArray *actions = [NSMutableArray array];
  for (NSDictionary *it in items) if (it[@"action"]) [actions addObject:it[@"action"]];
  [actions sortUsingSelector:@selector(compare:)];
  return [actions componentsJoinedByString:@"|"];
}

- (void)openRadialItemsEditor:(id)sender {
