- (void)closeRadialNewItem:(id)sender { [self.radialNewItemWindow orderOut:nil]; }

- (void)saveRadialCustomItem:(id)sender {
  NSString *title = [self.radialNewTitleField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  NSString *value = [self.radialNewValueField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!title.length || !value.length) { [self showToast:@"请填写名称和内容"]; return; }
  if (!self.radialItemsCurrentKey.length) { [self showToast:@"请先选择页面"]; return; }
  NSString *uid = [[NSUUID UUID] UUIDString];
  NSString *action = [@"custom://" stringByAppendingString:uid];
  NSArray *typeKeys = @[@"app", @"file", @"url", @"shell"];
  NSPopUpButton *iconPopup = [self.radialNewItemWindow.contentView viewWithTag:202];
  NSString *symbol = iconPopup.selectedItem.representedObject ?: @"star.fill";
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSMutableArray *items = [[ud arrayForKey:@"centerRadialCustomItems"] ?: @[] mutableCopy];
  NSInteger pageCount = 0; for (NSDictionary *ci in items) if ([ci[@"pageKey"] isEqualToString:self.radialItemsCurrentKey]) pageCount++;
  if (pageCount >= 8) { [self showToast:@"每页最多 8 个功能项"]; return; }
  NSDictionary *item = @{@"title": title, @"symbol": symbol, @"action": action,
                         @"custom": @YES, @"customType": typeKeys[[self.radialNewTypePopup indexOfSelectedItem]],
                         @"customValue": value, @"pageKey": self.radialItemsCurrentKey};
  [items addObject:item];
  [ud setObject:items forKey:@"centerRadialCustomItems"];
  [ud synchronize];
  self.radialCustomItems = items;
  [self.radialNewItemWindow orderOut:nil];
  NSInteger pageIdx = [self.radialItemsPagePopup.selectedItem.representedObject integerValue];
  [self loadRadialItemsForPageIndex:pageIdx];
  [self showToast:@"已添加自定义菜单项，保存后生效"];
}

- (void)deleteRadialItem:(id)sender {
  NSInteger row = self.radialItemsTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.radialItemsCurrentItems.count) { [self showToast:@"请先选中一项"]; return; }
  NSDictionary *it = self.radialItemsCurrentItems[row];
  NSString *action = it[@"action"] ?: @"";
  if (![action hasPrefix:@"custom://"]) { [self showToast:@"内置功能项不能删除，可取消勾选隐藏"]; return; }
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSMutableArray *items = [[ud arrayForKey:@"centerRadialCustomItems"] ?: @[] mutableCopy];
  NSMutableArray *keep = [NSMutableArray array];
  for (NSDictionary *ci in items) if (![ci[@"action"] isEqualToString:action]) [keep addObject:ci];
  [ud setObject:keep forKey:@"centerRadialCustomItems"];
  [ud synchronize];
  self.radialCustomItems = keep;
  [self loadRadialItemsForPageIndex:[self.radialItemsPagePopup.selectedItem.representedObject integerValue]];
  [self showToast:@"已删除自定义菜单项，保存后生效"];
}

- (void)openRadialPageCustomization:(id)sender {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSArray *savedOrder = [ud arrayForKey:@"centerRadialPageOrder"];
  NSMutableArray *order = [NSMutableArray array];
  for (NSNumber *n in savedOrder ?: @[]) if ([n integerValue] >= 0 && [n integerValue] < 7) [order addObject:n];
  for (NSInteger i = 0; i < 7; i++) if (![order containsObject:@(i)]) [order addObject:@(i)];
  self.radialCustomOrder = order;
  NSArray *names = @[@"AI 工具", @"图片 / 文档", @"截图工具", @"录屏工具", @"文件工具", @"分组 / 场景", @"系统工具"];
  NSArray *hidden = [ud arrayForKey:@"centerRadialHiddenPages"] ?: @[];
  self.radialCustomHiddenPending = [hidden mutableCopy];
  if (!self.radialCustomWindow) {
    self.radialCustomWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,430,410) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.radialCustomWindow.title = @"菜单栏页面自定义";
    self.radialCustomWindow.releasedWhenClosed = NO;
    NSView *cv = self.radialCustomWindow.contentView;
    NSTextField *t = [self label:@"菜单栏页面自定义" size:18 bold:YES color:nil];
    t.frame = NSMakeRect(24, 370, 320, 24); [cv addSubview:t];
    NSTextField *h = [self label:@"勾选显示页面；用 ↑↓ 调整顺序；至少保留一页" size:10 bold:NO color:[NSColor secondaryLabelColor]];
    h.frame = NSMakeRect(24, 348, 380, 18); [cv addSubview:h];
    self.radialCustomChecks = [NSMutableArray array];
    self.radialCustomUps = [NSMutableArray array];
    self.radialCustomDowns = [NSMutableArray array];
    for (NSInteger i=0;i<7;i++) {
      NSInteger idx = [self.radialCustomOrder[i] integerValue];
      NSButton *check = [NSButton checkboxWithTitle:names[idx] target:self action:@selector(radialPageCheckChanged:)];
      check.tag = i;
      check.state = [hidden containsObject:@(idx)] ? NSControlStateValueOff : NSControlStateValueOn;
      check.frame = NSMakeRect(24, 306 - i*36, 250, 24);
      [cv addSubview:check];
      [self.radialCustomChecks addObject:check];
      ColorHoverButton *up = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(292, 304 - i*36, 38, 26)];
      up.title = @"↑"; up.tag = i; up.hoverColor = [NSColor systemBlueColor]; up.target = self; up.action = @selector(radialPageMoveUp:);
      [up applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:up];
      [self.radialCustomUps addObject:up];
      ColorHoverButton *down = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(336, 304 - i*36, 38, 26)];
      down.title = @"↓"; down.tag = i; down.hoverColor = [NSColor systemTealColor]; down.target = self; down.action = @selector(radialPageMoveDown:);
      [down applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:down];
      [self.radialCustomDowns addObject:down];
    }
    ColorHoverButton *itemsBtn = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(24, 16, 100, 30)];
    itemsBtn.title = @"功能项…"; itemsBtn.hoverColor = [NSColor systemPurpleColor]; itemsBtn.target = self; itemsBtn.action = @selector(openRadialItemsEditor:);
    [itemsBtn applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:itemsBtn];
    ColorHoverButton *save = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(236, 16, 80, 30)];
    save.title = @"保存"; save.hoverColor = [NSColor systemGreenColor]; save.target = self; save.action = @selector(saveRadialPageCustomization:);
    [save applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:save];
    ColorHoverButton *cancel = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(324, 16, 80, 30)];
    cancel.title = @"取消"; cancel.hoverColor = [NSColor systemGrayColor]; cancel.target = self; cancel.action = @selector(closeRadialPageCustomization:);
    [cancel applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:cancel];
    [self.radialCustomWindow center];
  }
  [self refreshRadialCustomChecks];
  [self forceWindowToFront:self.radialCustomWindow];
}

- (void)radialPageCheckChanged:(id)sender { [self updateRadialCustomCheckStates]; }
- (void)updateRadialCustomCheckStates {
  NSMutableArray *hidden = [NSMutableArray array];
  for (NSInteger i=0;i<self.radialCustomChecks.count;i++) {
    if (self.radialCustomChecks[i].state != NSControlStateValueOn) [hidden addObject:self.radialCustomOrder[i]];
  }
  self.radialCustomHiddenPending = hidden;
}
- (void)radialPageMoveUp:(NSButton *)sender {
  NSInteger i = sender.tag;
  if (i <= 0 || i >= (NSInteger)self.radialCustomOrder.count) return;
  [self.radialCustomOrder exchangeObjectAtIndex:i withObjectAtIndex:i-1];
  [self refreshRadialCustomChecks];
}
- (void)radialPageMoveDown:(NSButton *)sender {
  NSInteger i = sender.tag;
  if (i < 0 || i+1 >= (NSInteger)self.radialCustomOrder.count) return;
  [self.radialCustomOrder exchangeObjectAtIndex:i withObjectAtIndex:i+1];
  [self refreshRadialCustomChecks];
}
- (void)refreshRadialCustomChecks {
  NSArray *names = @[@"AI 工具", @"图片 / 文档", @"截图工具", @"录屏工具", @"文件工具", @"分组 / 场景", @"系统工具"];
  NSArray *hidden = self.radialCustomHiddenPending ?: @[];
  for (NSInteger i=0;i<self.radialCustomChecks.count;i++) {
    NSInteger idx = [self.radialCustomOrder[i] integerValue];
    NSButton *b = self.radialCustomChecks[i];
    b.tag = i; b.title = names[idx];
    b.state = [hidden containsObject:@(idx)] ? NSControlStateValueOff : NSControlStateValueOn;
    if (i < self.radialCustomUps.count) self.radialCustomUps[i].tag = i;
    if (i < self.radialCustomDowns.count) self.radialCustomDowns[i].tag = i;
  }
}
- (void)saveRadialPageCustomization:(id)sender {
  NSMutableArray *shown = [NSMutableArray array];
  for (NSInteger i=0;i<self.radialCustomChecks.count;i++) if (self.radialCustomChecks[i].state == NSControlStateValueOn) [shown addObject:@(i)];
  if (!shown.count) { [self showToast:@"至少保留一页"]; return; }
  [self updateRadialCustomCheckStates];
  [[NSUserDefaults standardUserDefaults] setObject:self.radialCustomHiddenPending ?: @[] forKey:@"centerRadialHiddenPages"];
  [[NSUserDefaults standardUserDefaults] setObject:self.radialCustomOrder forKey:@"centerRadialPageOrder"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self.radialCustomWindow orderOut:nil];
  [self.popover performClose:nil];
  self.popover = nil;
  [self buildPopover];
  [self showToast:@"菜单栏页面已更新"];
}
- (void)closeRadialPageCustomization:(id)sender { [self.radialCustomWindow orderOut:nil]; }

- (NSString *)radialModuleTitleForPage:(NSInteger)page {
  NSArray *names=@[@"AI 工具",@"图片 / 文档",@"截图工具",@"录屏工具",@"文件工具",@"分组 / 场景",@"系统工具"];
  if(page>=0 && page<(NSInteger)names.count && page<(NSInteger)self.radialPages.count)return names[page];
  if(page>=0 && page<(NSInteger)names.count)return names[page];
  return @"模块";
}

- (void)showRadialSearch:(id)sender {
  [self.popover performClose:nil];
  if(!self.radialSearchWindow){
    self.radialSearchWindow=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,380,500) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.radialSearchWindow.title=@"搜索菜单栏功能";
    self.radialSearchWindow.releasedWhenClosed=NO;
    NSView *cv=self.radialSearchWindow.contentView;
    NSTextField *t=[self label:@"搜索菜单栏功能" size:18 bold:YES color:nil]; t.frame=NSMakeRect(20,456,300,24); [cv addSubview:t];
    self.radialSearchField=[[NSSearchField alloc] initWithFrame:NSMakeRect(20,418,340,28)];
    self.radialSearchField.placeholderString=@"搜索功能";
    self.radialSearchField.target=self; self.radialSearchField.action=@selector(radialSearchChanged:);
    [self.radialSearchField setContinuous:YES]; [cv addSubview:self.radialSearchField];
    self.radialSearchModulePopup=[[NSPopUpButton alloc] initWithFrame:NSMakeRect(20,382,340,26) pullsDown:NO];
    self.radialSearchModulePopup.target=self; self.radialSearchModulePopup.action=@selector(radialSearchChanged:);
    [cv addSubview:self.radialSearchModulePopup];
    NSScrollView *sv=[[NSScrollView alloc] initWithFrame:NSMakeRect(20,64,340,310)]; sv.hasVerticalScroller=YES; sv.borderType=NSBezelBorder;
    self.radialSearchTable=[[NSTableView alloc] initWithFrame:sv.contentView.bounds];
    NSTableColumn *col=[[NSTableColumn alloc] initWithIdentifier:@"rs"]; col.title=@"功能"; col.width=318; [self.radialSearchTable addTableColumn:col];
    self.radialSearchTable.rowHeight=34; self.radialSearchTable.dataSource=self; self.radialSearchTable.delegate=self;
    self.radialSearchTable.target=self; self.radialSearchTable.doubleAction=@selector(radialSearchOpenSelected:);
    sv.documentView=self.radialSearchTable; [cv addSubview:sv];
    ColorHoverButton *open=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(20,24,100,30)];
    open.title=@"打开"; open.hoverColor=[NSColor systemGreenColor]; open.target=self; open.action=@selector(radialSearchOpenSelected:);
    [open applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:open];
    ColorHoverButton *close=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(310,24,60,30)];
    close.title=@"关闭"; close.hoverColor=[NSColor systemGrayColor]; close.target=self; close.action=@selector(closeRadialSearch:);
    [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:close];
    [self.radialSearchWindow center];
    __weak typeof(self) weakSelf=self;
    self.radialSearchKeyMonitor=[NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e){
      if(!weakSelf.radialSearchWindow.isVisible)return e;
      if(e.keyCode==36||e.keyCode==76){[weakSelf radialSearchOpenSelected:nil];return nil;}
      if(e.keyCode==123){[weakSelf radialSearchToggleSelectedExpanded:NO];return nil;}
      if(e.keyCode==124){[weakSelf radialSearchToggleSelectedExpanded:YES];return nil;}
      if(e.keyCode==125||e.keyCode==126){
        NSInteger n=[weakSelf.radialSearchTable numberOfRows];
        if(n>0){NSInteger row=[weakSelf.radialSearchTable selectedRow];row += (e.keyCode==125?1:-1);row=MAX(0,MIN(n-1,row));[weakSelf.radialSearchTable selectRowIndexes:[NSIndexSet indexSetWithIndex:row] byExtendingSelection:NO];[weakSelf.radialSearchTable scrollRowToVisible:row];}
        return nil;
      }
      return e;
    }];
  }
  if(!self.radialSearchExpanded)self.radialSearchExpanded=[NSMutableSet set];
  self.radialSearchField.stringValue=@"";
  [self radialSearchBuildModulePopup];
  [self radialSearchChanged:nil];
  [self bringAuxiliaryWindowToFront:self.radialSearchWindow];
  [self.radialSearchWindow makeFirstResponder:self.radialSearchField];
}

- (void)closeRadialSearch:(id)sender {
  if(self.radialSearchKeyMonitor){[NSEvent removeMonitor:self.radialSearchKeyMonitor];self.radialSearchKeyMonitor=nil;}
  [self.radialSearchWindow orderOut:nil];
}

- (void)radialSearchBuildModulePopup {
  [self.radialSearchModulePopup removeAllItems];
  [self.radialSearchModulePopup addItemWithTitle:@"全部模块"]; self.radialSearchModulePopup.lastItem.representedObject=@(-1);
  for(NSInteger i=0;i<(NSInteger)self.radialPages.count;i++){
    [self.radialSearchModulePopup addItemWithTitle:[self radialModuleTitleForPage:i]];
    self.radialSearchModulePopup.lastItem.representedObject=@(i);
  }
  [self.radialSearchModulePopup selectItemAtIndex:0];
}

- (void)radialSearchChanged:(id)sender {
  NSString *q=[self.radialSearchField.stringValue lowercaseString] ?: @"";
  NSInteger filter=[self.radialSearchModulePopup.selectedItem.representedObject integerValue];
  NSMutableArray *rows=[NSMutableArray array];
  for(NSInteger page=0;page<(NSInteger)self.radialPages.count;page++){
    if(filter>=0&&filter!=page)continue;
    NSArray *items=self.radialPages[page];
    NSMutableArray *matches=[NSMutableArray array];
    for(NSDictionary *it in items){
      NSString *title=it[@"title"] ?: @"";
      if(q.length && ![title.lowercaseString containsString:q])continue;
      [matches addObject:it];
    }
    if(q.length&&!matches.count)continue;
    BOOL expanded=q.length?YES:[self.radialSearchExpanded containsObject:@(page)];
    [rows addObject:@{@"type":@"module",@"title":[self radialModuleTitleForPage:page],@"page":@(page),@"expanded":@(expanded),@"count":@(matches.count)}];
    if(expanded)for(NSDictionary *it in matches)[rows addObject:@{@"type":@"item",@"title":it[@"title"] ?: @"",@"action":it[@"action"] ?: @"",@"page":@(page)}];
  }
  if(!q.length && filter<0){
    NSArray *recent=[[NSUserDefaults standardUserDefaults] arrayForKey:@"centerRadialRecent"] ?: @[];
    if(recent.count){
      [rows insertObject:@{@"type":@"recentHeader",@"title":@"最近使用"} atIndex:0];
      NSInteger i=1;
      for(NSDictionary *r in recent){
        if(i>5)break;
        [rows insertObject:@{@"type":@"item",@"title":r[@"title"] ?: @"",@"action":r[@"action"] ?: @"",@"page":r[@"page"] ?: @0} atIndex:i++];
      }
    }
  }
  self.radialSearchResults=rows;
  [self.radialSearchTable reloadData];
  if(rows.count)[self.radialSearchTable selectRowIndexes:[NSIndexSet indexSetWithIndex:0] byExtendingSelection:NO];
}

- (void)radialSearchToggleRow:(NSButton *)sender {
  NSInteger row=sender.tag;
  if(row<0||row>=(NSInteger)self.radialSearchResults.count)return;
  NSDictionary *r=self.radialSearchResults[row];
  if(![r[@"type"] isEqualToString:@"module"])return;
  NSInteger page=[r[@"page"] integerValue];
  if([self.radialSearchExpanded containsObject:@(page)])[self.radialSearchExpanded removeObject:@(page)];
  else [self.radialSearchExpanded addObject:@(page)];
  [self radialSearchChanged:nil];
}

- (void)radialSearchToggleSelectedExpanded:(BOOL)expand {
  NSInteger row=self.radialSearchTable.selectedRow;
  if(row<0||row>=(NSInteger)self.radialSearchResults.count)return;
  NSDictionary *r=self.radialSearchResults[row];
  if(![r[@"type"] isEqualToString:@"module"])return;
  NSInteger page=[r[@"page"] integerValue];
  if(expand)[self.radialSearchExpanded addObject:@(page)]; else [self.radialSearchExpanded removeObject:@(page)];
  [self radialSearchChanged:nil];
}

- (void)radialSearchOpenSelected:(id)sender {
  NSInteger row=self.radialSearchTable.selectedRow;
  if(row<0||row>=(NSInteger)self.radialSearchResults.count)return;
  NSDictionary *r=self.radialSearchResults[row];
  if([r[@"type"] isEqualToString:@"module"]||[r[@"type"] isEqualToString:@"recentHeader"]){[self radialSearchToggleSelectedExpanded:YES];return;}
  NSMutableArray *recent=[[[NSUserDefaults standardUserDefaults] arrayForKey:@"centerRadialRecent"] mutableCopy] ?: [NSMutableArray array];
  [recent filterUsingPredicate:[NSPredicate predicateWithFormat:@"action != %@", r[@"action"] ?: @""]];
  [recent insertObject:@{@"title":r[@"title"] ?: @"",@"action":r[@"action"] ?: @"",@"page":r[@"page"] ?: @0} atIndex:0];
  if(recent.count>5)recent=[recent subarrayWithRange:NSMakeRange(0,5)].mutableCopy;
  [[NSUserDefaults standardUserDefaults] setObject:recent forKey:@"centerRadialRecent"];
  self.radialPage=[r[@"page"] integerValue];
  [self radialApplyPage];
  [self closeRadialSearch:nil];
  [self performRadialAction:r[@"action"] ?: @""];
}

