- (NSString *)currentDockGroupSignature {
  NSArray *names = [[self dockGroupNames] sortedArrayUsingSelector:@selector(compare:)];
  return [names componentsJoinedByString:@"|"];
}

- (void)startQuickSceneSync {
  if (self.quickSceneSyncTimer) return;
  self.quickSceneDockSignature = [self currentDockGroupSignature];
  self.quickSceneSyncTimer = [NSTimer scheduledTimerWithTimeInterval:0.2 target:self selector:@selector(quickSceneSyncTick:) userInfo:nil repeats:YES];
  [[NSRunLoop mainRunLoop] addTimer:self.quickSceneSyncTimer forMode:NSRunLoopCommonModes];
}

- (void)stopQuickSceneSync {
  [self.quickSceneSyncTimer invalidate];
  self.quickSceneSyncTimer = nil;
}

- (void)quickSceneSyncTick:(NSTimer *)timer {
  if (!self.popover.isShown) { [self stopQuickSceneSync]; return; }
  NSString *sig = [self currentDockGroupSignature];
  if (![sig isEqualToString:self.quickSceneDockSignature ?: @""]) {
    self.quickSceneDockSignature = sig;
    [self reloadQuickSceneChecks];
  }
}

- (void)reloadQuickSceneChecks {
  NSInteger idx = self.quickScenePopup ? self.quickScenePopup.indexOfSelectedItem : self.quickSceneIndex;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSArray *installed = [self installedGroupNames];
  NSArray *dockGroups = [self dockGroupNames];
  NSView *doc = [[FlippedView alloc] initWithFrame:NSMakeRect(0,0,376,MAX(226,installed.count*30))];
  self.quickSceneChecks = [NSMutableArray array];
  for (NSInteger i = 0; i < (NSInteger)installed.count; i++) {
    NSString *name = installed[i];
    NSButton *cb = [NSButton checkboxWithTitle:name target:self action:@selector(quickSceneCheckChanged:)];
    cb.frame = NSMakeRect(10, i*30+3, 350, 22);
    cb.tag = i;
    // 菜单栏以 Dock 实际存在的分组为准，保证勾选状态与 Dock 一致
    cb.state = [dockGroups containsObject:name] ? NSControlStateValueOn : NSControlStateValueOff;
    [doc addSubview:cb];
    [self.quickSceneChecks addObject:cb];
  }
  self.quickSceneScroll.documentView = doc;
  [self startQuickSceneSync];
}

- (void)quickScenePopupChanged:(id)sender {
  self.quickSceneIndex = self.quickScenePopup.indexOfSelectedItem;
  [self reloadQuickSceneChecks];
}

- (void)quickSceneCheckChanged:(id)sender {
  NSInteger idx = self.quickScenePopup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  NSArray *installed = [self installedGroupNames];
  NSMutableArray *checked = [NSMutableArray array];
  for (NSButton *cb in self.quickSceneChecks) {
    NSInteger tag = cb.tag;
    if (tag >= 0 && tag < (NSInteger)installed.count && cb.state == NSControlStateValueOn) [checked addObject:installed[tag]];
  }
  NSMutableDictionary *scene = [self.scenes[idx] mutableCopy];
  if (checked.count == installed.count) { scene[@"all"] = @YES; scene[@"groups"] = @[]; }
  else { scene[@"all"] = @NO; scene[@"groups"] = checked; }
  self.scenes[idx] = scene;
  [self saveScenes];
}

- (void)quickSceneAutoToggled:(id)sender {
  BOOL on = self.quickSceneAutoCheck.state == NSControlStateValueOn;
  [[NSUserDefaults standardUserDefaults] setBool:on forKey:@"centerSceneAuto"];
  [self.sceneTimer invalidate]; self.sceneTimer = nil;
  if (!on) return;
  self.sceneTimer = [NSTimer scheduledTimerWithTimeInterval:60 target:self selector:@selector(sceneAutoTick:) userInfo:nil repeats:YES];
  [self sceneAutoTick:nil];
}

- (void)quickSceneApply:(id)sender {
  NSInteger idx = self.quickScenePopup.indexOfSelectedItem;
  if (idx < 0 || idx >= (NSInteger)self.scenes.count) return;
  if ([self promptApplySceneAtIndex:idx]) [self.popover performClose:nil];
}

- (void)popoverDidClose:(NSNotification *)notification {
  [self.quickProcessTimer invalidate];
  self.quickProcessTimer = nil;
  [self stopQuickSceneSync];
}

- (void)refreshQuickProcess:(NSTimer *)timer {
  if (!self.popover.isShown) return;
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/bin/ps";
  t.arguments = @[@"-axo", @"pid=,pcpu=,rss=,comm="];
  NSPipe *pipe = [NSPipe pipe]; t.standardOutput = pipe;
  NSMutableArray *rows = [NSMutableArray array];
  @try {
    [t launch];
    NSString *out = [[NSString alloc] initWithData:[pipe.fileHandleForReading readDataToEndOfFile] encoding:NSUTF8StringEncoding] ?: @"";
    [t waitUntilExit];
    for (NSString *line in [out componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]]) {
      NSMutableArray *tok = [NSMutableArray array];
      for (NSString *x in [line componentsSeparatedByCharactersInSet:[NSCharacterSet whitespaceCharacterSet]]) if (x.length) [tok addObject:x];
      if (tok.count < 4) continue;
      NSInteger pid = [tok[0] integerValue];
      if (pid <= 1 || pid == getpid()) continue;
      [rows addObject:@{@"pid": @(pid), @"cpu": @([tok[1] doubleValue]), @"mem": @([tok[2] doubleValue] / 1024.0), @"name": [tok[3] lastPathComponent], @"path": tok[3]}];
    }
  } @catch (NSException *e) {}
  [rows sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) { return [b[@"cpu"] compare:a[@"cpu"]]; }];
  if (rows.count > 6) [rows removeObjectsInRange:NSMakeRange(6, rows.count - 6)];
  for (NSView *v in [self.quickProcessContainer.subviews copy]) [v removeFromSuperview];
  CGFloat rowH = 58;
  for (NSInteger i = 0; i < (NSInteger)rows.count; i++) {
    NSDictionary *p = rows[i];
    NSView *row = [self cardAt:NSMakeRect(4, 318 - i*rowH, 392, rowH - 6)];
    [self.quickProcessContainer addSubview:row];
    NSTextField *rank = [self label:[NSString stringWithFormat:@"%ld", (long)(i+1)] size:12 bold:YES color:[NSColor tertiaryLabelColor]];
    rank.frame = NSMakeRect(10, 16, 20, 18); [row addSubview:rank];
    NSImageView *iv = [[NSImageView alloc] initWithFrame:NSMakeRect(32, 12, 28, 28)];
    iv.image = ProcessIconForPID([p[@"pid"] integerValue], p[@"path"]);
    [row addSubview:iv];
    NSTextField *name = [self label:p[@"name"] size:12 bold:YES color:nil];
    name.lineBreakMode = NSLineBreakByTruncatingTail;
    name.frame = NSMakeRect(68, 18, 170, 18); [row addSubview:name];
    NSTextField *cpu = [self label:[NSString stringWithFormat:@"%.1f%%", [p[@"cpu"] doubleValue]] size:11 bold:YES color:[NSColor systemOrangeColor]];
    cpu.alignment = NSTextAlignmentRight;
    cpu.frame = NSMakeRect(240, 18, 65, 18); [row addSubview:cpu];
    NSTextField *mem = [self label:[NSString stringWithFormat:@"%.0f MB", [p[@"mem"] doubleValue]] size:10.5 bold:NO color:[NSColor secondaryLabelColor]];
    mem.alignment = NSTextAlignmentRight;
    mem.frame = NSMakeRect(305, 18, 78, 18); [row addSubview:mem];
  }
}

- (void)openFullProcessFromPopover:(id)sender {
  [self.popover performClose:nil];
  [self showProcessManager:nil];
}

- (void)refreshQuickLoginItems {
  self.quickLoginItems = ReadLoginItems();
  [self.quickLoginTable reloadData];
}

- (void)quickTabChanged:(id)sender {
  NSInteger idx = self.quickTabs.selectedSegment;
  self.quickOverview.hidden = (idx != 0);
  if (self.quickDetail) self.quickDetail.hidden = YES;
  if (self.quickGroupPage) self.quickGroupPage.hidden = YES;
  if (self.quickScenePage) self.quickScenePage.hidden = (idx != 1);
  if (self.quickAIPage) self.quickAIPage.hidden = (idx != 2);
  if (self.quickToolsPage) self.quickToolsPage.hidden = (idx != 3);
  if (self.quickProcessPage) self.quickProcessPage.hidden = (idx != 4);
  if (self.statusMetricButton) self.statusMetricButton.hidden = (idx != 4);
  [self.quickProcessTimer invalidate]; self.quickProcessTimer = nil;
  if (idx != 1) [self stopQuickSceneSync];
  if (idx == 1) [self rebuildQuickSceneTab];
  else if (idx == 2) [self rebuildQuickAITab];
  else if (idx == 3) [self refreshQuickLoginItems];
  else if (idx == 4) {
    [self refreshQuickProcess:nil];
    self.quickProcessTimer = [NSTimer scheduledTimerWithTimeInterval:2.0 target:self selector:@selector(refreshQuickProcess:) userInfo:nil repeats:YES];
  }
}

- (void)rebuildQuickGroupTab {
  if (!self.quickGroupContainer) return;
  for (NSView *v in [self.quickGroupContainer.subviews copy]) [v removeFromSuperview];
  NSFileManager *fm = [NSFileManager defaultManager];
  NSArray *items = [[fm contentsOfDirectoryAtPath:GroupDir() error:NULL] sortedArrayUsingComparator:^NSComparisonResult(id a, id b) { return [[a description] compare:[b description] options:NSCaseInsensitiveSearch]; }];
  NSMutableArray *apps = [NSMutableArray array];
  for (NSString *f in items) if ([f hasSuffix:@".app"]) [apps addObject:f];
  CGFloat width = 400, gap = 10;
  NSInteger cols = 3;
  CGFloat bw = (width - gap * (cols - 1)) / cols;
  CGFloat bh = 132;
  CGFloat y = 462 - bh;
  NSInteger col = 0;
  for (NSString *f in apps) {
    NSString *path = [GroupDir() stringByAppendingPathComponent:f];
    NSString *name = [f stringByDeletingPathExtension];
    name = [name stringByReplacingOccurrencesOfString:@"DockLaunchers" withString:@""];
    NSView *cell = [[NSView alloc] initWithFrame:NSMakeRect(col * (bw + gap), y, bw, bh)];
    cell.wantsLayer = YES;
    cell.layer.cornerRadius = 12;
    cell.layer.backgroundColor = [NSColor controlBackgroundColor].CGColor;
    cell.layer.borderWidth = 1;
    cell.layer.borderColor = [NSColor separatorColor].CGColor;
    cell.toolTip = path;
    NSImage *icon = [[NSImage alloc] initWithContentsOfFile:[path stringByAppendingPathComponent:@"Contents/Resources/AppIcon.icns"]];
    if (!icon) icon = [[NSImage alloc] initWithContentsOfFile:[path stringByAppendingPathComponent:@"Contents/Resources/AppIcon2.icns"]];
    if (!icon) icon = [NSImage imageNamed:NSImageNameApplicationIcon];
    NSImageView *iv = [[NSImageView alloc] initWithFrame:NSMakeRect((bw - 56)/2, 54, 56, 56)];
    iv.image = icon; iv.imageScaling = NSImageScaleProportionallyUpOrDown;
    [cell addSubview:iv];
    NSTextField *lb = [NSTextField labelWithString:name];
    lb.font = [NSFont systemFontOfSize:11.5 weight:NSFontWeightMedium];
    lb.alignment = NSTextAlignmentCenter;
    lb.lineBreakMode = NSLineBreakByTruncatingTail;
    lb.frame = NSMakeRect(6, 22, bw - 12, 20);
    [cell addSubview:lb];
    NSClickGestureRecognizer *click = [[NSClickGestureRecognizer alloc] initWithTarget:self action:@selector(openGroupFromMenuBarGesture:)];
    [cell addGestureRecognizer:click];
    [self.quickGroupContainer addSubview:cell];
    col++;
    if (col % cols == 0) { col = 0; y -= bh + gap; }
  }
}

- (void)openGroupFromMenuBarGesture:(NSClickGestureRecognizer *)g {
  NSString *path = g.view.toolTip;
  if (path) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path]];
  [self.popover performClose:nil];
}

- (void)openGroupFromMenuBar:(NSButton *)sender {
  NSString *path = sender.toolTip;
  if (path) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path]];
  [self.popover performClose:nil];
