- (void)loadShelfPaths {
  NSArray *saved = [[NSUserDefaults standardUserDefaults] arrayForKey:@"centerShelfPaths"] ?: @[];
  NSMutableArray *valid = [NSMutableArray array];
  for (NSString *p in saved) if ([p isKindOfClass:NSString.class] && [[NSFileManager defaultManager] fileExistsAtPath:p] && ![valid containsObject:p]) [valid addObject:p];
  self.shelfPaths = valid;
}

- (void)saveShelfPaths {
  [[NSUserDefaults standardUserDefaults] setObject:self.shelfPaths ?: @[] forKey:@"centerShelfPaths"];
  [[NSUserDefaults standardUserDefaults] synchronize];
}

- (NSInteger)shelfCategoryForPath:(NSString *)path {
  NSString *ext = path.pathExtension.lowercaseString;
  BOOL isDir = NO;
  [[NSFileManager defaultManager] fileExistsAtPath:path isDirectory:&isDir];
  if (isDir || [ext isEqualToString:@"app"]) return 3;
  NSSet *videos = [NSSet setWithArray:@[@"mp4",@"mov",@"m4v",@"avi",@"mkv",@"webm",@"flv",@"wmv"]];
  NSSet *images = [NSSet setWithArray:@[@"png",@"jpg",@"jpeg",@"gif",@"webp",@"heic",@"heif",@"tiff",@"tif",@"bmp"]];
  if ([videos containsObject:ext]) return 1;
  if ([images containsObject:ext]) return 2;
  return 4;
}

- (void)pruneMissingShelfFiles {
  if (!self.shelfPaths) return;
  NSMutableArray *valid = [NSMutableArray array];
  for (NSString *p in self.shelfPaths) if ([[NSFileManager defaultManager] fileExistsAtPath:p] && ![valid containsObject:p]) [valid addObject:p];
  if (valid.count != self.shelfPaths.count) {
    self.shelfPaths = valid;
    [self saveShelfPaths];
    [self reloadShelfTable];
  }
}

- (NSArray<NSString *> *)shelfFilteredPaths {
  NSMutableArray *out = [NSMutableArray array];
  for (NSString *p in self.shelfPaths) {
    if (self.shelfCategory == 0 || [self shelfCategoryForPath:p] == self.shelfCategory) [out addObject:p];
  }
  return out;
}

- (void)reloadShelfTable {
  [self pruneMissingShelfFiles];
  NSArray *filtered = [self shelfFilteredPaths];
  NSInteger perPage = 20;
  NSInteger pages = MAX(1, (NSInteger)((filtered.count + perPage - 1) / perPage));
  if (self.shelfPage >= pages) self.shelfPage = pages - 1;
  if (self.shelfPage < 0) self.shelfPage = 0;
  NSInteger start = self.shelfPage * perPage;
  NSInteger end = MIN((NSInteger)filtered.count, start + perPage);
  self.shelfVisiblePaths = start < (NSInteger)filtered.count ? [filtered subarrayWithRange:NSMakeRange(start, end - start)] : @[];
  [self.shelfTable reloadData];
  if (self.shelfPageLabel) self.shelfPageLabel.stringValue = [NSString stringWithFormat:@"%ld / %ld", (long)(self.shelfPage + 1), (long)pages];
  if (self.shelfPrevButton) self.shelfPrevButton.enabled = self.shelfPage > 0;
  if (self.shelfNextButton) self.shelfNextButton.enabled = self.shelfPage + 1 < pages;
}

- (void)shelfCategoryChanged:(id)sender {
  self.shelfCategory = self.shelfCategoryPopup.indexOfSelectedItem;
  self.shelfPage = 0;
  [self reloadShelfTable];
}
- (void)shelfPrevPage:(id)sender { if (self.shelfPage > 0) { self.shelfPage--; [self reloadShelfTable]; } }
- (void)shelfNextPage:(id)sender { self.shelfPage++; [self reloadShelfTable]; }

- (void)previewShelfSelection {
  NSArray *paths = [self selectedShelfPaths];
  if (!paths.count) return;
  NSMutableArray *ordered = [paths mutableCopy];
  for (NSString *p in self.shelfVisiblePaths) if (![ordered containsObject:p]) [ordered addObject:p];
  self.shelfPreviewPaths = ordered;
  self.shelfPreviewMode = YES;
  QLPreviewPanel *panel = [QLPreviewPanel sharedPreviewPanel];
  panel.dataSource = self;
  panel.delegate = self;
  [panel makeKeyAndOrderFront:nil];
  [panel reloadData];
}

- (void)addShelfURLs:(NSArray<NSURL *> *)urls {
  if (!self.shelfPaths) [self loadShelfPaths];
  for (NSURL *u in urls) {
    NSString *p = u.path;
    if (p.length && ![self.shelfPaths containsObject:p]) [self.shelfPaths addObject:p];
  }
  [self saveShelfPaths];
  [self reloadShelfTable];
}

- (NSArray<NSString *> *)selectedShelfPaths {
  NSMutableArray *out = [NSMutableArray array];
  NSIndexSet *rows = self.shelfTable.selectedRowIndexes;
  [rows enumerateIndexesUsingBlock:^(NSUInteger idx, BOOL *stop) {
    if (idx < self.shelfVisiblePaths.count) [out addObject:self.shelfVisiblePaths[idx]];
  }];
  return out.count ? out : (self.shelfVisiblePaths.count ? @[self.shelfVisiblePaths.firstObject] : @[]);
}

- (void)addShelfFiles:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = YES; p.canChooseDirectories = YES; p.allowsMultipleSelection = YES;
  if ([p runModal] == NSModalResponseOK) [self addShelfURLs:p.URLs];
}

- (void)openShelfFiles:(id)sender {
  for (NSString *p in [self selectedShelfPaths]) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:p]];
}

- (void)revealShelfFiles:(id)sender {
  NSArray *paths = [self selectedShelfPaths];
  NSMutableArray *urls = [NSMutableArray array];
  for (NSString *p in paths) [urls addObject:[NSURL fileURLWithPath:p]];
  if (urls.count) [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:urls];
}

- (void)airdropShelfFiles:(id)sender {
  NSArray *paths = [self selectedShelfPaths];
  NSMutableArray *urls = [NSMutableArray array];
  for (NSString *p in paths) if ([[NSFileManager defaultManager] fileExistsAtPath:p]) [urls addObject:[NSURL fileURLWithPath:p]];
  if (!urls.count) return;
  NSSharingService *svc = [NSSharingService sharingServiceNamed:NSSharingServiceNameSendViaAirDrop];
  if ([svc canPerformWithItems:urls]) [svc performWithItems:urls];
  else [self showToast:@"附近没有可用的 AirDrop 接收设备"];
}

- (void)removeShelfFiles:(id)sender {
  NSArray *remove = [self selectedShelfPaths];
  if (!remove.count) return;
  NSMutableArray *keep = [NSMutableArray array];
  for (NSString *p in self.shelfPaths) if (![remove containsObject:p]) [keep addObject:p];
  self.shelfPaths = keep;
  [self saveShelfPaths]; [self reloadShelfTable];
}

- (void)clearShelfFiles:(id)sender {
  if (!self.shelfPaths.count) return;
  self.shelfPaths = [NSMutableArray array];
  [self saveShelfPaths]; [self reloadShelfTable];
}

- (void)openShelfFileRow:(id)sender {
  NSInteger row = self.shelfTable.clickedRow;
  if (row < 0) row = self.shelfTable.selectedRow;
  if (row < 0 || row >= (NSInteger)self.shelfVisiblePaths.count) return;
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.shelfVisiblePaths[row]]];
}

- (void)layoutShelfWindow {
  if (!self.shelfWindow) return;
  NSView *cv = self.shelfWindow.contentView;
  CGFloat w = cv.bounds.size.width, h = cv.bounds.size.height;
  if (w < 300 || h < 300) return;
  self.shelfTitleLabel.frame = NSMakeRect(20, h-40, w-40, 24);
  self.shelfHelpLabel.frame = NSMakeRect(20, h-62, w-40, 18);
  CGFloat dropH = 60;
  CGFloat dropTop = h - 76;
  self.shelfDropView.frame = NSMakeRect(16, dropTop - dropH, w - 32, dropH);
  self.shelfDropLabel.frame = NSMakeRect(0, (dropH-20)/2.0, w - 32, 20);
  CGFloat buttonY = 20;
  CGFloat categoryY = 82;
  self.shelfCategoryPopup.frame = NSMakeRect(16, categoryY, 120, 26);
  CGFloat pw = 34, lw = 60;
  self.shelfNextButton.frame = NSMakeRect(w - 16 - pw, categoryY, pw, 26);
  self.shelfPageLabel.frame = NSMakeRect(w - 16 - pw - lw, categoryY+4, lw, 18);
  self.shelfPrevButton.frame = NSMakeRect(w - 16 - pw - lw - pw - 4, categoryY, pw, 26);
  CGFloat tableBottom = categoryY + 34;
  CGFloat tableTop = dropTop - dropH - 10;
  self.shelfScrollView.frame = NSMakeRect(16, tableBottom, w - 32, MAX(70, tableTop - tableBottom));
  CGFloat gap = 6;
  CGFloat bw = (w - 32 - gap * (self.shelfButtons.count - 1)) / MAX(1, self.shelfButtons.count);
  for (NSInteger i = 0; i < (NSInteger)self.shelfButtons.count; i++) {
    self.shelfButtons[i].frame = NSMakeRect(16 + i * (bw + gap), buttonY, bw, 30);
  }
}

- (void)installShelfServiceWorkflowIfNeeded {
  NSString *name = @"DockLaunchers 添加到文件暂存架.workflow";
  NSString *src = [[[NSBundle mainBundle] resourcePath] stringByAppendingPathComponent:[@"Services" stringByAppendingPathComponent:name]];
  if (![[NSFileManager defaultManager] fileExistsAtPath:src]) return;
  NSString *destDir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Services"];
  NSString *dest = [destDir stringByAppendingPathComponent:name];
  NSFileManager *fm = [NSFileManager defaultManager];
  [fm createDirectoryAtPath:destDir withIntermediateDirectories:YES attributes:nil error:NULL];
  [fm removeItemAtPath:dest error:NULL];
  [fm copyItemAtPath:src toPath:dest error:NULL];
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/System/Library/CoreServices/pbs";
  t.arguments = @[@"-update"];
  @try { [t launch]; } @catch (NSException *e) {}
}

- (void)startShelfInboxTimer {
  [self.shelfInboxTimer invalidate];
  __weak typeof(self) weakSelf = self;
  self.shelfInboxTimer = [NSTimer scheduledTimerWithTimeInterval:1.5 repeats:YES block:^(NSTimer *timer) {
    [weakSelf consumeShelfInbox];
  }];
  [self consumeShelfInbox];
}

- (void)consumeShelfInbox {
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  NSString *inbox = [support stringByAppendingPathComponent:@"shelf-inbox.txt"];
  NSString *content = [NSString stringWithContentsOfFile:inbox encoding:NSUTF8StringEncoding error:NULL];
  if (!content.length) return;
  [[NSFileManager defaultManager] removeItemAtPath:inbox error:NULL];
  NSMutableArray *urls = [NSMutableArray array];
  for (NSString *line in [content componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]]) {
    NSString *p = [line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (p.length && [[NSFileManager defaultManager] fileExistsAtPath:p]) [urls addObject:[NSURL fileURLWithPath:p]];
  }
  if (urls.count) {
    [self addShelfURLs:urls];
    [self openShelfWindow:nil];
    [self showToast:@"已从访达添加到文件暂存架"];
  }
}

- (void)addFilesToShelfFromShortcut:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = YES; p.canChooseDirectories = YES; p.allowsMultipleSelection = YES;
  p.prompt = @"添加到暂存架";
  if ([p runModal] == NSModalResponseOK) {
    [self addShelfURLs:p.URLs];
    [self openShelfWindow:nil];
    [self showToast:@"已添加到文件暂存架"];
  }
}

- (void)addToShelfService:(NSPasteboard *)pboard userData:(NSString *)userData error:(NSString **)error {
  NSArray *urls = [pboard readObjectsForClasses:@[NSURL.class] options:@{NSPasteboardURLReadingFileURLsOnlyKey: @YES}];
  if (!urls.count) {
    if (error) *error = @"没有可添加的文件";
    return;
  }
  [self addShelfURLs:urls];
  [self openShelfWindow:nil];
}

- (void)compressShelfSelection:(id)sender {
  NSArray *paths = [self selectedShelfPaths];
  if (!paths.count) { [self showToast:@"请先选择文件"]; return; }
  [self showCompressWindow:nil];
  [self.compressPaths addObjectsFromArray:paths];
  self.compressListLabel.stringValue = [NSString stringWithFormat:@"已加入 %ld 个项目", (long)self.compressPaths.count];
  self.compressStatus.stringValue = @"点压缩按钮生成压缩包";
}

- (void)renameShelfSelection:(id)sender {
  NSArray *paths = [self selectedShelfPaths];
  if (!paths.count) { [self showToast:@"请先选择文件"]; return; }
  [self showBatchRenamerForPaths:paths];
}

- (void)trashShelfSelection:(id)sender {
  NSArray *paths = [self selectedShelfPaths];
  if (!paths.count) { [self showToast:@"请先选择文件"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"移到废纸篓";
  a.informativeText = [NSString stringWithFormat:@"确定把 %ld 个文件移到废纸篓吗？", (long)paths.count];
  [a addButtonWithTitle:@"移到废纸篓"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  for (NSString *p in paths) [[NSWorkspace sharedWorkspace] recycleURLs:@[[NSURL fileURLWithPath:p]] completionHandler:nil];
  [self removeShelfPaths:paths];
}

- (void)removeShelfPaths:(NSArray<NSString *> *)paths {
  NSMutableArray *keep = [NSMutableArray array];
  for (NSString *p in self.shelfPaths) if (![paths containsObject:p]) [keep addObject:p];
  self.shelfPaths = keep;
  [self saveShelfPaths];
  [self reloadShelfTable];
}

- (void)openShelfWindow:(id)sender {
  if (!self.shelfWindow) {
    self.shelfWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,440,430) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable) backing:NSBackingStoreBuffered defer:NO];
    self.shelfWindow.title = @"文件暂存架";
    self.shelfWindow.releasedWhenClosed = NO;
    self.shelfWindow.minSize = NSMakeSize(340, 300);
    NSView *cv = self.shelfWindow.contentView;
    self.shelfTitleLabel = [self label:@"文件暂存架" size:18 bold:YES color:nil];
    [cv addSubview:self.shelfTitleLabel];
    self.shelfHelpLabel = [self label:@"拖文件进来添加；拖出列表移除；空格预览；文件删除后自动清理" size:10.5 bold:NO color:[NSColor secondaryLabelColor]];
    [cv addSubview:self.shelfHelpLabel];
    self.shelfDropView = [[DLShelfDropView alloc] initWithFrame:NSMakeRect(16,0,408,70)];
    __weak typeof(self) weakSelf = self;
    self.shelfDropView.onDrop = ^(NSArray<NSURL *> *urls) { [weakSelf addShelfURLs:urls]; };
    [cv addSubview:self.shelfDropView];
    self.shelfDropLabel = [self label:@"拖文件到这里" size:12 bold:YES color:[NSColor secondaryLabelColor]];
    self.shelfDropLabel.alignment = NSTextAlignmentCenter;
    [self.shelfDropView addSubview:self.shelfDropLabel];
    self.shelfScrollView = [[NSScrollView alloc] initWithFrame:NSMakeRect(16,0,408,200)];
    self.shelfScrollView.hasVerticalScroller = YES;
    self.shelfScrollView.borderType = NSBezelBorder;
    self.shelfTable = [[NSTableView alloc] initWithFrame:self.shelfScrollView.contentView.bounds];
    NSTableColumn *col = [[NSTableColumn alloc] initWithIdentifier:@"shelf"];
    col.width = 390; [self.shelfTable addTableColumn:col];
    self.shelfTable.headerView = nil; self.shelfTable.rowHeight = 34;
    self.shelfTable.dataSource = self; self.shelfTable.delegate = self;
    self.shelfTable.target = self; self.shelfTable.doubleAction = @selector(openShelfFileRow:);
    self.shelfScrollView.documentView = self.shelfTable;
    NSMenu *shelfMenu = [[NSMenu alloc] initWithTitle:@"暂存架"];
    [shelfMenu addItemWithTitle:@"压缩所选…" action:@selector(compressShelfSelection:) keyEquivalent:@""].target = self;
    [shelfMenu addItemWithTitle:@"批量重命名所选…" action:@selector(renameShelfSelection:) keyEquivalent:@""].target = self;
    [shelfMenu addItemWithTitle:@"AirDrop 所选" action:@selector(airdropShelfFiles:) keyEquivalent:@""].target = self;
    [shelfMenu addItemWithTitle:@"移到废纸篓" action:@selector(trashShelfSelection:) keyEquivalent:@""].target = self;
    self.shelfTable.menu = shelfMenu;
    [cv addSubview:self.shelfScrollView];
    NSArray *titles = @[@"添加", @"打开", @"显示", @"AirDrop", @"移除", @"清空"];
    NSArray *sels = @[@"addShelfFiles:", @"openShelfFiles:", @"revealShelfFiles:", @"airdropShelfFiles:", @"removeShelfFiles:", @"clearShelfFiles:"];
    self.shelfButtons = [NSMutableArray array];
    for (NSInteger i=0;i<6;i++) {
      ColorHoverButton *b=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(16+i*68,22,60,30)];
      b.title=titles[i]; b.hoverColor=i==5?[NSColor systemRedColor]:[NSColor systemBlueColor];
      b.target=self; b.action=NSSelectorFromString(sels[i]);
      [b applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:b];
      [self.shelfButtons addObject:b];
    }
    self.shelfCategoryPopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(16,82,120,26) pullsDown:NO];
    [self.shelfCategoryPopup addItemsWithTitles:@[@"全部", @"视频", @"图片", @"App", @"文件"]];
    self.shelfCategoryPopup.target=self; self.shelfCategoryPopup.action=@selector(shelfCategoryChanged:);
    [cv addSubview:self.shelfCategoryPopup];
    self.shelfPrevButton = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(0,0,34,26)];
    self.shelfPrevButton.title=@"‹"; self.shelfPrevButton.target=self; self.shelfPrevButton.action=@selector(shelfPrevPage:);
    [self.shelfPrevButton applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:self.shelfPrevButton];
    self.shelfNextButton = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(0,0,34,26)];
    self.shelfNextButton.title=@"›"; self.shelfNextButton.target=self; self.shelfNextButton.action=@selector(shelfNextPage:);
    [self.shelfNextButton applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:self.shelfNextButton];
    self.shelfPageLabel = [self label:@"1 / 1" size:10 bold:YES color:[NSColor secondaryLabelColor]];
    self.shelfPageLabel.alignment=NSTextAlignmentCenter; [cv addSubview:self.shelfPageLabel];
    __weak typeof(self) weakKey = self;
    self.shelfKeyMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e) {
      if (e.window == weakKey.shelfWindow && e.keyCode == 49 && (e.modifierFlags & (NSEventModifierFlagCommand|NSEventModifierFlagControl|NSEventModifierFlagOption)) == 0) {
        [weakKey previewShelfSelection]; return nil;
      }
      return e;
    }];
    [self layoutShelfWindow];
    [self.shelfWindow center];
  }
  [self loadShelfPaths];
  if (!self.shelfPaths) self.shelfPaths = [NSMutableArray array];
  self.shelfCategory = 0; self.shelfPage = 0;
  if (self.shelfCategoryPopup) [self.shelfCategoryPopup selectItemAtIndex:0];
  [self reloadShelfTable];
  [self layoutShelfWindow];
  [self.shelfPruneTimer invalidate];
  __weak typeof(self) weakShelf = self;
  self.shelfPruneTimer = [NSTimer scheduledTimerWithTimeInterval:2.0 repeats:YES block:^(NSTimer *t) {
    if (!weakShelf.shelfWindow.isVisible) return;
    [weakShelf pruneMissingShelfFiles];
  }];
  [NSApp activateIgnoringOtherApps:YES];
  [self.shelfWindow makeKeyAndOrderFront:nil];
}

- (NSString *)configBackupDirectory {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers/ConfigBackups"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return dir;
}

- (BOOL)runDitto:(NSArray *)args {
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/usr/bin/ditto";
  t.arguments = args;
  @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) { return NO; }
  return t.terminationStatus == 0;
}

- (void)exportConfiguration:(id)sender {
  NSOpenPanel *op = [NSOpenPanel openPanel];
  op.canChooseFiles = NO;
  op.canChooseDirectories = YES;
  op.canCreateDirectories = YES;
  op.allowsMultipleSelection = NO;
  op.prompt = @"选择导出位置";
  if ([op runModal] != NSModalResponseOK) return;
  NSDateFormatter *df = [[NSDateFormatter alloc] init];
  df.dateFormat = @"yyyyMMdd-HHmm";
  NSString *folderName = [NSString stringWithFormat:@"DockLaunchers配置-%@", [df stringFromDate:[NSDate date]] ?: @"backup"];
  NSString *outDir = [op.URL.path stringByAppendingPathComponent:folderName];
  NSFileManager *fm = [NSFileManager defaultManager];
  NSInteger suffix = 2;
  while ([fm fileExistsAtPath:outDir]) { outDir = [op.URL.path stringByAppendingPathComponent:[folderName stringByAppendingFormat:@"-%ld", (long)suffix++]]; }
  if (![fm createDirectoryAtPath:outDir withIntermediateDirectories:YES attributes:nil error:NULL]) { [self showToast:@"无法创建导出目录"]; return; }
  NSString *lists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:lists]) [fm copyItemAtPath:lists toPath:[outDir stringByAppendingPathComponent:@"lists"] error:NULL];
  NSDictionary *domain = [[NSUserDefaults standardUserDefaults] persistentDomainForName:@"com.docklaunchers.center"] ?: @{};
  [domain writeToFile:[outDir stringByAppendingPathComponent:@"settings.plist"] atomically:YES];
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  for (NSString *name in @[@"app_shortcuts.json",@"scenes.json",@"window_layouts.json",@"automation_rules.json",@"prompts.json"]) {
    NSString *src = [support stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:src]) [fm copyItemAtPath:src toPath:[outDir stringByAppendingPathComponent:name] error:NULL];
  }
  [[NSString stringWithFormat:@"DockLaunchers 配置备份\n导出时间：%@\n包含：分组列表、快捷键、应用设置\n注意：settings.plist 可能包含 AI API Key，请妥善保管。\n", [NSDate date]] writeToFile:[outDir stringByAppendingPathComponent:@"README.txt"] atomically:YES encoding:NSUTF8StringEncoding error:NULL];
  [[NSUserDefaults standardUserDefaults] setObject:outDir forKey:@"centerLastConfigExportPath"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self showToast:@"配置已导出到目录"];
  [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:outDir]]];
}

- (void)importConfiguration:(id)sender {
  NSOpenPanel *op = [NSOpenPanel openPanel];
  op.canChooseFiles = YES; op.canChooseDirectories = YES; op.allowsMultipleSelection = NO;
  op.prompt = @"选择配置目录或 ZIP";
  if ([op runModal] != NSModalResponseOK) return;
  NSAlert *confirm = [[NSAlert alloc] init];
  confirm.messageText = @"导入配置？";
  confirm.informativeText = @"将覆盖当前分组列表、快捷键和应用设置，导入前会自动备份当前配置。导入后建议重启 DockLaunchers。";
  [confirm addButtonWithTitle:@"导入"];
  [confirm addButtonWithTitle:@"取消"];
  if ([confirm runModal] != NSAlertFirstButtonReturn) return;
  NSFileManager *fm = [NSFileManager defaultManager];
  NSString *tmp = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"dl-config-import-%lld", (long long)[[NSDate date] timeIntervalSince1970]]];
  [fm removeItemAtPath:tmp error:NULL];
  BOOL isDir = NO;
  BOOL exists = [fm fileExistsAtPath:op.URL.path isDirectory:&isDir];
  if (exists && isDir) {
    tmp = op.URL.path;
  } else {
    if (![self runDitto:@[@"-x", @"-k", op.URL.path, tmp]]) { [self showToast:@"配置解压失败"]; return; }
  }
  NSString *backupDir = [[self configBackupDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"auto-%lld", (long long)[[NSDate date] timeIntervalSince1970]]];
  [fm createDirectoryAtPath:backupDir withIntermediateDirectories:YES attributes:nil error:NULL];
  NSString *liveLists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:liveLists]) [fm copyItemAtPath:liveLists toPath:[backupDir stringByAppendingPathComponent:@"lists"] error:NULL];
  NSDictionary *oldDomain = [[NSUserDefaults standardUserDefaults] persistentDomainForName:@"com.docklaunchers.center"] ?: @{};
  [oldDomain writeToFile:[backupDir stringByAppendingPathComponent:@"settings.plist"] atomically:YES];
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  for (NSString *name in @[@"app_shortcuts.json",@"scenes.json",@"window_layouts.json",@"automation_rules.json",@"prompts.json"]) {
    NSString *src = [support stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:src]) [fm copyItemAtPath:src toPath:[backupDir stringByAppendingPathComponent:name] error:NULL];
  }
  NSString *incomingLists = [tmp stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:incomingLists]) {
    [fm removeItemAtPath:liveLists error:NULL];
    [fm copyItemAtPath:incomingLists toPath:liveLists error:NULL];
  }
  NSString *incomingSettings = [tmp stringByAppendingPathComponent:@"settings.plist"];
  if ([fm fileExistsAtPath:incomingSettings]) {
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/usr/bin/defaults";
    t.arguments = @[@"import", @"com.docklaunchers.center", incomingSettings];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
  }
  [fm createDirectoryAtPath:support withIntermediateDirectories:YES attributes:nil error:NULL];
  for (NSString *name in @[@"app_shortcuts.json",@"scenes.json",@"window_layouts.json",@"automation_rules.json",@"prompts.json"]) {
    NSString *incoming = [tmp stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:incoming]) [fm copyItemAtPath:incoming toPath:[support stringByAppendingPathComponent:name] error:NULL];
  }
  // 安全：导入配置时移除可执行 shell 自定义菜单项，避免静默执行命令
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSArray *customItems = [ud arrayForKey:@"centerRadialCustomItems"] ?: @[];
  NSMutableArray *safeItems = [NSMutableArray array];
  for (NSDictionary *ci in customItems) if (![ci[@"customType"] isEqualToString:@"shell"]) [safeItems addObject:ci];
  if (safeItems.count != customItems.count) {
    [ud setObject:safeItems forKey:@"centerRadialCustomItems"];
    [ud synchronize];
  }
  if (!isDir) [fm removeItemAtPath:tmp error:NULL];
  [self refreshGroups];
  [self ensureGroupDockEntries];
  [self killDock];
  [self showToast:@"配置已导入，请重启 DockLaunchers"];
}

