    exp.title=@"导出到目录…"; exp.hoverColor=[NSColor systemBlueColor]; exp.target=self; exp.action=@selector(exportConfiguration:);
    [exp applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:exp];
    ColorHoverButton *imp = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(216,100,180,36)];
    imp.title=@"导入配置…"; imp.hoverColor=[NSColor systemOrangeColor]; imp.target=self; imp.action=@selector(importConfiguration:);
    [imp applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:imp];
    ColorHoverButton *open = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(24,40,180,30)];
    open.title=@"打开上次导出目录"; open.hoverColor=[NSColor systemTealColor]; open.target=self; open.action=@selector(openConfigBackupFolder:);
    open.toolTip = @"没有导出记录时打开自动配置备份目录";
    [open applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:open];
    ColorHoverButton *rollback = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(216,40,180,30)];
    rollback.title=@"一键回滚最近备份"; rollback.hoverColor=[NSColor systemRedColor]; rollback.target=self; rollback.action=@selector(rollbackLatestConfiguration:);
    rollback.toolTip = @"恢复最近一次导入前自动备份的配置";
