- (NSArray<NSString *> *)configBackupSnapshots {
  NSFileManager *fm = [NSFileManager defaultManager];
  NSArray *items = [fm contentsOfDirectoryAtPath:[self configBackupDirectory] error:NULL] ?: @[];
  NSMutableArray *dirs = [NSMutableArray array];
  for (NSString *n in items) {
    BOOL isDir = NO;
    NSString *p = [[self configBackupDirectory] stringByAppendingPathComponent:n];
    if ([fm fileExistsAtPath:p isDirectory:&isDir] && isDir) [dirs addObject:p];
  }
  [dirs sortUsingComparator:^NSComparisonResult(NSString *a, NSString *b) {
    NSDate *da = [[NSFileManager defaultManager] attributesOfItemAtPath:a error:NULL][NSFileModificationDate] ?: [NSDate distantPast];
    NSDate *db = [[NSFileManager defaultManager] attributesOfItemAtPath:b error:NULL][NSFileModificationDate] ?: [NSDate distantPast];
    return [db compare:da];
  }];
  return dirs;
}

- (void)rollbackLatestConfiguration:(id)sender {
  NSArray *snapshots = [self configBackupSnapshots];
  if (!snapshots.count) { [self showToast:@"没有可回滚的自动备份"]; return; }
  NSString *latest = snapshots.firstObject;
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"一键回滚配置？";
  a.informativeText = [NSString stringWithFormat:@"将恢复最近一次自动备份：\n%@\n\n当前配置会先自动备份，回滚后建议重启 DockLaunchers。", latest.lastPathComponent];
  [a addButtonWithTitle:@"回滚"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSFileManager *fm = [NSFileManager defaultManager];
  NSString *backupDir = [[self configBackupDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"pre-rollback-%lld", (long long)[[NSDate date] timeIntervalSince1970]]];
  [fm createDirectoryAtPath:backupDir withIntermediateDirectories:YES attributes:nil error:NULL];
  NSString *liveLists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:liveLists]) [fm copyItemAtPath:liveLists toPath:[backupDir stringByAppendingPathComponent:@"lists"] error:NULL];
  NSDictionary *currentDomain = [[NSUserDefaults standardUserDefaults] persistentDomainForName:@"com.docklaunchers.center"] ?: @{};
  [currentDomain writeToFile:[backupDir stringByAppendingPathComponent:@"settings.plist"] atomically:YES];
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  for (NSString *name in @[@"app_shortcuts.json",@"scenes.json",@"window_layouts.json",@"automation_rules.json",@"prompts.json"]) {
    NSString *src = [support stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:src]) [fm copyItemAtPath:src toPath:[backupDir stringByAppendingPathComponent:name] error:NULL];
  }
  NSString *incomingLists = [latest stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:incomingLists]) {
    [fm removeItemAtPath:liveLists error:NULL];
    [fm copyItemAtPath:incomingLists toPath:liveLists error:NULL];
  }
  for (NSString *name in @[@"app_shortcuts.json",@"scenes.json",@"window_layouts.json",@"automation_rules.json",@"prompts.json"]) {
    NSString *incoming = [latest stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:incoming]) [fm copyItemAtPath:incoming toPath:[support stringByAppendingPathComponent:name] error:NULL];
  }
  NSString *incomingSettings = [latest stringByAppendingPathComponent:@"settings.plist"];
  if ([fm fileExistsAtPath:incomingSettings]) {
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/usr/bin/defaults";
    t.arguments = @[@"import", @"com.docklaunchers.center", incomingSettings];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
  }
  [self refreshGroups];
  [self ensureGroupDockEntries];
  [self killDock];
  [self showToast:@"已回滚到最近的自动备份，请重启 DockLaunchers"];
}

- (NSString *)cloudSyncDirectory {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  NSString *dir = [ud stringForKey:@"centerCloudSyncDirectory"];
  if (!dir.length) {
    NSString *icloud = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Mobile Documents/com~apple~CloudDocs/DockLaunchers"];
    dir = icloud;
  }
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return dir;
}

- (void)writeCurrentConfigurationToDirectory:(NSString *)dir {
  NSFileManager *fm = [NSFileManager defaultManager];
  [fm createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  NSString *lists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  NSString *cloudLists = [dir stringByAppendingPathComponent:@"lists"];
  [fm removeItemAtPath:cloudLists error:NULL];
  if ([fm fileExistsAtPath:lists]) [fm copyItemAtPath:lists toPath:cloudLists error:NULL];
  NSDictionary *domain = [[NSUserDefaults standardUserDefaults] persistentDomainForName:@"com.docklaunchers.center"] ?: @{};
  [domain writeToFile:[dir stringByAppendingPathComponent:@"settings.plist"] atomically:YES];
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  for (NSString *name in @[@"app_shortcuts.json", @"scenes.json", @"window_layouts.json"]) {
    NSString *src = [support stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:src]) { [fm removeItemAtPath:[dir stringByAppendingPathComponent:name] error:NULL]; [fm copyItemAtPath:src toPath:[dir stringByAppendingPathComponent:name] error:NULL]; }
  }
  NSDictionary *manifest = @{@"version": [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"] ?: @"1.0", @"date": @([[NSDate date] timeIntervalSince1970]), @"host": [[NSProcessInfo processInfo] hostName] ?: @""};
  [manifest writeToFile:[dir stringByAppendingPathComponent:@"manifest.plist"] atomically:YES];
}

- (void)uploadConfigurationToCloud:(id)sender {
  NSString *dir = [self cloudSyncDirectory];
  [self writeCurrentConfigurationToDirectory:dir];
  [[NSUserDefaults standardUserDefaults] setDouble:[[NSDate date] timeIntervalSince1970] forKey:@"centerLastCloudSync"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [[NSUserDefaults standardUserDefaults] setObject:dir forKey:@"centerCloudSyncDirectory"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  self.cloudSyncPathLabel.stringValue = dir;
  self.cloudSyncStatus.stringValue = [NSString stringWithFormat:@"已上传：%@", [NSDate date]];
  [self showToast:@"配置已上传到云目录"];
}

- (BOOL)applyCloudConfigurationFromDirectory:(NSString *)dir {
  NSFileManager *fm = [NSFileManager defaultManager];
  if (![fm fileExistsAtPath:[dir stringByAppendingPathComponent:@"settings.plist"]] && ![fm fileExistsAtPath:[dir stringByAppendingPathComponent:@"lists"]]) return NO;
  NSString *cloudLists = [dir stringByAppendingPathComponent:@"lists"];
  NSString *liveLists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:cloudLists]) { [fm removeItemAtPath:liveLists error:NULL]; [fm copyItemAtPath:cloudLists toPath:liveLists error:NULL]; }
  NSString *settings = [dir stringByAppendingPathComponent:@"settings.plist"];
  if ([fm fileExistsAtPath:settings]) {
    NSTask *t = [[NSTask alloc] init]; t.launchPath = @"/usr/bin/defaults"; t.arguments = @[@"import", @"com.docklaunchers.center", settings];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
  }
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  for (NSString *name in @[@"app_shortcuts.json", @"scenes.json", @"window_layouts.json"]) {
    NSString *src = [dir stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:src]) { [fm removeItemAtPath:[support stringByAppendingPathComponent:name] error:NULL]; [fm copyItemAtPath:src toPath:[support stringByAppendingPathComponent:name] error:NULL]; }
  }
  [self refreshGroups];
  [self ensureGroupDockEntries];
  [self killDock];
  self.scenes = nil;
  self.savedLayouts = nil;
  [[NSUserDefaults standardUserDefaults] setDouble:[[NSDate date] timeIntervalSince1970] forKey:@"centerLastCloudSync"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  return YES;
}

- (void)autoRestoreCloudConfigurationIfNewer {
  if (![[NSUserDefaults standardUserDefaults] objectForKey:@"centerCloudAutoRestore"]) {
    [[NSUserDefaults standardUserDefaults] setBool:YES forKey:@"centerCloudAutoRestore"];
  }
  if (![[NSUserDefaults standardUserDefaults] boolForKey:@"centerCloudAutoRestore"]) return;
  NSString *dir = [self cloudSyncDirectory];
  NSString *manifestPath = [dir stringByAppendingPathComponent:@"manifest.plist"];
  NSDictionary *manifest = [NSDictionary dictionaryWithContentsOfFile:manifestPath];
  double cloudTime = [manifest[@"date"] doubleValue];
  if (!cloudTime) cloudTime = [[[NSFileManager defaultManager] attributesOfItemAtPath:manifestPath error:NULL][NSFileModificationDate] timeIntervalSince1970];
  if (![[NSUserDefaults standardUserDefaults] objectForKey:@"centerLastCloudSync"]) {
    [[NSUserDefaults standardUserDefaults] setDouble:cloudTime forKey:@"centerLastCloudSync"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    return;
  }
  double last = [[NSUserDefaults standardUserDefaults] doubleForKey:@"centerLastCloudSync"];
  if (cloudTime <= last + 1.0) return;
  NSString *backup = [[self configBackupDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"cloud-auto-%lld", (long long)[[NSDate date] timeIntervalSince1970]]];
  [self writeCurrentConfigurationToDirectory:backup];
  if ([self applyCloudConfigurationFromDirectory:dir]) {
    [[NSUserDefaults standardUserDefaults] setDouble:cloudTime forKey:@"centerLastCloudSync"];
    [[NSUserDefaults standardUserDefaults] synchronize];
    [self showToast:@"已自动恢复云端配置"];
  }
}

- (void)restoreConfigurationFromCloud:(id)sender {
  NSString *dir = [self cloudSyncDirectory];
  NSFileManager *fm = [NSFileManager defaultManager];
  if (![fm fileExistsAtPath:[dir stringByAppendingPathComponent:@"settings.plist"]] && ![fm fileExistsAtPath:[dir stringByAppendingPathComponent:@"lists"]]) { [self showToast:@"云目录里没有配置"]; return; }
  NSAlert *a = [[NSAlert alloc] init];
  a.messageText = @"从云端恢复配置？";
  a.informativeText = @"会覆盖当前分组列表、设置、快捷键、场景和窗口布局；恢复前会先本地备份。";
  [a addButtonWithTitle:@"恢复"];
  [a addButtonWithTitle:@"取消"];
  if ([a runModal] != NSAlertFirstButtonReturn) return;
  NSString *backup = [[self configBackupDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"cloud-restore-%lld", (long long)[[NSDate date] timeIntervalSince1970]]];
  [self writeCurrentConfigurationToDirectory:backup];
  NSString *cloudLists = [dir stringByAppendingPathComponent:@"lists"];
  NSString *liveLists = [GroupDir() stringByAppendingPathComponent:@"lists"];
  if ([fm fileExistsAtPath:cloudLists]) { [fm removeItemAtPath:liveLists error:NULL]; [fm copyItemAtPath:cloudLists toPath:liveLists error:NULL]; }
  NSString *settings = [dir stringByAppendingPathComponent:@"settings.plist"];
  if ([fm fileExistsAtPath:settings]) {
    NSTask *t = [[NSTask alloc] init]; t.launchPath = @"/usr/bin/defaults"; t.arguments = @[@"import", @"com.docklaunchers.center", settings];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
  }
  NSString *support = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  for (NSString *name in @[@"app_shortcuts.json", @"scenes.json", @"window_layouts.json"]) {
    NSString *src = [dir stringByAppendingPathComponent:name];
    if ([fm fileExistsAtPath:src]) { [fm removeItemAtPath:[support stringByAppendingPathComponent:name] error:NULL]; [fm copyItemAtPath:src toPath:[support stringByAppendingPathComponent:name] error:NULL]; }
  }
  [self refreshGroups];
  [self ensureGroupDockEntries];
  [self killDock];
  self.scenes = nil;
  self.savedLayouts = nil;
  [[NSUserDefaults standardUserDefaults] setDouble:[[NSDate date] timeIntervalSince1970] forKey:@"centerLastCloudSync"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  self.cloudSyncStatus.stringValue = @"已从云端恢复，请重启 DockLaunchers";
  [self showToast:@"云端配置已恢复"];
}

- (void)chooseCloudSyncFolder:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseDirectories = YES; p.canChooseFiles = NO; p.canCreateDirectories = YES;
  p.prompt = @"选择云同步目录";
  if ([p runModal] != NSModalResponseOK) return;
  [[NSUserDefaults standardUserDefaults] setObject:p.URL.path forKey:@"centerCloudSyncDirectory"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  self.cloudSyncPathLabel.stringValue = p.URL.path;
  self.cloudSyncStatus.stringValue = @"云目录已更新";
}

- (void)cloudAutoSyncChanged:(NSButton *)sender {
  [[NSUserDefaults standardUserDefaults] setBool:sender.state == NSControlStateValueOn forKey:@"centerCloudAutoSync"];
  [[NSUserDefaults standardUserDefaults] synchronize];
}

- (NSString *)automationRulesPath {
  NSString *dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers"];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return [dir stringByAppendingPathComponent:@"automation_rules.json"];
}

- (void)loadAutomationRules {
  if (self.automationRules) return;
  NSData *d = [NSData dataWithContentsOfFile:[self automationRulesPath]];
  id obj = d ? [NSJSONSerialization JSONObjectWithData:d options:0 error:NULL] : nil;
  self.automationRules = [obj isKindOfClass:[NSArray class]] ? [obj mutableCopy] : [NSMutableArray array];
}

- (void)saveAutomationRules {
  NSData *d = [NSJSONSerialization dataWithJSONObject:self.automationRules ?: @[] options:NSJSONWritingPrettyPrinted error:NULL];
  [d writeToFile:[self automationRulesPath] atomically:YES];
}

- (NSString *)automationTriggerTitle:(NSString *)key {
  if ([key isEqualToString:@"app_launch"]) return @"应用启动";
  if ([key isEqualToString:@"app_quit"]) return @"应用退出";
  if ([key isEqualToString:@"time"]) return @"每天时间";
  if ([key isEqualToString:@"space"]) return @"切换到桌面";
  return key ?: @"";
}

- (NSString *)automationActionTitle:(NSString *)key {
  if ([key isEqualToString:@"scene"]) return @"应用场景";
  if ([key isEqualToString:@"layout"]) return @"恢复窗口布局";
  if ([key isEqualToString:@"launch"]) return @"启动应用";
  if ([key isEqualToString:@"quit"]) return @"退出应用";
  if ([key isEqualToString:@"show_group"]) return @"显示分组";
  if ([key isEqualToString:@"hide_group"]) return @"隐藏分组";
  return key ?: @"";
}

- (NSString *)automationRuleSummary:(NSDictionary *)rule {
  return [NSString stringWithFormat:@"%@ · %@ → %@ · %@",
          [self automationTriggerTitle:rule[@"trigger"] ?: @""], rule[@"triggerValue"] ?: @"",
          [self automationActionTitle:rule[@"action"] ?: @""], rule[@"actionValue"] ?: @""];
}

- (void)openGroupScheduleRules:(id)sender {
  [self openAutomationRules:nil];
  [self showToast:@"用「每天时间」触发 +「显示分组/隐藏分组」动作即可定时切换"];
}

- (NSString *)privacyStateText:(NSInteger)state {
  if (state == 1) return @"已允许";
  if (state == 2) return @"已拒绝";
  if (state == 0) return @"未决定";
  return @"未知";
}

- (NSInteger)privacyStatusForRow:(NSInteger)i {
  if (i == 0) return CGPreflightScreenCaptureAccess() ? 1 : 2;
  if (i == 1) {
    AVAuthorizationStatus st=[AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeAudio];
    return st==AVAuthorizationStatusAuthorized?1:(st==AVAuthorizationStatusDenied?2:(st==AVAuthorizationStatusNotDetermined?0:3));
  }
  if (i == 2) {
    AVAuthorizationStatus st=[AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeVideo];
    return st==AVAuthorizationStatusAuthorized?1:(st==AVAuthorizationStatusDenied?2:(st==AVAuthorizationStatusNotDetermined?0:3));
  }
  if (i == 3) {
    SFSpeechRecognizerAuthorizationStatus st=[SFSpeechRecognizer authorizationStatus];
    return st==SFSpeechRecognizerAuthorizationStatusAuthorized?1:(st==SFSpeechRecognizerAuthorizationStatusDenied?2:(st==SFSpeechRecognizerAuthorizationStatusNotDetermined?0:3));
  }
  if (i == 4) return AXIsProcessTrusted()?1:2;
  if (i == 5) return CGPreflightListenEventAccess()?1:2;
  if (i == 6) return [[NSFileManager defaultManager] isReadableFileAtPath:@"/Library/Application Support/com.apple.TCC/TCC.db"]?1:2;
  if (i == 7) {
    PHAuthorizationStatus st=[PHPhotoLibrary authorizationStatusForAccessLevel:PHAccessLevelReadWrite];
    if(st==PHAuthorizationStatusAuthorized||st==PHAuthorizationStatusLimited)return 1;
    if(st==PHAuthorizationStatusDenied)return 2;
    if(st==PHAuthorizationStatusNotDetermined)return 0;
    return 3;
  }
  return 3;
}

- (void)refreshPrivacyDashboard {
  for(NSInteger i=0;i<(NSInteger)self.privacyStatusLabels.count;i++){
    NSInteger state=[self privacyStatusForRow:i];
    NSTextField *st=self.privacyStatusLabels[i];
    st.stringValue=[self privacyStateText:state];
    st.textColor=(state==1?[NSColor systemGreenColor]:[NSColor systemOrangeColor]);
  }
}

