    clearPageBtn.target=self; clearPageBtn.action=@selector(clearCurrentPageShortcuts:);
    [clearPageBtn applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:clearPageBtn];
    ColorHoverButton *clearBtn=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(450,20,140,28)];
    clearBtn.title=@"清除全部"; clearBtn.hoverColor=[NSColor systemRedColor]; clearBtn.font=[NSFont systemFontOfSize:10];
    clearBtn.target=self; clearBtn.action=@selector(clearAllRadialShortcuts:);
    [clearBtn applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:clearBtn];
    [self.allShortcutWindow center];
  }
  self.allShortcutDefs = [self radialShortcutDefs];
  if(!self.allShortcutDefs.count) self.allShortcutDefs = [self allGlobalActionDefs];
  [self.allShortcutCategoryPopup removeAllItems];
  if(self.radialPages.count){
    for(NSInteger p=0;p<(NSInteger)self.radialPages.count;p++)[self.allShortcutCategoryPopup addItemWithTitle:[NSString stringWithFormat:@"第 %ld 页：%@",(long)(p+1),[self radialModuleTitleForPage:p]]];
  } else {
    [self.allShortcutCategoryPopup addItemsWithTitles:@[@"截图 / 录制", @"文件与工具", @"启动与搜索", @"系统与分组", @"AI / 新功能"]];
  }
  self.allShortcutCategory = 0; self.allShortcutPage = 0;
  [self.allShortcutCategoryPopup selectItemAtIndex:0];
  [self rebuildAllShortcutPage];
  [NSApp activateIgnoringOtherApps:YES];
  [self.allShortcutWindow makeKeyAndOrderFront:nil];
}

- (void)clearCurrentPageShortcuts:(id)sender {
  NSArray *defs=[self allShortcutFilteredDefs];
  if(!defs.count){[self showToast:@"当前页没有可清除的快捷键"];return;}
  NSString *pageName=self.allShortcutCategoryPopup.titleOfSelectedItem ?: @"当前页";
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=[NSString stringWithFormat:@"清除%@的快捷键？",pageName];
  a.informativeText=@"只清除当前页已录制的组合键，其他页不受影响。";
  [a addButtonWithTitle:@"清除"]; [a addButtonWithTitle:@"取消"];
  if([a runModal]!=NSAlertFirstButtonReturn)return;
  [self stopAllShortcutRecording];
  NSUserDefaults *ud=[NSUserDefaults standardUserDefaults];
  for(NSDictionary *d in defs){
    NSInteger aid=[d[@"id"] integerValue];
    NSValue *v=self.allHotKeyRefs[@(aid)];
    if(v){EventHotKeyRef ref=(EventHotKeyRef)v.pointerValue; if(ref)UnregisterEventHotKey(ref); [self.allHotKeyRefs removeObjectForKey:@(aid)];}
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldCode",(long)aid]];
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldMods",(long)aid]];
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldDisplay",(long)aid]];
  }
  [ud synchronize];
  [self rebuildAllShortcutPage];
  [self showToast:[NSString stringWithFormat:@"已清除%@",pageName]];
}

- (void)clearAllRadialShortcuts:(id)sender {
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"清除全部快捷键？";
  a.informativeText=@"会清除七个菜单页、旧版基础快捷键和遗留的全部功能快捷键；分组快捷键不受影响。可随时重新设置。";
  [a addButtonWithTitle:@"清除"]; [a addButtonWithTitle:@"取消"];
  if([a runModal]!=NSAlertFirstButtonReturn)return;
  [self stopAllShortcutRecording];
  NSUserDefaults *ud=[NSUserDefaults standardUserDefaults];
  // 清除旧版 9 个基础快捷键，避免界面上看不到但仍生效
  for(NSInteger i=0;i<9;i++)[self clearShortcutForAction:i];
  // 清除七个菜单页已录制的快捷键
  for(NSDictionary *d in self.allShortcutDefs ?: [self radialShortcutDefs]){
    NSInteger aid=[d[@"id"] integerValue];
    NSValue *v=self.allHotKeyRefs[@(aid)];
    if(v){EventHotKeyRef ref=(EventHotKeyRef)v.pointerValue; if(ref)UnregisterEventHotKey(ref); [self.allHotKeyRefs removeObjectForKey:@(aid)];}
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldCode",(long)aid]];
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldMods",(long)aid]];
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldDisplay",(long)aid]];
  }
  // 清除旧版“全部功能快捷键”遗留的通用动作快捷键
  for(NSDictionary *d in [self allGlobalActionDefs]){
    NSInteger aid=[d[@"id"] integerValue];
    NSValue *v=self.allHotKeyRefs[@(aid)];
    if(v){EventHotKeyRef ref=(EventHotKeyRef)v.pointerValue; if(ref)UnregisterEventHotKey(ref); [self.allHotKeyRefs removeObjectForKey:@(aid)];}
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldCode",(long)aid]];
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldMods",(long)aid]];
    [ud removeObjectForKey:[NSString stringWithFormat:@"centerGA%ldDisplay",(long)aid]];
  }
  [ud synchronize];
  [self rebuildAllShortcutPage];
  [self showToast:@"已清除全部快捷键"];
}

- (void)allShortcutCategoryChanged:(id)sender {
  self.allShortcutCategory = self.allShortcutCategoryPopup.indexOfSelectedItem;
  self.allShortcutPage = 0;
  [self rebuildAllShortcutPage];
}

- (NSArray *)allShortcutFilteredDefs {
  NSMutableArray *a = [NSMutableArray array];
  for (NSDictionary *d in self.allShortcutDefs) if ([d[@"cat"] integerValue] == self.allShortcutCategory) [a addObject:d];
  return a;
}

- (void)rebuildAllShortcutPage {
  if (!self.allShortcutContainer) return;
  for (NSView *v in self.allShortcutContainer.subviews.copy) [v removeFromSuperview];
  NSArray *defs = [self allShortcutFilteredDefs];
  NSInteger perPage = 7;
  NSInteger pages = MAX(1, (NSInteger)((defs.count + perPage - 1) / perPage));
  if (self.allShortcutPage >= pages) self.allShortcutPage = pages - 1;
  if (self.allShortcutPage < 0) self.allShortcutPage = 0;
  NSInteger start = self.allShortcutPage * perPage;
  for (NSInteger i = 0; i < perPage && start + i < (NSInteger)defs.count; i++) {
    NSDictionary *d = defs[start + i];
    CGFloat y = 390 - i * 56;
    NSTextField *title = [self label:d[@"title"] ?: @"" size:13 bold:YES color:nil];
    title.frame = NSMakeRect(24,y+12,240,20); [self.allShortcutContainer addSubview:title];
    NSTextField *desc = [self label:d[@"desc"] ?: @"" size:10 bold:NO color:[NSColor secondaryLabelColor]];
    desc.frame = NSMakeRect(24,y-8,300,16); [self.allShortcutContainer addSubview:desc];
    ColorHoverButton *b = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(390,y+2,190,32)];
    NSInteger aid = [d[@"id"] integerValue];
    b.tag = aid; b.title = [self allGlobalShortcutDisplayForID:aid];
    b.hoverColor = [NSColor systemTealColor];
    b.target = self; b.action = @selector(recordAllShortcut:);
    [b applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
    [self.allShortcutContainer addSubview:b];
  }
  self.allShortcutPageLabel.stringValue = [NSString stringWithFormat:@"%ld / %ld", (long)(self.allShortcutPage + 1), (long)pages];
  BOOL canPrev = self.allShortcutPage > 0, canNext = self.allShortcutPage + 1 < pages;
  self.allShortcutPrevButton.enabled = canPrev; self.allShortcutNextButton.enabled = canNext;
}

- (void)allShortcutPrev:(id)sender { if (self.allShortcutPage > 0) { self.allShortcutPage--; [self rebuildAllShortcutPage]; } }
- (void)allShortcutNext:(id)sender { self.allShortcutPage++; [self rebuildAllShortcutPage]; }

- (NSDictionary<NSString *, NSDictionary *> *)computeGroupBadgeCounts {
  NSMutableSet *runningBIDs = [NSMutableSet set];
  NSMutableSet *runningPaths = [NSMutableSet set];
  for (NSRunningApplication *app in [[NSWorkspace sharedWorkspace] runningApplications]) {
    if (app.activationPolicy == NSApplicationActivationPolicyProhibited) continue;
    if (app.bundleIdentifier.length) [runningBIDs addObject:app.bundleIdentifier];
    if (app.bundleURL.path.length) [runningPaths addObject:[app.bundleURL.path stringByStandardizingPath]];
  }
  NSMutableDictionary *out = [NSMutableDictionary dictionary];
  NSFileManager *fm = [NSFileManager defaultManager];
  for (NSDictionary *g in self.groups ?: @[]) {
    NSString *name = g[@"name"] ?: @"";
    NSString *listPath = [[GroupDir() stringByAppendingPathComponent:@"lists"] stringByAppendingPathComponent:[name stringByAppendingPathExtension:@"txt"]];
    NSString *content = [NSString stringWithContentsOfFile:listPath encoding:NSUTF8StringEncoding error:NULL] ?: @"";
    NSInteger total = 0, running = 0;
    for (NSString *line in [content componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]]) {
      if (!line.length || [line hasPrefix:@"#"]) continue;
      NSArray *parts = [line componentsSeparatedByString:@"|"];
      NSString *target = parts.count > 1 ? parts.lastObject : parts.firstObject;
      target = [target stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
      if (!target.length) continue;
      total++;
      BOOL isRunning = NO;
      if ([target hasPrefix:@"/"]) {
        NSString *std = [target stringByStandardizingPath];
        if ([runningPaths containsObject:std]) isRunning = YES;
        NSString *bid = [[NSBundle bundleWithPath:std] objectForInfoDictionaryKey:@"CFBundleIdentifier"];
        if (bid.length && [runningBIDs containsObject:bid]) isRunning = YES;
      } else if ([runningBIDs containsObject:target]) {
        isRunning = YES;
      }
      if (isRunning) running++;
    }
    out[name] = @{@"running": @(running), @"total": @(total)};
  }
  return out;
}

- (void)startGroupBadgeTimer {
  [self.groupBadgeTimer invalidate];
  __weak typeof(self) weakSelf = self;
  self.groupBadgeTimer = [NSTimer scheduledTimerWithTimeInterval:4.0 repeats:YES block:^(NSTimer *timer) {
    [weakSelf updateGroupBadges];
  }];
  [self updateGroupBadges];
}

- (void)updateGroupBadges {
  BOOL enabled = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerGroupBadgesEnabled"] ? [[NSUserDefaults standardUserDefaults] boolForKey:@"centerGroupBadgesEnabled"] : YES;
  self.groupBadgeCounts = enabled ? [self computeGroupBadgeCounts] : @{};
  NSInteger totalRunning = 0;
  for (NSDictionary *d in self.groupBadgeCounts.allValues) totalRunning += [d[@"running"] integerValue];
  if (totalRunning > 0 && enabled) {
    NSMutableAttributedString *title = [[NSMutableAttributedString alloc] initWithString:[NSString stringWithFormat:@" %ld", (long)totalRunning] attributes:@{NSForegroundColorAttributeName: [NSColor systemRedColor], NSFontAttributeName: [NSFont systemFontOfSize:10 weight:NSFontWeightBold]}];
    self.statusItem.button.attributedTitle = title;
    self.statusItem.button.toolTip = [NSString stringWithFormat:@"分组内共有 %ld 个应用正在运行", (long)totalRunning];
    [NSApp dockTile].badgeLabel = [NSString stringWithFormat:@"%ld", (long)totalRunning];
  } else {
    self.statusItem.button.attributedTitle = nil;
    self.statusItem.button.title = @"";
    self.statusItem.button.toolTip = @"DockLaunchers";
    [NSApp dockTile].badgeLabel = nil;
  }
  if (self.groupPanelWindow.isVisible) [self.groupPanelTable reloadData];
  [self updateConsoleGroupRunLabels];
  if (enabled) [self applyGroupDockBadges];
}

- (void)applyGroupDockBadges {
  NSArray *groups = [self installedGroupNames];
  NSMutableString *sig = [NSMutableString string];
  for (NSString *name in groups) {
    NSDictionary *d = self.groupBadgeCounts[name] ?: @{};
    [sig appendFormat:@"%@:%@;", name, d[@"running"] ?: @0];
  }
  if (sig.length && [self.lastGroupDockBadgeSignature isEqualToString:sig]) return;
  self.lastGroupDockBadgeSignature = sig;
  for (NSString *name in groups) {
    NSString *path = [[GroupDir() stringByAppendingPathComponent:name] stringByAppendingPathExtension:@"app"];
    if (![[NSFileManager defaultManager] fileExistsAtPath:path]) continue;
    NSInteger running = [self.groupBadgeCounts[name][@"running"] integerValue];
    NSImage *base = [[NSImage alloc] initWithContentsOfFile:[path stringByAppendingPathComponent:@"Contents/Resources/AppIcon.icns"]];
    if (!base) base = [[NSWorkspace sharedWorkspace] iconForFile:path];
    if (!base || base.size.width <= 0 || base.size.height <= 0) continue;
    // 固定用 128x128 位图生成 ICNS，避免异常尺寸导致 NSWorkspace setIcon 崩溃
    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:128 pixelsHigh:128 bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
    if (!rep) continue;
    NSGraphicsContext *ctx = [NSGraphicsContext graphicsContextWithBitmapImageRep:rep];
    [NSGraphicsContext saveGraphicsState];
    [NSGraphicsContext setCurrentContext:ctx];
    [base drawInRect:NSMakeRect(0,0,128,128) fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1.0];
    if (running > 0) {
      NSString *num = running > 99 ? @"99+" : [NSString stringWithFormat:@"%ld", (long)running];
      NSRect br = NSMakeRect(82, 82, 40, 40);
      [[NSColor systemRedColor] setFill];
      [[NSBezierPath bezierPathWithOvalInRect:br] fill];
      [[NSColor whiteColor] setStroke];
      NSBezierPath *border = [NSBezierPath bezierPathWithOvalInRect:NSInsetRect(br, 2, 2)];
      border.lineWidth = 2.5; [border stroke];
      NSMutableParagraphStyle *ps = [[NSMutableParagraphStyle alloc] init]; ps.alignment = NSTextAlignmentCenter;
      NSDictionary *attrs = @{NSFontAttributeName: [NSFont systemFontOfSize:(running > 9 ? 16 : 21) weight:NSFontWeightBold], NSForegroundColorAttributeName: [NSColor whiteColor], NSParagraphStyleAttributeName: ps};
      [num drawInRect:NSMakeRect(br.origin.x, br.origin.y + 10, br.size.width, 22) withAttributes:attrs];
    }
    [NSGraphicsContext restoreGraphicsState];
    NSImage *icon = [[NSImage alloc] initWithSize:NSMakeSize(128,128)];
    [icon addRepresentation:rep];
    [[NSWorkspace sharedWorkspace] setIcon:icon forFile:path options:0];
  }
  [self reloadDockPreferences];
}

- (void)updateConsoleGroupRunLabels {
  if (!self.groupsList) return;
  for (NSView *row in self.groupsList.subviews) {
    NSString *name = objc_getAssociatedObject(row, "GroupRowName");
    if (!name.length) continue;
    NSDictionary *d = self.groupBadgeCounts[name] ?: @{};
    NSInteger running = [d[@"running"] integerValue];
    for (NSView *sub in row.subviews) {
      if (sub.tag == 301 && [sub isKindOfClass:[NSTextField class]]) {
        ((NSTextField *)sub).stringValue = running > 0 ? [NSString stringWithFormat:@"● %ld", (long)running] : @"";
      }
    }
  }
}

- (void)toggleGroupBadges:(id)sender {
  BOOL enabled = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerGroupBadgesEnabled"] ? [[NSUserDefaults standardUserDefaults] boolForKey:@"centerGroupBadgesEnabled"] : YES;
  enabled = !enabled;
  [[NSUserDefaults standardUserDefaults] setBool:enabled forKey:@"centerGroupBadgesEnabled"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self updateGroupBadges];
  if (self.groupBadgeToggleButton) self.groupBadgeToggleButton.title = enabled ? @"角标：开" : @"角标：关";
  if (self.consoleGroupBadgeButton) self.consoleGroupBadgeButton.title = enabled ? @"角标：开" : @"角标：关";
  [self showToast:enabled ? @"已开启分组动态角标" : @"已关闭分组动态角标"];
}

- (void)installGroupHotkeys {
  if (!self.groupHotKeyRefs) self.groupHotKeyRefs = [NSMutableDictionary dictionary];
  for (NSValue *v in self.groupHotKeyRefs.allValues) { EventHotKeyRef ref = (EventHotKeyRef)v.pointerValue; if (ref) UnregisterEventHotKey(ref); }
  [self.groupHotKeyRefs removeAllObjects];
  if (!self.groupHotKeyNames) self.groupHotKeyNames = [NSMutableDictionary dictionary];
  [self.groupHotKeyNames removeAllObjects];
  NSDictionary *store = [[NSUserDefaults standardUserDefaults] dictionaryForKey:@"centerGroupHotkeys"] ?: @{};
  NSArray *groups = [self installedGroupNames];
  for (NSInteger i = 0; i < (NSInteger)groups.count; i++) {
    NSString *name = groups[i];
    NSDictionary *info = store[name];
    if (![info isKindOfClass:[NSDictionary class]]) continue;
    UInt32 code = [info[@"code"] unsignedIntValue];
    UInt32 mods = [info[@"mods"] unsignedIntValue];
    if (!code) continue;
    EventHotKeyID hid = {'DLGR', (UInt32)(100 + i)};
    EventHotKeyRef ref = NULL;
    if (RegisterEventHotKey(code, mods, hid, GetApplicationEventTarget(), 0, &ref) == noErr && ref) {
      self.groupHotKeyRefs[name] = [NSValue valueWithPointer:ref];
      self.groupHotKeyNames[@(100 + i)] = name;
    }
  }
}

- (NSString *)groupHotkeyDisplayForName:(NSString *)name {
  NSDictionary *store = [[NSUserDefaults standardUserDefaults] dictionaryForKey:@"centerGroupHotkeys"] ?: @{};
  return store[name][@"display"] ?: @"未设置";
}

- (BOOL)registerGroupHotkeyForName:(NSString *)name code:(UInt32)code modifiers:(UInt32)mods display:(NSString *)display {
  NSArray *groups = [self installedGroupNames];
  NSInteger idx = [groups indexOfObject:name];
  if (idx == NSNotFound) return NO;
  NSValue *oldVal = self.groupHotKeyRefs[name];
  if (oldVal) UnregisterEventHotKey((EventHotKeyRef)oldVal.pointerValue);
  [self.groupHotKeyRefs removeObjectForKey:name];
  EventHotKeyID hid = {'DLGR', (UInt32)(100 + idx)};
  EventHotKeyRef ref = NULL;
  if (RegisterEventHotKey(code, mods, hid, GetApplicationEventTarget(), 0, &ref) != noErr || !ref) return NO;
  self.groupHotKeyRefs[name] = [NSValue valueWithPointer:ref];
  if (!self.groupHotKeyNames) self.groupHotKeyNames = [NSMutableDictionary dictionary];
  self.groupHotKeyNames[@(100 + idx)] = name;
  NSMutableDictionary *store = [([[NSUserDefaults standardUserDefaults] dictionaryForKey:@"centerGroupHotkeys"] ?: @{}) mutableCopy];
  store[name] = @{@"code": @(code), @"mods": @(mods), @"display": display ?: @""};
  [[NSUserDefaults standardUserDefaults] setObject:store forKey:@"centerGroupHotkeys"];
  return YES;
}

- (void)clearGroupHotkey:(NSButton *)sender {
  NSArray *groups = [self installedGroupNames];
  NSInteger idx = sender.tag;
  if (idx < 0 || idx >= (NSInteger)groups.count) return;
  NSString *name = groups[idx];
  NSValue *oldVal = self.groupHotKeyRefs[name];
  if (oldVal) UnregisterEventHotKey((EventHotKeyRef)oldVal.pointerValue);
  [self.groupHotKeyRefs removeObjectForKey:name];
  NSMutableDictionary *store = [([[NSUserDefaults standardUserDefaults] dictionaryForKey:@"centerGroupHotkeys"] ?: @{}) mutableCopy];
  [store removeObjectForKey:name];
  [[NSUserDefaults standardUserDefaults] setObject:store forKey:@"centerGroupHotkeys"];
  [self refreshGroupShortcutButtons];
}

- (void)refreshGroupShortcutButtons {
  NSArray *groups = [self installedGroupNames];
  for (ColorHoverButton *b in self.groupShortcutButtons) {
    NSInteger idx = b.tag;
    if (idx >= 0 && idx < (NSInteger)groups.count) b.title = [self groupHotkeyDisplayForName:groups[idx]];
  }
}

- (void)stopGroupShortcutRecording {
  if (self.groupShortcutMonitor) { [NSEvent removeMonitor:self.groupShortcutMonitor]; self.groupShortcutMonitor = nil; }
  self.groupShortcutRecordingName = nil;
  [self refreshGroupShortcutButtons];
}

- (void)recordGroupHotkey:(ColorHoverButton *)sender {
  [self stopGroupShortcutRecording];
  NSArray *groups = [self installedGroupNames];
  NSInteger idx = sender.tag;
  if (idx < 0 || idx >= (NSInteger)groups.count) return;
  self.groupShortcutRecordingName = groups[idx];
  sender.title = @"请按组合键…";
  __weak typeof(self) weakSelf = self;
  self.groupShortcutMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e) {
    if (!weakSelf.groupShortcutRecordingName.length) return e;
    if (e.keyCode == 53) { [weakSelf stopGroupShortcutRecording]; return nil; }
    NSEventModifierFlags f = e.modifierFlags & (NSEventModifierFlagCommand|NSEventModifierFlagControl|NSEventModifierFlagOption|NSEventModifierFlagShift);
    if (!(f & (NSEventModifierFlagCommand|NSEventModifierFlagControl|NSEventModifierFlagOption))) return nil;
    UInt32 mods = 0;
    if (f & NSEventModifierFlagControl) mods |= controlKey;
    if (f & NSEventModifierFlagOption) mods |= optionKey;
    if (f & NSEventModifierFlagShift) mods |= shiftKey;
    if (f & NSEventModifierFlagCommand) mods |= cmdKey;
    NSString *key = e.charactersIgnoringModifiers.uppercaseString;
    if (!key.length) key = [NSString stringWithFormat:@"Key%u", (unsigned)e.keyCode];
    if (e.keyCode == kVK_Return) key = @"↩";
    else if (e.keyCode == kVK_Space) key = @"Space";
    else if (e.keyCode == kVK_Tab) key = @"⇥";
    NSMutableString *disp = [NSMutableString string];
    if (mods & controlKey) [disp appendString:@"⌃"];
    if (mods & optionKey) [disp appendString:@"⌥"];
    if (mods & shiftKey) [disp appendString:@"⇧"];
    if (mods & cmdKey) [disp appendString:@"⌘"];
    [disp appendString:key];
    if (![weakSelf registerGroupHotkeyForName:weakSelf.groupShortcutRecordingName code:(UInt32)e.keyCode modifiers:mods display:disp]) {
      [weakSelf showToast:@"该快捷键被占用，请换一个"];
      return nil;
    }
    [weakSelf stopGroupShortcutRecording];
    [weakSelf showToast:@"分组快捷键已保存"];
    return nil;
  }];
}

- (void)openGroupShortcutSettings:(id)sender {
  [self installGroupHotkeys];
  NSArray *groups = [self installedGroupNames];
  if (!self.groupShortcutWindow) {
    self.groupShortcutWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,520,540) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.groupShortcutWindow.title = @"分组快捷键";
    self.groupShortcutWindow.releasedWhenClosed = NO;
    self.groupShortcutWindow.level = NSNormalWindowLevel;
    NSView *cv = self.groupShortcutWindow.contentView;
    NSTextField *t = [self label:@"分组快捷键" size:18 bold:YES color:nil];
    t.frame = NSMakeRect(24, 494, 300, 24); [cv addSubview:t];
    NSTextField *h = [self label:@"为每个 Dock 分组设置全局快捷键，按 Esc 取消录制" size:10.5 bold:NO color:[NSColor secondaryLabelColor]];
    h.frame = NSMakeRect(24, 472, 460, 18); [cv addSubview:h];
    NSScrollView *sv = [[NSScrollView alloc] initWithFrame:NSMakeRect(16, 64, 488, 394)];
    sv.hasVerticalScroller = YES; sv.borderType = NSBezelBorder;
    NSView *doc = [[NSView alloc] initWithFrame:NSMakeRect(0,0,470,MAX(394,groups.count*44))];
    self.groupShortcutButtons = [NSMutableArray array];
    for (NSInteger i = 0; i < (NSInteger)groups.count; i++) {
      CGFloat y = doc.frame.size.height - (i+1)*44;
      NSTextField *l = [self label:groups[i] size:12 bold:YES color:nil];
      l.frame = NSMakeRect(12, y+12, 160, 20); [doc addSubview:l];
      ColorHoverButton *b = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(176, y+7, 190, 30)];
      b.title = @"未设置"; b.tag = i; b.hoverColor = [NSColor systemTealColor];
      b.target = self; b.action = @selector(recordGroupHotkey:);
      [b applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
      [doc addSubview:b];
      [self.groupShortcutButtons addObject:b];
      ColorHoverButton *clr = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(376, y+7, 76, 30)];
      clr.title = @"清除"; clr.tag = i; clr.hoverColor = [NSColor systemRedColor];
      clr.target = self; clr.action = @selector(clearGroupHotkey:);
      [clr applyColor:DLButtonBackground() textColor:[NSColor labelColor]];
      [doc addSubview:clr];
    }
    sv.documentView = doc; [cv addSubview:sv];
    ColorHoverButton *close = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(404, 16, 90, 32)];
    close.title = @"关闭"; close.hoverColor = [NSColor systemGrayColor];
    close.target = self; close.action = @selector(closeGroupShortcutSettings:);
    [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:close];
    [self.groupShortcutWindow center];
  }
  [self refreshGroupShortcutButtons];
  [NSApp activateIgnoringOtherApps:YES];
  [self.groupShortcutWindow makeKeyAndOrderFront:nil];
  [self.groupShortcutWindow orderFrontRegardless];
}

