- (void)openGroupByHotkeyID:(UInt32)hotID {
  NSString *name = self.groupHotKeyNames[@(hotID)];
  if (!name.length) return;
  NSString *path = [[GroupDir() stringByAppendingPathComponent:name] stringByAppendingPathExtension:@"app"];
  if ([[NSFileManager defaultManager] fileExistsAtPath:path]) {
    [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path]];
    [self.popover performClose:nil];
  }
}

- (void)stopShortcutRecording {
  if (self.shortcutRecordingMonitor) {
    [NSEvent removeMonitor:self.shortcutRecordingMonitor];
    self.shortcutRecordingMonitor = nil;
  }
  self.shortcutRecordingAction = -1;
  [self refreshShortcutButtons];
  if (self.shortcutStatusLabel) self.shortcutStatusLabel.stringValue = @"点击右侧快捷键开始录制；Esc 取消";
}

- (void)clearShortcutForAction:(NSInteger)action {
  if(action < 0 || action > 8) return;
  EventHotKeyRef old = action == 0 ? self.translationHotKey : (action == 1 ? self.selectionHotKey : (action == 2 ? self.translateHotKey : (action == 3 ? self.appSearchHotKey : (action == 4 ? self.quickPanelHotKey : (action == 5 ? self.clipboardHotKey : (action == 6 ? self.consoleHotKey : (action == 7 ? self.screenshotHotKey : self.recordHotKey)))))));
  if(old) UnregisterEventHotKey(old);
  if(action == 0) { self.translationHotKey = NULL; self.shotKeyCode = 0; self.shotModifiers = 0; self.shotShortcutDisplay = @"未设置"; }
  else if(action == 1) { self.selectionHotKey = NULL; self.selectionKeyCode = 0; self.selectionModifiers = 0; self.selectionShortcutDisplay = @"未设置"; }
  else if(action == 2) { self.translateHotKey = NULL; self.translateKeyCode = 0; self.translateModifiers = 0; self.translateShortcutDisplay = @"未设置"; }
  else if(action == 3) { self.appSearchHotKey = NULL; self.appSearchKeyCode = 0; self.appSearchModifiers = 0; self.appSearchShortcutDisplay = @"未设置"; }
  else if(action == 4) { self.quickPanelHotKey = NULL; self.quickPanelKeyCode = 0; self.quickPanelModifiers = 0; self.quickPanelShortcutDisplay = @"未设置"; }
  else if(action == 5) { self.clipboardHotKey = NULL; self.clipboardKeyCode = 0; self.clipboardModifiers = 0; self.clipboardShortcutDisplay = @"未设置"; }
  else if(action == 6) { self.consoleHotKey = NULL; self.consoleKeyCode = 0; self.consoleModifiers = 0; self.consoleShortcutDisplay = @"未设置"; }
  else if(action == 7) { self.screenshotHotKey = NULL; self.screenshotKeyCode = 0; self.screenshotModifiers = 0; self.screenshotShortcutDisplay = @"未设置"; }
  else { self.recordHotKey = NULL; self.recordKeyCode = 0; self.recordModifiers = 0; self.recordShortcutDisplay = @"未设置"; }
  NSArray *kc=@[@"centerShotKeyCode",@"centerSelectKeyCode",@"centerTranslateKeyCode",@"centerAppSearchKeyCode",@"centerQuickPanelKeyCode",@"centerClipboardKeyCode",@"centerConsoleKeyCode",@"centerScreenshotKeyCode",@"centerRecordKeyCode"];
  NSArray *km=@[@"centerShotModifiers",@"centerSelectModifiers",@"centerTranslateModifiers",@"centerAppSearchModifiers",@"centerQuickPanelModifiers",@"centerClipboardModifiers",@"centerConsoleModifiers",@"centerScreenshotModifiers",@"centerRecordModifiers"];
  NSArray *kd=@[@"centerShotKeyDisplay",@"centerSelectKeyDisplay",@"centerTranslateKeyDisplay",@"centerAppSearchKeyDisplay",@"centerQuickPanelKeyDisplay",@"centerClipboardKeyDisplay",@"centerConsoleKeyDisplay",@"centerScreenshotKeyDisplay",@"centerRecordKeyDisplay"];
  NSUserDefaults *ud=[NSUserDefaults standardUserDefaults];
  [ud setInteger:0 forKey:kc[action]]; [ud setInteger:0 forKey:km[action]]; [ud setObject:@"未设置" forKey:kd[action]];
  [ud synchronize];
  [self refreshShortcutButtons];
  if(self.shortcutStatusLabel) self.shortcutStatusLabel.stringValue=@"已清除该快捷键";
}

- (void)clearAllShortcuts:(id)sender {
  if(self.shortcutRecordingMonitor) [self stopShortcutRecording];
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"清除全部全局快捷键？";
  a.informativeText=@"清除后这些功能不再响应全局快捷键，可随时重新录制。";
  [a addButtonWithTitle:@"清除"]; [a addButtonWithTitle:@"取消"];
  if([a runModal]!=NSAlertFirstButtonReturn)return;
  for(NSInteger i=0;i<9;i++)[self clearShortcutForAction:i];
  if(self.shortcutStatusLabel) self.shortcutStatusLabel.stringValue=@"已清除全部快捷键";
}

- (void)recordShortcutForAction:(ColorHoverButton *)sender {
  [self stopShortcutRecording];
  self.shortcutRecordingAction = sender.tag;
  sender.title = @"请按新组合键…";
  if (self.shortcutStatusLabel) self.shortcutStatusLabel.stringValue = @"录制中：按下组合键，Esc 取消";
  __weak typeof(self) weakSelf = self;
  self.shortcutRecordingMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^NSEvent *(NSEvent *e) {
    NSInteger action = weakSelf.shortcutRecordingAction;
    if (action < 0) return e;
    if (e.keyCode == 53) { [weakSelf stopShortcutRecording]; return nil; }
    NSEventModifierFlags f = e.modifierFlags & (NSEventModifierFlagCommand|NSEventModifierFlagControl|NSEventModifierFlagOption|NSEventModifierFlagShift);
    if (!(f & (NSEventModifierFlagCommand|NSEventModifierFlagControl|NSEventModifierFlagOption))) {
      weakSelf.shortcutStatusLabel.stringValue = @"请至少使用 Command / Control / Option 之一";
      return nil;
    }
    UInt32 mods = 0;
    if (f & NSEventModifierFlagControl) mods |= controlKey;
    if (f & NSEventModifierFlagOption) mods |= optionKey;
    if (f & NSEventModifierFlagShift) mods |= shiftKey;
    if (f & NSEventModifierFlagCommand) mods |= cmdKey;
    NSString *key = e.charactersIgnoringModifiers.uppercaseString;
    if (!key.length) key = [NSString stringWithFormat:@"Key%u", (unsigned)e.keyCode];
    if (e.keyCode == kVK_Return) key = @"↩";
    else if (e.keyCode == kVK_Space) key = @"Space";
    else if (e.keyCode == kVK_Tab) key = @"⇥";
    NSMutableString *disp = [NSMutableString string];
    if (mods & controlKey) [disp appendString:@"⌃"];
    if (mods & optionKey) [disp appendString:@"⌥"];
    if (mods & shiftKey) [disp appendString:@"⇧"];
    if (mods & cmdKey) [disp appendString:@"⌘"];
    [disp appendString:key];
    UInt32 oldCode = action == 0 ? weakSelf.shotKeyCode : (action == 1 ? weakSelf.selectionKeyCode : (action == 2 ? weakSelf.translateKeyCode : (action == 3 ? weakSelf.appSearchKeyCode : (action == 4 ? weakSelf.quickPanelKeyCode : (action == 5 ? weakSelf.clipboardKeyCode : (action == 6 ? weakSelf.consoleKeyCode : (action == 7 ? weakSelf.screenshotKeyCode : weakSelf.recordKeyCode)))))));
    UInt32 oldMods = action == 0 ? weakSelf.shotModifiers : (action == 1 ? weakSelf.selectionModifiers : (action == 2 ? weakSelf.translateModifiers : (action == 3 ? weakSelf.appSearchModifiers : (action == 4 ? weakSelf.quickPanelModifiers : (action == 5 ? weakSelf.clipboardModifiers : (action == 6 ? weakSelf.consoleModifiers : (action == 7 ? weakSelf.screenshotModifiers : weakSelf.recordModifiers)))))));
    NSString *oldDisp = [weakSelf shortcutDisplayForAction:action];
    if (![weakSelf registerHotKeyForAction:action code:(UInt32)e.keyCode modifiers:mods display:disp]) {
      [weakSelf registerHotKeyForAction:action code:oldCode modifiers:oldMods display:oldDisp];
      weakSelf.shortcutStatusLabel.stringValue = @"该快捷键被占用，请换一个";
      return nil;
    }
    [weakSelf stopShortcutRecording];
    weakSelf.shortcutStatusLabel.stringValue = @"已保存，立即生效";
    return nil;
  }];
}

- (void)beginScreenshotTranslation {
  NSTimeInterval shotStart = [[NSDate date] timeIntervalSince1970];
  NSString *tmp = [NSTemporaryDirectory() stringByAppendingPathComponent:@"dl-translate-shot.png"];
  [[NSFileManager defaultManager] removeItemAtPath:tmp error:NULL];
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    NSTask *t = [[NSTask alloc] init];
    t.launchPath = @"/usr/sbin/screencapture";
    t.arguments = @[@"-i", @"-x", tmp];
    @try { [t launch]; [t waitUntilExit]; } @catch (NSException *e) {}
    if (![[NSFileManager defaultManager] fileExistsAtPath:tmp]) return;
    NSTimeInterval shotDone = [[NSDate date] timeIntervalSince1970];
    [self translationOCRImage:tmp completion:^(NSString *text) {
      NSTimeInterval ocrDone = [[NSDate date] timeIntervalSince1970];
      NSString *log = [NSString stringWithFormat:@"capture=%.3fs ocr=%.3fs total=%.3fs chars=%ld\n", shotDone-shotStart, ocrDone-shotDone, ocrDone-shotStart, (long)text.length];
      [log writeToFile:@"/tmp/docklaunchers-shot-translate.log" atomically:YES encoding:NSUTF8StringEncoding error:NULL];
      [self showShotTranslatePanelWithText:text ?: @""];
    }];
  });
}

- (NSString *)shotTranslateLanguageCode {
  NSInteger i=self.shotTranslateTargetPopup.indexOfSelectedItem;
  NSArray *codes=@[@"中文（简体）",@"English",@"日本語",@"한국어",@"Français",@"Deutsch",@"Español",@"Русский"];
  return i>=0&&i<(NSInteger)codes.count?codes[i]:@"中文（简体）";
}

- (void)reloadShotTranslateModels {
  [self.shotTranslateModelPopup removeAllItems];
  NSDictionary *item=nil;
  if(self.shotTranslateSelectedService>=0 && self.shotTranslateSelectedService<(NSInteger)self.shotTranslateServiceItems.count)item=self.shotTranslateServiceItems[self.shotTranslateSelectedService];
  NSInteger provider=item?[item[@"provider"] integerValue]:-1;
  NSString *fallback=item[@"model"] ?: @"";
  if(!fallback.length) fallback=(provider<0?@"qwen2.5:3b":@"gpt-4o-mini");
  [self.shotTranslateModelPopup addItemWithTitle:fallback];
  self.shotTranslateModelPopup.stringValue=fallback;
  if(provider<0)return;
  NSInteger request=++self.shotTranslateModelRequest;
  NSDictionary *e=(provider<(NSInteger)self.aiEntries.count)?self.aiEntries[provider]:nil;
  NSString *base=e[@"apiBase"] ?: @"", *key=e[@"api"] ?: @"";
  if([base hasSuffix:@"/chat/completions"])base=[base substringToIndex:base.length-17];
  while([base hasSuffix:@"/"])base=[base substringToIndex:base.length-1];
  if(!base.length||!key.length)return;
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:[base stringByAppendingString:@"/models"]]];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"]; req.timeoutInterval=15;
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *d,NSURLResponse *r,NSError *err){
    id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil; NSArray *list=[o isKindOfClass:[NSDictionary class]]?o[@"data"]:nil;
    NSMutableArray *models=[NSMutableArray array];
    for(NSDictionary *x in list){NSString *mid=x[@"id"];if(mid.length)[models addObject:mid];}
    if(!models.count)return;
    dispatch_async(dispatch_get_main_queue(),^{
      if(request!=weakSelf.shotTranslateModelRequest)return;
      NSString *cur=weakSelf.shotTranslateModelPopup.titleOfSelectedItem;
      [weakSelf.shotTranslateModelPopup removeAllItems];
      [weakSelf.shotTranslateModelPopup addItemsWithTitles:models];
      if(cur.length&&[models containsObject:cur])weakSelf.shotTranslateModelPopup.stringValue=cur;
      else weakSelf.shotTranslateModelPopup.stringValue=models.firstObject;
    });
  }] resume];
}

- (void)shotTranslateNow:(id)sender {
  NSString *text=[self.shotTranslateSourceView.string stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
  if(!text.length){self.shotTranslateStatus.stringValue=@"没有可翻译的文字";return;}
  NSInteger token=++self.shotTranslateToken;
  NSString *target=[self shotTranslateLanguageCode];
  NSString *prompt=[NSString stringWithFormat:@"Translate the following text into %@. Output only the translation, no explanation, keep formatting.\n\n%@",target,text];
  NSInteger provider=-1;
  if(self.shotTranslateSelectedService>=0 && self.shotTranslateSelectedService<(NSInteger)self.shotTranslateServiceItems.count)
    provider=[self.shotTranslateServiceItems[self.shotTranslateSelectedService][@"provider"] integerValue];
  NSString *url=@"",*key=@"",*model=self.shotTranslateModelPopup.titleOfSelectedItem ?: @"";
  if(provider<0){
    url=@"http://127.0.0.1:11434/v1/chat/completions"; model=@"qwen2.5:3b";
  } else if(provider<(NSInteger)self.aiEntries.count){
    NSDictionary *e=self.aiEntries[provider];
    NSString *base=e[@"apiBase"] ?: @""; key=e[@"api"] ?: @""; model=e[@"model"] ?: @"";
    if([base hasSuffix:@"/chat/completions"])base=[base substringToIndex:base.length-17];
    while([base hasSuffix:@"/"])base=[base substringToIndex:base.length-1];
    if(base.length)url=[base stringByAppendingString:@"/chat/completions"];
    if(!model.length)model=@"gpt-4o-mini";
  }
  if(!url.length){self.shotTranslateStatus.stringValue=@"请先在 AI 管理配置文本服务";return;}
  self.shotTranslateStatus.stringValue=@"正在翻译…";
  __weak typeof(self) weakSelf=self;
  [self aiFileAPICall:prompt model:model url:url key:key completion:^(NSString *answer,NSString *error){
    if(token!=weakSelf.shotTranslateToken)return;
    if(answer.length){weakSelf.shotTranslateResultView.string=answer;weakSelf.shotTranslateStatus.stringValue=[NSString stringWithFormat:@"已翻译为 %@",target];}
    else {weakSelf.shotTranslateStatus.stringValue=[NSString stringWithFormat:@"翻译失败：%@",error ?: @"无返回"];}
  }];
}

- (void)reloadShotTranslateServices {
  if(!self.aiEntries)[self loadAIEntries];
  NSMutableArray *items=[NSMutableArray array];
  for(NSInteger i=0;i<(NSInteger)self.aiEntries.count;i++){
    NSDictionary *e=self.aiEntries[i];
    if([e[@"localOnly"] boolValue])continue;
    if(![[self aiModelCategoryKey:e] isEqualToString:@"text"])continue;
    if(![e[@"api"] length])continue;
    NSString *name=e[@"name"] ?: @""; if(!name.length)continue;
    NSString *shortName=[name componentsSeparatedByCharactersInSet:[NSCharacterSet whitespaceCharacterSet]].firstObject ?: name;
    [items addObject:@{@"title":[NSString stringWithFormat:@"API：%@",shortName],@"model":e[@"model"] ?: @"",@"provider":@(i)}];
  }
  [items addObject:@{@"title":@"本地 Ollama",@"model":@"qwen2.5:3b",@"provider":@(-1)}];
  self.shotTranslateServiceItems=items;
  if(self.shotTranslateSelectedService>=(NSInteger)items.count)self.shotTranslateSelectedService=0;
  for(NSView *v in self.shotTranslateServiceList.subviews.copy)[v removeFromSuperview];
  CGFloat rowH=34, h=MAX(rowH*items.count,34);
  self.shotTranslateServiceList.frame=NSMakeRect(0,0,640,h);
  for(NSInteger i=0;i<(NSInteger)items.count;i++){
    NSDictionary *it=items[i];
    BOOL sel=(i==self.shotTranslateSelectedService);
    ColorHoverButton *b=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(0,h-(i+1)*rowH+2,640,rowH-4)];
    NSString *title=it[@"title"] ?: @"";
    NSString *model=it[@"model"] ?: @"";
    if(model.length)title=[title stringByAppendingFormat:@"   %@",model];
    if(sel)title=[@"✓ " stringByAppendingString:title];
    b.title=title; b.font=[NSFont systemFontOfSize:11]; b.tag=i;
    b.hoverColor=[NSColor systemTealColor];
    b.target=self; b.action=@selector(shotTranslateServiceSelected:);
    [b applyColor:(sel?[NSColor controlAccentColor]:DLButtonBackground()) textColor:(sel?[NSColor whiteColor]:[NSColor labelColor])];
    [self.shotTranslateServiceList addSubview:b];
  }
  [self reloadShotTranslateModels];
}

- (void)shotTranslateServiceSelected:(ColorHoverButton *)sender {
  self.shotTranslateSelectedService=sender.tag;
  [self reloadShotTranslateServices];
  [self shotTranslateNow:nil];
}

