- (void)quickPanelOpenItem:(NSDictionary *)item {
  NSString *type = item[@"type"];
  if ([type isEqualToString:@"页面"] || [type isEqualToString:@"AI"]) {
    NSInteger page = [item[@"page"] integerValue];
    if (page == 4) { [self openUninstallFromMenu]; return; }
    [self.window makeKeyAndOrderFront:nil];
    [NSApp activateIgnoringOtherApps:YES];
    [self showSection:page];
  } else if ([type isEqualToString:@"分组"] || [type isEqualToString:@"分组应用"] || [type isEqualToString:@"应用"]) {
    NSString *path = item[@"path"];
    if (path.length) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path]];
  } else if ([type isEqualToString:@"录制"]) {
    NSString *tool = item[@"tool"] ?: @"";
    if ([tool isEqualToString:@"recordstart"]) [self startQuickRecording];
    else if ([tool isEqualToString:@"recordpause"]) [self pauseCapture:nil];
    else if ([tool isEqualToString:@"recordstop"]) [self captureVideo:nil];
    else if ([tool isEqualToString:@"recordpanel"]) [self showCaptureTool:nil];
    else if ([tool isEqualToString:@"recordrecent"]) [self openMostRecentRecording];
  } else if ([type isEqualToString:@"命令"]) {
    NSInteger cid = [item[@"commandID"] integerValue];
    if (cid > 0) [self performAllGlobalActionID:cid];
  } else if ([type isEqualToString:@"工具"]) {
    NSString *tool = item[@"tool"] ?: @"";
    if ([tool isEqualToString:@"translate"]) [self showTranslationWindow:nil];
    else if ([tool isEqualToString:@"compress"]) [self showCompressWindow:nil];
    else if ([tool isEqualToString:@"pdf"]) [self showPDFTools:nil];
    else if ([tool isEqualToString:@"image"]) [self showImageTools:nil];
    else if ([tool isEqualToString:@"rename"]) [self showBatchRenamer:nil];
    else if ([tool isEqualToString:@"clipboard"]) [self showClipboardWindow:nil];
    else if ([tool isEqualToString:@"layouts"]) [self showWindowLayouts:nil];
    else if ([tool isEqualToString:@"largefiles"]) [self showLargeFileCleaner:nil];
    else if ([tool isEqualToString:@"duplicates"]) [self showDuplicateFinder:nil];
    else if ([tool isEqualToString:@"process"]) [self showProcessManager:nil];
    else if ([tool isEqualToString:@"usage"]) [self showUsageStats:nil];
    else if ([tool isEqualToString:@"startup"]) [self showStartupItems:nil];
    else if ([tool isEqualToString:@"prompts"]) [self showPromptLibrary:nil];
    else if ([tool isEqualToString:@"appearance"]) [self showDockAppearance:nil];
    else if ([tool isEqualToString:@"password"]) [self showPasswordSettings:nil];
    else if ([tool isEqualToString:@"appshortcuts"]) [self showAppShortcutSettings:nil];
    else if ([tool isEqualToString:@"globalshortcuts"]) [self openShortcutSettings:nil];
    else if ([tool isEqualToString:@"disk"]) [self openDiskAnalysisFromMenu];
    else if ([tool isEqualToString:@"appsearch"]) [self showAppSearch:nil];
    else if ([tool isEqualToString:@"aimgmt"]) { if (![self ensureAIManagementAccess]) return; [self rebuildQuickAITab]; [self showDetachedPage:self.quickAIPage title:@"AI 管理"]; }
    else if ([tool isEqualToString:@"color"]) [self showColorSampler:nil];
    else if ([tool isEqualToString:@"filesearch"]) [self showFileSearch:nil];
    else if ([tool isEqualToString:@"capture"]) [self showCaptureTool:nil];
    else if ([tool isEqualToString:@"diagnostics"]) [self openDiagnosticsWindow:nil];
    else if ([tool isEqualToString:@"shelf"]) [self openShelfWindow:nil];
    else if ([tool isEqualToString:@"configbackup"]) [self openConfigBackupWindow:nil];
    else if ([tool isEqualToString:@"cloudsync"]) [self openCloudSyncWindow:nil];
    else if ([tool isEqualToString:@"automation"]) [self openAutomationRules:nil];
    else if ([tool isEqualToString:@"meeting"]) [self openMeetingAssistant:nil];
    else if ([tool isEqualToString:@"voicetext"]) [self openVoiceTextWindow:nil];
    else if ([tool isEqualToString:@"groupschedule"]) [self openGroupScheduleRules:nil];
    else if ([tool isEqualToString:@"privacy"]) [self openPrivacyDashboard:nil];
    else if ([tool isEqualToString:@"radialcustom"]) [self openRadialPageCustomization:nil];
    else if ([tool isEqualToString:@"speechsettings"]) [self openSpeechSettings:nil];
    else if ([tool isEqualToString:@"tts"]) [self openAITTSWindow:nil];
    else if ([tool isEqualToString:@"aiusage"]) [self showAIUsageStats:nil];
    else if ([tool isEqualToString:@"liveanno"]) [self toggleLiveAnnotation:nil];
    else if ([tool isEqualToString:@"aiquick"]) [self openAIQuickCommand:nil];
    else if ([tool isEqualToString:@"convert"]) [self openFileConverter:nil];
    else if ([tool isEqualToString:@"updatecheck"]) [self checkForUpdates:nil];
    else if ([tool isEqualToString:@"videopost"]) [self openVideoPostWindow:nil];
    else if ([tool isEqualToString:@"aitext"]) [self openAIAssistant:nil];
    else if ([tool isEqualToString:@"aiimage"]) [self openAIImagePanel:nil];
    else if ([tool isEqualToString:@"aivision"]) [self openAIVisionPanel:nil];
    else if ([tool isEqualToString:@"aiedit"]) [self openAIEditPanel:nil];
    else if ([tool isEqualToString:@"aivideo"]) [self openAIVideoPanel:nil];
    else if ([tool isEqualToString:@"capturehistory"]) [self showCaptureHistory:nil];
    else if ([tool isEqualToString:@"console"]) { [self showWindow:nil]; [self showSection:0]; }
    else if ([tool isEqualToString:@"uninstall"]) [self openUninstallFromMenu];
  }
}

