- (void)tagCaptureHistoryRow:(id)sender {
  NSInteger row = self.captureHistoryTable.selectedRow;
  if (row < 0) row = self.captureHistoryTable.clickedRow;
  if (row < 0 || row >= (NSInteger)self.captureHistoryItems.count) { [self showToast:@"请先选择一条记录"]; return; }
  NSDictionary *it=self.captureHistoryItems[row];
  if (!self.captureHistoryTags) self.captureHistoryTags=[[[NSUserDefaults standardUserDefaults] dictionaryForKey:@"centerCaptureHistoryTags"] ?: @{} mutableCopy];
  NSArray *existingTags = self.captureHistoryTags[it[@"path"]] ?: @[];
  NSString *existing=[existingTags componentsJoinedByString:@", "];
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"编辑截图标签"; a.informativeText=@"多个标签用逗号分隔，留空表示清除";
  NSTextField *tf=[[NSTextField alloc] initWithFrame:NSMakeRect(0,0,300,24)]; tf.stringValue=existing; a.accessoryView=tf;
  [a addButtonWithTitle:@"保存"]; [a addButtonWithTitle:@"取消"];
  if([a runModal]!=NSAlertFirstButtonReturn)return;
  NSMutableArray *tags=[NSMutableArray array];
  for(NSString *part in [tf.stringValue componentsSeparatedByString:@","]){NSString *v=[part stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(v.length)[tags addObject:v];}
  if(tags.count)self.captureHistoryTags[it[@"path"]]=tags; else [self.captureHistoryTags removeObjectForKey:it[@"path"]];
  [[NSUserDefaults standardUserDefaults] setObject:self.captureHistoryTags forKey:@"centerCaptureHistoryTags"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self refreshCaptureHistory:nil];
}

- (void)refreshCaptureHistory:(id)sender {
  NSFileManager *fm = [NSFileManager defaultManager];
  NSMutableArray *items = [NSMutableArray array];
  NSArray *dirs = @[[self captureImageDirectory], [self captureVideoDirectory]];
  NSMutableSet *seen = [NSMutableSet set];
  for (NSString *dir in dirs) {
    for (NSString *f in [fm contentsOfDirectoryAtPath:dir error:NULL] ?: @[]) {
      if ([f hasPrefix:@"."]) continue;
      NSString *lower=f.lowercaseString;
      if ([lower containsString:@"-part"] || [lower containsString:@"-composed"] || [lower containsString:@"camera-"] || [f containsString:@"音轨"] || [lower containsString:@"-nr-"] || [lower containsString:@"-audio"]) continue;
      NSString *ext=f.pathExtension.lowercaseString;
      BOOL isShot=[@[@"png",@"jpg",@"jpeg",@"heic",@"tiff"] containsObject:ext];
      BOOL isVid=[@[@"mov",@"mp4",@"m4v"] containsObject:ext];
      if(!isShot&&!isVid) continue;
      NSString *path = [dir stringByAppendingPathComponent:f];
      if ([seen containsObject:path]) continue;
      [seen addObject:path];
      NSDictionary *attrs = [fm attributesOfItemAtPath:path error:NULL] ?: @{};
      NSDate *date = attrs[NSFileModificationDate] ?: [NSDate date];
      BOOL isVideo = [@[@"mov", @"mp4"] containsObject:path.pathExtension.lowercaseString];
      [items addObject:@{@"path": path, @"name": f, @"date": date, @"type": isVideo ? @"录屏" : @"截图", @"dir": dir}];
    }
  }
  [items sortUsingComparator:^NSComparisonResult(NSDictionary *a, NSDictionary *b) { return [b[@"date"] compare:a[@"date"]]; }];
  self.captureHistoryAllItems = items;
  if (!self.captureHistoryTags) self.captureHistoryTags = [[[NSUserDefaults standardUserDefaults] dictionaryForKey:@"centerCaptureHistoryTags"] ?: @{} mutableCopy];
  NSString *q = self.captureHistorySearchField.stringValue.lowercaseString ?: @"";
  NSMutableArray *visible = [NSMutableArray array];
  for (NSMutableDictionary *it in items) {
    NSArray *tags = self.captureHistoryTags[it[@"path"]] ?: @[];
    if (q.length) {
      BOOL match = [[it[@"name"] lowercaseString] containsString:q];
      for (NSString *tag in tags) if ([tag.lowercaseString containsString:q]) match = YES;
      if (!match) continue;
    }
    NSMutableDictionary *m=[it mutableCopy]; m[@"tags"]=[tags componentsJoinedByString:@", "]; [visible addObject:m];
  }
  if (visible.count > 100) visible = [[visible subarrayWithRange:NSMakeRange(0, 100)] mutableCopy];
  self.captureHistoryItems = visible;
  [self.captureHistoryTable reloadData];
}

- (void)openCaptureHistoryRow:(id)sender {
  NSInteger row = self.captureHistoryTable.selectedRow;
  if (row < 0) row = self.captureHistoryTable.clickedRow;
  if (row < 0 || row >= (NSInteger)self.captureHistoryItems.count) return;
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.captureHistoryItems[row][@"path"]]];
}

- (void)revealCaptureHistoryRow:(id)sender {
  NSInteger row = self.captureHistoryTable.selectedRow;
  if (row < 0) row = self.captureHistoryTable.clickedRow;
  if (row < 0 || row >= (NSInteger)self.captureHistoryItems.count) return;
  [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:self.captureHistoryItems[row][@"path"]]]];
}

- (void)editCaptureHistoryVideo:(id)sender {
  NSInteger row = self.captureHistoryTable.selectedRow;
  if (row < 0) row = self.captureHistoryTable.clickedRow;
  if (row < 0 || row >= (NSInteger)self.captureHistoryItems.count) { [self showToast:@"请先选择一个录屏文件"]; return; }
  NSDictionary *it = self.captureHistoryItems[row];
  if (![it[@"type"] isEqualToString:@"录屏"]) { [self showToast:@"只有录屏可以剪辑"]; return; }
  NSError *err = nil;
  self.recordingEditor = [[SCRecordingEditor alloc] initWithURL:[NSURL fileURLWithPath:it[@"path"]]];
  [self.recordingEditor presentFromWindow:self.captureHistoryWindow completionHandler:^(NSError *error) {
    if (error) [self showToast:error.localizedDescription ?: @"无法打开剪辑器"];
  }];
}

- (void)annotateCaptureHistoryRow:(id)sender {
  NSInteger row = self.captureHistoryTable.selectedRow;
  if (row < 0) row = self.captureHistoryTable.clickedRow;
  if (row < 0 || row >= (NSInteger)self.captureHistoryItems.count) { [self showToast:@"请先选择一张截图"]; return; }
  NSDictionary *it = self.captureHistoryItems[row];
  if (![it[@"type"] isEqualToString:@"截图"]) { [self showToast:@"只能标注截图，录屏请用剪辑"]; return; }
  [self showAnnotationForPath:it[@"path"]];
}

- (void)openCaptureVideoFolder:(id)sender { [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:[self captureVideoDirectory]]]; }
- (void)closeCaptureHistory:(id)sender { [self.captureHistoryWindow orderOut:nil]; }

- (void)chooseCaptureImageFolder:(id)sender { [self chooseCaptureFolderForVideo:NO]; }
- (void)chooseCaptureVideoFolder:(id)sender { [self chooseCaptureFolderForVideo:YES]; }

- (void)chooseCaptureFolderForVideo:(BOOL)video {
  NSOpenPanel *panel = [NSOpenPanel openPanel];
  panel.canChooseFiles = NO;
  panel.canChooseDirectories = YES;
  panel.allowsMultipleSelection = NO;
  panel.canCreateDirectories = YES;
  panel.prompt = @"选择";
  panel.message = video ? @"选择录屏保存文件夹" : @"选择截图保存文件夹";
  NSString *current = video ? [self captureVideoDirectory] : [self captureImageDirectory];
  if (current.length) panel.directoryURL = [NSURL fileURLWithPath:current];
  __weak typeof(self) weakSelf = self;
  [panel beginSheetModalForWindow:self.captureWindow completionHandler:^(NSModalResponse result) {
    if (result != NSModalResponseOK || !panel.URL.path.length) return;
    NSString *dir = panel.URL.path;
    if (video) {
      [[NSUserDefaults standardUserDefaults] setObject:dir forKey:@"centerCaptureVideoDirectory"];
      weakSelf.captureVideoPathField.stringValue = dir;
    } else {
      [[NSUserDefaults standardUserDefaults] setObject:dir forKey:@"centerCaptureImageDirectory"];
      weakSelf.captureImagePathField.stringValue = dir;
    }
    [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
    weakSelf.captureStatusLabel.stringValue = [NSString stringWithFormat:@"%@保存目录已应用：%@", video ? @"录屏" : @"截图", dir];
  }];
}


- (NSString *)captureImageDirectory {
  NSString *dir = self.captureImagePathField.stringValue;
  if (!dir.length) dir = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCaptureImageDirectory"];
  if (!dir.length) dir = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCaptureDirectory"];
  if (!dir.length) dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Pictures/DockLaunchers Captures"];
  dir = [dir stringByExpandingTildeInPath];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return dir;
}

- (NSString *)captureVideoDirectory {
  NSString *dir = self.captureVideoPathField.stringValue;
  if (!dir.length) dir = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCaptureVideoDirectory"];
  if (!dir.length) dir = [NSHomeDirectory() stringByAppendingPathComponent:@"Pictures/DockLaunchers Captures"];
  dir = [dir stringByExpandingTildeInPath];
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  return dir;
}

- (NSString *)captureDirectory { return [self captureImageDirectory]; }

- (void)captureImagePathChanged:(id)sender {
  NSString *dir = [self.captureImagePathField.stringValue stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
  if (!dir.length) return;
  dir = [dir stringByExpandingTildeInPath];
