- (void)capturePiPShapeChanged:(id)sender {
  BOOL round = self.capturePiPShapeControl.selectedSegment == 0;
  [[NSUserDefaults standardUserDefaults] setBool:round forKey:@"centerCapturePiPShape"];
  if (self.captureCameraWindow.contentView) {
    CGFloat r = round ? self.captureCameraWindow.frame.size.width / 2.0 : 12.0;
    self.captureCameraWindow.contentView.layer.cornerRadius = r;
  }
}

- (void)captureCameraChanged:(id)sender {
  NSString *uid = self.captureCameraPopup.selectedItem.representedObject ?: @"";
  [[NSUserDefaults standardUserDefaults] setObject:uid forKey:@"centerCaptureCameraID"];
  if (uid.length) [self startCameraPreviewIfNeeded];
  else [self stopCameraPreview];
}

- (void)stopCameraPreview {
  if (self.captureCameraSession.isRunning) [self.captureCameraSession stopRunning];
  self.captureCameraSession = nil;
  [self.captureCameraWindow orderOut:nil];
  self.captureCameraWindow = nil;
  self.captureCameraLayer = nil;
}

- (void)startCameraPreviewIfNeeded {
  NSString *uid = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCaptureCameraID"];
  if (!uid.length) { [self stopCameraPreview]; return; }
  AVCaptureDevice *device = [AVCaptureDevice deviceWithUniqueID:uid];
  if (!device) { [self stopCameraPreview]; return; }
  __weak typeof(self) weakSelf = self;
  [AVCaptureDevice requestAccessForMediaType:AVMediaTypeVideo completionHandler:^(BOOL granted) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!granted) { [weakSelf showToast:@"没有摄像头权限"]; return; }
      [weakSelf stopCameraPreview];
      AVCaptureSession *session = [[AVCaptureSession alloc] init];
      session.sessionPreset = AVCaptureSessionPresetMedium;
      NSError *err = nil;
      AVCaptureDeviceInput *input = [AVCaptureDeviceInput deviceInputWithDevice:device error:&err];
      if (!input || ![session canAddInput:input]) { [weakSelf showToast:@"无法启动摄像头"]; return; }
      [session addInput:input];
      NSRect vis = [NSScreen mainScreen].visibleFrame;
      CGFloat camSize = 220;
      NSRect frame = NSMakeRect(NSMaxX(vis) - camSize - 24, NSMinY(vis) + 24, camSize, camSize);
      NSString *savedOrigin = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCaptureCameraOrigin"];
      if (savedOrigin.length) {
        NSPoint p = NSPointFromString(savedOrigin);
        if (p.x > NSMinX(vis) - 20 && p.x < NSMaxX(vis) - 40 && p.y > NSMinY(vis) - 20 && p.y < NSMaxY(vis) - 40) {
          frame.origin = p;
          frame = NSMakeRect(p.x, p.y, camSize, camSize);
        }
      }
      NSWindow *w = [[NSWindow alloc] initWithContentRect:frame styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
      w.opaque = NO;
      w.backgroundColor = [NSColor clearColor];
      w.level = NSFloatingWindowLevel;
      w.delegate = self;
      w.sharingType = self.captureUsePreviewOverlay ? NSWindowSharingReadOnly : NSWindowSharingNone;
      w.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
      w.movableByWindowBackground = YES;
      w.hasShadow = YES;
      AVCaptureVideoPreviewLayer *layer = [AVCaptureVideoPreviewLayer layerWithSession:session];
      layer.frame = NSMakeRect(0,0,frame.size.width,frame.size.height);
      layer.videoGravity = AVLayerVideoGravityResizeAspectFill;
      NSView *view = [[NSView alloc] initWithFrame:NSMakeRect(0,0,frame.size.width,frame.size.height)];
      view.wantsLayer = YES;
      [view.layer addSublayer:layer];
      view.layer.borderWidth = 2;
      view.layer.borderColor = [NSColor colorWithCalibratedRed:1 green:0.35 blue:0.25 alpha:0.9].CGColor;
      id shapeObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCapturePiPShape"];
      BOOL roundShape = !shapeObj || [shapeObj boolValue];
      view.layer.cornerRadius = roundShape ? camSize / 2.0 : 12.0;
      view.layer.masksToBounds = YES;
      w.contentView = view;
      weakSelf.captureCameraSession = session;
      weakSelf.captureCameraWindow = w;
      weakSelf.captureCameraLayer = layer;
      [w orderFront:nil];
      dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        [session startRunning];
        dispatch_async(dispatch_get_main_queue(), ^{ [weakSelf startCameraMovieIfNeeded]; });
      });
    });
  }];
}

- (void)startCameraMovieIfNeeded {
  if (self.captureUsePreviewOverlay) return;
  if (!self.captureRecording || !self.captureCameraSession.isRunning) return;
  if (self.captureCameraMovieOutput.isRecording) return;
  if (!self.captureCameraMovieOutput) {
    self.captureCameraMovieOutput = [[AVCaptureMovieFileOutput alloc] init];
    if ([self.captureCameraSession canAddOutput:self.captureCameraMovieOutput]) {
      [self.captureCameraSession beginConfiguration];
      [self.captureCameraSession addOutput:self.captureCameraMovieOutput];
      [self.captureCameraSession commitConfiguration];
    } else {
      self.captureCameraMovieOutput = nil;
      return;
    }
  }
  AVCaptureConnection *conn = [self.captureCameraMovieOutput connectionWithMediaType:AVMediaTypeVideo];
  if ([conn isVideoRotationAngleSupported:90]) conn.videoRotationAngle = 90;
  NSString *path = [[self captureVideoDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"camera-%@.mov", [self captureTimestamp]]];
  [[NSFileManager defaultManager] removeItemAtPath:path error:NULL];
  if (!self.captureCameraSegments) self.captureCameraSegments = [NSMutableArray array];
  self.captureCameraMoviePath = path;
  @try { [self.captureCameraMovieOutput startRecordingToOutputFileURL:[NSURL fileURLWithPath:path] recordingDelegate:self]; }
  @catch (NSException *e) { self.captureCameraMoviePath = nil; }
}

- (void)captureOutput:(AVCaptureFileOutput *)output didFinishRecordingToOutputFileAtURL:(NSURL *)outputFileURL fromConnections:(NSArray<AVCaptureConnection *> *)connections error:(NSError *)error {
  dispatch_async(dispatch_get_main_queue(), ^{
    if (!self.captureCameraSegments) self.captureCameraSegments = [NSMutableArray array];
    if ([[NSFileManager defaultManager] fileExistsAtPath:outputFileURL.path] && ![self.captureCameraSegments containsObject:outputFileURL]) [self.captureCameraSegments addObject:outputFileURL];
    if (self.captureCameraPauseStopping) {
      self.captureCameraPauseStopping = NO;
      self.captureCameraMoviePath = nil;
      return;
    }
    if (self.captureCameraWaiting && self.capturePendingScreenPath.length) {
      NSString *screenPath = self.capturePendingScreenPath;
      NSArray *cameraSegments = [self.captureCameraSegments copy];
      self.captureCameraWaiting = NO;
      self.capturePendingScreenPath = nil;
      [self composeCameraSegments:cameraSegments overScreen:screenPath];
    } else {
      self.captureCameraWaiting = NO;
    }
  });
}

- (void)composeCameraSegments:(NSArray<NSURL *> *)cameraPaths overScreen:(NSString *)screenPath {
  BOOL noiseReduction = [self noiseReductionLevel] > 0;
  if (noiseReduction && !self.captureNoiseAttempted && [self fileNeedsAudioMix:screenPath]) {
    self.captureNoiseAttempted = YES;
    NSInteger gainDB = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureMicGain"];
    self.captureStatusLabel.stringValue = @"正在处理麦克风降噪…";
    __weak typeof(self) weakSelf = self;
    [self applyMicGainToFile:screenPath gainDB:gainDB completion:^(BOOL ok) {
      if (!ok) dispatch_async(dispatch_get_main_queue(), ^{ weakSelf.captureStatusLabel.stringValue = @"麦克风降噪失败，继续合成"; });
      [weakSelf composeCameraSegments:cameraPaths overScreen:screenPath];
    }];
    return;
  }
  if (!cameraPaths.count || ![[NSFileManager defaultManager] fileExistsAtPath:screenPath]) {
    [self showToast:@"摄像头合成失败，已保留原录屏"];
    return;
  }
  self.captureCameraComposing = YES;
  self.captureStatusLabel.stringValue = @"正在合成摄像头画中画…";
  AVURLAsset *screenAsset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:screenPath] options:nil];
  AVAssetTrack *screenVideo = [screenAsset tracksWithMediaType:AVMediaTypeVideo].firstObject;
  AVAssetTrack *screenAudio = [screenAsset tracksWithMediaType:AVMediaTypeAudio].firstObject;
  if (!screenVideo) {
    self.captureCameraComposing = NO;
    [self showToast:@"摄像头合成失败，已保留原录屏"];
    return;
  }
  AVMutableComposition *comp = [AVMutableComposition composition];
  AVMutableCompositionTrack *sv = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
  NSError *insErr = nil;
  [sv insertTimeRange:CMTimeRangeMake(kCMTimeZero, screenAsset.duration) ofTrack:screenVideo atTime:kCMTimeZero error:&insErr];
  NSArray *screenAudios = [screenAsset tracksWithMediaType:AVMediaTypeAudio];
  NSMutableArray<AVMutableCompositionTrack *> *audioTracks = [NSMutableArray array];
  for (NSInteger ai = 0; ai < (NSInteger)screenAudios.count && ai < 2; ai++) {
    AVMutableCompositionTrack *at = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
    [at insertTimeRange:CMTimeRangeMake(kCMTimeZero, screenAsset.duration) ofTrack:screenAudios[ai] atTime:kCMTimeZero error:NULL];
    [audioTracks addObject:at];
  }
  AVMutableCompositionTrack *cv = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
  CMTime screenDuration = screenAsset.duration;
  CMTime camCursor = kCMTimeZero;
  CGSize cameraNaturalSize = NSZeroSize;
  for (NSURL *u in cameraPaths) {
    AVURLAsset *camAsset = [AVURLAsset URLAssetWithURL:u options:nil];
    AVAssetTrack *camTrack = [camAsset tracksWithMediaType:AVMediaTypeVideo].firstObject;
    if (!camTrack) continue;
    if (cameraNaturalSize.width <= 0) cameraNaturalSize = camTrack.naturalSize;
    if (CMTimeCompare(camCursor, screenDuration) >= 0) break;
    CMTime remaining = CMTimeSubtract(screenDuration, camCursor);
    CMTime take = CMTimeMinimum(camAsset.duration, remaining);
    if (CMTimeCompare(take, kCMTimeZero) > 0) [cv insertTimeRange:CMTimeRangeMake(kCMTimeZero, take) ofTrack:camTrack atTime:camCursor error:NULL];
    camCursor = CMTimeAdd(camCursor, take);
  }
  if (cameraNaturalSize.width <= 0) {
    self.captureCameraComposing = NO;
    [self showToast:@"摄像头合成失败，已保留原录屏"];
    return;
  }
  CGSize renderSize = screenVideo.naturalSize;
  AVMutableVideoComposition *vc = [AVMutableVideoComposition videoComposition];
  vc.renderSize = renderSize;
  NSInteger outFPS = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureFPS"];
  if (outFPS <= 0) outFPS = 30;
  vc.frameDuration = CMTimeMake(1, (int32_t)outFPS);
  AVMutableVideoCompositionInstruction *inst = [[AVMutableVideoCompositionInstruction alloc] init];
  inst.timeRange = CMTimeRangeMake(kCMTimeZero, screenAsset.duration);
  AVMutableVideoCompositionLayerInstruction *screenLayer = [AVMutableVideoCompositionLayerInstruction videoCompositionLayerInstructionWithAssetTrack:sv];
  AVMutableVideoCompositionLayerInstruction *camLayer = [AVMutableVideoCompositionLayerInstruction videoCompositionLayerInstructionWithAssetTrack:cv];
  NSString *pipPreset = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCapturePiPPreset"] ?: @"br-medium";
  BOOL pipMirror = [pipPreset hasSuffix:@"mirror"];
  NSString *pipBase = pipMirror ? [pipPreset stringByReplacingOccurrencesOfString:@"-mirror" withString:@""] : pipPreset;
  CGFloat pipFrac = 0.24;
  if ([pipBase hasSuffix:@"small"]) pipFrac = 0.18;
  else if ([pipBase hasSuffix:@"large"]) pipFrac = 0.30;
  BOOL pipLeft = [pipBase hasPrefix:@"bl"] || [pipBase hasPrefix:@"tl"];
  BOOL pipTop = [pipBase hasPrefix:@"tr"] || [pipBase hasPrefix:@"tl"];
  CGFloat targetW = renderSize.width * pipFrac;
  CGFloat scale = targetW / MAX(1, cameraNaturalSize.width);
  CGFloat targetH = MAX(1, cameraNaturalSize.height * scale);
  CGFloat margin = renderSize.width * 0.02;
  CGFloat pipX = pipLeft ? margin : (renderSize.width - targetW - margin);
  CGFloat pipY = pipTop ? margin : (renderSize.height - targetH - margin);
  CGAffineTransform t = pipMirror ? CGAffineTransformMake(-scale, 0, 0, scale, pipX + targetW, pipY) : CGAffineTransformMake(scale, 0, 0, scale, pipX, pipY);
  (void)t;
  [camLayer setTransform:t atTime:kCMTimeZero];
  inst.layerInstructions = @[camLayer, screenLayer];
  vc.instructions = @[inst];
  NSString *outPath = [[screenPath stringByDeletingPathExtension] stringByAppendingString:@"-composed.mp4"];
  [[NSFileManager defaultManager] removeItemAtPath:outPath error:NULL];
  AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPreset1920x1080];
  ex.videoComposition = vc;
  NSInteger micGainDB = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureMicGain"];
  if (audioTracks.count) {
    AVMutableAudioMix *am = [AVMutableAudioMix audioMix];
    NSMutableArray *params = [NSMutableArray array];
    if (audioTracks.count == 1) {
      AVMutableAudioMixInputParameters *ap = [AVMutableAudioMixInputParameters audioMixInputParametersWithTrack:audioTracks[0]];
      [ap setVolume:1.0f atTime:kCMTimeZero];
      [params addObject:ap];
    } else {
      NSInteger micIndex = [self micTrackIndexForAudioTracks:screenAudios];
      for (NSInteger ai = 0; ai < (NSInteger)audioTracks.count; ai++) {
        AVMutableAudioMixInputParameters *ap = [AVMutableAudioMixInputParameters audioMixInputParametersWithTrack:audioTracks[ai]];
        float vol = (ai == micIndex) ? pow(10.0, micGainDB / 20.0) : 1.0f;
        [ap setVolume:vol atTime:kCMTimeZero];
        [params addObject:ap];
      }
    }
    am.inputParameters = params;
    ex.audioMix = am;
  }
  ex.outputURL = [NSURL fileURLWithPath:outPath];
  ex.outputFileType = AVFileTypeMPEG4;
  ex.shouldOptimizeForNetworkUse = YES;
  __weak typeof(self) weakSelf = self;
  [ex exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      weakSelf.captureCameraComposing = NO;
      weakSelf.captureCameraMovieOutput = nil;
      weakSelf.captureCameraMoviePath = nil;
      [weakSelf finishCaptureUI];
      // macOS 27 may report AVAssetExportSessionStatusFailed with nil error while still writing a valid file.
      NSDictionary *outAttrs = [[NSFileManager defaultManager] attributesOfItemAtPath:outPath error:NULL];
      BOOL exported = (ex.status == AVAssetExportSessionStatusCompleted) || (outAttrs && [outAttrs[NSFileSize] longLongValue] > 0);
      if (exported) {
        [[NSFileManager defaultManager] removeItemAtPath:screenPath error:NULL];
        [[NSFileManager defaultManager] moveItemAtPath:outPath toPath:screenPath error:NULL];
        for (NSURL *u in cameraPaths) [[NSFileManager defaultManager] removeItemAtPath:u.path error:NULL];
        weakSelf.captureStatusLabel.stringValue = @"录屏已保存（含摄像头画中画）";
        [weakSelf showToast:@"摄像头画中画合成完成"];
      } else {
        [[NSFileManager defaultManager] removeItemAtPath:outPath error:NULL];
        weakSelf.captureStatusLabel.stringValue = @"摄像头合成失败，已保留原录屏";
        [weakSelf showToast:@"摄像头合成失败，已保留原录屏"];
      }
      for (NSURL *u in cameraPaths) [[NSFileManager defaultManager] removeItemAtPath:u.path error:NULL];
    });
  }];
}

