  self.captureSystemAudioCheck.state = (!sysObj || [sysObj boolValue]) ? NSControlStateValueOn : NSControlStateValueOff;
  id micVal2 = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureMicrophone"];
  self.captureMicCheck.state = (micVal2 ? [micVal2 boolValue] : YES) ? NSControlStateValueOn : NSControlStateValueOff;
  id boostVal2 = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureMicBoost"];
  if (self.captureMicBoostCheck) self.captureMicBoostCheck.state = (boostVal2 ? [boostVal2 boolValue] : YES) ? NSControlStateValueOn : NSControlStateValueOff;
  id curObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowCursor"];
  self.captureCursorCheck.state = (!curObj || [curObj boolValue]) ? NSControlStateValueOn : NSControlStateValueOff;
  id clickObj = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowClicks"];
  self.captureClickCheck.state = (!clickObj || [clickObj boolValue]) ? NSControlStateValueOn : NSControlStateValueOff;
  NSInteger noiseLevel = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureNoiseLevel"];
  if (noiseLevel == 0 && [[NSUserDefaults standardUserDefaults] boolForKey:@"centerCaptureNoiseReduction"]) noiseLevel = 2;
  for (NSMenuItem *mi in self.captureNoisePopup.itemArray) if ([mi.representedObject integerValue] == noiseLevel) [self.captureNoisePopup selectItem:mi];
  NSString *savedCam = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCaptureCameraID"];
  for (NSMenuItem *mi in self.captureCameraPopup.itemArray) if ([(mi.representedObject ?: @"") isEqualToString:savedCam ?: @""]) [self.captureCameraPopup selectItem:mi];
  NSString *savedPiP = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerCapturePiPPreset"];
  for (NSMenuItem *mi in self.capturePiPPopup.itemArray) if ([(mi.representedObject ?: @"") isEqualToString:savedPiP ?: @"br-medium"]) [self.capturePiPPopup selectItem:mi];
  NSInteger micGain = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureMicGain"];
  for (NSMenuItem *mi in self.captureMicGainPopup.itemArray) if ([mi.representedObject integerValue] == micGain) [self.captureMicGainPopup selectItem:mi];
  if (!self.captureRecording) {
    NSString *cam = self.captureCameraPopup.selectedItem.representedObject ?: @"";
    if (cam.length) [self startCameraPreviewIfNeeded]; else [self stopCameraPreview];
  }
  if (self.suppressCaptureToolShow) {
    [self.captureWindow orderOut:nil];
  } else {
    [NSApp activateIgnoringOtherApps:YES];
    [self.captureWindow makeKeyAndOrderFront:nil];
    [self startMicLevelMeterIfNeeded];
  }
}

- (void)openCaptureFolder:(id)sender { [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:[self captureDirectory]]]; }
- (void)closeCaptureTool:(id)sender { [self stopMicLevelMeter]; if (!self.captureRecording) [self stopCameraPreview]; [self.captureWindow orderOut:nil]; }

- (void)hideCapturePanelForCapture {
  if (self.captureWindow.isVisible) {
    [self.captureWindow orderOut:nil];
    [self.captureWindow displayIfNeeded];
  }
}

- (void)runScreenshotArgs:(NSArray *)args path:(NSString *)path {
  [self hideCapturePanelForCapture];
  usleep(150000);
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/usr/sbin/screencapture";
  t.arguments = args;
  self.captureTask = t;
  self.captureStatusLabel.stringValue = @"正在截图…";
  t.terminationHandler = ^(NSTask *task) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (task.terminationStatus == 0 && [[NSFileManager defaultManager] fileExistsAtPath:path]) {
        if (self.captureCopyCheck.state == NSControlStateValueOn) {
          NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
          if (img) {
            [[NSPasteboard generalPasteboard] clearContents];
            [[NSPasteboard generalPasteboard] writeObjects:@[img]];
          }
        }
        self.captureStatusLabel.stringValue = [NSString stringWithFormat:@"已保存：%@", path.lastPathComponent];
        [self showToast:@"截图已保存"];
        [self showCaptureResultPanel:path];
      } else {
        self.captureStatusLabel.stringValue = @"截图已取消，或没有屏幕录制权限";
      }
    });
  };
  @try { [t launch]; } @catch (NSException *e) { self.captureStatusLabel.stringValue = @"无法启动截图"; }
}

- (void)toggleLiveAnnotation:(id)sender {
  if (self.liveAnnotationWindow.isVisible) {
    [self.liveAnnotationWindow orderOut:nil];
    return;
  }
  [self hideCapturePanelForCapture];
  NSRect frame = [NSScreen mainScreen].frame;
  self.liveAnnotationWindow = [[NSWindow alloc] initWithContentRect:frame styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
  self.liveAnnotationWindow.opaque = NO;
  self.liveAnnotationWindow.backgroundColor = [NSColor clearColor];
  self.liveAnnotationWindow.hasShadow = NO;
  self.liveAnnotationWindow.level = NSStatusWindowLevel + 2;
  self.liveAnnotationWindow.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  self.liveAnnotationView = [[DLLiveAnnotationView alloc] initWithFrame:NSMakeRect(0,0,frame.size.width,frame.size.height)];
  self.liveAnnotationView.tool = 0;
  self.liveAnnotationView.color = [NSColor systemRedColor];
  self.liveAnnotationView.lineWidth = 5;
  self.liveAnnotationView.items = [NSMutableArray array];
  __weak typeof(self) weakSelf=self;
  self.liveAnnotationView.onEscape = ^{ [weakSelf.liveAnnotationWindow orderOut:nil]; };
  self.liveAnnotationWindow.contentView = self.liveAnnotationView;
  NSArray *titles = @[@"画笔", @"箭头", @"清除", @"关闭"];
  NSArray *sels = @[@"liveAnnoPen:", @"liveAnnoArrow:", @"liveAnnoClear:", @"liveAnnoClose:"];
  for (NSInteger i=0;i<4;i++) {
    ColorHoverButton *b = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(frame.size.width/2 - 190 + i*96, frame.size.height - 50, 88, 32)];
    b.title = titles[i]; b.hoverColor = [NSColor systemOrangeColor];
    b.target = self; b.action = NSSelectorFromString(sels[i]);
    [b applyColor:[NSColor colorWithWhite:0.1 alpha:0.85] textColor:[NSColor whiteColor]];
    [self.liveAnnotationView addSubview:b];
  }
  [self.liveAnnotationWindow makeKeyAndOrderFront:nil];
  [self.liveAnnotationWindow makeFirstResponder:self.liveAnnotationView];
  [self showToast:@"实时标注已开启；Esc 或顶部工具栏关闭"];
}

- (void)liveAnnoPen:(id)sender { self.liveAnnotationView.tool = 0; }
- (void)liveAnnoArrow:(id)sender { self.liveAnnotationView.tool = 1; }
- (void)liveAnnoClear:(id)sender { [self.liveAnnotationView.items removeAllObjects]; [self.liveAnnotationView setNeedsDisplay:YES]; }
- (void)liveAnnoClose:(id)sender { [self.liveAnnotationWindow orderOut:nil]; }

- (void)captureFullScreen:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  NSString *path = [[self captureDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"截图-%@.png", [self captureTimestamp]]];
  NSInteger delay = [self captureDelaySeconds];
  NSMutableArray *args = [NSMutableArray arrayWithObjects:@"-x", nil];
  if (delay > 0) [args addObjectsFromArray:@[@"-T", [NSString stringWithFormat:@"%ld", (long)delay]]];
  [args addObject:path];
  [self runScreenshotArgs:args path:path];
}

- (void)captureRegion:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  NSString *path = [[self captureDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"截图-%@.png", [self captureTimestamp]]];
  [self runScreenshotArgs:@[@"-i", @"-x", path] path:path];
}

- (void)captureWindowShot:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  NSString *path = [[self captureDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"截图-%@.png", [self captureTimestamp]]];
  [self runScreenshotArgs:@[@"-i", @"-W", @"-x", path] path:path];
}

- (NSString *)captureTimestamp {
  NSDateFormatter *df = [[NSDateFormatter alloc] init];
  df.dateFormat = @"yyyyMMdd-HHmmss";
  return [df stringFromDate:[NSDate date]];
}

- (NSInteger)captureDelaySeconds {
  NSArray *vals = @[@0, @3, @5, @10];
  NSInteger i = self.captureDelayPopup.indexOfSelectedItem;
  return (i >= 0 && i < (NSInteger)vals.count) ? [vals[i] integerValue] : 0;
}

- (NSInteger)captureRecordCountdownSeconds {
  NSArray *vals = @[@0, @3, @5, @10];
  NSInteger i = self.captureRecordCountdownPopup.indexOfSelectedItem;
  return (i >= 0 && i < (NSInteger)vals.count) ? [vals[i] integerValue] : 0;
}

- (void)showCaptureCountdown:(NSInteger)seconds completion:(void (^)(void))completion {
  [self.captureCountdownTimer invalidate];
  self.captureCountdownRemaining = seconds;
  if (!self.captureCountdownWindow) {
    self.captureCountdownWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,220,140) styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
    self.captureCountdownWindow.opaque = NO;
    self.captureCountdownWindow.backgroundColor = [NSColor colorWithCalibratedWhite:0.05 alpha:0.82];
    self.captureCountdownWindow.level = NSScreenSaverWindowLevel;
    self.captureCountdownWindow.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
    self.captureCountdownLabel = [self label:@"3" size:84 bold:YES color:[NSColor whiteColor]];
    self.captureCountdownLabel.alignment = NSTextAlignmentCenter;
    self.captureCountdownLabel.frame = NSMakeRect(0, 18, 220, 104);
    [self.captureCountdownWindow.contentView addSubview:self.captureCountdownLabel];
    [self.captureCountdownWindow center];
  }
  self.captureCountdownLabel.stringValue = [NSString stringWithFormat:@"%ld", (long)seconds];
  [self.captureCountdownWindow orderFront:nil];
  __weak typeof(self) weakSelf = self;
  self.captureCountdownTimer = [NSTimer scheduledTimerWithTimeInterval:1.0 repeats:YES block:^(NSTimer *timer) {
    weakSelf.captureCountdownRemaining--;
    if (weakSelf.captureCountdownRemaining <= 0) {
      [timer invalidate];
      weakSelf.captureCountdownTimer = nil;
      [weakSelf.captureCountdownWindow orderOut:nil];
      if (completion) completion();
    } else {
      weakSelf.captureCountdownLabel.stringValue = [NSString stringWithFormat:@"%ld", (long)weakSelf.captureCountdownRemaining];
    }
  }];
}

- (void)captureRegion:(NSRect)region toPath:(NSString *)path completion:(void (^)(BOOL ok))completion {
  NSScreen *primary = [NSScreen screens].firstObject ?: [NSScreen mainScreen];
  NSRect pf = primary.frame;
  CGFloat x = region.origin.x - pf.origin.x;
  CGFloat topY = pf.size.height - (region.origin.y - pf.origin.y + region.size.height);
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/usr/sbin/screencapture";
  t.arguments = @[@"-x", @"-R", [NSString stringWithFormat:@"%ld,%ld,%ld,%ld", (long)llround(x), (long)llround(topY), (long)llround(region.size.width), (long)llround(region.size.height)], path];
  t.terminationHandler = ^(NSTask *task) {
    dispatch_async(dispatch_get_main_queue(), ^{
      BOOL ok = task.terminationStatus == 0 && [[NSFileManager defaultManager] fileExistsAtPath:path];
      if (completion) completion(ok);
    });
  };
  @try { [t launch]; } @catch (NSException *e) { if (completion) completion(NO); }
}

- (void)pinImageAtPath:(NSString *)path {
  NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
  if (!img) { [self showToast:@"钉屏失败：图片读取错误"]; return; }
  if (!self.pinnedScreenshotWindows) self.pinnedScreenshotWindows = [NSMutableArray array];
  NSScreen *scr = [NSScreen mainScreen];
  NSRect vis = scr.visibleFrame;
  CGFloat maxW = vis.size.width * 0.72, maxH = vis.size.height * 0.72;
  CGFloat scale = MIN(1.0, MIN(maxW / MAX(1, img.size.width), maxH / MAX(1, img.size.height)));
  NSSize size = NSMakeSize(MAX(120, img.size.width * scale), MAX(80, img.size.height * scale));
  NSWindow *w = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,size.width,size.height) styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
  w.opaque = YES;
  w.backgroundColor = [NSColor blackColor];
  w.level = NSNormalWindowLevel;
  w.hasShadow = YES;
  w.releasedWhenClosed = NO;
  w.movableByWindowBackground = YES;
  w.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  NSView *cv = w.contentView;
  cv.wantsLayer = YES;
  cv.layer.borderWidth = 1;
  cv.layer.borderColor = [NSColor controlAccentColor].CGColor;
  DLPinnedImageView *iv = [[DLPinnedImageView alloc] initWithFrame:NSMakeRect(0,0,size.width,size.height)];
  iv.image = img;
  iv.imageScaling = NSImageScaleProportionallyUpOrDown;
  [cv addSubview:iv];
  NSButton *close = [[NSButton alloc] initWithFrame:NSMakeRect(size.width-30, size.height-30, 24, 24)];
  close.bordered = NO;
  close.image = [NSImage imageWithSystemSymbolName:@"xmark.circle.fill" accessibilityDescription:@"关闭钉屏"];
  close.contentTintColor = [NSColor systemRedColor];
  close.target = self;
  close.action = @selector(closePinnedScreenshot:);
  [cv addSubview:close];
  [w setFrameOrigin:NSMakePoint(NSMidX(vis)-size.width/2, NSMidY(vis)-size.height/2)];
  [w orderFrontRegardless];
  [self.pinnedScreenshotWindows addObject:w];
}

- (void)closePinnedScreenshot:(NSButton *)sender {
  NSWindow *w = sender.window;
  [w orderOut:nil];
  if (self.pinnedScreenshotWindows && w) [self.pinnedScreenshotWindows removeObject:w];
}

- (void)pinScreenshotInteractive:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  [self hideCapturePanelForCapture];
  __weak typeof(self) weakSelf = self;
  [self beginCaptureRegion:^(NSRect region) {
    NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"pin-%lld.png", (long long)[[NSDate date] timeIntervalSince1970]]];
    [weakSelf captureRegion:region toPath:path completion:^(BOOL ok) {
      if (ok) { [weakSelf pinImageAtPath:path]; [[NSFileManager defaultManager] removeItemAtPath:path error:NULL]; }
      else [weakSelf showToast:@"钉屏截图失败"];
    }];
  }];
}

- (void)startScrollCapture:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  [self hideCapturePanelForCapture];
  __weak typeof(self) weakSelf = self;
  [self beginCaptureRegion:^(NSRect region) {
    [weakSelf beginScrollCaptureInRegion:region];
  }];
}

- (void)beginScrollCaptureInRegion:(NSRect)region {
  [self stopScrollCapture:nil];
  self.scrollCaptureRegion = region;
  self.scrollCapturePaths = [NSMutableArray array];
  self.scrollCaptureCount = 0;
  self.scrollCaptureBusy = NO;
  NSPanel *hud = [[NSPanel alloc] initWithContentRect:NSMakeRect(0,0,300,74) styleMask:NSWindowStyleMaskBorderless|NSWindowStyleMaskNonactivatingPanel backing:NSBackingStoreBuffered defer:NO];
  hud.opaque = NO;
  hud.backgroundColor = [NSColor colorWithCalibratedWhite:0.08 alpha:0.90];
  hud.level = NSFloatingWindowLevel;
  hud.hasShadow = YES;
  hud.sharingType = NSWindowSharingNone;
  hud.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  NSView *cv = hud.contentView;
  cv.wantsLayer = YES; cv.layer.cornerRadius = 12; cv.layer.masksToBounds = YES;
  NSTextField *label = [self label:@"滚动长截图：请缓慢滚动页面" size:12 bold:YES color:[NSColor whiteColor]];
  label.frame=NSMakeRect(14,44,270,18); [cv addSubview:label];
  NSTextField *hint = [self label:@"完成后点右侧停止" size:9.5 bold:NO color:[NSColor whiteColor]];
  hint.frame=NSMakeRect(14,22,190,16); [cv addSubview:hint];
  ColorHoverButton *stop = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(208,20,78,34)];
  stop.title=@"停止拼接"; stop.hoverColor=[NSColor systemRedColor];
  stop.target=self; stop.action=@selector(stopScrollCapture:);
  [stop applyColor:[NSColor systemRedColor] textColor:[NSColor whiteColor]];
  [cv addSubview:stop];
  NSScreen *scr=[NSScreen mainScreen]; NSRect vis=scr.visibleFrame;
  [hud setFrameOrigin:NSMakePoint(NSMaxX(vis)-hud.frame.size.width-24, NSMaxY(vis)-hud.frame.size.height-24)];
  self.scrollCaptureHUD = hud;
  [hud orderFrontRegardless];
  [self captureNextScrollFrame];
  self.scrollCaptureTimer = [NSTimer scheduledTimerWithTimeInterval:0.75 target:self selector:@selector(captureNextScrollFrame) userInfo:nil repeats:YES];
}

- (void)captureNextScrollFrame {
  if (self.scrollCaptureBusy || !self.scrollCapturePaths) return;
  self.scrollCaptureBusy = YES;
  self.scrollCaptureCount++;
  NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"scroll-%04ld.png", (long)self.scrollCaptureCount]];
  __weak typeof(self) weakSelf = self;
  [self captureRegion:self.scrollCaptureRegion toPath:path completion:^(BOOL ok) {
    weakSelf.scrollCaptureBusy = NO;
    if (ok) [weakSelf.scrollCapturePaths addObject:path];
  }];
}

- (void)stopScrollCapture:(id)sender {
  [self.scrollCaptureTimer invalidate];
  self.scrollCaptureTimer = nil;
  [self.scrollCaptureHUD orderOut:nil];
  self.scrollCaptureHUD = nil;
  NSArray *paths = [self.scrollCapturePaths copy];
  self.scrollCapturePaths = nil;
  if (paths.count < 2) { [self showToast:@"至少需要两帧才能拼接"]; return; }
  [self showToast:@"正在拼接长截图…"];
  __weak typeof(self) weakSelf = self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    NSString *out = [weakSelf stitchScrollImages:paths];
    dispatch_async(dispatch_get_main_queue(), ^{
      if (out.length) { [weakSelf showToast:@"长截图已保存"]; [weakSelf showCaptureResultPanel:out]; }
      else [weakSelf showToast:@"长截图拼接失败"];
    });
  });
}

- (NSBitmapImageRep *)rgbaRepForPath:(NSString *)path {
  NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
  if (!img) return nil;
  NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithData:[img TIFFRepresentation]];
  if (!rep) return nil;
  if (rep.bitsPerSample == 8 && rep.samplesPerPixel >= 3 && !rep.isPlanar) return rep;
  NSInteger w = rep.pixelsWide, h = rep.pixelsHigh;
  NSBitmapImageRep *std = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:w pixelsHigh:h bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:w*4 bitsPerPixel:32];
  [NSGraphicsContext saveGraphicsState];
  [NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithBitmapImageRep:std]];
  [rep drawInRect:NSMakeRect(0,0,w,h)];
  [NSGraphicsContext restoreGraphicsState];
  return std;
}

- (NSMutableData *)topDownRowsForRep:(NSBitmapImageRep *)rep widthBytes:(NSInteger)w4 {
  NSInteger h = rep.pixelsHigh;
  NSInteger srcStride = rep.bytesPerRow;
  NSMutableData *out = [NSMutableData dataWithLength:(NSUInteger)w4*h];
  unsigned char *dst = out.mutableBytes;
  unsigned char *src = rep.bitmapData;
  for (NSInteger y = 0; y < h; y++) {
    memcpy(dst + y*w4, src + (h-1-y)*srcStride, MIN((NSInteger)w4, srcStride));
  }
  return out;
}

- (NSInteger)overlapFromPrevTop:(NSData *)prev prevH:(NSInteger)prevH nextTop:(NSData *)next nextH:(NSInteger)nextH widthBytes:(NSInteger)w4 {
  const unsigned char *a = prev.bytes, *b = next.bytes;
  NSInteger maxO = MIN(prevH, nextH) - 8;
  if (maxO < 12) return 0;
  for (NSInteger o = maxO; o >= 12; o--) {
    double diff = 0; NSInteger samples = 0;
    NSInteger rows = MIN(36, o);
    for (NSInteger y = 0; y < rows; y += 3) {
      const unsigned char *ra = a + (prevH-o+y)*w4;
      const unsigned char *rb = b + y*w4;
      for (NSInteger x = 0; x < w4/4; x += 6) {
        diff += ABS((int)ra[x*4] - (int)rb[x*4]) + ABS((int)ra[x*4+1] - (int)rb[x*4+1]) + ABS((int)ra[x*4+2] - (int)rb[x*4+2]);
        samples += 3;
      }
    }
    if (samples && diff/samples < 10.0) return o;
  }
  return 0;
}

- (NSString *)stitchScrollImages:(NSArray<NSString *> *)paths {
  NSMutableArray<NSBitmapImageRep *> *reps = [NSMutableArray array];
  for (NSString *p in paths) { NSBitmapImageRep *r = [self rgbaRepForPath:p]; if (r) [reps addObject:r]; }
  if (reps.count < 2) return nil;
  NSBitmapImageRep *first = reps.firstObject;
  NSInteger w = first.pixelsWide;
  NSInteger w4 = w * 4;
  NSMutableData *comp = [self topDownRowsForRep:first widthBytes:w4];
  NSInteger totalH = first.pixelsHigh;
  for (NSInteger i = 1; i < (NSInteger)reps.count; i++) {
    NSBitmapImageRep *next = reps[i];
    NSMutableData *nextTop = [self topDownRowsForRep:next widthBytes:w4];
    NSInteger overlap = [self overlapFromPrevTop:comp prevH:totalH nextTop:nextTop nextH:next.pixelsHigh widthBytes:w4];
    NSInteger appendH = next.pixelsHigh - overlap;
    if (appendH <= 0) continue;
    NSMutableData *grown = [NSMutableData dataWithCapacity:(NSUInteger)w4*(totalH+appendH)];
    [grown appendData:comp];
    [grown appendBytes:(const void *)((const unsigned char *)nextTop.bytes + overlap*w4) length:(NSUInteger)w4*appendH];
    comp = grown;
    totalH += appendH;
  }
  NSBitmapImageRep *outRep = [[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:w pixelsHigh:totalH bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:w4 bitsPerPixel:32];
  unsigned char *dst = outRep.bitmapData;
  const unsigned char *src = comp.bytes;
  for (NSInteger y = 0; y < totalH; y++) {
    memcpy(dst + (totalH-1-y)*w4, src + y*w4, w4);
  }
  NSData *png = [outRep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
  NSString *out = [[self captureDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"截图-滚动-%@.png", [self captureTimestamp]]];
  return [png writeToFile:out atomically:YES] ? out : nil;
}

- (void)beginCaptureRegion:(void (^)(NSRect region))completion {
  NSRect frame = NSZeroRect;
  for (NSScreen *sc in [NSScreen screens]) frame = NSUnionRect(frame, sc.frame);
  if (NSIsEmptyRect(frame)) frame = [NSScreen mainScreen].frame;
  NSWindow *w = [[NSWindow alloc] initWithContentRect:frame styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
  w.opaque = NO;
  w.backgroundColor = [NSColor colorWithCalibratedWhite:0 alpha:0.18];
  w.level = NSScreenSaverWindowLevel;
  w.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  DLRegionSelectView *view = [[DLRegionSelectView alloc] initWithFrame:NSMakeRect(0,0,frame.size.width,frame.size.height)];
  __weak typeof(self) weakSelf = self;
  view.onComplete = ^(NSRect rect) {
    [w orderOut:nil];
    weakSelf.captureRegionWindow = nil;
    if (completion) completion(rect);
  };
  view.onCancel = ^{
    [w orderOut:nil];
    weakSelf.captureRegionWindow = nil;
    weakSelf.captureStatusLabel.stringValue = @"已取消区域选择";
  };
  w.contentView = view;
  self.captureRegionWindow = w;
  [NSApp activateIgnoringOtherApps:YES];
  [w makeKeyAndOrderFront:nil];
  [w makeFirstResponder:view];
}

- (void)startClickHighlighting {
  BOOL enabled = [[NSUserDefaults standardUserDefaults] objectForKey:@"centerCaptureShowClicks"] ? [[NSUserDefaults standardUserDefaults] boolForKey:@"centerCaptureShowClicks"] : YES;
  if (!enabled) return;
  [self stopClickHighlighting];
  self.clickRingWindows = [NSMutableArray array];
  __weak typeof(self) weakSelf = self;
  self.clickGlobalMonitor = [NSEvent addGlobalMonitorForEventsMatchingMask:(NSEventMaskLeftMouseDown|NSEventMaskRightMouseDown) handler:^(NSEvent *event) {
    dispatch_async(dispatch_get_main_queue(), ^{ [weakSelf showClickRingAtPoint:NSEvent.mouseLocation]; });
  }];
  self.clickLocalMonitor = [NSEvent addLocalMonitorForEventsMatchingMask:(NSEventMaskLeftMouseDown|NSEventMaskRightMouseDown) handler:^NSEvent *(NSEvent *event) {
    dispatch_async(dispatch_get_main_queue(), ^{ [weakSelf showClickRingAtPoint:NSEvent.mouseLocation]; });
    return event;
  }];
}

- (void)stopClickHighlighting {
  if (self.clickGlobalMonitor) { [NSEvent removeMonitor:self.clickGlobalMonitor]; self.clickGlobalMonitor = nil; }
  if (self.clickLocalMonitor) { [NSEvent removeMonitor:self.clickLocalMonitor]; self.clickLocalMonitor = nil; }
  for (NSWindow *w in self.clickRingWindows) [w orderOut:nil];
  [self.clickRingWindows removeAllObjects];
}

- (void)showClickRingAtPoint:(NSPoint)screenPoint {
  CGFloat size = 54;
  NSWindow *w = [[NSWindow alloc] initWithContentRect:NSMakeRect(screenPoint.x - size/2, screenPoint.y - size/2, size, size) styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
  w.opaque = NO;
  w.backgroundColor = [NSColor clearColor];
  w.level = NSScreenSaverWindowLevel;
  w.alphaValue = 1.0;
  w.ignoresMouseEvents = YES;
  w.hasShadow = NO;
  w.sharingType = NSWindowSharingReadOnly;
  w.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  NSView *v = [[NSView alloc] initWithFrame:NSMakeRect(0,0,size,size)];
  v.wantsLayer = YES;
  v.layer.cornerRadius = size/2;
  v.layer.borderWidth = 3.5;
  v.layer.borderColor = [NSColor colorWithCalibratedRed:1 green:0.62 blue:0.15 alpha:1].CGColor;
  v.layer.backgroundColor = [NSColor colorWithCalibratedRed:1 green:0.62 blue:0.15 alpha:0.20].CGColor;
  w.contentView = v;
  [w orderFrontRegardless];
  [self.clickRingWindows addObject:w];
  __weak typeof(self) weakSelf = self;
  [NSAnimationContext runAnimationGroup:^(NSAnimationContext *ctx) {
    ctx.duration = 0.55;
    w.animator.alphaValue = 0.0;
  } completionHandler:^{
    [w orderOut:nil];
    [weakSelf.clickRingWindows removeObject:w];
  }];
}

- (NSInteger)micTrackIndexForAudioTracks:(NSArray<AVAssetTrack *> *)audios {
  if (audios.count < 2) return 0;
  for (NSInteger i = 0; i < (NSInteger)audios.count; i++) {
    CMFormatDescriptionRef desc = (__bridge CMFormatDescriptionRef)audios[i].formatDescriptions.firstObject;
    const AudioStreamBasicDescription *asbd = desc ? CMAudioFormatDescriptionGetStreamBasicDescription(desc) : NULL;
    if (asbd && asbd->mChannelsPerFrame == 1) return i;
  }
  return 1;
}

- (BOOL)fileNeedsAudioMix:(NSString *)path {
  if (![[NSFileManager defaultManager] fileExistsAtPath:path]) return NO;
  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:path] options:nil];
  return [asset tracksWithMediaType:AVMediaTypeAudio].count > 1;
}

- (void)exportAudioComposition:(AVMutableComposition *)comp mix:(AVAudioMix *)mix toURL:(NSURL *)url completion:(void (^)(BOOL ok))completion {
  [[NSFileManager defaultManager] removeItemAtURL:url error:NULL];
  AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPresetAppleM4A];
  ex.audioMix = mix;
  ex.outputURL = url;
  ex.outputFileType = AVFileTypeAppleM4A;
  [ex exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      NSDictionary *attrs = [[NSFileManager defaultManager] attributesOfItemAtPath:url.path error:NULL];
      BOOL ok = (ex.status == AVAssetExportSessionStatusCompleted) || (attrs && [attrs[NSFileSize] longLongValue] > 0);
      if (completion) completion(ok);
    });
  }];
}

- (void)processNoiseReductionAudio:(NSURL *)inURL toURL:(NSURL *)outURL completion:(void (^)(BOOL ok))completion {
  NSError *err = nil;
  AVAudioFile *inFile = [[AVAudioFile alloc] initForReading:inURL error:&err];
  if (!inFile) { if (completion) completion(NO); return; }
  AVAudioFormat *format = [[AVAudioFormat alloc] initStandardFormatWithSampleRate:48000 channels:2];
  AVAudioEngine *engine = [[AVAudioEngine alloc] init];
  AVAudioPlayerNode *player = [[AVAudioPlayerNode alloc] init];
  NSInteger noiseLevel = [self noiseReductionLevel];
  float cutoff = noiseLevel >= 3 ? 130.0f : (noiseLevel == 1 ? 60.0f : 90.0f);
  AVAudioUnitEQ *eq = [[AVAudioUnitEQ alloc] initWithNumberOfBands:1];
  AVAudioUnitEQFilterParameters *hp = eq.bands.firstObject;
  hp.filterType = AVAudioUnitEQFilterTypeHighPass;
  hp.frequency = cutoff;
  hp.bypass = NO;
  AudioComponentDescription gateDesc = {kAudioUnitType_Effect, kAudioUnitSubType_DynamicsProcessor, kAudioUnitManufacturer_Apple, 0, 0};
  AVAudioUnitEffect *gate = [[AVAudioUnitEffect alloc] initWithAudioComponentDescription:gateDesc];
  if (gate) {
    AudioUnit au = gate.audioUnit;
    AudioUnitSetParameter(au, kDynamicsProcessorParam_Threshold, kAudioUnitScope_Global, 0, -20.0f, 0);
    AudioUnitSetParameter(au, kDynamicsProcessorParam_HeadRoom, kAudioUnitScope_Global, 0, 5.0f, 0);
    AudioUnitSetParameter(au, kDynamicsProcessorParam_ExpansionThreshold, kAudioUnitScope_Global, 0, noiseLevel >= 3 ? -30.0f : -46.0f, 0);
    AudioUnitSetParameter(au, kDynamicsProcessorParam_ExpansionRatio, kAudioUnitScope_Global, 0, noiseLevel >= 3 ? 4.0f : 2.0f, 0);
    AudioUnitSetParameter(au, kDynamicsProcessorParam_AttackTime, kAudioUnitScope_Global, 0, 0.001f, 0);
    AudioUnitSetParameter(au, kDynamicsProcessorParam_ReleaseTime, kAudioUnitScope_Global, 0, 0.08f, 0);
    AudioUnitSetParameter(au, kDynamicsProcessorParam_OverallGain, kAudioUnitScope_Global, 0, 0.0f, 0);
  }
  [engine attachNode:player];
  [engine attachNode:eq];
  [engine connect:player to:eq format:inFile.processingFormat];
  if (gate) {
    [engine attachNode:gate];
    [engine connect:eq to:gate format:inFile.processingFormat];
    [engine connect:gate to:engine.mainMixerNode format:inFile.processingFormat];
  } else {
    [engine connect:eq to:engine.mainMixerNode format:inFile.processingFormat];
  }
  if (![engine enableManualRenderingMode:AVAudioEngineManualRenderingModeOffline format:format maximumFrameCount:4096 error:&err]) { if (completion) completion(NO); return; }
  [[NSFileManager defaultManager] removeItemAtURL:outURL error:NULL];
  NSMutableDictionary *writeSettings = [format.settings mutableCopy];
  writeSettings[AVLinearPCMIsNonInterleaved] = @NO;
  AVAudioFile *outFile = [[AVAudioFile alloc] initForWriting:outURL settings:writeSettings error:&err];
  if (!outFile) { if (completion) completion(NO); return; }
  if (![engine startAndReturnError:&err]) { if (completion) completion(NO); return; }
  [player scheduleFile:inFile atTime:nil completionHandler:nil];
  [player play];
  double duration = inFile.length / MAX(1.0, inFile.processingFormat.sampleRate);
  NSUInteger totalFrames = (NSUInteger)llround(duration * 48000.0);
  NSUInteger rendered = 0;
  while (rendered < totalFrames) {
    AVAudioPCMBuffer *buffer = [[AVAudioPCMBuffer alloc] initWithPCMFormat:engine.manualRenderingFormat frameCapacity:4096];
    AVAudioEngineManualRenderingStatus status = [engine renderOffline:4096 toBuffer:buffer error:&err];
    if (status != AVAudioEngineManualRenderingStatusSuccess || buffer.frameLength == 0) break;
    [outFile writeFromBuffer:buffer error:NULL];
    rendered += buffer.frameLength;
  }
  [player stop];
  [engine stop];
  BOOL ok = [[NSFileManager defaultManager] fileExistsAtPath:outURL.path];
  if (completion) completion(ok);
}

- (void)applyNoiseReductionToFile:(NSString *)path gainDB:(NSInteger)gainDB completion:(void (^)(BOOL ok))completion {
  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:path] options:nil];
  AVAssetTrack *video = [asset tracksWithMediaType:AVMediaTypeVideo].firstObject;
  NSArray *audios = [asset tracksWithMediaType:AVMediaTypeAudio];
  if (!video || audios.count < 2) { if (completion) completion(NO); return; }
  NSInteger micIndex = [self micTrackIndexForAudioTracks:audios];
  NSInteger sysIndex = (micIndex == 0) ? 1 : 0;
  NSString *base = [path stringByDeletingPathExtension];
  NSString *micRawPath = [base stringByAppendingString:@"-mic.m4a"];
  NSString *micNRPath = [base stringByAppendingString:@"-mic-nr.caf"];
  NSString *mixedPath = [base stringByAppendingString:@"-nr-mix.m4a"];
  NSString *tmpPath = [base stringByAppendingString:@"-nr-remux.mp4"];
  [[NSFileManager defaultManager] removeItemAtPath:micRawPath error:NULL];
  [[NSFileManager defaultManager] removeItemAtPath:micNRPath error:NULL];
  [[NSFileManager defaultManager] removeItemAtPath:mixedPath error:NULL];
  [[NSFileManager defaultManager] removeItemAtPath:tmpPath error:NULL];
  AVMutableComposition *micComp = [AVMutableComposition composition];
  AVMutableCompositionTrack *mt = [micComp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
  [mt insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:audios[micIndex] atTime:kCMTimeZero error:NULL];
  __weak typeof(self) weakSelf = self;
  [self exportAudioComposition:micComp mix:nil toURL:[NSURL fileURLWithPath:micRawPath] completion:^(BOOL ok) {
    if (!ok) { if (completion) completion(NO); return; }
    [weakSelf processNoiseReductionAudio:[NSURL fileURLWithPath:micRawPath] toURL:[NSURL fileURLWithPath:micNRPath] completion:^(BOOL nrOK) {
      if (!nrOK) { if (completion) completion(NO); return; }
      AVURLAsset *micAsset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:micNRPath] options:nil];
      AVAssetTrack *micTrack = [micAsset tracksWithMediaType:AVMediaTypeAudio].firstObject;
      AVMutableComposition *mixComp = [AVMutableComposition composition];
      AVMutableCompositionTrack *st = [mixComp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
      [st insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:audios[sysIndex] atTime:kCMTimeZero error:NULL];
      AVMutableCompositionTrack *mct = [mixComp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
      [mct insertTimeRange:CMTimeRangeMake(kCMTimeZero, CMTimeMinimum(micAsset.duration, asset.duration)) ofTrack:micTrack atTime:kCMTimeZero error:NULL];
      AVMutableAudioMix *mix = [AVMutableAudioMix audioMix];
      AVMutableAudioMixInputParameters *sp = [AVMutableAudioMixInputParameters audioMixInputParametersWithTrack:st];
      [sp setVolume:1.0f atTime:kCMTimeZero];
      AVMutableAudioMixInputParameters *mp = [AVMutableAudioMixInputParameters audioMixInputParametersWithTrack:mct];
      [mp setVolume:pow(10.0, gainDB / 20.0) atTime:kCMTimeZero];
      mix.inputParameters = @[sp, mp];
      [weakSelf exportAudioComposition:mixComp mix:mix toURL:[NSURL fileURLWithPath:mixedPath] completion:^(BOOL mixOK) {
        if (!mixOK) { if (completion) completion(NO); return; }
        AVURLAsset *mixedAsset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:mixedPath] options:nil];
        AVAssetTrack *mixedAudio = [mixedAsset tracksWithMediaType:AVMediaTypeAudio].firstObject;
        AVMutableComposition *comp = [AVMutableComposition composition];
        AVMutableCompositionTrack *v = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
        [v insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:video atTime:kCMTimeZero error:NULL];
        AVMutableCompositionTrack *a = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
        [a insertTimeRange:CMTimeRangeMake(kCMTimeZero, CMTimeMinimum(mixedAsset.duration, asset.duration)) ofTrack:mixedAudio atTime:kCMTimeZero error:NULL];
        AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPresetPassthrough];
        ex.outputURL = [NSURL fileURLWithPath:tmpPath];
        ex.outputFileType = AVFileTypeMPEG4;
        ex.shouldOptimizeForNetworkUse = YES;
        [ex exportAsynchronouslyWithCompletionHandler:^{
          dispatch_async(dispatch_get_main_queue(), ^{
            NSDictionary *attrs = [[NSFileManager defaultManager] attributesOfItemAtPath:tmpPath error:NULL];
            BOOL remuxOK = (ex.status == AVAssetExportSessionStatusCompleted) || (attrs && [attrs[NSFileSize] longLongValue] > 0);
            if (remuxOK) {
              [[NSFileManager defaultManager] removeItemAtPath:path error:NULL];
              [[NSFileManager defaultManager] moveItemAtPath:tmpPath toPath:path error:NULL];
            } else {
              [[NSFileManager defaultManager] removeItemAtPath:tmpPath error:NULL];
            }
            [[NSFileManager defaultManager] removeItemAtPath:micRawPath error:NULL];
            [[NSFileManager defaultManager] removeItemAtPath:micNRPath error:NULL];
            [[NSFileManager defaultManager] removeItemAtPath:mixedPath error:NULL];
            if (completion) completion(remuxOK);
          });
        }];
      }];
    }];
  }];
}

- (void)applyMicGainToFile:(NSString *)path gainDB:(NSInteger)gainDB completion:(void (^)(BOOL ok))completion {
  if (![[NSFileManager defaultManager] fileExistsAtPath:path]) { if (completion) completion(NO); return; }
  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:path] options:nil];
  AVAssetTrack *video = [asset tracksWithMediaType:AVMediaTypeVideo].firstObject;
  NSArray *audios = [asset tracksWithMediaType:AVMediaTypeAudio];
  if (!video || !audios.count || (audios.count == 1 && gainDB == 0)) { if (completion) completion(YES); return; }
  if ([self noiseReductionLevel] > 0 && audios.count >= 2) {
    [self applyNoiseReductionToFile:path gainDB:gainDB completion:completion];
    return;
  }

  // Step 1: mix audio tracks (and apply mic gain) into a temporary audio-only file.
  AVMutableComposition *audioComp = [AVMutableComposition composition];
  NSMutableArray<AVMutableCompositionTrack *> *audioTracks = [NSMutableArray array];
  for (NSInteger i = 0; i < (NSInteger)audios.count && i < 2; i++) {
    AVMutableCompositionTrack *at = [audioComp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
    [at insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:audios[i] atTime:kCMTimeZero error:NULL];
    [audioTracks addObject:at];
  }
  NSInteger micIndex = [self micTrackIndexForAudioTracks:audios];
  AVMutableAudioMix *mix = [AVMutableAudioMix audioMix];
  NSMutableArray *params = [NSMutableArray array];
  for (NSInteger i = 0; i < (NSInteger)audioTracks.count; i++) {
    AVMutableAudioMixInputParameters *ap = [AVMutableAudioMixInputParameters audioMixInputParametersWithTrack:audioTracks[i]];
    float vol = (i == micIndex) ? pow(10.0, gainDB / 20.0) : 1.0f;
    [ap setVolume:vol atTime:kCMTimeZero];
    [params addObject:ap];
  }
  mix.inputParameters = params;
  NSString *mixedAudio = [[path stringByDeletingPathExtension] stringByAppendingString:@"-audio.m4a"];
  [[NSFileManager defaultManager] removeItemAtPath:mixedAudio error:NULL];
  AVAssetExportSession *audioEx = [[AVAssetExportSession alloc] initWithAsset:audioComp presetName:AVAssetExportPresetAppleM4A];
  audioEx.audioMix = mix;
  audioEx.outputURL = [NSURL fileURLWithPath:mixedAudio];
  audioEx.outputFileType = AVFileTypeAppleM4A;
  __weak typeof(self) weakSelf = self;
  [audioEx exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      NSDictionary *aAttrs = [[NSFileManager defaultManager] attributesOfItemAtPath:mixedAudio error:NULL];
      BOOL audioOK = (audioEx.status == AVAssetExportSessionStatusCompleted) || (aAttrs && [aAttrs[NSFileSize] longLongValue] > 0);
      if (!audioOK) { [[NSFileManager defaultManager] removeItemAtPath:mixedAudio error:NULL]; if (completion) completion(NO); return; }
      // Step 2: remux the original video (passthrough) with the mixed audio, avoiding video re-encode.
      AVURLAsset *mixedAsset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:mixedAudio] options:nil];
      AVAssetTrack *mixedAudioTrack = [mixedAsset tracksWithMediaType:AVMediaTypeAudio].firstObject;
      if (!mixedAudioTrack) { [[NSFileManager defaultManager] removeItemAtPath:mixedAudio error:NULL]; if (completion) completion(NO); return; }
      AVMutableComposition *comp = [AVMutableComposition composition];
      AVMutableCompositionTrack *v = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
      [v insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:video atTime:kCMTimeZero error:NULL];
      AVMutableCompositionTrack *a = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
      [a insertTimeRange:CMTimeRangeMake(kCMTimeZero, CMTimeMinimum(mixedAsset.duration, asset.duration)) ofTrack:mixedAudioTrack atTime:kCMTimeZero error:NULL];
      NSString *tmp = [[path stringByDeletingPathExtension] stringByAppendingString:@"-remux.mp4"];
      [[NSFileManager defaultManager] removeItemAtPath:tmp error:NULL];
      AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPresetPassthrough];
      ex.outputURL = [NSURL fileURLWithPath:tmp];
      ex.outputFileType = AVFileTypeMPEG4;
      ex.shouldOptimizeForNetworkUse = YES;
      [ex exportAsynchronouslyWithCompletionHandler:^{
        dispatch_async(dispatch_get_main_queue(), ^{
          NSDictionary *attrs = [[NSFileManager defaultManager] attributesOfItemAtPath:tmp error:NULL];
          BOOL ok = (ex.status == AVAssetExportSessionStatusCompleted) || (attrs && [attrs[NSFileSize] longLongValue] > 0);
          if (ok) {
            [[NSFileManager defaultManager] removeItemAtPath:path error:NULL];
            [[NSFileManager defaultManager] moveItemAtPath:tmp toPath:path error:NULL];
          } else {
            [[NSFileManager defaultManager] removeItemAtPath:tmp error:NULL];
          }
          [[NSFileManager defaultManager] removeItemAtPath:mixedAudio error:NULL];
          if (completion) completion(ok);
        });
      }];
    });
  }];
}

- (void)videoPostStatusText:(NSString *)text {
  dispatch_async(dispatch_get_main_queue(), ^{ if (self.videoPostStatus) self.videoPostStatus.stringValue = text ?: @""; });
}

- (BOOL)windowSnapEnabled {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  return [ud objectForKey:@"centerWindowSnapEnabled"] ? [ud boolForKey:@"centerWindowSnapEnabled"] : NO;
}

- (void)startWindowSnapMonitor {
  if (self.windowSnapMonitor) { [NSEvent removeMonitor:self.windowSnapMonitor]; self.windowSnapMonitor = nil; }
  if (![self windowSnapEnabled]) return;
  __weak typeof(self) weakSelf = self;
  self.windowSnapMonitor = [NSEvent addGlobalMonitorForEventsMatchingMask:NSEventMaskLeftMouseUp handler:^(NSEvent *e) {
    [weakSelf handleWindowSnapMouseUp];
  }];
}

- (void)toggleWindowSnap:(id)sender {
  BOOL enabled = ![self windowSnapEnabled];
  [[NSUserDefaults standardUserDefaults] setBool:enabled forKey:@"centerWindowSnapEnabled"];
  [[NSUserDefaults standardUserDefaults] synchronize];
  [self startWindowSnapMonitor];
  [self showToast:enabled ? @"已开启窗口拖拽吸附" : @"已关闭窗口拖拽吸附"];
}

- (void)handleWindowSnapMouseUp {
  if (![self windowSnapEnabled] || !AXIsProcessTrusted()) return;
  NSPoint mouse = [NSEvent mouseLocation];
  NSScreen *screen = nil;
  for (NSScreen *s in [NSScreen screens]) if (NSPointInRect(mouse, s.frame)) { screen = s; break; }
  if (!screen) return;
  NSRect vis = screen.visibleFrame;
  CGFloat threshold = 24;
  NSInteger edge = 0;
  if (mouse.x <= NSMinX(vis) + threshold) edge = 1;
  else if (mouse.x >= NSMaxX(vis) - threshold) edge = 2;
  else if (mouse.y >= NSMaxY(vis) - threshold) edge = 3;
  else return;
  AXUIElementRef system = AXUIElementCreateSystemWide();
  CFTypeRef appRaw = NULL;
  AXUIElementRef app = NULL;
  if (AXUIElementCopyAttributeValue(system, kAXFocusedApplicationAttribute, &appRaw) == kAXErrorSuccess && appRaw) app = (AXUIElementRef)CFRetain(appRaw);
  if (appRaw) CFRelease(appRaw);
  CFRelease(system);
  if (!app) return;
  pid_t pid = 0; AXUIElementGetPid(app, &pid);
  if (pid == [[NSProcessInfo processInfo] processIdentifier]) { CFRelease(app); return; }
  CFTypeRef winRaw = NULL;
  AXUIElementRef win = NULL;
  if (AXUIElementCopyAttributeValue(app, kAXFocusedWindowAttribute, &winRaw) == kAXErrorSuccess && winRaw) win = (AXUIElementRef)CFRetain(winRaw);
  if (winRaw) CFRelease(winRaw);
  CFRelease(app);
  if (!win) return;
  NSRect target = vis;
  if (edge == 1) target = NSMakeRect(vis.origin.x, vis.origin.y, vis.size.width/2.0 - 4, vis.size.height);
  else if (edge == 2) target = NSMakeRect(NSMidX(vis)+4, vis.origin.y, vis.size.width/2.0 - 4, vis.size.height);
  else if (edge == 3) target = vis;
  CGFloat screenH = screen.frame.size.height;
  CGPoint p = CGPointMake(target.origin.x, screenH - (target.origin.y + target.size.height));
  CGSize z = CGSizeMake(target.size.width, target.size.height);
  AXValueRef pv = AXValueCreate(kAXValueCGPointType, &p);
  AXValueRef zv = AXValueCreate(kAXValueCGSizeType, &z);
  AXUIElementSetAttributeValue(win, kAXPositionAttribute, pv);
  AXUIElementSetAttributeValue(win, kAXSizeAttribute, zv);
  if (pv) CFRelease(pv); if (zv) CFRelease(zv);
  CFRelease(win);
}

- (void)aiAssistantApplyEndpointDefaults:(NSDictionary *)entry {
  NSString *savedBase = entry[@"apiBase"] ?: @"";
  NSString *savedModel = entry[@"model"] ?: @"";
  if (savedBase.length) {
    NSString *url = [savedBase hasSuffix:@"/chat/completions"] ? savedBase : [savedBase stringByAppendingString:@"/chat/completions"];
    self.aiAssistantURLField.stringValue = url;
  }
  if (savedModel.length) self.aiAssistantModelField.stringValue = savedModel;
  if (savedBase.length && savedModel.length) return;
  NSString *name = [entry[@"name"] ?: @"" lowercaseString];
  NSString *url = @"", *model = @"";
  if ([name containsString:@"deepseek"]) { url = @"https://api.deepseek.com/v1/chat/completions"; model = @"deepseek-chat"; }
  else if ([name containsString:@"kimi"] || [name containsString:@"moonshot"]) { url = @"https://api.moonshot.cn/v1/chat/completions"; model = @"moonshot-v1-8k"; }
  else if ([name containsString:@"openrouter"]) { url = @"https://openrouter.ai/api/v1/chat/completions"; model = @"openai/gpt-4o-mini"; }
  else if ([name containsString:@"siliconflow"] || [name containsString:@"硅基流动"]) { url = @"https://api.siliconflow.cn/v1/chat/completions"; model = @"Qwen/Qwen2.5-7B-Instruct"; }
  else if ([name containsString:@"openai"] || [name containsString:@"gpt"]) { url = @"https://api.openai.com/v1/chat/completions"; model = @"gpt-4o-mini"; }
  if (url.length) { self.aiAssistantURLField.stringValue = url; self.aiAssistantModelField.stringValue = model; }
}

- (void)reloadAIAssistantServices {
  [self.aiAssistantServicePopup removeAllItems];
  if (!self.aiEntries) [self loadAIEntries];
  [self hydrateAIKeys];
  for (NSInteger i=0;i<(NSInteger)self.aiEntries.count;i++) {
    NSDictionary *e = self.aiEntries[i];
    if (![[self aiModelCategoryKey:e] isEqualToString:@"text"]) continue;
    [self.aiAssistantServicePopup addItemWithTitle:e[@"name"] ?: @"未命名"];
    self.aiAssistantServicePopup.lastItem.representedObject = @(i);
  }
  if (!self.aiAssistantServicePopup.numberOfItems) {
    [self.aiAssistantServicePopup addItemWithTitle:@"请先在 AI 管理设置文本模型"];
    self.aiAssistantServicePopup.enabled = NO;
    self.aiAssistantStatus.stringValue = @"没有文本模型，请到 AI 管理把某个服务分类设为「文本」";
  } else {
    self.aiAssistantServicePopup.enabled = YES;
    [self.aiAssistantServicePopup selectItemAtIndex:0]; [self aiAssistantServiceChanged:nil];
  }
}

- (void)fetchAIModelsForAssistant:(id)sender {
  NSInteger idx = [self.aiAssistantServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)self.aiEntries.count) return;
  NSDictionary *e = self.aiEntries[idx];
  NSString *key = e[@"api"] ?: @"";
  NSString *base = self.aiAssistantURLField.stringValue ?: @"";
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length - @"/chat/completions".length];
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length - 1];
  if (!base.length || !key.length) { self.aiAssistantStatus.stringValue = @"需要 API 基础地址和 Key 才能获取模型"; return; }
  self.aiAssistantStatus.stringValue = @"正在获取模型列表…";
  NSURL *url = [NSURL URLWithString:[base stringByAppendingString:@"/models"]];
  if (!url) { self.aiAssistantStatus.stringValue = @"API 地址无效"; return; }
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:url];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.timeoutInterval = 20;
  __weak typeof(self) weakSelf = self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    NSMutableArray *models = [NSMutableArray array];
    if (data.length) {
      id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
      id list = [obj isKindOfClass:[NSDictionary class]] ? obj[@"data"] : nil;
      if ([list isKindOfClass:[NSArray class]]) for (id m in list) {
        NSString *mid = [m isKindOfClass:[NSDictionary class]] ? m[@"id"] : nil;
        if (!mid.length) continue;
        NSString *low = mid.lowercaseString;
        if ([low containsString:@"embed"] || [low containsString:@"nomic"] || [low containsString:@"bge"] || [low containsString:@"mxbai"]) continue;
        [models addObject:mid];
      }
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      if (!models.count) { weakSelf.aiAssistantStatus.stringValue = err.localizedDescription ?: @"未获取到模型，可手动输入"; return; }
      [models sortUsingSelector:@selector(localizedStandardCompare:)];
      NSString *current = weakSelf.aiAssistantModelField.stringValue;
      [weakSelf.aiAssistantModelField removeAllItems];
      [weakSelf.aiAssistantModelField addItemsWithObjectValues:models];
      if (current.length && [models containsObject:current]) weakSelf.aiAssistantModelField.stringValue = current;
      else weakSelf.aiAssistantModelField.stringValue = models.firstObject;
      weakSelf.aiAssistantStatus.stringValue = [NSString stringWithFormat:@"已获取 %ld 个模型，可下拉选择", (long)models.count];
    });
  }] resume];
}

- (void)aiAssistantServiceChanged:(id)sender {
  NSInteger idx = [self.aiAssistantServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)self.aiEntries.count) return;
  [self aiAssistantApplyEndpointDefaults:self.aiEntries[idx]];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.35 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{ [self fetchAIModelsForAssistant:nil]; });
}

- (void)reloadAIVideoServices {
  if (!self.aiEntries) [self loadAIEntries];
  [self hydrateAIKeys];
  [self.aiVideoServicePopup removeAllItems];
  for (NSInteger i=0;i<(NSInteger)self.aiEntries.count;i++) {
    NSDictionary *e = self.aiEntries[i];
    if (![[self aiModelCategoryKey:e] isEqualToString:@"video"]) continue;
    [self.aiVideoServicePopup addItemWithTitle:e[@"name"] ?: @"未命名"];
    self.aiVideoServicePopup.lastItem.representedObject = @(i);
  }
  if (!self.aiVideoServicePopup.numberOfItems) {
    [self.aiVideoServicePopup addItemWithTitle:@"请先在 AI 管理设置视频模型"];
    self.aiVideoServicePopup.enabled = NO;
    self.aiVideoStatus.stringValue = @"没有视频模型，请把支持视频的服务分类设为「视频」";
  } else {
    self.aiVideoServicePopup.enabled = YES;
    [self.aiVideoServicePopup selectItemAtIndex:0]; [self aiVideoServiceChanged:nil];
  }
}

- (void)aiVideoServiceChanged:(id)sender {
  NSInteger idx = [self.aiVideoServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)self.aiEntries.count) return;
  NSDictionary *e = self.aiEntries[idx];
  NSString *name = e[@"name"] ?: @"";
  NSString *base = e[@"apiBase"] ?: @"";
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length - @"/chat/completions".length];
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length - 1];
  [self.aiVideoModelField removeAllItems];
  self.aiVideoModelField.stringValue = @"";
  self.aiVideoURLField.stringValue = @"";
  self.aiVideoStatus.stringValue = @"";
  BOOL capable = [[self aiModelCategoryKey:e] isEqualToString:@"video"] || [self aiServiceSupportsVideo:name];
  BOOL saved = [(NSString *)(e[@"videoAPI"] ?: @"") length] > 0;
  if (!capable && !saved) {
    self.aiVideoStatus.stringValue = @"该 AI 服务只支持文本，暂无视频生成接口";
    return;
  }
  NSString *defaultURL = @"", *defaultModel = @"";
  if ([self aiServiceName:name containsAny:@[@"豆包",@"方舟",@"volcengine",@"doubao",@"seedance"]]) {
    if (!base.length) base = @"https://ark.cn-beijing.volces.com/api/v3";
    defaultURL = [base stringByAppendingString:@"/contents/generations/tasks"];
    defaultModel = @"doubao-seedance-1-0-pro-250528";
  } else if ([self aiServiceName:name containsAny:@[@"siliconflow",@"硅基流动"]] || [base containsString:@"siliconflow"]) {
    defaultURL = [base stringByAppendingString:@"/video/submit"];
    defaultModel = @"Wan-AI/Wan2.2-T2V-A14B";
  } else if (base.length) {
    defaultURL = [base stringByAppendingString:@"/videos/generations"];
  }
  if (((NSString *)e[@"videoAPI"]).length) defaultURL = e[@"videoAPI"];
  if (((NSString *)e[@"videoModel"]).length) defaultModel = e[@"videoModel"];
  else if (((NSString *)e[@"model"]).length) defaultModel = e[@"model"];
  self.aiVideoURLField.stringValue = defaultURL;
  [self.aiVideoModelField removeAllItems];
  if (defaultModel.length) [self.aiVideoModelField addItemWithObjectValue:defaultModel];
  self.aiVideoModelField.stringValue = defaultModel;
  if (!defaultURL.length) { self.aiVideoStatus.stringValue = @"该服务没有可用的视频生成地址"; return; }
  NSString *key = e[@"api"] ?: @"";
  if (!key.length) { self.aiVideoStatus.stringValue = @"缺少 API Key，无法自动获取视频模型"; return; }
  self.aiVideoStatus.stringValue = @"正在获取视频模型…";
  __weak typeof(self) weakSelf = self;
  NSString *modelListURL = ([self aiServiceName:name containsAny:@[@"siliconflow",@"硅基流动"]] || [base containsString:@"siliconflow"]) ? base : defaultURL;
  [self fetchModelsForPanel:self.aiVideoModelField url:modelListURL key:key keywords:@[@"sora",@"seedance",@"veo",@"kling",@"runway",@"luma",@"video",@"minimax",@"hailuo",@"wan"] knownDefault:defaultModel completion:^(NSArray *models) {
    if (models.count) { weakSelf.aiVideoStatus.stringValue = [NSString stringWithFormat:@"已获取 %ld 个视频模型", (long)models.count]; }
    else { weakSelf.aiVideoStatus.stringValue = defaultModel.length ? @"未获取到视频模型，使用默认模型" : @"未获取到视频模型，请手动填写"; }
  }];
}


