- (void)reloadAIFileServices {
  if(!self.aiEntries)[self loadAIEntries];
  [self.aiFileServicePopup removeAllItems];
  [self.aiFileServicePopup addItemWithTitle:@"本地 Ollama"]; self.aiFileServicePopup.lastItem.representedObject=@(-1);
  for(NSInteger i=0;i<(NSInteger)self.aiEntries.count;i++){
    NSDictionary *e=self.aiEntries[i];
    if([e[@"localOnly"] boolValue])continue;
    if([(NSString *)(e[@"name"] ?: @"") containsString:@"Ollama 本地"])continue;
    if(![[self aiModelCategoryKey:e] isEqualToString:@"text"])continue;
    [self.aiFileServicePopup addItemWithTitle:e[@"name"] ?: @"未命名"]; self.aiFileServicePopup.lastItem.representedObject=@(i);
  }
  [self.aiFileServicePopup selectItemAtIndex:0];
  [self aiFileServiceChanged:nil];
}

- (void)fetchAIFileModelsForEntry:(NSDictionary *)e defaultModel:(NSString *)model fallback:(NSString *)fallback {
  NSString *base=e[@"apiBase"] ?: @""; NSString *key=e[@"api"] ?: @"";
  if([base hasSuffix:@"/chat/completions"])base=[base substringToIndex:base.length-17];
  while([base hasSuffix:@"/"])base=[base substringToIndex:base.length-1];
  if(!base.length||!key.length){[self.aiFileModelField addItemWithObjectValue:model];self.aiFileModelField.stringValue=model;return;}
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:[base stringByAppendingString:@"/models"]]];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"]; req.timeoutInterval=15;
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *d,NSURLResponse *r,NSError *err){
    id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil; NSArray *list=[o isKindOfClass:[NSDictionary class]]?o[@"data"]:nil;
    NSMutableArray *models=[NSMutableArray array];
    for(NSDictionary *x in list){NSString *mid=x[@"id"];if(!mid.length)continue;NSString *low=mid.lowercaseString;if([low containsString:@"embed"]||[low containsString:@"nomic"]||[low containsString:@"bge"]||[low containsString:@"mxbai"])continue;[models addObject:mid];}
    dispatch_async(dispatch_get_main_queue(),^{
      if(models.count){
        [weakSelf.aiFileModelField removeAllItems];
        for(NSString *m in models)[weakSelf.aiFileModelField addItemWithObjectValue:m];
        weakSelf.aiFileModelField.stringValue=[models containsObject:model]?model:models.firstObject;
      } else {[weakSelf.aiFileModelField addItemWithObjectValue:model];weakSelf.aiFileModelField.stringValue=model;}
      (void)fallback;
    });
  }] resume];
}

- (void)aiFileServiceChanged:(id)sender {
  NSInteger idx=[self.aiFileServicePopup.selectedItem.representedObject integerValue];
  [self.aiFileModelField removeAllItems];
  NSString *model=@"qwen2.5:3b";
  if(idx<0){
    NSString *out=[self runLocalTool:@"/opt/homebrew/bin/ollama" args:@[@"list"]];
    NSMutableArray *names=[NSMutableArray array];
    for(NSString *line in [out componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]){
      NSString *t=[line stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet];
      if(!t.length||[t hasPrefix:@"NAME "])continue;
      NSString *n=[t componentsSeparatedByCharactersInSet:NSCharacterSet.whitespaceCharacterSet].firstObject;
      if(n.length && ![n containsString:@"nomic-embed"])[names addObject:n];
    }
    if(!names.count)[names addObject:model];
    for(NSString *n in names)[self.aiFileModelField addItemWithObjectValue:n];
    self.aiFileModelField.stringValue=[names containsObject:model]?model:names.firstObject;
    return;
  }
  if(idx>=0 && idx<(NSInteger)self.aiEntries.count){
    NSDictionary *e=self.aiEntries[idx];model=e[@"model"] ?: @"qwen2.5:3b";
    [self.aiFileModelField addItemWithObjectValue:model]; self.aiFileModelField.stringValue=model;
    [self fetchAIFileModelsForEntry:e defaultModel:model fallback:model];
    return;
  }
}

- (NSString *)aiFileOCRImage:(NSString *)path {
  NSImage *img=[[NSImage alloc] initWithContentsOfFile:path]; if(!img)return @"";
  CGImageRef cg=[img CGImageForProposedRect:NULL context:nil hints:nil]; if(!cg)return @"";
  __block NSString *result=@"";
  dispatch_semaphore_t sem=dispatch_semaphore_create(0);
  VNRecognizeTextRequest *req=[[VNRecognizeTextRequest alloc] initWithCompletionHandler:^(VNRequest *request,NSError *error){
    NSMutableArray *lines=[NSMutableArray array];
    for(VNRecognizedTextObservation *obs in request.results){VNRecognizedText *top=[obs topCandidates:1].firstObject;if(top.string.length)[lines addObject:top.string];}
    result=[lines componentsJoinedByString:@"\n"]; dispatch_semaphore_signal(sem);
  }];
  req.recognitionLevel=VNRequestTextRecognitionLevelAccurate; req.usesLanguageCorrection=YES;
  req.recognitionLanguages=@[@"zh-Hans",@"zh-Hant",@"en-US"];
  VNImageRequestHandler *handler=[[VNImageRequestHandler alloc] initWithCGImage:cg options:@{}];
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{[handler performRequests:@[req] error:NULL];});
  dispatch_semaphore_wait(sem,dispatch_time(DISPATCH_TIME_NOW,(int64_t)(12*NSEC_PER_SEC)));
  return result ?: @"";
}

- (NSData *)aiFileUnzipEntry:(NSString *)path entry:(NSString *)entry {
  NSTask *t=[[NSTask alloc] init]; t.launchPath=@"/usr/bin/unzip"; t.arguments=@[@"-p",path,entry];
  NSPipe *pipe=[NSPipe pipe]; t.standardOutput=pipe; t.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[t launch];}@catch(NSException *e){return nil;}
  NSData *d=[pipe.fileHandleForReading readDataToEndOfFile]; [t waitUntilExit];
  return d;
}

- (NSString *)aiFileExtractXLSX:(NSString *)path {
  NSData *ssData=[self aiFileUnzipEntry:path entry:@"xl/sharedStrings.xml"];
  NSMutableArray *shared=[NSMutableArray array];
  if(ssData.length){
    NSXMLDocument *doc=[[NSXMLDocument alloc] initWithData:ssData options:0 error:NULL];
    NSArray *nodes=[doc nodesForXPath:@"//*[local-name()='si']" error:NULL] ?: @[];
    for(NSXMLElement *si in nodes){
      NSMutableString *v=[NSMutableString string];
      for(NSXMLElement *t in [si nodesForXPath:@".//*[local-name()='t']" error:NULL] ?: @[]) if(t.stringValue)[v appendString:t.stringValue];
      [shared addObject:v];
    }
  }
  NSData *listData=[self aiFileUnzipEntry:path entry:@"xl/worksheets"];
  NSMutableArray *sheetNames=[NSMutableArray array];
  NSString *list=[[NSString alloc] initWithData:listData encoding:NSUTF8StringEncoding];
  if(!list.length){
    NSTask *t=[[NSTask alloc] init]; t.launchPath=@"/usr/bin/unzip"; t.arguments=@[@"-Z1",path];
    NSPipe *pipe=[NSPipe pipe]; t.standardOutput=pipe; t.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[t launch];}@catch(NSException *e){}
    NSData *d=[pipe.fileHandleForReading readDataToEndOfFile]; [t waitUntilExit];
    NSString *all=[[NSString alloc] initWithData:d encoding:NSUTF8StringEncoding] ?: @"";
    for(NSString *line in [all componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]) if([line hasPrefix:@"xl/worksheets/sheet"]&&[line hasSuffix:@".xml"])[sheetNames addObject:line];
  }
  NSMutableString *out=[NSMutableString string];
  for(NSString *entry in sheetNames){
    NSData *d=[self aiFileUnzipEntry:path entry:entry]; if(!d.length)continue;
    NSXMLDocument *doc=[[NSXMLDocument alloc] initWithData:d options:0 error:NULL];
    [out appendFormat:@"\n===== 工作表：%@ =====\n",entry.lastPathComponent.stringByDeletingPathExtension];
    NSArray *rows=[doc nodesForXPath:@"//*[local-name()='row']" error:NULL] ?: @[];
    for(NSXMLElement *row in rows){
      NSMutableArray *vals=[NSMutableArray array];
      for(NSXMLElement *c in [row nodesForXPath:@"./*[local-name()='c']" error:NULL] ?: @[]){
        NSString *type=[[c attributeForName:@"t"] stringValue] ?: @"";
        NSString *v=[[c nodesForXPath:@"./*[local-name()='v']" error:NULL].firstObject stringValue] ?: @"";
        if([type isEqualToString:@"s"]){NSInteger idx=v.integerValue;if(idx>=0&&idx<(NSInteger)shared.count)v=shared[idx];}
        else if([type isEqualToString:@"inlineStr"]){NSXMLElement *is=[c nodesForXPath:@"./*[local-name()='is']" error:NULL].firstObject;v=is.stringValue ?: @"";}
        [vals addObject:v.length?v:@""];
      }
      if(vals.count)[out appendString:[vals componentsJoinedByString:@"\t"]]; [out appendString:@"\n"];
    }
  }
  return out;
}

- (NSString *)aiFileTranscribeMedia:(NSString *)path {
  NSString *exe=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerWhisperExe"] ?: @"/opt/homebrew/bin/whisper-cli";
  NSString *model=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerWhisperModel"] ?: @"";
  if(!model.length)model=[NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers/Models/ggml-base.bin"];
  if(![[NSFileManager defaultManager] isExecutableFileAtPath:exe] || ![[NSFileManager defaultManager] isReadableFileAtPath:model]) return @"";
  NSString *tmp=[NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"dl-aifile-%@",[[NSUUID UUID] UUIDString]]];
  [[NSFileManager defaultManager] createDirectoryAtPath:tmp withIntermediateDirectories:YES attributes:nil error:NULL];
  NSString *wav=[tmp stringByAppendingPathComponent:@"audio.wav"];
  NSString *ext=path.pathExtension.lowercaseString;
  if(![ext isEqualToString:@"wav"]){
    NSTask *a=[[NSTask alloc] init]; a.launchPath=@"/usr/bin/afconvert";
    a.arguments=@[@"-f",@"WAVE",@"-d",@"LEI16@16000",@"-c",@"1",path,wav];
    a.standardOutput=[NSFileHandle fileHandleWithNullDevice]; a.standardError=[NSFileHandle fileHandleWithNullDevice];
    @try{[a launch];[a waitUntilExit];}@catch(NSException *e){return @"";}
    if(![[NSFileManager defaultManager] fileExistsAtPath:wav])return @"";
  } else wav=path;
  NSString *prefix=[tmp stringByAppendingPathComponent:@"out"];
  NSTask *w=[[NSTask alloc] init]; w.launchPath=exe;
  w.arguments=@[@"-m",model,@"-f",wav,@"-l",@"zh",@"-otxt",@"-of",prefix];
  w.standardOutput=[NSFileHandle fileHandleWithNullDevice]; w.standardError=[NSFileHandle fileHandleWithNullDevice];
  @try{[w launch];[w waitUntilExit];}@catch(NSException *e){return @"";}
  NSString *out=[NSString stringWithContentsOfFile:[prefix stringByAppendingPathExtension:@"txt"] encoding:NSUTF8StringEncoding error:NULL] ?: @"";
  [[NSFileManager defaultManager] removeItemAtPath:tmp error:NULL];
  return [out stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
}

- (void)aiFilePDFRangeSettings:(id)sender {
  NSUserDefaults *ud=[NSUserDefaults standardUserDefaults];
  NSInteger start=[ud integerForKey:@"centerAIFilePDFStart"]; if(start<1)start=1;
  NSInteger end=[ud integerForKey:@"centerAIFilePDFEnd"]; if(end<1)end=12;
  NSAlert *a=[[NSAlert alloc] init]; a.messageText=@"扫描 PDF OCR 页码范围";
  NSTextField *sf=[[NSTextField alloc] initWithFrame:NSMakeRect(0,0,80,24)]; sf.integerValue=start;
  NSTextField *ef=[[NSTextField alloc] initWithFrame:NSMakeRect(100,0,80,24)]; ef.integerValue=end;
  NSView *av=[[NSView alloc] initWithFrame:NSMakeRect(0,0,200,24)]; [av addSubview:sf]; [av addSubview:ef]; a.accessoryView=av;
  a.informativeText=@"起始页 / 结束页；仅对没有文本层的扫描 PDF 生效";
  [a addButtonWithTitle:@"保存"]; [a addButtonWithTitle:@"导出页…"]; [a addButtonWithTitle:@"取消"];
  NSModalResponse resp=[a runModal];
  if(resp==NSAlertThirdButtonReturn)return;
  [ud setInteger:MAX(1,sf.integerValue) forKey:@"centerAIFilePDFStart"];
  [ud setInteger:MAX(1,ef.integerValue) forKey:@"centerAIFilePDFEnd"];
  self.aiFileStatus.stringValue=[NSString stringWithFormat:@"PDF 范围：%ld–%ld 页",(long)sf.integerValue,(long)ef.integerValue];
  if(resp==NSAlertSecondButtonReturn)[self aiFileExportPDFPages:nil start:sf.integerValue end:ef.integerValue];
}

- (void)aiFileExportPDFPages:(id)sender start:(NSInteger)start end:(NSInteger)end {
  NSString *pdf=nil; for(NSString *p in self.aiFiles)if([p.pathExtension.lowercaseString isEqualToString:@"pdf"]){pdf=p;break;}
  if(!pdf){NSOpenPanel *op=[NSOpenPanel openPanel];op.canChooseFiles=YES;op.allowedFileTypes=@[@"pdf"];if([op runModal]!=NSModalResponseOK)return;pdf=op.URL.path;}
  PDFDocument *doc=[[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:pdf]]; if(!doc){[self showToast:@"PDF 读取失败"];return;}
  start=MAX(1,MIN(start,(NSInteger)doc.pageCount)); end=MAX(start,MIN(end,(NSInteger)doc.pageCount));
  NSOpenPanel *dir=[NSOpenPanel openPanel]; dir.canChooseFiles=NO; dir.canChooseDirectories=YES; dir.prompt=@"选择导出目录"; if([dir runModal]!=NSModalResponseOK)return;
  NSString *base=pdf.lastPathComponent.stringByDeletingPathExtension;
  NSInteger count=0;
  for(NSInteger i=start-1;i<end;i++){
    PDFPage *page=[doc pageAtIndex:i]; if(!page)continue;
    NSImage *img=[page thumbnailOfSize:NSMakeSize(1600,2200) forBox:kPDFDisplayBoxMediaBox]; if(!img)continue;
    NSBitmapImageRep *rep=[NSBitmapImageRep imageRepWithData:[img TIFFRepresentation]]; NSData *png=[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    NSString *file=[dir.URL.path stringByAppendingPathComponent:[NSString stringWithFormat:@"%@-第%ld页.png",base,(long)(i+1)]];
    if([png writeToFile:file atomically:YES])count++;
  }
  self.aiFileStatus.stringValue=[NSString stringWithFormat:@"已导出 %ld 页",(long)count];
}

- (NSString *)aiFileOCRPDF:(NSString *)path {
  PDFDocument *doc=[[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:path]]; if(!doc)return @"";
  NSMutableString *out=[NSMutableString string];
  NSInteger start=[[NSUserDefaults standardUserDefaults] integerForKey:@"centerAIFilePDFStart"]; if(start<1)start=1;
  NSInteger end=[[NSUserDefaults standardUserDefaults] integerForKey:@"centerAIFilePDFEnd"]; if(end<1)end=12;
  start=MAX(1,MIN(start,(NSInteger)doc.pageCount)); end=MAX(start,MIN(end,(NSInteger)doc.pageCount));
  for(NSInteger i=start-1;i<end;i++){
    PDFPage *page=[doc pageAtIndex:i]; if(!page)continue;
    NSImage *img=[page thumbnailOfSize:NSMakeSize(1600,2200) forBox:kPDFDisplayBoxMediaBox]; if(!img)continue;
    NSData *tiff=[img TIFFRepresentation]; NSBitmapImageRep *rep=[NSBitmapImageRep imageRepWithData:tiff]; NSData *png=[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    NSString *tmp=[NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"dl-pdf-ocr-%ld.png",(long)i]];
    [png writeToFile:tmp atomically:YES];
    NSString *t=[self aiFileOCRImage:tmp]; [[NSFileManager defaultManager] removeItemAtPath:tmp error:NULL];
    if(t.length)[out appendFormat:@"\n=== 第 %ld 页 ===\n%@",(long)(i+1),t];
  }
  return out;
}

- (NSString *)aiFileExtractText:(NSString *)path {
  NSString *ext=path.pathExtension.lowercaseString;
  if([ext isEqualToString:@"pdf"]){
    PDFDocument *doc=[[PDFDocument alloc] initWithURL:[NSURL fileURLWithPath:path]];
    NSString *t=doc.string ?: @"";
    if(t.length>40)return t;
    return [self aiFileOCRPDF:path];
  }
  if([@[@"doc",@"docx",@"rtf",@"rtfd",@"html",@"htm",@"odt"] containsObject:ext]) return DLTextutilToText(path) ?: @"";
  if([@[@"txt",@"md",@"markdown",@"csv",@"tsv",@"json",@"xml",@"yaml",@"yml",@"log",@"swift",@"m",@"h",@"py",@"js",@"ts",@"css"] containsObject:ext]){
    NSString *t=[NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:NULL];
    if(!t.length)t=[NSString stringWithContentsOfFile:path encoding:NSISOLatin1StringEncoding error:NULL];
    return t ?: @"";
  }
  if([@[@"wav",@"mp3",@"m4a",@"aac",@"flac",@"ogg",@"aiff",@"aif",@"mp4",@"mov",@"m4v"] containsObject:ext]) return [self aiFileTranscribeMedia:path];
  if([ext isEqualToString:@"xlsx"]) return [self aiFileExtractXLSX:path] ?: @"";
  if([ext isEqualToString:@"xls"]) return @"旧版 Excel .xls 暂不支持，请另存为 .xlsx 后导入";
  if([@[@"png",@"jpg",@"jpeg",@"heic",@"heif",@"tiff",@"tif",@"bmp",@"webp"] containsObject:ext]) return [self aiFileOCRImage:path];
  return @"";
}

