}

- (void)aiFileAPICall:(NSString *)prompt model:(NSString *)model url:(NSString *)url key:(NSString *)key completion:(void (^)(NSString *answer, NSString *error))completion {
  NSDictionary *body=@{@"model":model ?: @"qwen2.5:3b",@"messages":@[@{@"role":@"user",@"content":prompt ?: @""}],@"temperature":@0.3,@"max_tokens":@1800};
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod=@"POST"; [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  if(key.length)[req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:NULL]; req.timeoutInterval=240;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *d,NSURLResponse *r,NSError *err){
    id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
    NSString *answer=nil;
    if([o isKindOfClass:[NSDictionary class]]){id c=o[@"choices"];if([c isKindOfClass:[NSArray class]]&&[c count]){id m=c[0][@"message"];if([m isKindOfClass:[NSDictionary class]])answer=m[@"content"];}}
    dispatch_async(dispatch_get_main_queue(),^{ completion(answer,err.localizedDescription); });
  }] resume];
}

- (void)aiFileCancelAnalysis:(id)sender {
  self.aiFileAnalysisToken++;
  self.aiFileStatus.stringValue=@"已取消分析";
  self.aiFileOutput.string=@"分析已取消。";
}

- (void)aiFileSaveReport:(NSString *)answer files:(NSArray *)files {
  NSDateFormatter *df=[[NSDateFormatter alloc] init]; df.dateFormat=@"yyyyMMdd-HHmmss";
  NSString *name=[NSString stringWithFormat:@"AI文件分析-%@.md",[df stringFromDate:[NSDate date]]];
  NSString *desktop=[NSHomeDirectory() stringByAppendingPathComponent:@"Desktop"];
  NSString *configured=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerAIFileOutputDirectory"] ?: @"";
  NSString *dir=(configured.length && [[NSFileManager defaultManager] fileExistsAtPath:configured])?configured:([[NSFileManager defaultManager] fileExistsAtPath:desktop]?desktop:[NSHomeDirectory() stringByAppendingPathComponent:@"Library/Application Support/DockLaunchers/AI文件"]);
  [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
  NSString *path=[dir stringByAppendingPathComponent:name];
  NSString *md=[NSString stringWithFormat:@"# AI 文件分析\n\n生成时间：%@\n\n## 文件列表\n\n%@\n\n## AI 分析\n\n%@\n",[NSDate date],files.count?[NSString stringWithFormat:@"- %@",[files componentsJoinedByString:@"\n- "]]:@"- 无",answer ?: @""];
  [md writeToFile:path atomically:YES encoding:NSUTF8StringEncoding error:NULL];
  self.aiFileResultPath=path; self.aiFileOutput.string=md; self.aiFileStatus.stringValue=[NSString stringWithFormat:@"已生成：%@",path];
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:path]];
}

- (void)aiFileAddPaths:(NSArray<NSString *> *)paths {
  if(!paths.count)return;
  NSSet *allowed=[NSSet setWithArray:@[@"txt",@"md",@"markdown",@"csv",@"json",@"xml",@"yaml",@"yml",@"log",@"pdf",@"doc",@"docx",@"rtf",@"odt",@"xlsx",@"png",@"jpg",@"jpeg",@"heic",@"tiff",@"webp",@"wav",@"mp3",@"m4a",@"flac",@"mp4",@"mov"]];
  NSMutableArray *files=[NSMutableArray array];
  for(NSString *path in paths){
    BOOL isDir=NO;
    if(![[NSFileManager defaultManager] fileExistsAtPath:path isDirectory:&isDir])continue;
    if(isDir){
      NSDirectoryEnumerator *en=[[NSFileManager defaultManager] enumeratorAtPath:path];
      for(NSString *rel in en){
        if(files.count>=500)break;
        NSString *full=[path stringByAppendingPathComponent:rel];
        BOOL d=NO;[[NSFileManager defaultManager] fileExistsAtPath:full isDirectory:&d];
        if(!d && [allowed containsObject:full.pathExtension.lowercaseString])[files addObject:full];
      }
    } else if([allowed containsObject:path.pathExtension.lowercaseString]) [files addObject:path];
  }
  if(!self.aiFiles)self.aiFiles=[NSMutableArray array];
  NSInteger added=0;
  for(NSString *path in files)if(![self.aiFiles containsObject:path]){[self.aiFiles addObject:path];added++;}
  [self.aiFileTable reloadData];
  self.aiFileStatus.stringValue=added?[NSString stringWithFormat:@"已拖入 %ld 个文件，可开始分析",(long)added]:@"没有可导入的新文件";
}

- (void)aiFileAddFolder:(id)sender {
  NSOpenPanel *p=[NSOpenPanel openPanel]; p.canChooseFiles=NO; p.canChooseDirectories=YES; p.allowsMultipleSelection=NO; p.message=@"选择要加入本地知识库的文件夹";
  if([p runModal]!=NSModalResponseOK)return;
  NSSet *allowed=[NSSet setWithArray:@[@"txt",@"md",@"markdown",@"csv",@"json",@"xml",@"yaml",@"yml",@"log",@"pdf",@"doc",@"docx",@"rtf",@"odt",@"xlsx",@"png",@"jpg",@"jpeg",@"heic",@"tiff",@"webp",@"wav",@"mp3",@"m4a",@"flac",@"mp4",@"mov"]];
  NSMutableArray *paths=[NSMutableArray array];
  NSDirectoryEnumerator *en=[[NSFileManager defaultManager] enumeratorAtPath:p.URL.path];
  for(NSString *rel in en){if(paths.count>=500)break;NSString *full=[p.URL.path stringByAppendingPathComponent:rel];BOOL isDir=NO;[[NSFileManager defaultManager] fileExistsAtPath:full isDirectory:&isDir];if(isDir)continue;if([allowed containsObject:full.pathExtension.lowercaseString])[paths addObject:full];}
  if(!self.aiFiles)self.aiFiles=[NSMutableArray array];
  for(NSString *x in paths)if(![self.aiFiles containsObject:x])[self.aiFiles addObject:x];
  [self.aiFileTable reloadData];
  self.aiFileStatus.stringValue=[NSString stringWithFormat:@"知识库已加入 %ld 个文件",(long)paths.count];
}

- (NSImage *)aiFileChartImage {
  NSArray *vals=self.aiFileChartValues ?: @[];
  NSImage *img=[[NSImage alloc] initWithSize:NSMakeSize(640,400)];
  [img lockFocus];
  [[NSColor whiteColor] setFill]; NSRectFill(NSMakeRect(0,0,640,400));
  [[NSColor darkGrayColor] setStroke];
  NSBezierPath *axis=[NSBezierPath bezierPath]; [axis moveToPoint:NSMakePoint(60,40)]; [axis lineToPoint:NSMakePoint(60,350)]; [axis lineToPoint:NSMakePoint(610,40)]; axis.lineWidth=1.5; [axis stroke];
  double maxV=1; for(NSNumber *n in vals) maxV=MAX(maxV,n.doubleValue);
  NSInteger count=vals.count; CGFloat w=count?500.0/count:0;
  if(self.aiFileChartLine){
    NSBezierPath *line=[NSBezierPath bezierPath];
    for(NSInteger i=0;i<(NSInteger)count;i++){CGFloat x=60+w*(i+0.5);CGFloat y=40+290*([vals[i] doubleValue]/maxV);if(i==0)[line moveToPoint:NSMakePoint(x,y)];else[line lineToPoint:NSMakePoint(x,y)];}
    [[NSColor systemBlueColor] setStroke]; line.lineWidth=2; [line stroke];
  } else {
    for(NSInteger i=0;i<(NSInteger)count;i++){CGFloat x=60+w*i+4;CGFloat h=290*([vals[i] doubleValue]/maxV);[[NSColor systemBlueColor] setFill];NSRectFill(NSMakeRect(x,40,w-8,MAX(1,h)));}
  }
  [[NSColor labelColor] setFill]; NSString *title=self.aiFileChartTitle.length?self.aiFileChartTitle:(self.aiFileChartValues.count?@"数据图表":@"暂无数据"); [title drawAtPoint:NSMakePoint(60,365) withAttributes:@{NSFontAttributeName:[NSFont boldSystemFontOfSize:14],NSForegroundColorAttributeName:[NSColor labelColor]}];
  [img unlockFocus];
  return img;
}

- (void)openAIFileChart:(id)sender {
  NSString *target=nil;
  for(NSString *p in self.aiFiles)if([p.pathExtension.lowercaseString isEqualToString:@"xlsx"]){target=p;break;}
  if(!target){NSOpenPanel *op=[NSOpenPanel openPanel];op.canChooseFiles=YES;op.allowedFileTypes=@[@"xlsx"];if([op runModal]!=NSModalResponseOK)return;target=op.URL.path;}
  NSString *text=[self aiFileExtractXLSX:target]; NSMutableArray *cols=[NSMutableArray array];
  for(NSString *line in [text componentsSeparatedByCharactersInSet:NSCharacterSet.newlineCharacterSet]){
    NSArray *cells=[line componentsSeparatedByString:@"\t"];
    for(NSInteger i=0;i<(NSInteger)cells.count;i++){
      NSString *t=[cells[i] stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceCharacterSet]; NSScanner *sc=[NSScanner scannerWithString:t]; double v=0;
      if([sc scanDouble:&v]&&sc.isAtEnd){while((NSInteger)cols.count<=i)[cols addObject:[NSMutableArray array]];[cols[i] addObject:@(v)];}
    }
  }
  NSMutableArray *columns=[NSMutableArray array];
  for(NSMutableArray *c in cols)if(c.count>=2)[columns addObject:[c copy]];
  if(!columns.count){[self showToast:@"没有找到可绘图的数值列"];return;}
  self.aiFileChartColumns=columns; self.aiFileChartValues=columns.firstObject; self.aiFileChartLine=NO;
  if(!self.aiFileChartWindow){
    self.aiFileChartWindow=[[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,700,500) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable) backing:NSBackingStoreBuffered defer:NO];
    self.aiFileChartWindow.title=@"Excel 图表"; self.aiFileChartWindow.releasedWhenClosed=NO;
    NSView *cv=self.aiFileChartWindow.contentView;
    self.aiFileChartColumnPopup=[[NSPopUpButton alloc] initWithFrame:NSMakeRect(20,76,260,26) pullsDown:NO]; self.aiFileChartColumnPopup.target=self; self.aiFileChartColumnPopup.action=@selector(aiFileChartColumnChanged:); [cv addSubview:self.aiFileChartColumnPopup];
    self.aiFileChartTitleField=[[NSTextField alloc] initWithFrame:NSMakeRect(300,76,380,26)]; self.aiFileChartTitleField.placeholderString=@"图表标题"; self.aiFileChartTitleField.target=self; self.aiFileChartTitleField.action=@selector(aiFileChartTitleChanged:); [cv addSubview:self.aiFileChartTitleField];
    self.aiFileChartImageView=[[NSImageView alloc] initWithFrame:NSMakeRect(20,112,660,368)]; self.aiFileChartImageView.imageScaling=NSImageScaleProportionallyUpOrDown; [cv addSubview:self.aiFileChartImageView];
    NSArray *titles=@[@"柱状图",@"折线图",@"保存 PNG"]; NSArray *sels=@[@"aiFileChartBar:",@"aiFileChartLineMode:",@"aiFileChartSave:"];
    for(NSInteger i=0;i<3;i++){ColorHoverButton *b=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(20+i*120,30,110,30)];b.title=titles[i];b.hoverColor=[NSColor systemTealColor];b.font=[NSFont systemFontOfSize:10];b.target=self;b.action=NSSelectorFromString(sels[i]);[b applyColor:DLButtonBackground() textColor:[NSColor labelColor]];[cv addSubview:b];}
    ColorHoverButton *close=[[ColorHoverButton alloc] initWithFrame:NSMakeRect(600,30,80,30)]; close.title=@"关闭"; close.hoverColor=[NSColor systemGrayColor]; close.target=self; close.action=@selector(closeAIFileChart:); [close applyColor:DLButtonBackground() textColor:[NSColor labelColor]]; [cv addSubview:close];
    [self.aiFileChartWindow center];
  }
  [self.aiFileChartColumnPopup removeAllItems];
  for(NSInteger i=0;i<(NSInteger)self.aiFileChartColumns.count;i++)[self.aiFileChartColumnPopup addItemWithTitle:[NSString stringWithFormat:@"第 %ld 列（%ld 个数值）",(long)(i+1),(long)[self.aiFileChartColumns[i] count]]];
  [self.aiFileChartColumnPopup selectItemAtIndex:0];
  self.aiFileChartTitle=target.lastPathComponent.stringByDeletingPathExtension; self.aiFileChartTitleField.stringValue=self.aiFileChartTitle ?: @"";
  self.aiFileChartLine=NO; self.aiFileChartImageView.image=[self aiFileChartImage];
  [self bringAuxiliaryWindowToFront:self.aiFileChartWindow];
}
- (void)aiFileChartColumnChanged:(id)sender {
  NSInteger i=self.aiFileChartColumnPopup.indexOfSelectedItem;
  if(i>=0&&i<(NSInteger)self.aiFileChartColumns.count){self.aiFileChartValues=self.aiFileChartColumns[i];self.aiFileChartImageView.image=[self aiFileChartImage];}
}

