- (void)aiFileCompareStart:(id)sender {
  NSInteger ia=self.aiFileCompareAPopup.indexOfSelectedItem, ib=self.aiFileCompareBPopup.indexOfSelectedItem;
  if(ia<0||ib<0||ia>=self.aiFiles.count||ib>=self.aiFiles.count){self.aiFileCompareStatus.stringValue=@"请选择两个文件";return;}
  if(ia==ib){self.aiFileCompareStatus.stringValue=@"请选择两个不同的文件";return;}
  NSString *ta=[self aiFileExtractText:self.aiFiles[ia]], *tb=[self aiFileExtractText:self.aiFiles[ib]];
  if(!ta.length||!tb.length){self.aiFileCompareStatus.stringValue=@"文件内容读取失败";return;}
  NSString *url=@"",*key=@"",*model=self.aiFileModelField.stringValue ?: @"";
  NSInteger ci=[self.aiFileServicePopup.selectedItem.representedObject integerValue];
  NSDictionary *e=(ci>=0&&ci<self.aiEntries.count)?self.aiEntries[ci]:nil;
  if(e){NSString *b=e[@"apiBase"] ?: @"";if([b hasSuffix:@"/chat/completions"])b=[b substringToIndex:b.length-17];while([b hasSuffix:@"/"])b=[b substringToIndex:b.length-1];url=b.length?[b stringByAppendingString:@"/chat/completions"]:@"";key=e[@"api"] ?: @"";if(!model.length)model=e[@"model"] ?: @"qwen2.5:3b";}
  else {url=@"http://127.0.0.1:11434/v1/chat/completions";if(!model.length)model=@"qwen2.5:3b";}
  if(!url.length){self.aiFileCompareStatus.stringValue=@"没有可用的 AI 服务";return;}
  NSString *prompt=[NSString stringWithFormat:@"请对比两份文档，输出 Markdown：新增内容、删除内容、修改内容、风险变化、建议。引用时标注版本。\n\n== 版本 A：%@ ==\n%@\n\n== 版本 B：%@ ==\n%@",[self.aiFiles[ia] lastPathComponent],[ta substringToIndex:MIN(ta.length,(NSUInteger)20000)],[self.aiFiles[ib] lastPathComponent],[tb substringToIndex:MIN(tb.length,(NSUInteger)20000)]];
  self.aiFileCompareStatus.stringValue=@"对比中…"; self.aiFileCompareOutput.string=@"正在对比，请稍候…";
  __weak typeof(self) weakSelf=self;
  [self aiFileAPICall:prompt model:model url:url key:key completion:^(NSString *answer,NSString *err){ if(answer.length){weakSelf.aiFileCompareOutput.string=answer;weakSelf.aiFileCompareStatus.stringValue=@"对比完成";}else{weakSelf.aiFileCompareOutput.string=[NSString stringWithFormat:@"对比失败：%@",err ?: @"无返回"];weakSelf.aiFileCompareStatus.stringValue=@"对比失败";} }];
}

- (NSArray *)aiFileEmbeddingsForTexts:(NSArray<NSString *> *)texts {
  if(!texts.count)return @[];
  NSDictionary *body=@{@"model":@"nomic-embed-text",@"input":texts};
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:@"http://127.0.0.1:11434/api/embed"]];
  req.HTTPMethod=@"POST"; [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  req.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:NULL]; req.timeoutInterval=60;
  __block NSArray *result=nil; dispatch_semaphore_t sem=dispatch_semaphore_create(0);
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *d,NSURLResponse *r,NSError *e){
    id o=d.length?[NSJSONSerialization JSONObjectWithData:d options:0 error:NULL]:nil;
    if([o isKindOfClass:[NSDictionary class]] && [o[@"embeddings"] isKindOfClass:[NSArray class]])result=o[@"embeddings"];
    dispatch_semaphore_signal(sem);
  }] resume];
  dispatch_semaphore_wait(sem,dispatch_time(DISPATCH_TIME_NOW,(int64_t)(65*NSEC_PER_SEC)));
  return result ?: @[];
}

- (double)aiFileCosineArray:(NSArray<NSNumber *> *)a with:(NSArray<NSNumber *> *)b {
  double dot=0;NSInteger n=MIN(a.count,b.count);for(NSInteger i=0;i<n;i++)dot+=[a[i] doubleValue]*[b[i] doubleValue];return dot;
}

- (NSDictionary *)aiFileVectorForText:(NSString *)text {
  const NSInteger dim=384; NSMutableDictionary *v=[NSMutableDictionary dictionary];
  NSString *l=text.lowercaseString;
  NSMutableArray *tokens=[NSMutableArray array];
  NSMutableString *latin=[NSMutableString string];
  for(NSUInteger i=0;i<l.length;i++){
    unichar c=[l characterAtIndex:i];
    if((c>='a'&&c<='z')||(c>='0'&&c<='9'))[latin appendFormat:@"%C",c];
    else {if(latin.length>1)[tokens addObject:[latin copy]];[latin setString:@""];}
  }
  if(latin.length>1)[tokens addObject:[latin copy]];
  NSMutableString *han=[NSMutableString string];
  for(NSUInteger i=0;i<l.length;i++){
    unichar c=[l characterAtIndex:i];
    if(c>=0x4E00&&c<=0x9FFF)[han appendFormat:@"%C",c];
    else {for(NSUInteger j=0;j+2<=han.length;j++)[tokens addObject:[han substringWithRange:NSMakeRange(j,2)]];[han setString:@""];}
  }
  for(NSUInteger j=0;j+2<=han.length;j++)[tokens addObject:[han substringWithRange:NSMakeRange(j,2)]];
  for(NSString *t in tokens){NSUInteger h=[t hash]%dim;NSNumber *n=v[@(h)] ?: @0;v[@(h)]=@(n.doubleValue+1);}
  double norm=0;for(NSNumber *n in v.allValues)norm+=n.doubleValue*n.doubleValue;norm=sqrt(norm);
  if(norm<=0)return @{};
  NSMutableDictionary *out=[NSMutableDictionary dictionary];for(NSNumber *k in v)out[k]=@([v[k] doubleValue]/norm);
  return out;
}

- (double)aiFileCosine:(NSDictionary *)a with:(NSDictionary *)b {
  double dot=0;for(NSNumber *k in a)dot+=[a[k] doubleValue]*[b[k] doubleValue];return dot;
}

