- (void)aiFileAskQuestion:(id)sender {
  NSString *q=[self.aiFileChatInput.stringValue stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];
  if(!q.length)return;
  if(!self.aiFiles.count && !self.aiCloudDocs.count){self.aiFileChatStatus.stringValue=@"请先在 AI 文件窗口导入文件或云文档";return;}
  NSString *url=@"", *key=@"", *model=self.aiFileModelField.stringValue ?: @"";
  NSInteger chosenIdx=[self.aiFileServicePopup.selectedItem.representedObject integerValue];
  NSDictionary *chosen=(chosenIdx>=0 && chosenIdx<(NSInteger)self.aiEntries.count)?self.aiEntries[chosenIdx]:nil;
  if(chosen){NSString *base=chosen[@"apiBase"] ?: @"";if([base hasSuffix:@"/chat/completions"])base=[base substringToIndex:base.length-17];while([base hasSuffix:@"/"])base=[base substringToIndex:base.length-1];url=base.length?[base stringByAppendingString:@"/chat/completions"]:@"";key=chosen[@"api"] ?: @"";if(!model.length)model=chosen[@"model"] ?: @"qwen2.5:3b";}
  else {url=@"http://127.0.0.1:11434/v1/chat/completions";if(!model.length)model=@"qwen2.5:3b";}
  if(!url.length){self.aiFileChatStatus.stringValue=@"请先选择可用的 AI 服务";return;}
  self.aiFileChatInput.stringValue=@""; self.aiFileChatStatus.stringValue=@"正在检索文件并回答…";
  [self.aiFileChatTranscript appendFormat:@"\n\n**你：** %@\n\n",q];
  self.aiFileChatOutput.string=self.aiFileChatTranscript;
  __weak typeof(self) weakSelf=self;
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{
    NSMutableArray *chunks=[NSMutableArray array];
    for(NSString *path in self.aiFiles){NSString *t=[self aiFileExtractText:path];if(t.length){NSInteger n=0;for(NSInteger i=0;i<(NSInteger)t.length;i+=6000){n++;[chunks addObject:@{@"src":path.lastPathComponent,@"text":[t substringWithRange:NSMakeRange(i,MIN((NSUInteger)6000,t.length-i))]}];}}}
    for(NSDictionary *c in self.aiCloudDocs){NSString *t=c[@"content"] ?: @"";if(t.length){NSInteger n=0;for(NSInteger i=0;i<(NSInteger)t.length;i+=6000){n++;[chunks addObject:@{@"src":c[@"title"] ?: @"云文档",@"text":[t substringWithRange:NSMakeRange(i,MIN((NSUInteger)6000,t.length-i))]}];}}}
    NSMutableArray *embedTexts=[NSMutableArray arrayWithObject:q]; NSInteger embedCount=MIN((NSInteger)chunks.count,24);
    for(NSInteger i=0;i<embedCount;i++){NSString *t=chunks[i][@"text"];[embedTexts addObject:[t substringToIndex:MIN(t.length,(NSUInteger)2000)]];}
    NSArray *embs=[self aiFileEmbeddingsForTexts:embedTexts];
    NSMutableArray *scored=[NSMutableArray array];
    if(embs.count==embedTexts.count){
      NSArray *qv=embs[0];
      for(NSInteger i=0;i<(NSInteger)chunks.count;i++){double score=(i<embedCount)?[self aiFileCosineArray:qv with:embs[i+1]]:0;[scored addObject:@{@"src":chunks[i][@"src"],@"text":chunks[i][@"text"],@"score":@(score)}];}
    } else {
      NSDictionary *qv=[self aiFileVectorForText:q];
      for(NSDictionary *c in chunks){NSDictionary *cv=[self aiFileVectorForText:c[@"text"]];double score=[self aiFileCosine:qv with:cv];[scored addObject:@{@"src":c[@"src"],@"text":c[@"text"],@"score":@(score)}];}
    }
    [scored sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [b[@"score"] compare:a[@"score"]];}];
    NSMutableString *context=[NSMutableString string];NSInteger used=0;
    for(NSDictionary *c in scored){if(used>30000)break;if([c[@"score"] doubleValue]<=0.001 && used>0)continue;[context appendFormat:@"\n[来源：%@]\n%@",c[@"src"],c[@"text"]];used+=[c[@"text"] length];if(used>30000)break;}
    if(!context.length){for(NSDictionary *c in scored){[context appendFormat:@"\n[来源：%@]\n%@",c[@"src"],c[@"text"]];if(context.length>20000)break;}}
    NSString *prompt=[NSString stringWithFormat:@"你是文件问答助手。只能根据下面资料回答；资料不足就明确说资料中没有。引用时标注 [来源：文件名]。\n\n资料：%@\n\n问题：%@",context,q];
    dispatch_async(dispatch_get_main_queue(),^{
      [weakSelf aiFileAPICall:prompt model:model url:url key:key completion:^(NSString *answer,NSString *err){
        NSString *text=answer.length?answer:[NSString stringWithFormat:@"回答失败：%@",err ?: @"无返回"];
        [weakSelf.aiFileChatTranscript appendFormat:@"**AI：** %@\n\n",text];
        weakSelf.aiFileChatOutput.string=weakSelf.aiFileChatTranscript;
        [weakSelf.aiFileChatOutput scrollToEndOfDocument:nil];
        weakSelf.aiFileChatStatus.stringValue=answer.length?@"回答完成":@"回答失败";
      }];
    });
  });
}

- (void)aiFileAnalyze:(id)sender {
  if(!self.aiFiles.count && !self.aiCloudDocs.count){self.aiFileStatus.stringValue=@"请先导入文件或云文档";return;}
  NSString *url=@"", *key=@"", *model=self.aiFileModelField.stringValue ?: @"";
  NSInteger chosenIdx=[self.aiFileServicePopup.selectedItem.representedObject integerValue];
  NSDictionary *chosen=(chosenIdx>=0 && chosenIdx<(NSInteger)self.aiEntries.count)?self.aiEntries[chosenIdx]:nil;
  if(chosen){
    NSString *base=chosen[@"apiBase"] ?: @"";
    if([base hasSuffix:@"/chat/completions"])base=[base substringToIndex:base.length-17];
    while([base hasSuffix:@"/"])base=[base substringToIndex:base.length-1];
    url=base.length?[base stringByAppendingString:@"/chat/completions"]:@"";
    key=chosen[@"api"] ?: @"";
    if(!model.length)model=chosen[@"model"] ?: @"qwen2.5:3b";
  } else {url=@"http://127.0.0.1:11434/v1/chat/completions"; if(!model.length)model=@"qwen2.5:3b";}
  if(!url.length){self.aiFileStatus.stringValue=@"请选择可用的 AI 服务";return;}
  NSMutableArray *docs=[NSMutableArray array];
  for(NSString *path in self.aiFiles){NSString *t=[self aiFileExtractText:path];if(t.length)[docs addObject:@{@"source":path.lastPathComponent,@"text":t}];}
  for(NSDictionary *c in self.aiCloudDocs){NSString *t=c[@"content"] ?: @"";if(t.length)[docs addObject:@{@"source":c[@"title"] ?: @"云文档",@"text":t}];}
  if(!docs.count){self.aiFileStatus.stringValue=@"没有可提取的文本内容";return;}
  NSMutableArray *files=[NSMutableArray array]; for(NSDictionary *d in docs)[files addObject:d[@"source"]];
  NSInteger total=0; for(NSDictionary *d in docs)total+=[d[@"text"] length];
  self.aiFileOutput.string=@"正在分析，请稍候…";
  self.aiFileAnalysisToken++;
  NSInteger token=self.aiFileAnalysisToken;
  __weak typeof(self) weakSelf=self;
  if(total<=30000){
    NSMutableString *content=[NSMutableString string];
    for(NSDictionary *d in docs)[content appendFormat:@"\n\n===== 来源：%@ =====\n%@",d[@"source"],d[@"text"]];
    NSString *prompt=[NSString stringWithFormat:@"%@\n\n请输出 Markdown 报告，引用内容时标注 [来源: 文件名]。包含：文件概览、核心内容、关键数据、风险与待办、建议。不要编造。\n\n%@",self.aiFilePromptField.stringValue,content];
    self.aiFileStatus.stringValue=@"AI 分析中…";
    [self aiFileAPICall:prompt model:model url:url key:key completion:^(NSString *answer,NSString *err){ if(token!=weakSelf.aiFileAnalysisToken)return; if(!answer.length){weakSelf.aiFileStatus.stringValue=[NSString stringWithFormat:@"分析失败：%@",err ?: @"无返回"];return;} [weakSelf aiFileSaveReport:answer files:files]; }];
    return;
  }
  NSMutableArray *chunks=[NSMutableArray array];
  for(NSDictionary *d in docs){
    NSString *t=d[@"text"]; NSInteger part=0;
    for(NSInteger i=0;i<(NSInteger)t.length && chunks.count<24;i+=8000){part++;NSString *sub=[t substringWithRange:NSMakeRange(i,MIN((NSUInteger)8000,t.length-i))];[chunks addObject:@{@"source":d[@"source"],@"part":@(part),@"text":sub}];}
  }
  __block NSInteger ci=0; NSMutableArray *summaries=[NSMutableArray array];
  __block void (^next)(void); next=^{
    if(token!=weakSelf.aiFileAnalysisToken)return;
    if(ci>=(NSInteger)chunks.count){
      NSMutableString *joined=[NSMutableString string];
      for(NSString *x in summaries)[joined appendFormat:@"\n\n%@",x];
      NSString *prompt=[NSString stringWithFormat:@"%@\n\n以下是长文档的分段摘要，请综合成完整 Markdown 报告，保留关键数据和条款，引用时标注来源和片段。\n\n%@",weakSelf.aiFilePromptField.stringValue,joined];
      weakSelf.aiFileStatus.stringValue=@"正在生成最终报告…";
      [weakSelf aiFileAPICall:prompt model:model url:url key:key completion:^(NSString *answer,NSString *err){ if(token!=weakSelf.aiFileAnalysisToken)return; if(!answer.length){weakSelf.aiFileStatus.stringValue=[NSString stringWithFormat:@"分析失败：%@",err ?: @"无返回"];return;} [weakSelf aiFileSaveReport:answer files:files]; }];
      return;
    }
    NSInteger start=ci; NSInteger end=MIN(start+2,(NSInteger)chunks.count); ci=end;
    weakSelf.aiFileStatus.stringValue=[NSString stringWithFormat:@"分段分析 %ld-%ld/%ld（并发 2）…",(long)(start+1),(long)end,(long)chunks.count];
    __block NSInteger pending=end-start;
    dispatch_group_t group=dispatch_group_create();
    for(NSInteger idx=start;idx<end;idx++){
      NSDictionary *c=chunks[idx];
      dispatch_group_enter(group);
      NSString *p=[NSString stringWithFormat:@"请总结下面这段文档，保留关键数据、条款、结论和风险，并保留来源标记。\n来源：%@ 第%@段\n\n%@",c[@"source"],c[@"part"],c[@"text"]];
      [weakSelf aiFileAPICall:p model:model url:url key:key completion:^(NSString *answer,NSString *err){
        if(token!=weakSelf.aiFileAnalysisToken){dispatch_group_leave(group);return;}
        if(answer.length)[summaries addObject:[NSString stringWithFormat:@"[来源：%@ 第%@段]\n%@",c[@"source"],c[@"part"],answer]];
        pending--;
        dispatch_group_leave(group);
      }];
    }
    dispatch_group_notify(group,dispatch_get_main_queue(),^{ if(token==weakSelf.aiFileAnalysisToken)next(); });
  };
  next();
}

