- (void)closeAIVideoBatch:(id)sender { [self.aiVideoBatchWindow orderOut:nil]; }

- (void)startAIVideoBatch:(id)sender {
  NSMutableArray *lines = [NSMutableArray array];
  for (NSString *line in [self.aiVideoBatchTextView.string componentsSeparatedByString:@"\n"]) {
    NSString *v = [line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (v.length) [lines addObject:v];
  }
  if (!lines.count) { [self showToast:@"请每行输入一个提示词"]; return; }
  if (self.aiVideoBusy) { [self showToast:@"当前正在生成，请稍后"]; return; }
  self.aiVideoBatchQueue = lines;
  self.aiVideoBatchRunning = YES;
  [self.aiVideoBatchWindow orderOut:nil];
  [self runNextAIVideoBatch];
}

- (void)runNextAIVideoBatch {
  if (!self.aiVideoBatchRunning) return;
  if (self.aiVideoBusy) {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(1.5*NSEC_PER_SEC)),dispatch_get_main_queue(),^{ [self runNextAIVideoBatch]; });
    return;
  }
  if (!self.aiVideoBatchQueue.count) {
    self.aiVideoBatchRunning = NO;
    self.aiVideoStatus.stringValue = @"视频批量生成完成";
    [self showToast:@"视频批量生成完成"];
    return;
  }
  NSString *prompt = self.aiVideoBatchQueue.firstObject;
  [self.aiVideoBatchQueue removeObjectAtIndex:0];
  self.aiVideoPrompt.string = prompt;
  self.aiVideoStatus.stringValue = [NSString stringWithFormat:@"批量生成：%@", prompt];
  [self generateAIVideo:nil];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(1.8*NSEC_PER_SEC)),dispatch_get_main_queue(),^{ [self runNextAIVideoBatch]; });
}

- (void)pickAIVideoFirstFrame:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = YES; p.canChooseDirectories = NO; p.allowsMultipleSelection = NO;
  p.allowedFileTypes = @[@"png", @"jpg", @"jpeg", @"webp", @"heic", @"tiff"];
  if ([p runModal] != NSModalResponseOK) return;
  self.aiVideoFirstFramePath = p.URL.path;
  self.aiVideoStatus.stringValue = [NSString stringWithFormat:@"已选择首帧：%@，请选择 I2V 模型", p.URL.lastPathComponent];
}

- (void)generateAIVideo:(id)sender {
  if (self.aiVideoBusy) return;
  NSInteger idx=[self.aiVideoServicePopup.selectedItem.representedObject integerValue];
  if (idx<0 || idx>=(NSInteger)self.aiEntries.count) { self.aiVideoStatus.stringValue=@"请先在 AI 管理添加服务"; return; }
  NSDictionary *e=self.aiEntries[idx];
  NSString *key=e[@"api"] ?: @"";
  NSString *prompt=self.aiVideoPrompt.string;
  NSString *url=self.aiVideoURLField.stringValue;
  NSString *model=self.aiVideoModelField.stringValue;
  if (!key.length || !prompt.length || !url.length || !model.length) { self.aiVideoStatus.stringValue=@"请填写 API Key、提示词、地址和模型"; return; }
  NSString *modelLower = model.lowercaseString;
  if (self.aiVideoFirstFramePath.length && [modelLower containsString:@"t2v"]) {
    self.aiVideoStatus.stringValue = @"当前模型是 T2V 文生视频，不能使用首帧图片；请选择 I2V 模型";
    return;
  }
  if (!self.aiVideoFirstFramePath.length && [modelLower containsString:@"i2v"]) {
    self.aiVideoStatus.stringValue = @"当前模型是 I2V 图生视频，请先选择首帧图片";
    return;
  }
  NSMutableDictionary *entry=[e mutableCopy]; entry[@"videoModel"]=model; entry[@"videoAPI"]=url; self.aiEntries[idx]=entry; [self saveAIEntries];
  BOOL ark = [url containsString:@"/contents/generations/tasks"];
  BOOL silicon = [url containsString:@"/video/submit"];
  if (self.aiVideoFirstFramePath.length && !silicon) {
    self.aiVideoStatus.stringValue = @"首帧图生视频目前先支持硅基流动接口";
    return;
  }
  self.aiVideoSiliconFlow = silicon;
  NSMutableDictionary *body;
  if (ark) body = [@{@"model":model,@"content":@[@{@"type":@"text",@"text":prompt}]} mutableCopy];
  else if (silicon) {
    body = [@{@"model":model,@"prompt":prompt,@"image_size":@"1280x720"} mutableCopy];
    if (self.aiVideoFirstFramePath.length) {
      NSData *imgData = [NSData dataWithContentsOfFile:self.aiVideoFirstFramePath];
      if (!imgData.length) { self.aiVideoStatus.stringValue=@"首帧图片读取失败"; return; }
      NSString *ext = self.aiVideoFirstFramePath.pathExtension.lowercaseString;
      NSString *mime = [ext isEqualToString:@"jpg"] || [ext isEqualToString:@"jpeg"] ? @"image/jpeg" : ([ext isEqualToString:@"webp"] ? @"image/webp" : @"image/png");
      NSString *dataURL = [NSString stringWithFormat:@"data:%@;base64,%@", mime, [imgData base64EncodedStringWithOptions:0]];
      body[@"image"] = dataURL;
    }
  }
  else body = [@{@"model":model,@"prompt":prompt,@"duration":@([self.aiVideoDurationPopup.titleOfSelectedItem integerValue])} mutableCopy];
  NSString *reasonVid = [self reasoningEffortForPopup:self.aiVideoReasoningPopup];
  if (reasonVid.length) body[@"reasoning_effort"] = reasonVid;
  NSData *data=[NSJSONSerialization dataWithJSONObject:body options:0 error:NULL];
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod=@"POST"; [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.HTTPBody=data; req.timeoutInterval=60;
  self.aiVideoBusy=YES; self.aiVideoStatus.stringValue=@"正在提交视频任务…"; self.aiVideoPollCount=0; self.aiVideoPollErrors=0;
  self.aiVideoTaskID=nil; self.aiVideoPollURL=nil;
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *respData, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (err || !respData.length) { weakSelf.aiVideoBusy=NO; weakSelf.aiVideoStatus.stringValue=err.localizedDescription ?: @"提交失败"; return; }
      id obj=[NSJSONSerialization JSONObjectWithData:respData options:0 error:NULL];
      NSString *videoURL=[weakSelf firstURLStringInJSONObject:obj];
      NSString *taskID=nil;
      if ([obj isKindOfClass:[NSDictionary class]]) {
        taskID=obj[@"id"] ?: obj[@"task_id"] ?: obj[@"requestId"];
        if (!taskID) { id d=obj[@"data"]; if ([d isKindOfClass:[NSDictionary class]]) taskID=d[@"id"] ?: d[@"task_id"] ?: d[@"requestId"]; }
      }
      if (videoURL.length) { [weakSelf downloadAIVideoURL:videoURL]; return; }
      if (!taskID.length) { weakSelf.aiVideoBusy=NO; weakSelf.aiVideoStatus.stringValue=[weakSelf friendlyAIErrorFromData:respData fallback:@"没有解析到任务"]; return; }
      weakSelf.aiVideoTaskID=taskID;
      if (silicon) weakSelf.aiVideoPollURL=[url stringByReplacingOccurrencesOfString:@"/video/submit" withString:@"/video/status"];
      else weakSelf.aiVideoPollURL=[url stringByAppendingFormat:@"/%@", taskID];
      weakSelf.aiVideoStatus.stringValue=[NSString stringWithFormat:@"任务已提交：%@，等待生成…", taskID];
      [weakSelf.aiVideoPollTimer invalidate];
      weakSelf.aiVideoPollTimer=[NSTimer scheduledTimerWithTimeInterval:5.0 repeats:YES block:^(NSTimer *timer) { [weakSelf pollAIVideoTask]; }];
    });
  }] resume];
}

- (void)pollAIVideoTask {
  if (!self.aiVideoPollURL.length) return;
  self.aiVideoPollCount++;
  if (self.aiVideoPollCount > 120) { [self.aiVideoPollTimer invalidate]; self.aiVideoBusy=NO; self.aiVideoStatus.stringValue=@"视频任务超时"; return; }
  NSInteger idx=[self.aiVideoServicePopup.selectedItem.representedObject integerValue];
  NSString *key = (idx>=0 && idx<(NSInteger)self.aiEntries.count) ? (self.aiEntries[idx][@"api"] ?: @"") : @"";
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:self.aiVideoPollURL]];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  if (self.aiVideoSiliconFlow) {
    req.HTTPMethod=@"POST";
    [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
    req.HTTPBody=[NSJSONSerialization dataWithJSONObject:@{@"requestId":self.aiVideoTaskID ?: @""} options:0 error:NULL];
  }
  req.timeoutInterval=30;
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (err || !data.length) {
        weakSelf.aiVideoPollErrors++;
        if (weakSelf.aiVideoPollErrors >= 3) { [weakSelf.aiVideoPollTimer invalidate]; weakSelf.aiVideoBusy=NO; weakSelf.aiVideoStatus.stringValue=err.localizedDescription ?: @"视频轮询失败，请检查网络或任务"; }
        return;
      }
      weakSelf.aiVideoPollErrors=0;
      id obj=[NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
      NSString *status = ([obj isKindOfClass:[NSDictionary class]] ? obj[@"status"] : nil);
      NSString *statusLow = [status isKindOfClass:[NSString class]] ? status.lowercaseString : @"";
      if ([@[@"failed",@"error",@"cancel",@"cancelled",@"timeout"] containsObject:statusLow]) {
        [weakSelf.aiVideoPollTimer invalidate]; weakSelf.aiVideoBusy=NO;
        NSString *reason = ([obj isKindOfClass:[NSDictionary class]] ? obj[@"reason"] : nil) ?: @"视频生成失败";
        weakSelf.aiVideoStatus.stringValue=reason; return;
      }
      NSString *videoURL=[weakSelf firstURLStringInJSONObject:obj];
      if (videoURL.length) { [weakSelf.aiVideoPollTimer invalidate]; [weakSelf downloadAIVideoURL:videoURL]; return; }
      weakSelf.aiVideoStatus.stringValue=[NSString stringWithFormat:@"生成中…（第 %ld 次检查）", (long)weakSelf.aiVideoPollCount];
    });
  }] resume];
}

- (void)downloadAIVideoURL:(NSString *)url {
  self.aiVideoStatus.stringValue=@"正在下载视频…";
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithURL:[NSURL URLWithString:url] completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (err || !data.length) { weakSelf.aiVideoBusy=NO; weakSelf.aiVideoStatus.stringValue=err.localizedDescription ?: @"视频下载失败"; return; }
      NSString *dir=[self aiVideoOutputDirectory];
      [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
      NSDateFormatter *df=[[NSDateFormatter alloc] init]; df.dateFormat=@"yyyyMMdd-HHmmss";
      NSString *path=[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"AI视频-%@.mp4",[df stringFromDate:[NSDate date]]]];
      [data writeToFile:path atomically:YES];
      weakSelf.aiVideoResultPath=path; weakSelf.aiVideoBusy=NO;
      weakSelf.aiVideoStatus.stringValue=[NSString stringWithFormat:@"已生成：%@",path.lastPathComponent];
      AVAsset *asset=[AVAsset assetWithURL:[NSURL fileURLWithPath:path]];
      AVAssetImageGenerator *gen=[AVAssetImageGenerator assetImageGeneratorWithAsset:asset];
      gen.appliesPreferredTrackTransform=YES; gen.maximumSize=CGSizeMake(600,400);
      CGImageRef img=[gen copyCGImageAtTime:CMTimeMake(0,1) actualTime:NULL error:NULL];
      if (img) { weakSelf.aiVideoPreview.image=[[NSImage alloc] initWithCGImage:img size:NSZeroSize]; CGImageRelease(img); }
    });
  }] resume];
}

- (void)saveAIVideo:(id)sender {
  if (!self.aiVideoResultPath.length) { [self showToast:@"还没有生成视频"]; return; }
  NSSavePanel *sp=[NSSavePanel savePanel]; sp.allowedFileTypes=@[@"mp4"];
  sp.nameFieldStringValue=self.aiVideoResultPath.lastPathComponent;
  if ([sp runModal]==NSModalResponseOK) {
    [[NSFileManager defaultManager] removeItemAtPath:sp.URL.path error:NULL];
    if ([[NSFileManager defaultManager] copyItemAtPath:self.aiVideoResultPath toPath:sp.URL.path error:NULL]) [self showToast:@"视频已保存"];
  }
}
- (void)openAIVideo:(id)sender { if (self.aiVideoResultPath.length) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.aiVideoResultPath]]; }

- (NSString *)reasoningEffortForPopup:(NSPopUpButton *)popup {
  NSInteger idx = popup.indexOfSelectedItem;
  if (idx == 1) return @"low";
  if (idx == 2) return @"medium";
  if (idx == 3) return @"high";
  return nil;
}

- (void)aiReasoningChanged:(id)sender {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  if (sender == self.aiAssistantReasoningPopup) [ud setInteger:self.aiAssistantReasoningPopup.indexOfSelectedItem forKey:@"aiAssistantReasoning"];
  else if (sender == self.aiImageReasoningPopup) [ud setInteger:self.aiImageReasoningPopup.indexOfSelectedItem forKey:@"aiImageReasoning"];
  else if (sender == self.aiVideoReasoningPopup) [ud setInteger:self.aiVideoReasoningPopup.indexOfSelectedItem forKey:@"aiVideoReasoning"];
  [ud synchronize];
}

- (NSData *)pngDataForImagePath:(NSString *)path {
  NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
  if (!img) return nil;
  NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithData:img.TIFFRepresentation];
  return [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
}

- (void)aiVisionLoadImagePath:(NSString *)path {
  if (!path.length || ![[NSFileManager defaultManager] fileExistsAtPath:path]) return;
  self.aiVisionImagePath = path;
  self.aiVisionPreview.image = [[NSImage alloc] initWithContentsOfFile:path];
  self.aiVisionStatus.stringValue = [NSString stringWithFormat:@"已选择：%@", path.lastPathComponent];
}

- (void)aiVisionPickImage:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles=YES; p.canChooseDirectories=NO; p.allowsMultipleSelection=NO;
  p.allowedFileTypes=@[@"png",@"jpg",@"jpeg",@"heic",@"tiff",@"webp"];
  if ([p runModal] == NSModalResponseOK) [self aiVisionLoadImagePath:p.URL.path];
}

- (void)aiVisionCapture:(id)sender {
  NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"ai-vision-%lld.png", (long long)[[NSDate date] timeIntervalSince1970]]];
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/usr/sbin/screencapture";
  t.arguments = @[@"-i", @"-x", path];
  self.aiVisionStatus.stringValue = @"正在截图，按 Esc 取消…";
  __weak typeof(self) weakSelf = self;
  t.terminationHandler = ^(NSTask *task) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if ([[NSFileManager defaultManager] fileExistsAtPath:path]) [weakSelf aiVisionLoadImagePath:path];
      else weakSelf.aiVisionStatus.stringValue = @"截图已取消";
    });
  };
  @try { [t launch]; } @catch (NSException *e) { self.aiVisionStatus.stringValue = @"无法启动截图"; }
}

- (void)aiVisionPaste:(id)sender {
  NSPasteboard *pb = [NSPasteboard generalPasteboard];
  NSArray *imgs = [pb readObjectsForClasses:@[NSImage.class] options:nil];
  NSImage *img = imgs.firstObject;
  if (!img) { self.aiVisionStatus.stringValue = @"剪贴板里没有图片"; return; }
  NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithData:img.TIFFRepresentation];
  NSData *png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
  NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"ai-paste-%lld.png", (long long)[[NSDate date] timeIntervalSince1970]]];
  [png writeToFile:path atomically:YES];
  [self aiVisionLoadImagePath:path];
}

- (void)aiVisionOCR:(id)sender {
  if (!self.aiVisionImagePath.length) { self.aiVisionStatus.stringValue = @"请先选择图片"; return; }
  self.aiVisionStatus.stringValue = @"正在本地识别文字…";
  __weak typeof(self) weakSelf = self;
  [self translationOCRImage:self.aiVisionImagePath completion:^(NSString *text) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (text.length) {
        weakSelf.aiVisionOutput.string = text;
        weakSelf.aiVisionStatus.stringValue = @"本地 OCR 完成；可以继续让 AI 总结";
      } else weakSelf.aiVisionStatus.stringValue = @"没有识别到文字";
    });
  }];
}

