  self.aiVisionPrompt.string = @"请识别图片内容并用中文总结要点。";
  [[NSUserDefaults standardUserDefaults] setObject:self.aiVisionPrompt.string forKey:@"centerAIVisionPrompt"];
  [self showToast:@"已恢复默认提示词"];
