- (void)closeAIInpaint:(id)sender { [self.aiInpaintWindow orderOut:nil]; }

- (void)generateAIInpaint:(id)sender {
  if(!self.aiInpaintView.image){[self showToast:@"请先加载图片"];return;}
  NSRect crop=[self.aiInpaintView selectionInImagePixels];
  if(crop.size.width<8||crop.size.height<8){[self showToast:@"请先拖动框选区域"];return;}
  NSDictionary *info=[self inpaintEditEntry]; if(!info){[self showToast:@"请先在 AI 管理配置图片编辑服务"];return;}
  NSImage *source=self.aiInpaintView.image; NSSize src=source.size;
  crop=NSMakeRect(MAX(0,MIN(crop.origin.x,src.width-1)),MAX(0,MIN(crop.origin.y,src.height-1)),MIN(crop.size.width,src.width),MIN(crop.size.height,src.height));
  NSBitmapImageRep *rep=[[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:(NSInteger)MAX(1,crop.size.width) pixelsHigh:(NSInteger)MAX(1,crop.size.height) bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
  NSGraphicsContext *g=[NSGraphicsContext graphicsContextWithBitmapImageRep:rep]; [NSGraphicsContext saveGraphicsState]; [NSGraphicsContext setCurrentContext:g];
  [source drawInRect:NSMakeRect(-crop.origin.x,-crop.origin.y,src.width,src.height)];
  [NSGraphicsContext restoreGraphicsState];
  NSData *png=[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
  NSString *prompt=self.aiInpaintPrompt.string ?: @"只修改这张局部图，保持自然衔接";
  [self sendInpaintImageData:png crop:crop source:source info:info prompt:prompt];
}

- (void)generateAIOutpaint:(id)sender {
  NSImage *source=self.aiInpaintView.image; if(!source){[self showToast:@"请先加载图片"];return;}
  NSDictionary *info=[self inpaintEditEntry]; if(!info){[self showToast:@"请先在 AI 管理配置图片编辑服务"];return;}
  NSSize s=source.size; CGFloat mx=s.width*0.2,my=s.height*0.2; NSSize out=NSMakeSize(s.width+2*mx,s.height+2*my);
  NSBitmapImageRep *rep=[[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:(NSInteger)out.width pixelsHigh:(NSInteger)out.height bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
  NSGraphicsContext *g=[NSGraphicsContext graphicsContextWithBitmapImageRep:rep]; [NSGraphicsContext saveGraphicsState]; [NSGraphicsContext setCurrentContext:g];
  [[NSColor whiteColor] setFill]; NSRectFill(NSMakeRect(0,0,out.width,out.height)); [source drawInRect:NSMakeRect(mx,my,s.width,s.height)];
  [NSGraphicsContext restoreGraphicsState];
  NSData *png=[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
  [self sendInpaintImageData:png crop:NSZeroRect source:nil info:info prompt:@"扩展画面并自然补全四周背景，保持主体和原有内容不变"];
}

- (void)sendInpaintImageData:(NSData *)imgData crop:(NSRect)crop source:(NSImage *)source info:(NSDictionary *)info prompt:(NSString *)prompt {
  NSString *url=info[@"url"],*model=info[@"model"],*key=info[@"key"];
  if(!url.length||!model.length||!key.length){[self showToast:@"图片编辑服务配置不完整"];return;}
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]]; req.HTTPMethod=@"POST"; req.timeoutInterval=180;
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  if([info[@"silicon"] boolValue]){
    NSString *dataURL=[@"data:image/png;base64," stringByAppendingString:[imgData base64EncodedStringWithOptions:0]];
    req.HTTPBody=[NSJSONSerialization dataWithJSONObject:@{@"model":model,@"prompt":prompt,@"image":dataURL} options:0 error:NULL];
    [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  } else {
    NSString *b=[[NSUUID UUID] UUIDString]; NSMutableData *body=[NSMutableData data];
    void(^f)(NSString*,NSString*)=^(NSString *n,NSString *v){[body appendData:[[NSString stringWithFormat:@"--%@\r\nContent-Disposition: form-data; name=\"%@\"\r\n\r\n%@\r\n",b,n,v] dataUsingEncoding:NSUTF8StringEncoding]];};
    f(@"model",model); f(@"prompt",prompt);
    [body appendData:[[NSString stringWithFormat:@"--%@\r\nContent-Disposition: form-data; name=\"image\"; filename=\"image.png\"\r\nContent-Type: image/png\r\n\r\n",b] dataUsingEncoding:NSUTF8StringEncoding]];
    [body appendData:imgData]; [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
    [body appendData:[[NSString stringWithFormat:@"--%@--\r\n",b] dataUsingEncoding:NSUTF8StringEncoding]];
    req.HTTPBody=body; [req setValue:[NSString stringWithFormat:@"multipart/form-data; boundary=%@",b] forHTTPHeaderField:@"Content-Type"];
  }
  self.aiInpaintStatus.stringValue=@"AI 正在处理…";
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *rd,NSURLResponse *rsp,NSError *err){
    if(err||!rd.length){dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiInpaintStatus.stringValue=err.localizedDescription?:@"处理失败";});return;}
    id obj=[NSJSONSerialization JSONObjectWithData:rd options:0 error:NULL]; NSString *imageURL=[weakSelf firstURLStringInJSONObject:obj]; NSData *imageData=nil;
    if(!imageURL&&[obj isKindOfClass:[NSDictionary class]]){id d=obj[@"data"];if([d isKindOfClass:[NSArray class]]&&[d count]){id bb=d[0][@"b64_json"];if([bb isKindOfClass:[NSString class]])imageData=[[NSData alloc] initWithBase64EncodedString:bb options:0];}}
    void(^finish)(NSData*)=^(NSData *data){
      if(!data.length){dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiInpaintStatus.stringValue=@"结果下载失败";});return;}
      NSImage *result=[[NSImage alloc] initWithData:data]; if(!result){dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiInpaintStatus.stringValue=@"结果解析失败";});return;}
      NSImage *output=result;
      if(source&&crop.size.width>1&&crop.size.height>1){
        NSSize full=source.size;
        NSBitmapImageRep *cr=[[NSBitmapImageRep alloc] initWithBitmapDataPlanes:NULL pixelsWide:(NSInteger)full.width pixelsHigh:(NSInteger)full.height bitsPerSample:8 samplesPerPixel:4 hasAlpha:YES isPlanar:NO colorSpaceName:NSCalibratedRGBColorSpace bytesPerRow:0 bitsPerPixel:0];
        NSGraphicsContext *g=[NSGraphicsContext graphicsContextWithBitmapImageRep:cr]; [NSGraphicsContext saveGraphicsState]; [NSGraphicsContext setCurrentContext:g];
        [source drawInRect:NSMakeRect(0,0,full.width,full.height)]; [result drawInRect:crop]; [NSGraphicsContext restoreGraphicsState];
        output=[[NSImage alloc] initWithSize:full]; [output addRepresentation:cr];
      }
      NSBitmapImageRep *orp=[[NSBitmapImageRep alloc] initWithData:[output TIFFRepresentation]]; NSData *png=[orp representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
      NSDateFormatter *df=[[NSDateFormatter alloc] init];df.dateFormat=@"yyyyMMdd-HHmmss";
      NSString *path=[[weakSelf aiEditOutputDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"AI局部重绘-%@.png",[df stringFromDate:[NSDate date]]]];
      [png writeToFile:path atomically:YES];
      dispatch_async(dispatch_get_main_queue(),^{
        weakSelf.aiEditResultPath=path; if(weakSelf.aiEditResultPreview)weakSelf.aiEditResultPreview.image=output;
        weakSelf.aiInpaintStatus.stringValue=[NSString stringWithFormat:@"已生成：%@",path.lastPathComponent]; [weakSelf showToast:@"局部重绘完成"];
      });
    };
    if(imageData.length){finish(imageData);return;}
    if(imageURL.length){[[[NSURLSession sharedSession] dataTaskWithURL:[NSURL URLWithString:imageURL] completionHandler:^(NSData *d,NSURLResponse *r,NSError *e2){finish(d);}] resume];return;}
    dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiInpaintStatus.stringValue=[weakSelf friendlyAIErrorFromData:rd fallback:@"处理失败"];});
  }] resume];
}

- (void)sendAIEdit {
  if(self.aiEditBusy)return;
  if(!self.aiEditImagePath.length){self.aiEditStatus.stringValue=@"请先选择图片";return;}
  NSInteger idx=[self.aiEditServicePopup.selectedItem.representedObject integerValue];
  if(idx<0||idx>=(NSInteger)self.aiEntries.count){self.aiEditStatus.stringValue=@"请先配置 AI 服务";return;}
  NSDictionary *e=self.aiEntries[idx];
  NSString *key=e[@"api"]?:@"";NSString *url=self.aiEditURLField.stringValue;NSString *model=self.aiEditModelField.stringValue;NSString *prompt=self.aiEditPrompt.string;
  if(!key.length||!url.length||!model.length||!prompt.length){self.aiEditStatus.stringValue=@"请填写 Key、地址、模型和提示词";return;}
  NSData *imgData=[[NSData alloc] initWithContentsOfFile:self.aiEditImagePath];
  if(!imgData.length){self.aiEditStatus.stringValue=@"图片读取失败";return;}
  NSMutableDictionary *entry=[e mutableCopy];entry[@"editModel"]=model;entry[@"editAPI"]=url;self.aiEntries[idx]=entry;[self saveAIEntries];
  NSString *editServiceName=[e[@"name"]?:@"" lowercaseString];
  BOOL siliconEdit = [url containsString:@"siliconflow"] || [editServiceName containsString:@"siliconflow"] || [editServiceName containsString:@"硅基流动"];
  NSMutableURLRequest *req=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod=@"POST";
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.timeoutInterval=180;
  if (siliconEdit) {
    NSString *b64=[imgData base64EncodedStringWithOptions:0];
    NSString *dataURL=[@"data:image/png;base64," stringByAppendingString:b64];
    NSDictionary *json=@{@"model":model,@"prompt":prompt,@"image":dataURL};
    req.HTTPBody=[NSJSONSerialization dataWithJSONObject:json options:0 error:NULL];
    [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  } else {
    NSString *boundary=[[NSUUID UUID] UUIDString];
    NSMutableData *body=[NSMutableData data];
    void (^field)(NSString*,NSString*)=^(NSString *name,NSString *value){
      [body appendData:[[NSString stringWithFormat:@"--%@\r\nContent-Disposition: form-data; name=\"%@\"\r\n\r\n%@\r\n",boundary,name,value] dataUsingEncoding:NSUTF8StringEncoding]];
    };
    field(@"model",model);
    field(@"prompt",prompt);
    field(@"size",self.aiEditSizePopup.titleOfSelectedItem?:@"1024x1024");
    field(@"n",@"1");
    [body appendData:[[NSString stringWithFormat:@"--%@\r\nContent-Disposition: form-data; name=\"image\"; filename=\"image.png\"\r\nContent-Type: image/png\r\n\r\n",boundary] dataUsingEncoding:NSUTF8StringEncoding]];
    [body appendData:imgData];
    [body appendData:[@"\r\n" dataUsingEncoding:NSUTF8StringEncoding]];
    [body appendData:[[NSString stringWithFormat:@"--%@--\r\n",boundary] dataUsingEncoding:NSUTF8StringEncoding]];
    [req setValue:[NSString stringWithFormat:@"multipart/form-data; boundary=%@",boundary] forHTTPHeaderField:@"Content-Type"];
    req.HTTPBody=body;
  }
  self.aiEditBusy=YES;self.aiEditStatus.stringValue=@"正在编辑图片…";
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *rd,NSURLResponse *rsp,NSError *err){
    if(err||!rd.length){dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiEditBusy=NO;weakSelf.aiEditStatus.stringValue=err.localizedDescription?:@"编辑失败";});return;}
    id obj=[NSJSONSerialization JSONObjectWithData:rd options:0 error:NULL];
    NSString *imageURL=[weakSelf firstURLStringInJSONObject:obj];
    NSData *imageData=nil;
    if(!imageURL&&[obj isKindOfClass:[NSDictionary class]]){
      id d=obj[@"data"];if([d isKindOfClass:[NSArray class]]&&[d count]){
        id b64=d[0][@"b64_json"];if([b64 isKindOfClass:[NSString class]])imageData=[[NSData alloc] initWithBase64EncodedString:b64 options:0];
      }
    }
    void (^finish)(NSData*)=^(NSData *data){
      if(!data.length){dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiEditBusy=NO;weakSelf.aiEditStatus.stringValue=@"图片下载失败";});return;}
      NSString *dir=[self aiEditOutputDirectory];
      [[NSFileManager defaultManager] createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:nil error:NULL];
      NSDateFormatter *df=[[NSDateFormatter alloc] init];df.dateFormat=@"yyyyMMdd-HHmmss";
      NSString *path=[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"AI编辑-%@.png",[df stringFromDate:[NSDate date]]]];
      [data writeToFile:path atomically:YES];
      dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiEditBusy=NO;weakSelf.aiEditResultPath=path;weakSelf.aiEditResultPreview.image=[[NSImage alloc] initWithData:data];weakSelf.aiEditStatus.stringValue=[NSString stringWithFormat:@"已生成：%@",path.lastPathComponent];});
    };
    if(imageData.length){finish(imageData);return;}
    if(imageURL.length){[[[NSURLSession sharedSession] dataTaskWithURL:[NSURL URLWithString:imageURL] completionHandler:^(NSData *d,NSURLResponse *r,NSError *er){finish(d);}] resume];return;}
    dispatch_async(dispatch_get_main_queue(),^{weakSelf.aiEditBusy=NO;weakSelf.aiEditStatus.stringValue=[weakSelf friendlyAIErrorFromData:rd fallback:@"没有解析到结果"];});
  }] resume];
}

- (void)saveAIEdit {
  if(!self.aiEditResultPath.length){[self showToast:@"还没有编辑结果"];return;}
  NSSavePanel *sp=[NSSavePanel savePanel];sp.allowedFileTypes=@[@"png"];sp.nameFieldStringValue=self.aiEditResultPath.lastPathComponent;
  if([sp runModal]==NSModalResponseOK){[[NSFileManager defaultManager] removeItemAtPath:sp.URL.path error:NULL];if([[NSFileManager defaultManager] copyItemAtPath:self.aiEditResultPath toPath:sp.URL.path error:NULL])[self showToast:@"图片已保存"];}
}
- (void)openAIEdit { if(self.aiEditResultPath.length)[[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.aiEditResultPath]]; }

- (void)reloadAIImageServices {
  if (!self.aiEntries) [self loadAIEntries];
  [self hydrateAIKeys];
  [self.aiImageServicePopup removeAllItems];
  for (NSInteger i=0;i<(NSInteger)self.aiEntries.count;i++) {
    NSDictionary *e = self.aiEntries[i];
    if (![[self aiModelCategoryKey:e] isEqualToString:@"image"]) continue;
    [self.aiImageServicePopup addItemWithTitle:e[@"name"] ?: @"未命名"];
    self.aiImageServicePopup.lastItem.representedObject = @(i);
  }
  if (!self.aiImageServicePopup.numberOfItems) {
    [self.aiImageServicePopup addItemWithTitle:@"请先在 AI 管理设置图片模型"];
    self.aiImageServicePopup.enabled = NO;
    self.aiImageStatus.stringValue = @"没有图片模型，请把服务分类设为「图片」";
  } else {
    self.aiImageServicePopup.enabled = YES;
    [self.aiImageServicePopup selectItemAtIndex:0]; [self aiImageServiceChanged:nil];
  }
}

- (BOOL)aiServiceName:(NSString *)name containsAny:(NSArray *)words {
  NSString *hay = [name lowercaseString] ?: @"";
  for (NSString *w in words) if ([hay containsString:[w lowercaseString]]) return YES;
  return NO;
}

- (BOOL)aiServiceSupportsImage:(NSString *)name {
  if ([self aiServiceName:name containsAny:@[@"deepseek",@"kimi",@"moonshot",@"claude",@"anthropic",@"mistral",@"qwen",@"千问",@"通义",@"智谱",@"glm",@"ernie",@"文心",@"百川",@"yi",@"零一",@"混元",@"hunyuan",@"groq"]]) return NO;
  return [self aiServiceName:name containsAny:@[@"openai",@"chatgpt",@"gpt-image",@"dall",@"豆包",@"方舟",@"volcengine",@"doubao",@"seedream",@"siliconflow",@"硅基流动",@"flux",@"stable",@"image",@"图片",@"comfy"]];
}

- (BOOL)aiServiceSupportsVideo:(NSString *)name {
  return [self aiServiceName:name containsAny:@[@"豆包",@"方舟",@"volcengine",@"doubao",@"seedance",@"sora",@"runway",@"kling",@"可灵",@"luma",@"minimax",@"海螺",@"veo",@"video",@"视频"]];
}

- (NSArray<NSString *> *)filterModelIDs:(NSArray *)ids keywords:(NSArray *)keywords {
  NSMutableArray *out = [NSMutableArray array];
  for (id m in ids) {
    if (![m isKindOfClass:[NSString class]]) continue;
    NSString *low = [m lowercaseString];
    if ([low containsString:@"edit"] || [low containsString:@"embed"] || [low containsString:@"nomic"] || [low containsString:@"bge"] || [low containsString:@"mxbai"]) continue;
    for (NSString *k in keywords) if ([low containsString:k]) { [out addObject:m]; break; }
  }
  return out;
}

- (void)fetchModelsForPanel:(NSComboBox *)combo url:(NSString *)base key:(NSString *)key keywords:(NSArray *)keywords knownDefault:(NSString *)knownDefault completion:(void (^)(NSArray *models))completion {
  if (!combo || !base.length || !key.length) { if (completion) completion(@[]); return; }
  NSString *root = base;
  if ([root hasSuffix:@"/chat/completions"]) root = [root substringToIndex:root.length - @"/chat/completions".length];
  while ([root hasSuffix:@"/"]) root = [root substringToIndex:root.length - 1];
  NSURL *url = [NSURL URLWithString:[root stringByAppendingString:@"/models"]];
  if (!url) { if (completion) completion(@[]); return; }
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:url];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.timeoutInterval = 20;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    NSMutableArray *all = [NSMutableArray array];
    if (data.length) {
      id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
      id list = [obj isKindOfClass:[NSDictionary class]] ? obj[@"data"] : nil;
      if ([list isKindOfClass:[NSArray class]]) for (id m in list) { id mid = [m isKindOfClass:[NSDictionary class]] ? m[@"id"] : nil; if ([mid isKindOfClass:[NSString class]]) [all addObject:mid]; }
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      NSArray *filtered = [self filterModelIDs:all keywords:keywords];
      if (filtered.count) {
        [combo removeAllItems]; [combo addItemsWithObjectValues:filtered];
        if (knownDefault.length && [filtered containsObject:knownDefault]) combo.stringValue = knownDefault;
        else if (!combo.stringValue.length) combo.stringValue = filtered.firstObject;
      }
      if (completion) completion(filtered);
    });
  }] resume];
}

- (void)aiImageServiceChanged:(id)sender {
  NSInteger idx = [self.aiImageServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)self.aiEntries.count) return;
  NSDictionary *e = self.aiEntries[idx];
  NSString *name = e[@"name"] ?: @"";
  NSString *base = e[@"apiBase"] ?: @"";
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length - @"/chat/completions".length];
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length - 1];
  [self.aiImageModelField removeAllItems];
  self.aiImageModelField.stringValue = @"";
  self.aiImageURLField.stringValue = @"";
  self.aiImageStatus.stringValue = @"";
  if (![[self aiModelCategoryKey:e] isEqualToString:@"image"] && ![self aiServiceSupportsImage:name]) {
    self.aiImageStatus.stringValue = @"该 AI 服务只支持文本，暂无图片生成接口";
    return;
  }
  NSString *key = e[@"api"] ?: @"";
  NSString *defaultURL = @"", *defaultModel = @"";
  NSString *low = [name lowercaseString];
  BOOL comfy = [low containsString:@"comfy"] || [base containsString:@":8188"];
  if (comfy) {
    self.aiImageModelField.editable=NO; self.aiImageModelField.completes=NO;
    [self.aiImageModelField removeAllItems];
    NSString *ckptDir=[NSHomeDirectory() stringByAppendingPathComponent:@"ComfyUI/models/checkpoints"];
    for(NSString *f in [[NSFileManager defaultManager] contentsOfDirectoryAtPath:ckptDir error:NULL] ?: @[]) if([@[@"safetensors",@"ckpt"] containsObject:f.pathExtension.lowercaseString])[self.aiImageModelField addItemWithObjectValue:f];
    if(!self.aiImageModelField.numberOfItems)[self.aiImageModelField addItemWithObjectValue:@"v1-5-pruned-emaonly.safetensors"];
    NSString *want=e[@"imageModel"] ?: @"v1-5-pruned-emaonly.safetensors";
    self.aiImageModelField.stringValue=[self.aiImageModelField.objectValues containsObject:want]?want:self.aiImageModelField.objectValues.firstObject;
    self.aiImageURLField.stringValue = base.length ? base : @"http://127.0.0.1:8188";
    self.aiImageStatus.stringValue = @"ComfyUI 本地：模型填 checkpoint 名称，地址填 127.0.0.1:8188；8GB 建议 512x512";
    [self.aiImageSizePopup selectItemWithTitle:@"512x512"];
    return;
  }
  self.aiImageModelField.editable = NO;
  if ([low containsString:@"openai"] || [low containsString:@"chatgpt"]) { defaultURL = @"https://api.openai.com/v1/images/generations"; defaultModel = @"gpt-image-1"; }
  else if ([low containsString:@"豆包"] || [low containsString:@"方舟"] || [low containsString:@"volcengine"] || [low containsString:@"doubao"]) { defaultURL = @"https://ark.cn-beijing.volces.com/api/v3/images/generations"; defaultModel = @"doubao-seedream-3-0-t2i-250415"; }
  else if ([low containsString:@"siliconflow"] || [low containsString:@"硅基流动"]) { defaultURL = @"https://api.siliconflow.cn/v1/images/generations"; defaultModel = @"Qwen/Qwen-Image"; }
  else if (base.length) defaultURL = [base stringByAppendingString:@"/images/generations"];
  if (((NSString *)e[@"imageAPI"]).length) defaultURL = e[@"imageAPI"];
  if (((NSString *)e[@"imageModel"]).length) defaultModel = e[@"imageModel"];
  else if (((NSString *)e[@"model"]).length) defaultModel = e[@"model"];
  self.aiImageURLField.stringValue = defaultURL;
  [self.aiImageModelField removeAllItems];
  if (defaultModel.length) [self.aiImageModelField addItemWithObjectValue:defaultModel];
  self.aiImageModelField.stringValue = defaultModel;
  if (!defaultURL.length) { self.aiImageStatus.stringValue = @"该服务没有可用的图片生成地址"; return; }
  if (!key.length) { self.aiImageStatus.stringValue = @"缺少 API Key，无法自动获取图片模型"; return; }
  self.aiImageStatus.stringValue = @"正在获取图片模型…";
  __weak typeof(self) weakSelf = self;
  NSString *imageModelListURL = base.length ? base : defaultURL;
  [self fetchModelsForPanel:self.aiImageModelField url:imageModelListURL key:key keywords:@[@"dall-e",@"gpt-image",@"image",@"flux",@"seedream",@"stable",@"sdxl",@"midjourney",@"imagen",@"kolors",@"z-image",@"qwen-image"] knownDefault:defaultModel completion:^(NSArray *models) {
    if (models.count) { weakSelf.aiImageStatus.stringValue = [NSString stringWithFormat:@"已获取 %ld 个图片模型", (long)models.count]; }
    else { [weakSelf.aiImageModelField removeAllItems]; if (defaultModel.length) [weakSelf.aiImageModelField addItemWithObjectValue:defaultModel]; weakSelf.aiImageModelField.stringValue = defaultModel; weakSelf.aiImageStatus.stringValue = @"未获取到图片模型，使用默认模型"; }
  }];
}


- (void)openAIImagePanel:(id)sender {
  if (!self.aiImageWindow) {
    self.aiImageWindow = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,660,620) styleMask:(NSWindowStyleMaskTitled|NSWindowStyleMaskClosable|NSWindowStyleMaskResizable) backing:NSBackingStoreBuffered defer:NO];
    self.aiImageWindow.title = @"AI 图片生成";
    self.aiImageWindow.releasedWhenClosed = NO;
    NSView *cv = self.aiImageWindow.contentView;
    NSTextField *t = [self label:@"AI 图片生成" size:20 bold:YES color:nil];
    t.frame=NSMakeRect(24,578,300,28); [cv addSubview:t];
    NSTextField *h = [self label:@"使用 AI 管理中的服务和 Key；默认调用 /images/generations" size:10.5 bold:NO color:[NSColor secondaryLabelColor]];
    h.frame=NSMakeRect(24,556,560,18); [cv addSubview:h];
    self.aiImageServicePopup = [[NSPopUpButton alloc] initWithFrame:NSMakeRect(24,520,160,28) pullsDown:NO];
    self.aiImageServicePopup.target=self; self.aiImageServicePopup.action=@selector(aiImageServiceChanged:);
    [cv addSubview:self.aiImageServicePopup];
    self.aiImageModelField = [[NSComboBox alloc] initWithFrame:NSMakeRect(190,520,230,28)];
