- (void)sendAIAssistant:(id)sender {
  if (self.aiAssistantBusy) return;
  NSInteger idx = [self.aiAssistantServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)self.aiEntries.count) { self.aiAssistantStatus.stringValue=@"请先在 AI 管理添加服务"; return; }
  NSDictionary *e = self.aiEntries[idx];
  NSString *key = e[@"api"] ?: @"";
  if (!key.length) { self.aiAssistantStatus.stringValue=@"该服务没有 API Key"; return; }
  NSString *url = self.aiAssistantURLField.stringValue;
  if (![url containsString:@"/chat/completions"]) {
    while ([url hasSuffix:@"/"]) url = [url substringToIndex:url.length - 1];
    url = [url stringByAppendingString:@"/chat/completions"];
  }
  NSString *base = url;
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length - @"/chat/completions".length];
  NSMutableDictionary *savedEntry = [e mutableCopy];
  savedEntry[@"apiBase"] = base;
  savedEntry[@"model"] = self.aiAssistantModelField.stringValue;
  self.aiEntries[idx] = savedEntry;
  [self saveAIEntries];
  NSString *model = self.aiAssistantModelField.stringValue;
  NSString *text = self.aiAssistantInput.string;
  if (!url.length || !model.length || !text.length) { self.aiAssistantStatus.stringValue=@"请填写 API 地址、模型和输入文本"; return; }
  NSInteger mode = self.aiAssistantModePopup.indexOfSelectedItem;
  NSString *sys = @"你是一个中文助手。回答要准确、简洁。";
  if (mode == 0) sys = @"请用中文总结用户内容，保留关键信息，输出简洁要点。";
  else if (mode == 1) sys = @"请润色用户内容，保持原意，使表达更自然、专业。";
  else if (mode == 2) sys = @"请把用户内容翻译成简体中文，只输出译文。";
  else sys = @"请按用户的要求处理内容。";
  NSMutableDictionary *body = [@{@"model": model, @"messages": @[@{@"role":@"system",@"content":sys},@{@"role":@"user",@"content":text}], @"temperature": @0.3} mutableCopy];
  NSString *reasonEffort = [self reasoningEffortForPopup:self.aiAssistantReasoningPopup];
  if (reasonEffort.length) body[@"reasoning_effort"] = reasonEffort;
  NSData *data = [NSJSONSerialization dataWithJSONObject:body options:0 error:NULL];
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod = @"POST";
  [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.HTTPBody = data;
  req.timeoutInterval = 60;
  self.aiAssistantBusy = YES;
  self.aiAssistantStatus.stringValue = @"请求中…";
  __weak typeof(self) weakSelf = self;
  NSURLSessionDataTask *task = [[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *respData, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      weakSelf.aiAssistantBusy = NO;
      if (err || !respData.length) { weakSelf.aiAssistantStatus.stringValue = err.localizedDescription ?: @"请求失败"; return; }
      id obj = [NSJSONSerialization JSONObjectWithData:respData options:0 error:NULL];
      NSString *content = nil;
      if ([obj isKindOfClass:[NSDictionary class]]) {
        NSArray *choices = obj[@"choices"];
        if ([choices isKindOfClass:[NSArray class]] && choices.count) {
          NSDictionary *msg = choices[0][@"message"];
          if ([msg isKindOfClass:[NSDictionary class]]) content = msg[@"content"];
        }
        if (!content.length) { id er=obj[@"error"]; if([er isKindOfClass:[NSDictionary class]]) content=er[@"message"]; else if([er isKindOfClass:[NSString class]]) content=er; }
      }
      if (content.length) { weakSelf.aiAssistantOutput.string = content; weakSelf.aiAssistantStatus.stringValue = @"完成"; }
      else { weakSelf.aiAssistantStatus.stringValue = @"没有解析到返回内容"; weakSelf.aiAssistantOutput.string = [[NSString alloc] initWithData:respData encoding:NSUTF8StringEncoding] ?: @""; }
    });
  }];
  [task resume];
}

- (void)extractAudioFromMediaAtPath:(NSString *)path completion:(void (^)(NSString *audioPath, NSError *error))completion {
  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:path] options:nil];
  if ([asset tracksWithMediaType:AVMediaTypeAudio].count == 0) {
    completion(nil, [NSError errorWithDomain:@"DockLaunchers" code:1 userInfo:@{NSLocalizedDescriptionKey: @"文件里没有音频轨道"}]);
    return;
  }
  if ([asset tracksWithMediaType:AVMediaTypeVideo].count == 0) { completion(path, nil); return; }
  NSString *tmp = [NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"dl-audio-%@.m4a", [[NSUUID UUID] UUIDString]]];
  AVAssetExportSession *ex = [AVAssetExportSession exportSessionWithAsset:asset presetName:AVAssetExportPresetAppleM4A];
  ex.outputURL = [NSURL fileURLWithPath:tmp];
  ex.outputFileType = AVFileTypeAppleM4A;
  [ex exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (ex.status == AVAssetExportSessionStatusCompleted) completion(tmp, nil);
      else completion(nil, ex.error ?: [NSError errorWithDomain:@"DockLaunchers" code:2 userInfo:@{NSLocalizedDescriptionKey: @"提取音频失败"}]);
    });
  }];
}

- (NSArray<NSDictionary *> *)sttServices {
  if (!self.aiEntries) [self loadAIEntries];
  [self hydrateAIKeys];
  NSMutableArray *out = [NSMutableArray array];
  for (NSDictionary *e in self.aiEntries) if ([e[@"api"] length] && [[self aiModelCategoryKey:e] isEqualToString:@"speech"]) [out addObject:e];
  return out;
}

- (NSInteger)sttSelectedServiceIndex {
  NSArray *services = [self sttServices];
  NSInteger saved = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerSTTServiceIndex"];
  if (saved >= 0 && saved < (NSInteger)services.count) return saved;
  return services.count ? 0 : -1;
}

- (NSString *)sttModelName {
  NSString *m = [[NSUserDefaults standardUserDefaults] stringForKey:@"centerSTTModel"];
  NSArray *services = [self sttServices];
  NSInteger idx = [self sttSelectedServiceIndex];
  BOOL silicon = NO;
  if (idx >= 0 && idx < (NSInteger)services.count) {
    NSString *name = [services[idx][@"name"] ?: @"" lowercaseString];
    silicon = [name containsString:@"siliconflow"] || [name containsString:@"硅基流动"];
  }
  if (silicon) {
    if (!m.length || [m isEqualToString:@"whisper-1"]) return @"FunAudioLLM/SenseVoiceSmall";
    return m;
  }
  return m.length ? m : @"whisper-1";
}

- (BOOL)sttUseThirdParty {
  return [[NSUserDefaults standardUserDefaults] integerForKey:@"centerSTTEngine"] == 1;
}

- (BOOL)sttUseLocalWhisper {
  return [[NSUserDefaults standardUserDefaults] integerForKey:@"centerSTTEngine"] == 2;
}

- (NSString *)chatCompletionsBaseForEntry:(NSDictionary *)entry {
  NSString *base = entry[@"apiBase"] ?: @"";
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length - 1];
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length - @"/chat/completions".length];
  return base;
}

- (void)transcribeThirdPartyMediaAtPath:(NSString *)path serviceIndex:(NSInteger)index model:(NSString *)model update:(void (^)(NSString *text, BOOL final, NSError *error))update {
  NSArray *services = [self sttServices];
  if (index < 0 || index >= (NSInteger)services.count) {
    update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:10 userInfo:@{NSLocalizedDescriptionKey: @"没有可用的第三方 AI 服务，请先在 AI 管理添加带 Key 的服务"}]);
    return;
  }
  NSDictionary *entry = services[index];
  NSString *base = [self chatCompletionsBaseForEntry:entry];
  if (!base.length) { update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:11 userInfo:@{NSLocalizedDescriptionKey: @"该 AI 服务没有 API 地址"}]); return; }
  NSString *url = [base stringByAppendingString:@"/audio/transcriptions"];
  [self extractAudioFromMediaAtPath:path completion:^(NSString *audio, NSError *err) {
    if (!audio.length) { update(nil, YES, err); return; }
    NSData *fileData = [NSData dataWithContentsOfFile:audio];
    if (!fileData.length) { update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:12 userInfo:@{NSLocalizedDescriptionKey: @"读取音频失败"}]); return; }
    NSString *boundary = [NSString stringWithFormat:@"DLBoundary%@", [[NSUUID UUID] UUIDString]];
    NSMutableData *body = [NSMutableData data];
    void (^field)(NSString *, NSString *) = ^(NSString *name, NSString *value) {
      [body appendData:[[NSString stringWithFormat:@"--%@\r\nContent-Disposition: form-data; name=\"%@\"\r\n\r\n%@\r\n", boundary, name, value] dataUsingEncoding:NSUTF8StringEncoding]];
    };
    field(@"model", model ?: @"whisper-1");
    NSString *lang=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerSTTLanguage"] ?: @"auto";
    if (![lang isEqualToString:@"auto"]) field(@"language", lang);
    field(@"response_format", @"json");
    [body appendData:[[NSString stringWithFormat:@"--%@\r\nContent-Disposition: form-data; name=\"file\"; filename=\"audio.m4a\"\r\nContent-Type: audio/mp4\r\n\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
    [body appendData:fileData];
    [body appendData:[[NSString stringWithFormat:@"\r\n--%@--\r\n", boundary] dataUsingEncoding:NSUTF8StringEncoding]];
    NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
    req.HTTPMethod = @"POST";
    req.timeoutInterval = 180;
    [req setValue:[@"multipart/form-data; boundary=" stringByAppendingString:boundary] forHTTPHeaderField:@"Content-Type"];
    [req setValue:[@"Bearer " stringByAppendingString:entry[@"api"] ?: @""] forHTTPHeaderField:@"Authorization"];
    req.HTTPBody = body;
    [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *error) {
      dispatch_async(dispatch_get_main_queue(), ^{
        if (error || !data.length) {
          NSString *msg = error.localizedDescription ?: @"第三方转写请求失败";
          update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:13 userInfo:@{NSLocalizedDescriptionKey: msg}]);
          return;
        }
        id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
        NSString *text = nil;
        BOOL hasTextKey = NO;
        if ([obj isKindOfClass:[NSDictionary class]]) {
          id raw = obj[@"text"];
          if ([raw isKindOfClass:[NSString class]]) { hasTextKey = YES; text = raw; }
          if (!text.length) {
            id er=obj[@"error"]; NSString *apiErr=nil; if([er isKindOfClass:[NSDictionary class]])apiErr=er[@"message"]; else if([er isKindOfClass:[NSString class]])apiErr=er; if(!apiErr)apiErr=obj[@"message"];
            if (apiErr.length) {
              update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:13 userInfo:@{NSLocalizedDescriptionKey: apiErr}]);
              return;
            }
          }
        } else if ([obj isKindOfClass:[NSString class]]) {
          text = obj;
        }
        if (hasTextKey && !text.length) {
          update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:14 userInfo:@{NSLocalizedDescriptionKey: @"没有识别到语音：请确认录屏包含麦克风人声，或录音不是静音"}]);
          return;
        }
        if (!text.length) {
          // 非 JSON 的纯文本响应才当作转写结果，避免把 JSON 元数据显示到界面
          NSString *plain = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
          if (plain.length && ![plain hasPrefix:@"{"]) text = plain;
        }
        if (text.length) update(text, YES, nil);
        else update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:15 userInfo:@{NSLocalizedDescriptionKey: @"第三方接口没有返回文字，请确认模型支持 /audio/transcriptions"}]);
      });
    }] resume];
  }];
}

- (void)transcribeMediaSmartAtPath:(NSString *)path update:(void (^)(NSString *text, BOOL final, NSError *error))update {
  if ([self sttUseLocalWhisper]) { [self transcribeLocalWhisperAtPath:path update:update]; return; }
  if (![self sttUseThirdParty]) { [self transcribeMediaAtPath:path update:update]; return; }
  NSInteger idx = [self sttSelectedServiceIndex];
  NSString *model = [self sttModelName];
  __weak typeof(self) weakSelf = self;
  [self transcribeThirdPartyMediaAtPath:path serviceIndex:idx model:model update:^(NSString *text, BOOL final, NSError *error) {
    if (text.length) { update(text, final, error); return; }
    // 第三方失败时回退到本机识别
    [weakSelf transcribeMediaAtPath:path update:update];
  }];
}

