- (void)speechEngineChanged:(id)sender {
  [self.speechServicePopup removeAllItems];
  NSArray *services = [self sttServices];
  for (NSInteger i=0;i<(NSInteger)services.count;i++) {
    NSString *name = services[i][@"name"] ?: [NSString stringWithFormat:@"服务 %ld", (long)(i+1)];
    [self.speechServicePopup addItemWithTitle:name];
    self.speechServicePopup.lastItem.representedObject = @(i);
  }
  if (!services.count) [self.speechServicePopup addItemWithTitle:@"未配置带 Key 的 AI 服务"];
  NSInteger saved = [self sttSelectedServiceIndex];
  if (saved >= 0 && saved < (NSInteger)self.speechServicePopup.numberOfItems) [self.speechServicePopup selectItemAtIndex:saved];
  NSInteger engine = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerSTTEngine"];
  if (engine < 0 || engine > 2) engine = 0;
  [self.speechEnginePopup selectItemAtIndex:engine];
  self.speechModelField.stringValue = [self sttModelName];
  NSString *lang=[[NSUserDefaults standardUserDefaults] stringForKey:@"centerSTTLanguage"] ?: @"auto";
  NSArray *langVals=@[@"auto",@"zh",@"en",@"ja"];
  [self.speechLanguagePopup selectItemAtIndex:MAX(0,[langVals indexOfObject:lang])];
  NSInteger sel = [self sttSelectedServiceIndex];
  NSArray *svc = [self sttServices];
  if (sel >= 0 && sel < (NSInteger)svc.count) {
    NSString *nm = [svc[sel][@"name"] ?: @"" lowercaseString];
    if (([nm containsString:@"siliconflow"] || [nm containsString:@"硅基流动"]) && [self.speechModelField.stringValue isEqualToString:@"whisper-1"]) self.speechModelField.stringValue = @"FunAudioLLM/SenseVoiceSmall";
  }
  self.speechServerCheck.state = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerSTTAllowServer"] ? NSControlStateValueOn : NSControlStateValueOff;
  BOOL api = engine == 1;
  self.speechServicePopup.enabled = api;
  self.speechModelField.enabled = api;
  self.speechServerCheck.enabled = engine == 0;
  [self speechSettingChanged:nil];
}

- (void)speechServiceChanged:(id)sender {
  NSInteger idx = [self.speechServicePopup.selectedItem.representedObject integerValue];
  NSArray *services = [self sttServices];
  if (idx < 0 || idx >= (NSInteger)services.count) return;
  NSDictionary *e = services[idx];
  NSString *name = [e[@"name"] ?: @"" lowercaseString];
  if ([name containsString:@"siliconflow"] || [name containsString:@"硅基流动"]) self.speechModelField.stringValue = @"FunAudioLLM/SenseVoiceSmall";
  else if ([name containsString:@"openai"]) self.speechModelField.stringValue = @"whisper-1";
  else if (!self.speechModelField.stringValue.length) self.speechModelField.stringValue = @"whisper-1";
  [self speechSettingChanged:nil];
}

- (void)speechSettingChanged:(id)sender {
  NSInteger engine = self.speechEnginePopup.indexOfSelectedItem;
  self.speechServicePopup.enabled = engine == 1;
  self.speechModelField.enabled = engine == 1;
  self.speechLanguagePopup.enabled = engine == 1;
  self.speechServerCheck.enabled = engine == 0;
}

- (void)saveSpeechSettings:(id)sender {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  [ud setInteger:self.speechEnginePopup.indexOfSelectedItem forKey:@"centerSTTEngine"];
  if (self.speechServicePopup.selectedItem.representedObject) [ud setInteger:[self.speechServicePopup.selectedItem.representedObject integerValue] forKey:@"centerSTTServiceIndex"];
  [ud setObject:(self.speechModelField.stringValue.length ? self.speechModelField.stringValue : @"whisper-1") forKey:@"centerSTTModel"];
  NSArray *langVals=@[@"auto",@"zh",@"en",@"ja"];
  [ud setObject:langVals[MAX(0,MIN(3,self.speechLanguagePopup.indexOfSelectedItem))] forKey:@"centerSTTLanguage"];
  [ud setBool:(self.speechServerCheck.state == NSControlStateValueOn) forKey:@"centerSTTAllowServer"];
  [ud synchronize];
  [self.speechSettingsWindow orderOut:nil];
  NSInteger eng = self.speechEnginePopup.indexOfSelectedItem;
  [self showToast:(eng == 1 ? @"已切换到第三方语音转写" : (eng == 2 ? @"已切换到本地 Whisper" : @"已切换到本机语音识别"))];
}

- (void)closeSpeechSettings:(id)sender { [self.speechSettingsWindow orderOut:nil]; }

- (void)transcribeMediaAtPath:(NSString *)path update:(void (^)(NSString *text, BOOL final, NSError *error))update {
  if (!path.length) { update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:3 userInfo:@{NSLocalizedDescriptionKey: @"没有选择文件"}]); return; }
  [self extractAudioFromMediaAtPath:path completion:^(NSString *audio, NSError *err) {
    if (!audio.length) { update(nil, YES, err); return; }
    [SFSpeechRecognizer requestAuthorization:^(SFSpeechRecognizerAuthorizationStatus status) {
      dispatch_async(dispatch_get_main_queue(), ^{
        if (status != SFSpeechRecognizerAuthorizationStatusAuthorized) {
          update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:4 userInfo:@{NSLocalizedDescriptionKey: @"语音识别权限未授权，请在系统设置中允许"}]);
          return;
        }
        SFSpeechRecognizer *rec = [[SFSpeechRecognizer alloc] initWithLocale:[NSLocale localeWithLocaleIdentifier:@"zh-CN"]];
        if (!rec || !rec.isAvailable) { update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:5 userInfo:@{NSLocalizedDescriptionKey: @"中文语音识别当前不可用"}]); return; }
        self.speechRecognizer = rec;
        SFSpeechURLRecognitionRequest *req = [[SFSpeechURLRecognitionRequest alloc] initWithURL:[NSURL fileURLWithPath:audio]];
        req.shouldReportPartialResults = YES;
        req.taskHint = SFSpeechRecognitionTaskHintDictation;
        if ([req respondsToSelector:@selector(setAddsPunctuation:)]) req.addsPunctuation = YES;
        BOOL allowServer = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerSTTAllowServer"];
        if (allowServer) {
          req.requiresOnDeviceRecognition = NO;
        } else if ([rec supportsOnDeviceRecognition]) {
          req.requiresOnDeviceRecognition = YES;
        } else {
          update(nil, YES, [NSError errorWithDomain:@"DockLaunchers" code:6 userInfo:@{NSLocalizedDescriptionKey: @"本机离线中文语音模型不可用，请在转写设置中允许 Apple 云端识别，或改用第三方 Whisper"}]);
          return;
        }
        SFSpeechRecognitionTask *task = [rec recognitionTaskWithRequest:req resultHandler:^(SFSpeechRecognitionResult *result, NSError *error) {
          dispatch_async(dispatch_get_main_queue(), ^{
            if (result) {
              NSString *text = result.bestTranscription.formattedString ?: @"";
              update(text, result.isFinal, nil);
            } else if (error) {
              update(nil, YES, error);
            }
          });
        }];
        self.activeSpeechTask = task;
      });
    }];
  }];
}

- (void)chooseMediaForTranscription:(void (^)(NSString *path))done {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = YES; p.canChooseDirectories = NO; p.allowsMultipleSelection = NO;
  p.allowedFileTypes = @[@"mp4", @"mov", @"m4v", @"m4a", @"mp3", @"wav", @"aiff", @"caf"];
  if ([p runModal] == NSModalResponseOK && p.URL.path.length) done(p.URL.path);
}

- (NSArray<NSDictionary *> *)ttsServices {
  if (!self.aiEntries) [self loadAIEntries];
  [self hydrateAIKeys];
  NSMutableArray *out = [NSMutableArray array];
  for (NSDictionary *e in self.aiEntries) if ([e[@"api"] length] && [[self aiModelCategoryKey:e] isEqualToString:@"speech"]) [out addObject:e];
  return out;
}

