- (void)reloadAITTSServices {
  [self.aiTTSServicePopup removeAllItems];
  NSArray *services = [self ttsServices];
  for (NSInteger i=0;i<(NSInteger)services.count;i++) {
    NSDictionary *e = services[i];
    [self.aiTTSServicePopup addItemWithTitle:e[@"name"] ?: @"未命名"];
    self.aiTTSServicePopup.lastItem.representedObject = @(i);
  }
  if (!services.count) {
    [self.aiTTSServicePopup addItemWithTitle:@"请先在 AI 管理设置语音模型"];
    self.aiTTSServicePopup.enabled=NO;
    self.aiTTSStatus.stringValue=@"没有语音模型，请把支持 TTS 的服务分类设为「语音」";
  } else {
    self.aiTTSServicePopup.enabled=YES;
    [self.aiTTSServicePopup selectItemAtIndex:0];
    [self aiTTSServiceChanged:nil];
  }
}

- (void)aiTTSServiceChanged:(id)sender {
  NSArray *services = [self ttsServices];
  NSInteger idx = [self.aiTTSServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)services.count) return;
  NSDictionary *e = services[idx];
  NSString *name = [e[@"name"] ?: @"" lowercaseString];
  NSString *base = e[@"apiBase"] ?: @"";
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length-1];
  if ([base hasSuffix:@"/chat/completions"]) base = [base substringToIndex:base.length-@"/chat/completions".length];
  self.aiTTSURLField.stringValue = base.length ? [base stringByAppendingString:@"/audio/speech"] : @"";
  [self.aiTTSModelField removeAllItems];
  if ([name containsString:@"siliconflow"] || [name containsString:@"硅基流动"]) {
    [self.aiTTSModelField addItemsWithTitles:@[@"FunAudioLLM/CosyVoice2-0.5B", @"fnlp/MOSS-TTSD-v0.5"]];
  } else if ([name containsString:@"openai"]) {
    [self.aiTTSModelField addItemsWithTitles:@[@"gpt-4o-mini-tts", @"tts-1"]];
  } else {
    [self.aiTTSModelField addItemsWithTitles:@[@"tts-1"]];
  }
  [self aiTTSModelChanged:nil];
}

- (void)aiTTSModelChanged:(id)sender {
  NSString *model = self.aiTTSModelField.titleOfSelectedItem ?: @"";
  [self.aiTTSVoiceField removeAllItems];
  NSArray *titles = nil, *ids = nil;
  if ([model containsString:@"CosyVoice"]) {
    titles = @[@"亚历克斯（Alex）", @"安娜（Anna）", @"贝拉（Bella）", @"本杰明（Benjamin）", @"查尔斯（Charles）", @"克莱尔（Claire）"];
    ids = @[@"FunAudioLLM/CosyVoice2-0.5B:alex", @"FunAudioLLM/CosyVoice2-0.5B:anna", @"FunAudioLLM/CosyVoice2-0.5B:bella", @"FunAudioLLM/CosyVoice2-0.5B:benjamin", @"FunAudioLLM/CosyVoice2-0.5B:charles", @"FunAudioLLM/CosyVoice2-0.5B:claire"];
  } else if ([model containsString:@"MOSS"]) {
    titles = @[@"亚历克斯（Alex）", @"安娜（Anna）"];
    ids = @[@"fnlp/MOSS-TTSD-v0.5:alex", @"fnlp/MOSS-TTSD-v0.5:anna"];
  } else {
    titles = @[@"合金（Alloy）", @"回声（Echo）", @"寓言（Fable）", @"玛瑙（Onyx）", @"新星（Nova）", @"微光（Shimmer）"];
    ids = @[@"alloy", @"echo", @"fable", @"onyx", @"nova", @"shimmer"];
  }
  for (NSInteger i = 0; i < (NSInteger)titles.count; i++) {
    [self.aiTTSVoiceField addItemWithTitle:titles[i]];
    self.aiTTSVoiceField.lastItem.representedObject = ids[i];
    self.aiTTSVoiceField.lastItem.toolTip = ids[i];
  }
}

- (void)auditionAITTSVoice:(id)sender {
  NSArray *services = [self ttsServices];
  NSInteger idx = [self.aiTTSServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)services.count) { self.aiTTSStatus.stringValue=@"请先选择语音服务"; return; }
  NSDictionary *e = services[idx];
  NSString *key = e[@"api"] ?: @"";
  NSString *url = self.aiTTSURLField.stringValue;
  NSString *model = self.aiTTSModelField.titleOfSelectedItem ?: @"";
  NSString *voice = self.aiTTSVoiceField.selectedItem.representedObject ?: self.aiTTSVoiceField.titleOfSelectedItem ?: @"";
  if (!key.length || !url.length || !model.length || !voice.length) { self.aiTTSStatus.stringValue=@"请先配置服务、模型和音色"; return; }
  NSDictionary *body = @{@"model":model,@"input":@"你好，这是 DockLaunchers 的音色试听。",@"voice":voice,@"response_format":@"mp3"};
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod=@"POST"; req.timeoutInterval=60;
  [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:NULL];
  self.aiTTSStatus.stringValue=@"正在试听…";
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (err || !data.length) { weakSelf.aiTTSStatus.stringValue=err.localizedDescription ?: @"试听失败"; return; }
      NSString *path = [NSTemporaryDirectory() stringByAppendingPathComponent:@"dl-tts-preview.mp3"];
      [[NSFileManager defaultManager] removeItemAtPath:path error:NULL];
      if (![data writeToFile:path atomically:YES]) { weakSelf.aiTTSStatus.stringValue=@"试听文件写入失败"; return; }
      NSSound *sound = [[NSSound alloc] initWithContentsOfFile:path byReference:YES];
      [sound play];
      weakSelf.aiTTSStatus.stringValue = [NSString stringWithFormat:@"试听：%@", weakSelf.aiTTSVoiceField.titleOfSelectedItem ?: @""];
    });
  }] resume];
}

- (void)chooseAITTSVideoTarget:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles = YES; p.canChooseDirectories = NO; p.allowsMultipleSelection = NO;
  p.allowedFileTypes = @[@"mp4", @"mov", @"m4v"];
  if ([p runModal] != NSModalResponseOK) return;
  self.aiTTSTargetVideoPath = p.URL.path;
  self.aiTTSStatus.stringValue = [NSString stringWithFormat:@"已选择视频：%@，生成配音后会合成", p.URL.lastPathComponent];
}

- (void)muxTTSAudio:(NSString *)audioPath intoVideo:(NSString *)videoPath output:(NSString *)output keepOriginal:(BOOL)keepOriginal completion:(void (^)(NSError *error))completion {
  AVURLAsset *videoAsset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:videoPath] options:nil];
  AVURLAsset *audioAsset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:audioPath] options:nil];
  [videoAsset loadValuesAsynchronouslyForKeys:@[@"duration", @"tracks"] completionHandler:^{
    [videoAsset loadTracksWithMediaType:AVMediaTypeVideo completionHandler:^(NSArray<AVAssetTrack *> *videoTracks, NSError *ve) {
      if (ve || !videoTracks.count) {
        dispatch_async(dispatch_get_main_queue(), ^{ completion(ve ?: [NSError errorWithDomain:@"DockLaunchers" code:50 userInfo:@{NSLocalizedDescriptionKey:@"视频没有画面轨道"}]); });
        return;
      }
      [videoAsset loadTracksWithMediaType:AVMediaTypeAudio completionHandler:^(NSArray<AVAssetTrack *> *videoAudio, NSError *ae) {
        [audioAsset loadValuesAsynchronouslyForKeys:@[@"duration", @"tracks"] completionHandler:^{
          [audioAsset loadTracksWithMediaType:AVMediaTypeAudio completionHandler:^(NSArray<AVAssetTrack *> *ttsTracks, NSError *te) {
            dispatch_async(dispatch_get_main_queue(), ^{
              if (te || !ttsTracks.count) { completion(te ?: [NSError errorWithDomain:@"DockLaunchers" code:51 userInfo:@{NSLocalizedDescriptionKey:@"配音音频没有音轨"}]); return; }
              AVMutableComposition *comp = [AVMutableComposition composition];
              NSError *err = nil;
              CMTime videoDuration = videoAsset.duration;
              AVMutableCompositionTrack *vt = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
              [vt insertTimeRange:CMTimeRangeMake(kCMTimeZero, videoDuration) ofTrack:videoTracks[0] atTime:kCMTimeZero error:&err];
              if (err) { completion(err); return; }
              if (keepOriginal && videoAudio.count) {
                for (AVAssetTrack *at in videoAudio) {
                  AVMutableCompositionTrack *ct = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
                  [ct insertTimeRange:CMTimeRangeMake(kCMTimeZero, videoDuration) ofTrack:at atTime:kCMTimeZero error:NULL];
                }
              }
              CMTime ttsDuration = audioAsset.duration;
              CMTime useDuration = CMTimeCompare(ttsDuration, videoDuration) < 0 ? ttsDuration : videoDuration;
              AVMutableCompositionTrack *tts = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
              [tts insertTimeRange:CMTimeRangeMake(kCMTimeZero, useDuration) ofTrack:ttsTracks[0] atTime:kCMTimeZero error:NULL];
              AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPresetHighestQuality];
              ex.outputURL = [NSURL fileURLWithPath:output];
              ex.outputFileType = AVFileTypeMPEG4;
              [ex exportAsynchronouslyWithCompletionHandler:^{
                dispatch_async(dispatch_get_main_queue(), ^{
                  if (ex.status == AVAssetExportSessionStatusCompleted) completion(nil);
                  else completion(ex.error ?: [NSError errorWithDomain:@"DockLaunchers" code:52 userInfo:@{NSLocalizedDescriptionKey:@"视频配音合成失败"}]);
                });
              }];
            });
          }];
        }];
      }];
    }];
  }];
}

- (void)generateAITTS:(id)sender {
  NSArray *services = [self ttsServices];
  NSInteger idx = [self.aiTTSServicePopup.selectedItem.representedObject integerValue];
  if (idx < 0 || idx >= (NSInteger)services.count) { self.aiTTSStatus.stringValue=@"请先配置语音模型"; return; }
  NSDictionary *e = services[idx];
  NSString *key = e[@"api"] ?: @"";
  NSString *url = self.aiTTSURLField.stringValue;
  NSString *model = self.aiTTSModelField.titleOfSelectedItem ?: @"";
  NSString *voice = self.aiTTSVoiceField.selectedItem.representedObject ?: self.aiTTSVoiceField.titleOfSelectedItem ?: @"";
  NSString *text = self.aiTTSText.string;
  if (!key.length || !url.length || !model.length || !voice.length || !text.length) { self.aiTTSStatus.stringValue=@"请填写服务、模型、音色和文本"; return; }
  NSDictionary *body = @{@"model":model,@"input":text,@"voice":voice,@"response_format":@"mp3"};
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod=@"POST"; req.timeoutInterval=180;
  [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  [req setValue:[@"Bearer " stringByAppendingString:key] forHTTPHeaderField:@"Authorization"];
  req.HTTPBody=[NSJSONSerialization dataWithJSONObject:body options:0 error:NULL];
  self.aiTTSStatus.stringValue=@"正在合成语音…";
  __weak typeof(self) weakSelf=self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (err || !data.length) { weakSelf.aiTTSStatus.stringValue=err.localizedDescription ?: @"语音合成失败"; return; }
      NSString *dir=[self aiTTSOutputDirectory];
      NSDateFormatter *df=[[NSDateFormatter alloc] init]; df.dateFormat=@"yyyyMMdd-HHmmss";
      NSString *path=[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"AI语音-%@.mp3",[df stringFromDate:[NSDate date]]]];
      if (![data writeToFile:path atomically:YES]) { weakSelf.aiTTSStatus.stringValue=@"语音保存失败"; return; }
      weakSelf.aiTTSResultPath=path;
      weakSelf.aiTTSStatus.stringValue=[NSString stringWithFormat:@"已生成：%@",path.lastPathComponent];
      NSSound *sound=[[NSSound alloc] initWithContentsOfFile:path byReference:YES];
      [sound play];
      if (weakSelf.aiTTSTargetVideoPath.length) {
        NSDateFormatter *vdf=[[NSDateFormatter alloc] init]; vdf.dateFormat=@"yyyyMMdd-HHmmss";
        NSString *videoOut=[[weakSelf aiVideoOutputDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"AI配音-%@.mp4",[vdf stringFromDate:[NSDate date]]]];
        weakSelf.aiTTSStatus.stringValue=@"正在合成视频配音…";
        [weakSelf muxTTSAudio:path intoVideo:weakSelf.aiTTSTargetVideoPath output:videoOut keepOriginal:(weakSelf.aiTTSKeepOriginalCheck.state == NSControlStateValueOn) completion:^(NSError *muxError) {
          if (muxError) weakSelf.aiTTSStatus.stringValue = muxError.localizedDescription ?: @"视频配音合成失败";
          else { weakSelf.aiTTSVideoResultPath = videoOut; weakSelf.aiTTSStatus.stringValue = [NSString stringWithFormat:@"配音视频已生成：%@", videoOut.lastPathComponent]; }
        }];
      }
    });
  }] resume];
}

- (void)saveAITTSResult:(id)sender {
  if (!self.aiTTSResultPath.length || ![[NSFileManager defaultManager] fileExistsAtPath:self.aiTTSResultPath]) {
    [self showToast:@"还没有生成语音"];
    return;
  }
  NSSavePanel *sp = [NSSavePanel savePanel];
  sp.allowedFileTypes = @[@"mp3"];
  sp.nameFieldStringValue = self.aiTTSResultPath.lastPathComponent;
  if ([sp runModal] != NSModalResponseOK) return;
  NSError *err = nil;
  [[NSFileManager defaultManager] removeItemAtPath:sp.URL.path error:NULL];
  if ([[NSFileManager defaultManager] copyItemAtPath:self.aiTTSResultPath toPath:sp.URL.path error:&err]) {
    self.aiTTSStatus.stringValue = [NSString stringWithFormat:@"已保存：%@", sp.URL.lastPathComponent];
    [self showToast:@"语音已另存"];
  } else {
    self.aiTTSStatus.stringValue = err.localizedDescription ?: @"保存失败";
  }
}

- (void)openAITTSVideoResult:(id)sender {
  if (!self.aiTTSVideoResultPath.length || ![[NSFileManager defaultManager] fileExistsAtPath:self.aiTTSVideoResultPath]) { [self showToast:@"还没有合成配音视频"]; return; }
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.aiTTSVideoResultPath]];
}

- (void)openAITTSResult:(id)sender {
  if (!self.aiTTSResultPath.length) { [self showToast:@"还没有生成语音"]; return; }
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.aiTTSResultPath]];
}

- (void)clearAITTSPanel:(id)sender {
  self.aiTTSText.string=@"";
  self.aiTTSResultPath=nil;
  self.aiTTSVideoResultPath=nil;
  self.aiTTSTargetVideoPath=nil;
  self.aiTTSStatus.stringValue=@"已清空";
}

