- (void)burnMeetingSubtitles:(id)sender {
  if (!self.meetingPath.length) { [self showToast:@"请先选择录屏"]; return; }
  NSString *text = self.meetingTranscript.string ?: @"";
  if (!text.length) { [self showToast:@"请先完成会议转写"]; return; }
  NSSavePanel *sp = [NSSavePanel savePanel];
  sp.allowedFileTypes = @[@"mp4"];
  sp.nameFieldStringValue = @"会议字幕版.mp4";
  if ([sp runModal] != NSModalResponseOK) return;
  NSString *out = sp.URL.path;
  [[NSFileManager defaultManager] removeItemAtPath:out error:NULL];
  self.meetingStatus.stringValue = @"正在烧录字幕…";
  [self burnSubtitlesIntoVideo:self.meetingPath transcript:text output:out completion:^(NSError *error) {
    self.meetingStatus.stringValue = error ? (error.localizedDescription ?: @"字幕烧录失败") : [NSString stringWithFormat:@"已生成字幕视频：%@", out.lastPathComponent];
    if (!error) [self showToast:@"字幕视频已生成"];
  }];
}

- (void)burnSubtitlesIntoVideo:(NSString *)videoPath transcript:(NSString *)transcript output:(NSString *)output completion:(void (^)(NSError *error))completion {
  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:videoPath] options:nil];
  [asset loadValuesAsynchronouslyForKeys:@[@"duration"] completionHandler:^{
    [asset loadTracksWithMediaType:AVMediaTypeVideo completionHandler:^(NSArray<AVAssetTrack *> *videoTracks, NSError *videoError) {
      if (videoError || !videoTracks.count) {
        dispatch_async(dispatch_get_main_queue(), ^{ completion([NSError errorWithDomain:@"DockLaunchers" code:30 userInfo:@{NSLocalizedDescriptionKey:videoError.localizedDescription ?: @"视频没有画面轨道"}]); });
        return;
      }
      [asset loadTracksWithMediaType:AVMediaTypeAudio completionHandler:^(NSArray<AVAssetTrack *> *audioTracks, NSError *audioError) {
        dispatch_async(dispatch_get_main_queue(), ^{
          [self burnSubtitlesLoadedAsset:asset videoTracks:videoTracks audioTracks:audioTracks transcript:transcript output:output completion:completion];
        });
      }];
    }];
  }];
}

- (void)burnSubtitlesLoadedAsset:(AVURLAsset *)asset videoTracks:(NSArray<AVAssetTrack *> *)videoTracks audioTracks:(NSArray<AVAssetTrack *> *)audioTracks transcript:(NSString *)transcript output:(NSString *)output completion:(void (^)(NSError *error))completion {
  AVMutableComposition *comp = [AVMutableComposition composition];
  NSError *err = nil;
  AVMutableCompositionTrack *vt = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
  [vt insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:videoTracks[0] atTime:kCMTimeZero error:&err];
  if (err) { completion(err); return; }
  for (AVAssetTrack *at in audioTracks) {
    AVMutableCompositionTrack *ct = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
    [ct insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:at atTime:kCMTimeZero error:NULL];
  }
  AVMutableVideoComposition *vc = [AVMutableVideoComposition videoComposition];
  vc.renderSize = videoTracks[0].naturalSize;
  vc.frameDuration = CMTimeMake(1, 30);
  AVMutableVideoCompositionInstruction *instruction = [AVMutableVideoCompositionInstruction videoCompositionInstruction];
  instruction.timeRange = CMTimeRangeMake(kCMTimeZero, comp.duration);
  AVMutableVideoCompositionLayerInstruction *layerInstruction = [AVMutableVideoCompositionLayerInstruction videoCompositionLayerInstructionWithAssetTrack:vt];
  [layerInstruction setTransform:videoTracks[0].preferredTransform atTime:kCMTimeZero];
  instruction.layerInstructions = @[layerInstruction];
  vc.instructions = @[instruction];
  CGSize size = vc.renderSize;
  CGFloat duration = CMTimeGetSeconds(asset.duration);
  NSMutableArray *lines = [NSMutableArray array];
  NSArray *rawLines = [transcript componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"\n。！？!?"]];
  for (NSString *raw in rawLines) {
    NSString *line = [raw stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
    if (!line.length) continue;
    while (line.length > 32) {
      [lines addObject:[line substringToIndex:32]];
      line = [line substringFromIndex:32];
    }
    if (line.length) [lines addObject:line];
  }
  if (!lines.count) { completion([NSError errorWithDomain:@"DockLaunchers" code:31 userInfo:@{NSLocalizedDescriptionKey:@"没有可烧录的字幕"}]); return; }
  CGFloat cue = MAX(1.2, MIN(4.0, duration / MAX(1, (NSInteger)lines.count)));
  CALayer *parent = [CALayer layer];
  parent.frame = CGRectMake(0, 0, size.width, size.height);
  parent.masksToBounds = YES;
  CALayer *videoLayer = [CALayer layer];
  videoLayer.frame = parent.frame;
  [parent addSublayer:videoLayer];
  NSUserDefaults *subUD = [NSUserDefaults standardUserDefaults];
  NSInteger fontSizeLevel = [subUD objectForKey:@"centerSubtitleFontSize"] ? [subUD integerForKey:@"centerSubtitleFontSize"] : 1;
  CGFloat fontScale = fontSizeLevel == 0 ? 0.75 : (fontSizeLevel == 2 ? 1.35 : 1.0);
  CGFloat fontSize = MAX(16, (size.width / 34.0) * fontScale);
  NSInteger colorIndex = [subUD integerForKey:@"centerSubtitleColor"];
  NSColor *subColor = colorIndex == 1 ? [NSColor systemYellowColor] : (colorIndex == 2 ? [NSColor systemGreenColor] : (colorIndex == 3 ? [NSColor blackColor] : [NSColor whiteColor]));
  NSInteger position = [subUD integerForKey:@"centerSubtitlePosition"];
  for (NSInteger i = 0; i < (NSInteger)lines.count; i++) {
    CGFloat start = i * cue;
    if (start >= duration) break;
    CGFloat end = MIN(duration, start + cue);
    CATextLayer *text = [CATextLayer layer];
    text.string = lines[i];
    text.font = (__bridge CFTypeRef)[NSFont boldSystemFontOfSize:fontSize];
    text.fontSize = fontSize;
    text.foregroundColor = subColor.CGColor;
    text.backgroundColor = (colorIndex == 3 ? [[NSColor whiteColor] colorWithAlphaComponent:0.65] : [[NSColor blackColor] colorWithAlphaComponent:0.55]).CGColor;
    text.alignmentMode = kCAAlignmentCenter;
    text.wrapped = YES;
    text.contentsScale = 2.0;
    text.cornerRadius = fontSize * 0.25;
    CGFloat posY = position == 2 ? size.height * 0.82 : (position == 1 ? size.height * 0.42 : size.height * 0.07);
    text.frame = CGRectMake(size.width * 0.06, posY, size.width * 0.88, fontSize * 2.6);
    text.opacity = 0;
    CAKeyframeAnimation *anim = [CAKeyframeAnimation animationWithKeyPath:@"opacity"];
    anim.values = @[@0.0, @1.0, @1.0, @0.0];
    anim.keyTimes = @[@0.0, @0.06, @0.88, @1.0];
    anim.beginTime = start;
    anim.duration = MAX(0.2, end - start);
    anim.fillMode = kCAFillModeForwards;
    anim.removedOnCompletion = NO;
    [text addAnimation:anim forKey:@"subtitle"];
    [parent addSublayer:text];
  }
  vc.animationTool = [AVVideoCompositionCoreAnimationTool videoCompositionCoreAnimationToolWithPostProcessingAsVideoLayer:videoLayer inLayer:parent];
  AVAssetExportSession *ex = [[AVAssetExportSession alloc] initWithAsset:comp presetName:AVAssetExportPresetHighestQuality];
  ex.videoComposition = vc;
  ex.outputURL = [NSURL fileURLWithPath:output];
  ex.outputFileType = AVFileTypeMPEG4;
  ex.shouldOptimizeForNetworkUse = YES;
  [ex exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      if (ex.status == AVAssetExportSessionStatusCompleted) completion(nil);
      else completion(ex.error ?: [NSError errorWithDomain:@"DockLaunchers" code:32 userInfo:@{NSLocalizedDescriptionKey:@"字幕导出失败"}]);
    });
  }];
}

- (void)exportMeetingTranscript:(NSPopUpButton *)sender {
  NSString *transcript = self.meetingTranscript.string ?: @"";
  NSString *summary = self.meetingSummary.string ?: @"";
  if (!transcript.length && !summary.length) { [self showToast:@"没有可导出的内容"]; return; }
  NSInteger idx = sender.indexOfSelectedItem;
  NSString *ext = idx == 1 ? @"md" : (idx == 2 ? @"srt" : @"txt");
  NSSavePanel *sp = [NSSavePanel savePanel];
  sp.allowedFileTypes = @[ext];
  sp.nameFieldStringValue = [NSString stringWithFormat:@"会议纪要.%@", ext];
  if ([sp runModal] != NSModalResponseOK) return;
  NSString *content = @"";
  if (idx == 2) {
    NSMutableString *srt = [NSMutableString string];
    NSArray *parts = [transcript componentsSeparatedByCharactersInSet:[NSCharacterSet characterSetWithCharactersInString:@"。！？\n"]];
    NSInteger n = 0;
    double start = 0;
    for (NSString *p in parts) {
      NSString *line = [p stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
      if (!line.length) continue;
      n++;
      double end = start + 3.0;
      [srt appendFormat:@"%ld\n%02ld:%02ld:%02ld,000 --> %02ld:%02ld:%02ld,000\n%@\n\n", (long)n, (long)(start/3600), (long)((long)start%3600)/60, (long)((long)start%60), (long)(end/3600), (long)((long)end%3600)/60, (long)((long)end%60), line];
      start = end;
    }
    content = srt;
  } else if (idx == 1) {
    content = [NSString stringWithFormat:@"# 会议纪要\n\n## 会议转写\n\n%@\n\n## AI 会议纪要\n\n%@\n", transcript, summary];
  } else {
    content = [NSString stringWithFormat:@"会议转写\n%@\n\nAI 会议纪要\n%@\n", transcript, summary];
  }
  [content writeToFile:sp.URL.path atomically:YES encoding:NSUTF8StringEncoding error:NULL];
  self.meetingStatus.stringValue = [NSString stringWithFormat:@"已导出：%@", sp.URL.lastPathComponent];
}

- (void)closeMeetingAssistant:(id)sender { [self.meetingWindow orderOut:nil]; }

- (void)pickMeetingFile:(id)sender {
  [self chooseMediaForTranscription:^(NSString *path) {
    self.meetingPath = path;
    self.meetingPathLabel.stringValue = path.lastPathComponent;
    self.meetingStatus.stringValue = @"已选择录屏，点击开始转写";
  }];
}

- (void)startMeetingTranscript:(id)sender {
  if (!self.meetingPath.length) { self.meetingStatus.stringValue = @"请先选择录屏文件"; return; }
  self.meetingTranscript.string = @"";
  self.meetingSummary.string = @"";
  self.meetingStatus.stringValue = @"正在识别语音…";
  [self transcribeMediaSmartAtPath:self.meetingPath update:^(NSString *text, BOOL final, NSError *error) {
    if (text.length) self.meetingTranscript.string = text;
    if (final) {
      if (error) self.meetingStatus.stringValue = error.localizedDescription ?: @"转写失败";
      else if (!self.meetingTranscript.string.length) self.meetingStatus.stringValue = @"没有识别到语音：请确认录屏包含麦克风声音，或换一个带人声的录屏";
      else self.meetingStatus.stringValue = @"转写完成，可生成 AI 纪要";
    }
  }];
}

- (void)summarizeMeeting:(id)sender {
  NSString *text = self.meetingTranscript.string;
  if (text.length < 10) { self.meetingStatus.stringValue = @"请先完成转写"; return; }
  if (!self.aiEntries) [self loadAIEntries];
  [self hydrateAIKeys];
  NSDictionary *entry = nil;
  for (NSDictionary *e in self.aiEntries) if ([e[@"api"] length] && [[self aiModelCategoryKey:e] isEqualToString:@"text"]) { entry = e; break; }
  if (!entry) { self.meetingStatus.stringValue = @"请先在 AI 管理添加带 Key 的服务"; return; }
  NSString *base = entry[@"apiBase"] ?: @"";
  while ([base hasSuffix:@"/"]) base = [base substringToIndex:base.length-1];
  NSString *url = [base containsString:@"/chat/completions"] ? base : [base stringByAppendingString:@"/chat/completions"];
  NSString *model = entry[@"model"] ?: @"deepseek-chat";
  NSString *sys = @"你是会议纪要助手。根据转写内容输出：1. 会议主题 2. 关键结论 3. 行动项（负责人/时间，如有） 4. 待确认问题。使用中文，简洁分点。";
  NSDictionary *body = @{@"model": model, @"messages": @[@{@"role":@"system",@"content":sys}, @{@"role":@"user",@"content":text}], @"temperature": @0.2};
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:[NSURL URLWithString:url]];
  req.HTTPMethod = @"POST"; req.timeoutInterval = 120;
  [req setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];
  [req setValue:[@"Bearer " stringByAppendingString:entry[@"api"] ?: @""] forHTTPHeaderField:@"Authorization"];
  req.HTTPBody = [NSJSONSerialization dataWithJSONObject:body options:0 error:NULL];
  self.meetingStatus.stringValue = @"AI 正在生成会议纪要…";
  __weak typeof(self) weakSelf = self;
  [[[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      NSString *out = nil;
      id obj = data.length ? [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL] : nil;
      if ([obj isKindOfClass:[NSDictionary class]]) {
        NSArray *choices = obj[@"choices"];
        if ([choices isKindOfClass:[NSArray class]] && choices.count) out = choices[0][@"message"][@"content"];
        if (!out.length) { id er=obj[@"error"]; if([er isKindOfClass:[NSDictionary class]]) out=er[@"message"]; else if([er isKindOfClass:[NSString class]]) out=er; }
      }
      if (out.length) { weakSelf.meetingSummary.string = out; weakSelf.meetingStatus.stringValue = @"会议纪要已生成"; }
      else weakSelf.meetingStatus.stringValue = err.localizedDescription ?: @"生成失败";
    });
  }] resume];
}

