- (void)pickVideoForPost:(id)sender {
  NSOpenPanel *p = [NSOpenPanel openPanel];
  p.canChooseFiles=YES; p.canChooseDirectories=NO; p.allowsMultipleSelection=NO;
  p.allowedFileTypes=@[@"mp4",@"mov",@"m4v"];
  if ([p runModal] != NSModalResponseOK) return;
  self.videoPostPath = p.URL.path;
  self.videoPostFileLabel.stringValue = p.URL.lastPathComponent;
  self.videoPostStatus.stringValue = @"已选择视频";
  AVAsset *asset = [AVAsset assetWithURL:p.URL];
  self.videoPostEnd.stringValue = [NSString stringWithFormat:@"%.1f", CMTimeGetSeconds(asset.duration)];
}

- (NSString *)videoPostOutputPathWithExtension:(NSString *)ext suggested:(NSString *)name {
  NSSavePanel *sp = [NSSavePanel savePanel];
  sp.allowedFileTypes = @[ext];
  sp.nameFieldStringValue = name;
  if ([sp runModal] != NSModalResponseOK) return nil;
  return sp.URL.path;
}

- (void)exportTrimmedVideo:(id)sender {
  if (!self.videoPostPath.length) { [self showToast:@"请先选择视频"]; return; }
  NSString *out = [self videoPostOutputPathWithExtension:@"mp4" suggested:@"裁剪-录屏.mp4"];
  if (!out.length) return;
  AVAsset *asset = [AVAsset assetWithURL:[NSURL fileURLWithPath:self.videoPostPath]];
  CGFloat dur = CMTimeGetSeconds(asset.duration);
  CGFloat start = MAX(0, self.videoPostStart.doubleValue);
  CGFloat end = self.videoPostEnd.stringValue.length ? self.videoPostEnd.doubleValue : dur;
  end = MIN(dur, MAX(start + 0.1, end));
  AVMutableComposition *comp = [AVMutableComposition composition];
  NSError *err = nil;
  CMTimeRange range = CMTimeRangeMake(CMTimeMakeWithSeconds(start, 600), CMTimeMakeWithSeconds(end-start, 600));
  for (AVAssetTrack *track in [asset tracksWithMediaType:AVMediaTypeVideo]) {
    AVMutableCompositionTrack *ct = [comp addMutableTrackWithMediaType:AVMediaTypeVideo preferredTrackID:kCMPersistentTrackID_Invalid];
    if (![ct insertTimeRange:range ofTrack:track atTime:kCMTimeZero error:&err]) { [self showToast:err.localizedDescription ?: @"裁剪失败"]; return; }
  }
  for (AVAssetTrack *track in [asset tracksWithMediaType:AVMediaTypeAudio]) {
    AVMutableCompositionTrack *ct = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
    [ct insertTimeRange:range ofTrack:track atTime:kCMTimeZero error:NULL];
  }
  AVAssetExportSession *ex = [AVAssetExportSession exportSessionWithAsset:comp presetName:AVAssetExportPresetHighestQuality];
  ex.outputURL = [NSURL fileURLWithPath:out];
  ex.outputFileType = AVFileTypeMPEG4;
  [self.videoPostStatus setStringValue:@"正在裁剪…"];
  [ex exportAsynchronouslyWithCompletionHandler:^{
    dispatch_async(dispatch_get_main_queue(), ^{
      self.videoPostStatus.stringValue = ex.status == AVAssetExportSessionStatusCompleted ? [NSString stringWithFormat:@"已保存：%@", out.lastPathComponent] : (ex.error.localizedDescription ?: @"裁剪失败");
      if (ex.status == AVAssetExportSessionStatusCompleted) [self showCaptureResultPanel:out];
    });
  }];
}

- (void)exportCompressedVideo:(id)sender {
  if (!self.videoPostPath.length) { [self showToast:@"请先选择视频"]; return; }
  NSInteger idx = self.videoPostQualityPopup.indexOfSelectedItem;
  if (idx == 3) {
    NSString *out = [self videoPostOutputPathWithExtension:@"m4a" suggested:@"音频.m4a"];
    if (!out.length) return;
    AVAsset *asset = [AVAsset assetWithURL:[NSURL fileURLWithPath:self.videoPostPath]];
    AVAssetExportSession *ex = [AVAssetExportSession exportSessionWithAsset:asset presetName:AVAssetExportPresetAppleM4A];
    ex.outputURL=[NSURL fileURLWithPath:out]; ex.outputFileType=AVFileTypeAppleM4A;
    [self.videoPostStatus setStringValue:@"正在提取音频…"];
    [ex exportAsynchronouslyWithCompletionHandler:^{ dispatch_async(dispatch_get_main_queue(), ^{
      self.videoPostStatus.stringValue = ex.status == AVAssetExportSessionStatusCompleted ? [NSString stringWithFormat:@"已保存：%@", out.lastPathComponent] : (ex.error.localizedDescription ?: @"提取失败");
      if (ex.status == AVAssetExportSessionStatusCompleted) [self showCaptureResultPanel:out];
    }); }];
    return;
  }
  NSString *preset = idx == 0 ? AVAssetExportPreset1280x720 : (idx == 1 ? AVAssetExportPreset1920x1080 : AVAssetExportPreset960x540);
  NSString *out = [self videoPostOutputPathWithExtension:@"mp4" suggested:[NSString stringWithFormat:@"压缩-%@.mp4", self.videoPostQualityPopup.titleOfSelectedItem]];
  if (!out.length) return;
  AVAsset *asset = [AVAsset assetWithURL:[NSURL fileURLWithPath:self.videoPostPath]];
  AVAssetExportSession *ex = [AVAssetExportSession exportSessionWithAsset:asset presetName:preset];
  ex.outputURL=[NSURL fileURLWithPath:out]; ex.outputFileType=AVFileTypeMPEG4;
  [self.videoPostStatus setStringValue:@"正在压缩…"];
  [ex exportAsynchronouslyWithCompletionHandler:^{ dispatch_async(dispatch_get_main_queue(), ^{
    self.videoPostStatus.stringValue = ex.status == AVAssetExportSessionStatusCompleted ? [NSString stringWithFormat:@"已保存：%@", out.lastPathComponent] : (ex.error.localizedDescription ?: @"压缩失败");
    if (ex.status == AVAssetExportSessionStatusCompleted) [self showCaptureResultPanel:out];
  }); }];
}

- (void)exportGIFVideo:(id)sender {
  if (!self.videoPostPath.length) { [self showToast:@"请先选择视频"]; return; }
  NSString *out = [self videoPostOutputPathWithExtension:@"gif" suggested:@"动图.gif"];
  if (!out.length) return;
  AVAsset *asset = [AVAsset assetWithURL:[NSURL fileURLWithPath:self.videoPostPath]];
  CGFloat dur = CMTimeGetSeconds(asset.duration);
  CGFloat start = MAX(0, self.videoPostStart.doubleValue);
  CGFloat end = self.videoPostEnd.stringValue.length ? self.videoPostEnd.doubleValue : dur;
  end = MIN(dur, MAX(start + 0.2, end));
  if (end - start > 10) end = start + 10;
  self.videoPostStatus.stringValue = @"正在生成 GIF…";
  dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
    AVAssetImageGenerator *gen = [AVAssetImageGenerator assetImageGeneratorWithAsset:asset];
    gen.appliesPreferredTrackTransform=YES;
    gen.maximumSize=CGSizeMake(640,640);
    NSInteger frames = MAX(2, (NSInteger)((end-start)*10));
    NSMutableArray *images = [NSMutableArray array];
    for (NSInteger i=0;i<frames;i++) {
      CGImageRef img = [gen copyCGImageAtTime:CMTimeMakeWithSeconds(start + i/10.0, 600) actualTime:NULL error:NULL];
      if (img) { [images addObject:CFBridgingRelease(img)]; }
    }
    BOOL ok = NO;
    if (images.count) {
      CFURLRef url = (__bridge CFURLRef)[NSURL fileURLWithPath:out];
      CGImageDestinationRef dest = CGImageDestinationCreateWithURL(url, kUTTypeGIF, images.count, NULL);
      if (dest) {
        NSDictionary *frameProps = @{(__bridge NSString *)kCGImagePropertyGIFDelayTime: @0.1};
        NSDictionary *gifProps = @{(__bridge NSString *)kCGImagePropertyGIFLoopCount: @0};
        CGImageDestinationSetProperties(dest, (__bridge CFDictionaryRef)gifProps);
        for (id img in images) CGImageDestinationAddImage(dest, (__bridge CGImageRef)img, (__bridge CFDictionaryRef)frameProps);
        ok = CGImageDestinationFinalize(dest); CFRelease(dest);
      }
    }
    dispatch_async(dispatch_get_main_queue(), ^{
      self.videoPostStatus.stringValue = ok ? [NSString stringWithFormat:@"已保存：%@", out.lastPathComponent] : @"GIF 生成失败";
      if (ok) [self showCaptureResultPanel:out];
    });
  });
}

- (void)showCaptureResultPanel:(NSString *)path {
  if (![[NSFileManager defaultManager] fileExistsAtPath:path]) return;
  self.captureResultPath = path;
  [self.captureResultTimer invalidate];
  if (self.captureResultWindow) [self.captureResultWindow orderOut:nil];
  BOOL isVideo = [@[@"mp4",@"mov",@"m4v"] containsObject:path.pathExtension.lowercaseString];
  NSWindow *w = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,400,140) styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
  w.opaque = NO;
  w.backgroundColor = [NSColor clearColor];
  w.level = NSFloatingWindowLevel;
  w.hasShadow = YES;
  w.releasedWhenClosed = NO;
  w.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  NSView *cv = w.contentView;
  cv.wantsLayer = YES;
  cv.layer.backgroundColor = [NSColor colorWithCalibratedWhite:0.10 alpha:0.94].CGColor;
  cv.layer.cornerRadius = 14;
  cv.layer.masksToBounds = YES;
  NSImageView *thumb = [[NSImageView alloc] initWithFrame:NSMakeRect(12,14,96,104)];
  thumb.imageScaling = NSImageScaleProportionallyUpOrDown;
  thumb.wantsLayer = YES; thumb.layer.cornerRadius = 9; thumb.layer.masksToBounds = YES;
  thumb.image = isVideo ? [[NSWorkspace sharedWorkspace] iconForFile:path] : [[NSImage alloc] initWithContentsOfFile:path];
  [cv addSubview:thumb];
  NSTextField *name = [self label:path.lastPathComponent size:12 bold:YES color:[NSColor whiteColor]];
  name.lineBreakMode = NSLineBreakByTruncatingMiddle;
  name.frame = NSMakeRect(120,102,230,18); [cv addSubview:name];
  NSTextField *kind = [self label:isVideo ? @"录屏已保存" : @"截图已保存" size:10 bold:NO color:[NSColor colorWithCalibratedWhite:0.75 alpha:1.0]];
  kind.frame = NSMakeRect(120,80,230,16); [cv addSubview:kind];
  NSArray *titles = @[@"复制", @"打开", @"访达", @"AirDrop", @"删除"];
  NSArray *sels = @[@"copyCaptureResult:", @"openCaptureResult:", @"revealCaptureResult:", @"airdropCaptureResult:", @"trashCaptureResult:"];
  for (NSInteger i=0;i<5;i++) {
    ColorHoverButton *b = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(120+i*46,32,42,28)];
    b.title=titles[i]; b.tag=i; b.hoverColor = i==4 ? [NSColor systemRedColor] : [NSColor systemTealColor];
    b.target=self; b.action=NSSelectorFromString(sels[i]);
    [b applyColor:[NSColor colorWithCalibratedWhite:0.22 alpha:1.0] textColor:[NSColor whiteColor]];
    [cv addSubview:b];
  }
  ColorHoverButton *close = [[ColorHoverButton alloc] initWithFrame:NSMakeRect(368,104,22,22)];
  close.title=@"×"; close.hoverColor=[NSColor systemRedColor]; close.target=self; close.action=@selector(closeCaptureResult:);
  [close applyColor:[NSColor colorWithCalibratedWhite:0.20 alpha:1.0] textColor:[NSColor whiteColor]];
  [cv addSubview:close];
  NSScreen *scr = [NSScreen mainScreen];
  NSRect vis = scr.visibleFrame;
  [w setFrameOrigin:NSMakePoint(NSMaxX(vis)-w.frame.size.width-20, NSMinY(vis)+20)];
  self.captureResultWindow = w;
  [w orderFrontRegardless];
  __weak typeof(self) weakSelf = self;
  self.captureResultTimer = [NSTimer scheduledTimerWithTimeInterval:12.0 repeats:NO block:^(NSTimer *t) {
    [weakSelf.captureResultWindow orderOut:nil];
  }];
}

- (void)copyCaptureResult:(id)sender {
  NSString *path = self.captureResultPath;
  if (![[NSFileManager defaultManager] fileExistsAtPath:path]) return;
  NSPasteboard *pb = [NSPasteboard generalPasteboard];
  [pb clearContents];
  if ([@[@"png",@"jpg",@"jpeg",@"tiff",@"heic"] containsObject:path.pathExtension.lowercaseString]) {
    NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
    if (img) [pb writeObjects:@[img]];
  } else {
    [pb writeObjects:@[[NSURL fileURLWithPath:path]]];
  }
  [self showToast:@"已复制到剪贴板"];
}

- (void)openCaptureResult:(id)sender {
  if (self.captureResultPath.length) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:self.captureResultPath]];
}

- (void)revealCaptureResult:(id)sender {
  if (self.captureResultPath.length) [[NSWorkspace sharedWorkspace] activateFileViewerSelectingURLs:@[[NSURL fileURLWithPath:self.captureResultPath]]];
}

- (void)airdropCaptureResult:(id)sender {
  if (!self.captureResultPath.length) return;
  NSSharingService *svc = [NSSharingService sharingServiceNamed:NSSharingServiceNameSendViaAirDrop];
  NSURL *u = [NSURL fileURLWithPath:self.captureResultPath];
  if ([svc canPerformWithItems:@[u]]) [svc performWithItems:@[u]];
  else [self showToast:@"附近没有可用的 AirDrop 接收设备"];
}

- (void)trashCaptureResult:(id)sender {
  NSString *path = self.captureResultPath;
  if (!path.length || ![[NSFileManager defaultManager] fileExistsAtPath:path]) return;
  NSURL *u = [NSURL fileURLWithPath:path];
  NSError *err = nil;
  if ([[NSFileManager defaultManager] trashItemAtURL:u resultingItemURL:NULL error:&err]) {
    [self closeCaptureResult:nil];
    [self showToast:@"已移到废纸篓"];
  } else {
    [self showToast:err.localizedDescription ?: @"删除失败"];
  }
}

- (void)closeCaptureResult:(id)sender {
  [self.captureResultTimer invalidate];
  [self.captureResultWindow orderOut:nil];
}

- (void)finalizeCaptureFile:(NSString *)path error:(NSError *)error {
  NSInteger gainDB = [[NSUserDefaults standardUserDefaults] integerForKey:@"centerCaptureMicGain"];
  BOOL needsAudio = [self fileNeedsAudioMix:path] || (gainDB != 0 && [[NSFileManager defaultManager] fileExistsAtPath:path]);
  if (needsAudio) {
    self.captureStatusLabel.stringValue = @"正在调整麦克风音量…";
    __weak typeof(self) weakSelf = self;
    [self applyMicGainToFile:path gainDB:gainDB completion:^(BOOL ok) {
      [weakSelf finishCaptureUI];
      if ([[NSFileManager defaultManager] fileExistsAtPath:path]) {
        weakSelf.captureStatusLabel.stringValue = [NSString stringWithFormat:@"录屏已保存：%@", path.lastPathComponent];
        [weakSelf showToast:ok ? @"录屏已保存" : @"录屏已保存，音量调整失败"];
        if (weakSelf.captureSplitAudioCheck.state == NSControlStateValueOn) {
          [weakSelf exportSplitAudioTracksForFile:path completion:^(NSInteger count) {
            if (count > 0) [weakSelf showToast:[NSString stringWithFormat:@"已导出 %ld 个独立音轨", (long)count]];
          }];
        }
        [weakSelf showCaptureResultPanel:path];
      } else if (error) {
        weakSelf.captureStatusLabel.stringValue = error.localizedDescription ?: @"录屏失败";
        [weakSelf showToast:error.localizedDescription ?: @"录屏失败"];
      } else {
        weakSelf.captureStatusLabel.stringValue = @"录屏已取消";
      }
    }];
    return;
  }
  [self finishCaptureUI];
  if ([[NSFileManager defaultManager] fileExistsAtPath:path]) {
    self.captureStatusLabel.stringValue = [NSString stringWithFormat:@"录屏已保存：%@", path.lastPathComponent];
    [self showToast:@"录屏已保存"];
    if (self.captureSplitAudioCheck.state == NSControlStateValueOn) {
      [self exportSplitAudioTracksForFile:path completion:^(NSInteger count) {
        if (count > 0) [self showToast:[NSString stringWithFormat:@"已导出 %ld 个独立音轨", (long)count]];
      }];
    }
    [self showCaptureResultPanel:path];
  } else if (error) {
    self.captureStatusLabel.stringValue = error.localizedDescription ?: @"录屏失败";
    [self showToast:error.localizedDescription ?: @"录屏失败"];
  } else {
    self.captureStatusLabel.stringValue = @"录屏已取消";
  }
}

- (void)captureOptionsChanged:(id)sender {
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  [ud setBool:self.captureSplitAudioCheck.state == NSControlStateValueOn forKey:@"centerCaptureSplitAudio"];
  [ud setBool:self.captureKeyDisplayCheck.state == NSControlStateValueOn forKey:@"centerCaptureKeyDisplay"];
  [ud synchronize];
}

- (void)stopKeyDisplay {
  if (self.captureKeyMonitor) { [NSEvent removeMonitor:self.captureKeyMonitor]; self.captureKeyMonitor = nil; }
  [self.captureKeyTimer invalidate]; self.captureKeyTimer = nil;
  [self.captureKeyWindow orderOut:nil];
  self.captureKeyWindow = nil;
}

- (NSString *)displayStringForKeyEvent:(NSEvent *)e {
  NSMutableString *s = [NSMutableString string];
  NSEventModifierFlags f = e.modifierFlags;
  if (f & NSEventModifierFlagControl) [s appendString:@"⌃"];
  if (f & NSEventModifierFlagOption) [s appendString:@"⌥"];
  if (f & NSEventModifierFlagShift) [s appendString:@"⇧"];
  if (f & NSEventModifierFlagCommand) [s appendString:@"⌘"];
  NSString *key = e.charactersIgnoringModifiers.uppercaseString ?: @"";
  if (e.keyCode == 36) key = @"Return";
  else if (e.keyCode == 48) key = @"Tab";
  else if (e.keyCode == 49) key = @"Space";
  else if (e.keyCode == 51) key = @"Delete";
  else if (e.keyCode == 53) key = @"Esc";
  else if (e.keyCode == 123) key = @"←";
  else if (e.keyCode == 124) key = @"→";
  else if (e.keyCode == 125) key = @"↓";
  else if (e.keyCode == 126) key = @"↑";
  if (!key.length) key = [NSString stringWithFormat:@"Key%u", (unsigned)e.keyCode];
  [s appendString:key];
  return s;
}

- (void)showKeyDisplay:(NSString *)text {
  if (!text.length) return;
  if (!self.captureKeyWindow) {
    NSWindow *w = [[NSWindow alloc] initWithContentRect:NSMakeRect(0,0,260,56) styleMask:NSWindowStyleMaskBorderless backing:NSBackingStoreBuffered defer:NO];
    w.opaque = NO;
    w.backgroundColor = [NSColor colorWithCalibratedWhite:0.08 alpha:0.88];
    w.level = NSFloatingWindowLevel;
    w.hasShadow = YES;
    w.ignoresMouseEvents = YES;
    w.sharingType = NSWindowSharingReadOnly;
    w.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
    NSView *cv = w.contentView;
    cv.wantsLayer = YES; cv.layer.cornerRadius = 12; cv.layer.masksToBounds = YES;
    self.captureKeyLabel = [self label:@"" size:20 bold:YES color:[NSColor whiteColor]];
    self.captureKeyLabel.alignment = NSTextAlignmentCenter;
    self.captureKeyLabel.frame = NSMakeRect(10,15,240,26);
    [cv addSubview:self.captureKeyLabel];
    self.captureKeyWindow = w;
  }
  self.captureKeyLabel.stringValue = text;
  NSScreen *scr = [NSScreen mainScreen];
  NSRect vis = scr.visibleFrame;
  [self.captureKeyWindow setFrameOrigin:NSMakePoint(NSMidX(vis)-130, NSMinY(vis)+70)];
  [self.captureKeyWindow orderFrontRegardless];
  [self.captureKeyTimer invalidate];
  __weak typeof(self) weakSelf = self;
  self.captureKeyTimer = [NSTimer scheduledTimerWithTimeInterval:1.6 repeats:NO block:^(NSTimer *t) { [weakSelf.captureKeyWindow orderOut:nil]; }];
}

- (void)startKeyDisplayIfNeeded {
  [self stopKeyDisplay];
  if (self.captureKeyDisplayCheck.state != NSControlStateValueOn) return;
  __weak typeof(self) weakSelf = self;
  self.captureKeyMonitor = [NSEvent addGlobalMonitorForEventsMatchingMask:NSEventMaskKeyDown handler:^(NSEvent *e) {
    [weakSelf showKeyDisplay:[weakSelf displayStringForKeyEvent:e]];
  }];
}

- (void)exportSplitAudioTracksForFile:(NSString *)path completion:(void (^)(NSInteger count))completion {
  AVURLAsset *asset = [AVURLAsset URLAssetWithURL:[NSURL fileURLWithPath:path] options:nil];
  [asset loadValuesAsynchronouslyForKeys:@[@"tracks"] completionHandler:^{
    NSError *loadErr = nil;
    AVKeyValueStatus st = [asset statusOfValueForKey:@"tracks" error:&loadErr];
    NSArray<AVAssetTrack *> *audios = st == AVKeyValueStatusLoaded ? [asset tracksWithMediaType:AVMediaTypeAudio] : @[];
    if (!audios.count) { dispatch_async(dispatch_get_main_queue(), ^{ if (completion) completion(0); }); return; }
    dispatch_group_t group = dispatch_group_create();
    __block NSInteger done = 0;
    NSString *base = [path stringByDeletingPathExtension];
    for (NSInteger i = 0; i < (NSInteger)audios.count; i++) {
      AVAssetTrack *track = audios[i];
      AVMutableComposition *comp = [AVMutableComposition composition];
      AVMutableCompositionTrack *ct = [comp addMutableTrackWithMediaType:AVMediaTypeAudio preferredTrackID:kCMPersistentTrackID_Invalid];
      [ct insertTimeRange:CMTimeRangeMake(kCMTimeZero, asset.duration) ofTrack:track atTime:kCMTimeZero error:NULL];
      NSString *outPath = [NSString stringWithFormat:@"%@-音轨%ld.m4a", base, (long)(i+1)];
      AVAssetExportSession *ex = [AVAssetExportSession exportSessionWithAsset:comp presetName:AVAssetExportPresetAppleM4A];
      ex.outputURL = [NSURL fileURLWithPath:outPath];
      ex.outputFileType = AVFileTypeAppleM4A;
      [[NSFileManager defaultManager] removeItemAtPath:outPath error:NULL];
      dispatch_group_enter(group);
      [ex exportAsynchronouslyWithCompletionHandler:^{
        if (ex.status == AVAssetExportSessionStatusCompleted) done++;
        dispatch_group_leave(group);
      }];
    }
    dispatch_group_notify(group, dispatch_get_main_queue(), ^{
      if (completion) completion(done);
    });
  }];
}

- (void)startCaptureHUD {
  [self stopCaptureHUD];
  NSPanel *p = [[NSPanel alloc] initWithContentRect:NSMakeRect(0,0,230,48) styleMask:NSWindowStyleMaskBorderless|NSWindowStyleMaskNonactivatingPanel backing:NSBackingStoreBuffered defer:NO];
  p.opaque = NO;
  p.backgroundColor = [NSColor colorWithCalibratedWhite:0.08 alpha:0.86];
  p.level = NSFloatingWindowLevel;
  p.hasShadow = YES;
  p.sharingType = NSWindowSharingNone;
  p.collectionBehavior = NSWindowCollectionBehaviorCanJoinAllSpaces | NSWindowCollectionBehaviorFullScreenAuxiliary;
  p.movableByWindowBackground = YES;
  NSView *v = [[NSView alloc] initWithFrame:NSMakeRect(0,0,230,48)];
  v.wantsLayer = YES;
  v.layer.cornerRadius = 12;
  v.layer.masksToBounds = YES;
  NSTextField *lab = [self label:@"00:00" size:15 bold:YES color:[NSColor whiteColor]];
  lab.frame = NSMakeRect(14, 14, 96, 20); lab.tag = 100;
  [v addSubview:lab];
  NSButton *pause = [NSButton buttonWithTitle:@"暂停" target:self action:@selector(hudPause:)];
  pause.frame = NSMakeRect(112, 10, 56, 28);
  pause.bezelStyle = NSBezelStyleRounded;
  [v addSubview:pause];
  NSButton *stop = [NSButton buttonWithTitle:@"停止" target:self action:@selector(hudStop:)];
  stop.frame = NSMakeRect(170, 10, 54, 28);
  stop.bezelStyle = NSBezelStyleRounded;
  [v addSubview:stop];
  p.contentView = v;
  NSRect vis = [NSScreen mainScreen].visibleFrame;
  [p setFrameOrigin:NSMakePoint(NSMaxX(vis) - 250, NSMaxY(vis) - 64)];
  self.captureHUDWindow = p;
  self.captureHUDLabel = lab;
  self.captureHUDPauseButton = pause;
  self.captureHUDStartDate = [NSDate date];
  self.captureHUDPaused = NO;
  self.captureHUDPausedElapsed = 0;
  [p orderFrontRegardless];
  __weak typeof(self) weakSelf = self;
  self.captureHUDTimer = [NSTimer scheduledTimerWithTimeInterval:0.5 repeats:YES block:^(NSTimer *timer) {
    if (!weakSelf.captureHUDWindow) return;
    NSTimeInterval elapsed = weakSelf.captureHUDPaused ? weakSelf.captureHUDPausedElapsed : [[NSDate date] timeIntervalSinceDate:weakSelf.captureHUDStartDate];
    NSInteger sec = MAX(0, (NSInteger)elapsed);
    weakSelf.captureHUDLabel.stringValue = [NSString stringWithFormat:@"%02ld:%02ld", (long)(sec/60), (long)(sec%60)];
  }];
}

- (void)stopCaptureHUD {
  [self.captureHUDTimer invalidate]; self.captureHUDTimer = nil;
  [self.captureHUDWindow orderOut:nil];
  self.captureHUDWindow = nil;
  self.captureHUDLabel = nil;
  self.captureHUDPauseButton = nil;
}

- (void)hudPause:(id)sender {
  if (!self.captureRecording) return;
  [self pauseCapture:nil];
  if (self.capturePaused) {
    self.captureHUDPausedElapsed = [[NSDate date] timeIntervalSinceDate:self.captureHUDStartDate];
    self.captureHUDPaused = YES;
    self.captureHUDPauseButton.title = @"继续";
  } else {
    self.captureHUDStartDate = [NSDate dateWithTimeIntervalSinceNow:-self.captureHUDPausedElapsed];
    self.captureHUDPaused = NO;
    self.captureHUDPauseButton.title = @"暂停";
  }
}

- (void)hudStop:(id)sender {
  if (self.captureRecording) [self captureVideo:nil];
}

- (void)finishCaptureUI {
  [self restoreMicBoost];
  self.captureRecording = NO;
  self.capturePaused = NO;
  [self stopCaptureHUD];
  [self stopKeyDisplay];
  self.capturePauseButton.hidden = YES;
  self.captureRecordButton.title = @"开始录屏";
  self.captureRecordButton.hoverColor = [NSColor systemRedColor];
  [self stopCameraPreview];
  self.captureCameraSegments = nil;
  self.captureCameraMoviePath = nil;
  self.captureCameraPauseStopping = NO;
  self.captureCameraWaiting = NO;
  self.capturePendingScreenPath = nil;
  self.captureRecorder = nil;
  if (self.captureWindow.isVisible) [self startMicLevelMeterIfNeeded];
}

- (void)startCaptureRecorderWithScene:(NSInteger)scene region:(NSRect)region {
  self.captureNoiseAttempted = NO;
  if (!self.captureRecorder) self.captureRecorder = [[DLScreenRecorder alloc] init];
  NSInteger seconds = [self.captureDurationPopup.selectedItem.representedObject integerValue];
  NSString *path = [[self captureVideoDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"录屏-%@.mp4", [self captureTimestamp]]];
  [self beginMicBoostIfNeeded];
  self.captureRecording = YES;
  self.capturePaused = NO;
  self.captureCameraSegments = [NSMutableArray array];
  self.captureCameraPauseStopping = NO;
  self.captureCameraWaiting = NO;
  self.capturePendingScreenPath = nil;
  NSString *camUID = self.captureCameraPopup.selectedItem.representedObject ?: @"";
  self.captureUsePreviewOverlay = (scene == DLRecordSceneFull || scene == DLRecordSceneRegion) && camUID.length > 0;
  [self startCameraPreviewIfNeeded];
  [self startCaptureHUD];
  [self captureOptionsChanged:nil];
  [self startKeyDisplayIfNeeded];
  self.captureRecordButton.title = @"停止录屏";
  self.capturePauseButton.hidden = NO;
  self.capturePauseButton.title = @"暂停";
  self.captureRecordButton.hoverColor = [NSColor systemOrangeColor];
  self.captureStatusLabel.stringValue = @"正在启动录屏…";
  __weak typeof(self) weakSelf = self;
  DLScreenRecorder *rec = self.captureRecorder;
  rec.onStarted = ^{
    dispatch_async(dispatch_get_main_queue(), ^{
      weakSelf.captureStatusLabel.stringValue = seconds > 0 ? [NSString stringWithFormat:@"正在录制，%ld 秒后自动停止…", (long)seconds] : @"正在录制，点「停止录屏」结束";
    });
  };
  rec.onFinished = ^(NSURL *url, NSError *error) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (weakSelf.captureCameraMovieOutput.isRecording && weakSelf.captureCameraMoviePath.length) {
        weakSelf.capturePendingScreenPath = path;
        weakSelf.captureCameraWaiting = YES;
        weakSelf.captureStatusLabel.stringValue = @"正在停止摄像头并合成画中画…";
        [weakSelf.captureCameraMovieOutput stopRecording];
        return;
      }
      if (weakSelf.captureCameraSegments.count) {
        weakSelf.captureStatusLabel.stringValue = @"正在合成摄像头画中画…";
        [weakSelf composeCameraSegments:[weakSelf.captureCameraSegments copy] overScreen:path];
        return;
      }
      [weakSelf finalizeCaptureFile:path error:error];
    });
  };
  [rec startWithScene:scene seconds:seconds region:region url:[NSURL fileURLWithPath:path]];
}

- (void)pauseCapture:(id)sender {
  if (!self.captureRecording || !self.captureRecorder) return;
  if (self.capturePaused) {
    [self.captureRecorder resume];
    [self startCameraMovieIfNeeded];
    [self startKeyDisplayIfNeeded];
    self.capturePaused = NO;
    self.capturePauseButton.title = @"暂停";
    self.captureStatusLabel.stringValue = @"继续录制…";
  } else {
    [self stopKeyDisplay];
    if (self.captureCameraMovieOutput.isRecording) {
      self.captureCameraPauseStopping = YES;
      [self.captureCameraMovieOutput stopRecording];
    }
    [self.captureRecorder pause];
    self.capturePaused = YES;
    self.capturePauseButton.title = @"继续";
    self.captureStatusLabel.stringValue = @"已暂停录制，点「继续」恢复";
  }
}

- (BOOL)ensureScreenCapturePermission {
  if (CGPreflightScreenCaptureAccess()) return YES;
  CGRequestScreenCaptureAccess();
  self.captureStatusLabel.stringValue = @"需要屏幕录制权限";
  NSAlert *alert = [[NSAlert alloc] init];
  alert.messageText = @"需要屏幕录制权限";
  alert.informativeText = @"请在「系统设置 → 隐私与安全性 → 屏幕录制」中勾选 DockLaunchers 控制台，然后重新打开应用。授权后可能需要重启控制台才能开始录屏。";
  [alert addButtonWithTitle:@"打开系统设置"];
  [alert addButtonWithTitle:@"稍后"];
  if ([alert runModal] == NSAlertFirstButtonReturn) {
    [[NSWorkspace sharedWorkspace] openURL:[NSURL URLWithString:@"x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture"]];
  }
  [self showToast:@"录屏需要屏幕录制权限"];
  return NO;
}

- (NSString *)capturePreflightIssue {
  BOOL mic = self.captureMicCheck.state == NSControlStateValueOn;
  if (mic) {
    AVAuthorizationStatus st = [AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeAudio];
    if (st == AVAuthorizationStatusDenied || st == AVAuthorizationStatusRestricted)
      return @"麦克风权限被拒绝。请在 系统设置 → 隐私与安全性 → 麦克风 中允许 DockLaunchers 控制台。";
  }
  NSString *camUID = self.captureCameraPopup.selectedItem.representedObject ?: @"";
  if (camUID.length) {
    AVAuthorizationStatus st = [AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeVideo];
    if (st == AVAuthorizationStatusDenied || st == AVAuthorizationStatusRestricted)
      return @"摄像头权限被拒绝。请在 系统设置 → 隐私与安全性 → 摄像头 中允许 DockLaunchers 控制台。";
  }
  NSString *dir = [self captureVideoDirectory];
  NSDictionary *attrs = [[NSFileManager defaultManager] attributesOfFileSystemForPath:dir error:NULL];
  unsigned long long freeBytes = [attrs[NSFileSystemFreeSize] unsignedLongLongValue];
  if (freeBytes > 0 && freeBytes < 500ULL * 1024 * 1024)
    return @"磁盘剩余空间不足 500 MB，录制可能失败。请清理磁盘后再试。";
  return nil;
}

- (void)openPrivacyPaneForCaptureIssue:(NSString *)issue {
  NSString *url = [issue containsString:@"摄像头"] ? @"x-apple.systempreferences:com.apple.preference.security?Privacy_Camera" :
                  ([issue containsString:@"麦克风"] ? @"x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone" : nil);
  if (url) [[NSWorkspace sharedWorkspace] openURL:[NSURL URLWithString:url]];
}

- (void)stopMicLevelMeter {
  AVAudioEngine *engine = self.captureMicMeterEngine;
  if (!engine) return;
  self.captureMicMeterEngine = nil;
  @try { [engine.inputNode removeTapOnBus:0]; } @catch (NSException *e) {}
  [engine stop];
  self.captureMicLevelIndicator.doubleValue = 0;
}

- (void)startMicLevelMeterIfNeeded {
  if (self.captureMicMeterEngine) return;
  if (!self.captureMicCheck || self.captureMicCheck.state != NSControlStateValueOn) return;
  if ([AVCaptureDevice authorizationStatusForMediaType:AVMediaTypeAudio] == AVAuthorizationStatusDenied) {
    self.captureMicLevelIndicator.toolTip = @"麦克风权限被拒绝";
    return;
  }
  AVAudioEngine *engine = [[AVAudioEngine alloc] init];
  AVAudioInputNode *input = engine.inputNode;
  AVAudioFormat *fmt = [input outputFormatForBus:0];
  if (!fmt) return;
  __weak typeof(self) weakSelf = self;
  [input installTapOnBus:0 bufferSize:1024 format:fmt block:^(AVAudioPCMBuffer *buffer, AVAudioTime *when) {
    float rms = 0;
    if (buffer.floatChannelData && buffer.frameLength > 0) {
      float *data = buffer.floatChannelData[0];
      double sum = 0;
      for (AVAudioFrameCount i = 0; i < buffer.frameLength; i++) sum += data[i] * data[i];
      rms = sqrt(sum / (double)buffer.frameLength);
    }
    double db = 20.0 * log10(MAX(rms, 0.000001));
    double level = MAX(0, MIN(1, (db + 60.0) / 60.0));
    dispatch_async(dispatch_get_main_queue(), ^{
      weakSelf.captureMicLevelIndicator.doubleValue = level;
    });
  }];
  NSError *err = nil;
  if (![engine startAndReturnError:&err]) {
    self.captureMicLevelIndicator.toolTip = err.localizedDescription ?: @"无法打开麦克风";
    return;
  }
  self.captureMicMeterEngine = engine;
}

- (void)openMostRecentRecording {
  NSString *dir = [self captureVideoDirectory];
  NSArray *files = [[NSFileManager defaultManager] contentsOfDirectoryAtPath:dir error:NULL] ?: @[];
  NSString *latest = nil; NSDate *latestDate = nil;
  for (NSString *f in files) {
    if (![[f.pathExtension lowercaseString] isEqualToString:@"mp4"]) continue;
    if ([f containsString:@"-part"]) continue;
    NSString *p = [dir stringByAppendingPathComponent:f];
    NSDate *d = [[NSFileManager defaultManager] attributesOfItemAtPath:p error:NULL][NSFileModificationDate];
    if (!latestDate || [d compare:latestDate] == NSOrderedDescending) { latest = p; latestDate = d; }
  }
  if (!latest.length) { [self showToast:@"还没有录屏文件"]; return; }
  [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:latest]];
}

- (void)startQuickRecording {
  if (self.captureRecording) return;
  self.suppressCaptureToolShow = YES;
  [self showCaptureTool:nil];
  self.suppressCaptureToolShow = NO;
  [self.captureWindow orderOut:nil];
  [self stopMicLevelMeter];
  __weak typeof(self) weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW,(int64_t)(0.15*NSEC_PER_SEC)),dispatch_get_main_queue(),^{
    [weakSelf captureVideo:nil];
  });
}

- (void)capturePresetChanged:(id)sender {
  NSInteger idx = self.capturePresetPopup.indexOfSelectedItem;
  NSUserDefaults *ud = [NSUserDefaults standardUserDefaults];
  [ud setInteger:idx forKey:@"centerCapturePreset"];
  if (idx <= 0) return;
  BOOL systemAudio = YES, mic = NO, clicks = NO, cursor = YES;
  NSInteger scene = 0, height = 1440, fps = 30, countdown = 0;
  NSString *cameraUID = @"";
  if (idx == 1) { scene = 0; height = 1080; fps = 30; mic = YES; clicks = YES; countdown = 0; }
  else if (idx == 2) { scene = 1; height = 1080; fps = 30; mic = YES; clicks = NO; countdown = 0; }
  else if (idx == 3) { scene = 0; height = 1440; fps = 60; mic = NO; clicks = NO; countdown = 0; }
  else if (idx == 4) {
    scene = 0; height = 1440; fps = 30; mic = YES; clicks = NO; countdown = 0;
    NSArray *devices = [AVCaptureDeviceDiscoverySession discoverySessionWithDeviceTypes:@[AVCaptureDeviceTypeBuiltInWideAngleCamera, AVCaptureDeviceTypeExternal] mediaType:AVMediaTypeVideo position:AVCaptureDevicePositionUnspecified].devices;
    for (AVCaptureDevice *d in devices) { if (d.position == AVCaptureDevicePositionFront) { cameraUID = d.uniqueID ?: @""; break; } }
    if (!cameraUID.length && devices.count) cameraUID = ((AVCaptureDevice *)devices.firstObject).uniqueID ?: @"";
  }
  [ud setBool:systemAudio forKey:@"centerCaptureSystemAudio"];
  [ud setBool:mic forKey:@"centerCaptureMicrophone"];
  [ud setBool:clicks forKey:@"centerCaptureShowClicks"];
  [ud setBool:cursor forKey:@"centerCaptureShowCursor"];
  [ud setInteger:height forKey:@"centerCaptureQuality"];
  [ud setInteger:fps forKey:@"centerCaptureFPS"];
  if (cameraUID.length) [ud setObject:cameraUID forKey:@"centerCaptureCameraID"];
  [self.captureScenePopup selectItemAtIndex:scene];
  self.captureSystemAudioCheck.state = systemAudio ? NSControlStateValueOn : NSControlStateValueOff;
  self.captureMicCheck.state = mic ? NSControlStateValueOn : NSControlStateValueOff;
  self.captureClickCheck.state = clicks ? NSControlStateValueOn : NSControlStateValueOff;
  self.captureCursorCheck.state = cursor ? NSControlStateValueOn : NSControlStateValueOff;
  NSInteger qidx = 1;
  if (height == 1080) qidx = 0; else if (height == 2160) qidx = 2; else if (height == 1440 && fps == 60) qidx = 3;
  [self.captureQualityPopup selectItemAtIndex:qidx];
  if (cameraUID.length) {
    for (NSMenuItem *mi in self.captureCameraPopup.itemArray) if ([(mi.representedObject ?: @"") isEqualToString:cameraUID]) { [self.captureCameraPopup selectItem:mi]; break; }
  } else {
    [self.captureCameraPopup selectItemAtIndex:0];
  }
  if (scene == 0) [self.captureScenePopup selectItemAtIndex:0];
  [self startMicLevelMeterIfNeeded];
  [self showToast:[NSString stringWithFormat:@"已应用%@", self.capturePresetPopup.titleOfSelectedItem]];
}

- (void)captureVideo:(id)sender {
  if (self.captureRecording) {
    [self.captureRecorder stop];
    self.captureStatusLabel.stringValue = @"正在停止录屏…";
    return;
  }
  NSInteger scene = self.captureScenePopup.indexOfSelectedItem;
  NSInteger delay = [self captureRecordCountdownSeconds];
  __weak typeof(self) weakSelf = self;
  if (![self ensureScreenCapturePermission]) return;
  [self stopMicLevelMeter];
  NSString *preflight = [self capturePreflightIssue];
  if (preflight.length) {
    self.captureStatusLabel.stringValue = preflight;
    NSAlert *a = [[NSAlert alloc] init];
    a.messageText = @"录制前检查未通过";
    a.informativeText = preflight;
    [a addButtonWithTitle:@"打开系统设置"];
    [a addButtonWithTitle:@"取消"];
    if ([a runModal] == NSAlertFirstButtonReturn) [self openPrivacyPaneForCaptureIssue:preflight];
    return;
  }
  [self hideCapturePanelForCapture];
  if (scene == 3) {
    [self beginCaptureRegion:^(NSRect region) {
      if (region.size.width < 12 || region.size.height < 12) return;
      if (delay > 0) [weakSelf showCaptureCountdown:delay completion:^{ [weakSelf startCaptureRecorderWithScene:3 region:region]; }];
      else [weakSelf startCaptureRecorderWithScene:3 region:region];
    }];
    return;
  }
  if (delay > 0) [self showCaptureCountdown:delay completion:^{ [weakSelf startCaptureRecorderWithScene:scene region:NSZeroRect]; }];
  else [self startCaptureRecorderWithScene:scene region:NSZeroRect];
}

- (void)quickScreenshot:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  [self hideCapturePanelForCapture];
  usleep(120000);
  NSString *path = [[self captureDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"截图-%@.png", [self captureTimestamp]]];
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/usr/sbin/screencapture";
  t.arguments = @[@"-i", @"-x", path];
  t.terminationHandler = ^(NSTask *task) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (task.terminationStatus == 0 && [[NSFileManager defaultManager] fileExistsAtPath:path]) {
        NSImage *img = [[NSImage alloc] initWithContentsOfFile:path];
        if (img) { [[NSPasteboard generalPasteboard] clearContents]; [[NSPasteboard generalPasteboard] writeObjects:@[img]]; }
        [self showToast:@"截图已保存并复制"];
        [self showCaptureResultPanel:path];
      } else {
        [self showToast:@"截图已取消或没有屏幕录制权限"];
      }
    });
  };
  @try { [t launch]; } @catch (NSException *e) { [self showToast:@"无法启动截图"]; }
}

- (void)quickRecord:(id)sender {
  if (![self ensureScreenCapturePermission]) return;
  [self hideCapturePanelForCapture];
  NSString *path = [[self captureVideoDirectory] stringByAppendingPathComponent:[NSString stringWithFormat:@"录屏-%@.mp4", [self captureTimestamp]]];
  DLScreenRecorder *rec = [[DLScreenRecorder alloc] init];
  rec.onFinished = ^(NSURL *url, NSError *error) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if ([[NSFileManager defaultManager] fileExistsAtPath:path]) [self showToast:@"录屏已保存"];
      else [self showToast:error.localizedDescription ?: @"录屏已取消"];
    });
  };
  [rec startWithScene:0 seconds:30 region:NSZeroRect url:[NSURL fileURLWithPath:path]];
  [self showToast:@"开始录制，30 秒后自动结束"];
}

