    title.frame = NSMakeRect(20, 310, 300, 24); [cv addSubview:title];
    self.colorSwatch = [[NSView alloc] initWithFrame:NSMakeRect(20, 170, 140, 120)];
    self.colorSwatch.wantsLayer = YES;
    self.colorSwatch.layer.cornerRadius = 12;
