- (BOOL)handleGlobalEscape {
  if (NSApp.modalWindow) return NO;
  if (self.popover.isShown) { [self.popover performClose:nil]; return YES; }
  QLPreviewPanel *ql = [QLPreviewPanel sharedPreviewPanel];
  if (ql.isVisible) { [ql orderOut:nil]; return YES; }
  NSWindow *target = NSApp.keyWindow;
  if (!target.isVisible) target = self.window;
  if (!target.isVisible) {
    for (NSWindow *w in [NSApp orderedWindows]) if (w.isVisible) { target = w; break; }
  }
  if (!target.isVisible) return NO;
  BOOL isMain = (target == self.window);
  [target orderOut:nil];
  if (isMain) {
    [NSApp setActivationPolicy:NSApplicationActivationPolicyAccessory];
  }
  return YES;
}

- (void)bringAuxiliaryWindowToFront:(NSWindow *)w {
  if (!w) return;
  [[NSRunningApplication currentApplication] activateWithOptions:NSApplicationActivateIgnoringOtherApps];
  [NSApp activateIgnoringOtherApps:YES];
  [w makeKeyAndOrderFront:nil];
  [w orderFrontRegardless];
}

- (void)forceWindowToFront:(NSWindow *)w {
  if (!w) return;
  [self restoreDockIcon];
  [[NSRunningApplication currentApplication] activateWithOptions:(NSApplicationActivateAllWindows | NSApplicationActivateIgnoringOtherApps)];
  [NSApp activateIgnoringOtherApps:YES];
  [w makeKeyAndOrderFront:nil];
  [w orderFrontRegardless];
  __weak typeof(self) weakSelf = self;
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.35 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    [weakSelf restoreDockIcon];
    [[NSRunningApplication currentApplication] activateWithOptions:(NSApplicationActivateAllWindows | NSApplicationActivateIgnoringOtherApps)];
    [NSApp activateIgnoringOtherApps:YES];
    [w makeKeyAndOrderFront:nil];
    [w orderFrontRegardless];
  });
}

- (NSString *)latestRecordingFilePath {
  NSString *dir = [self captureVideoDirectory];
  NSArray *files = [[NSFileManager defaultManager] contentsOfDirectoryAtPath:dir error:NULL] ?: @[];
  NSString *latest = nil; NSDate *latestDate = nil;
  for (NSString *f in files) {
    if (![[f.pathExtension lowercaseString] isEqualToString:@"mp4"]) continue;
    NSString *p = [dir stringByAppendingPathComponent:f];
    NSDate *d = [[NSFileManager defaultManager] attributesOfItemAtPath:p error:NULL][NSFileModificationDate];
    if (!latestDate || [d compare:latestDate] == NSOrderedDescending) { latest = p; latestDate = d; }
  }
  return latest;
}

- (void)openConsoleFromPopover:(id)sender {
  [self.popover performClose:nil];
  [self restoreDockIcon];
  [self showWindow:nil];
