- (void)installUpdateDMG:(NSString *)dmgPath {
  if (!dmgPath.length || ![[NSFileManager defaultManager] fileExistsAtPath:dmgPath]) { [self showToast:@"更新文件不存在"]; return; }
  NSString *appPath = [[NSBundle mainBundle] bundlePath];
  NSString *script = @"exec >/tmp/dl-update.log 2>&1\n"
    "sleep 1\n"
    "DMG=\"$1\"; APP_PATH=\"$2\"; MNT=$(mktemp -d /tmp/dl-update-mnt.XXXXXX); STAGE=$(mktemp -d /tmp/dl-update-stage.XXXXXX); BAK=\"$APP_PATH.bak\"\n"
    "cleanup(){ hdiutil detach \"$MNT\" -quiet 2>/dev/null; rm -rf \"$STAGE\"; }\n"
    "trap cleanup EXIT\n"
    "hdiutil attach \"$DMG\" -nobrowse -quiet -mountpoint \"$MNT\" || exit 1\n"
    "APP=$(find \"$MNT\" -maxdepth 2 -name '*.app' -print -quit); [ -z \"$APP\" ] && exit 2\n"
    "codesign --verify --deep --strict \"$APP\" 2>/dev/null || exit 3\n"
    "rm -rf \"$STAGE/App.app\"; ditto \"$APP\" \"$STAGE/App.app\" || exit 4\n"
    "codesign --verify --deep --strict \"$STAGE/App.app\" 2>/dev/null || exit 3\n"
    "rm -rf \"$BAK\"; mv \"$APP_PATH\" \"$BAK\" || exit 5\n"
    "if ditto \"$STAGE/App.app\" \"$APP_PATH\"; then rm -rf \"$BAK\"; else rm -rf \"$APP_PATH\"; mv \"$BAK\" \"$APP_PATH\"; exit 6; fi\n"
    "open -a \"$APP_PATH\"\n";
  NSString *scriptPath=[NSTemporaryDirectory() stringByAppendingPathComponent:[NSString stringWithFormat:@"dl-update-%@.sh",[[NSUUID UUID] UUIDString]]];
  [script writeToFile:scriptPath atomically:YES encoding:NSUTF8StringEncoding error:NULL];
  [[NSFileManager defaultManager] setAttributes:@{NSFilePosixPermissions:@(0700)} ofItemAtPath:scriptPath error:NULL];
  NSTask *t = [[NSTask alloc] init];
  t.launchPath = @"/bin/sh";
  t.arguments = @[scriptPath, dmgPath, appPath];
  @try { [t launch]; } @catch (NSException *e) { [self showToast:@"启动安装失败"]; return; }
  [self showToast:@"正在安装更新，应用会自动重启"];
  dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{
    self.allowTerminate = YES;
    [NSApp terminate:nil];
  });
}

- (void)downloadUpdateAsset:(NSString *)urlString name:(NSString *)name {
  if (!urlString.length) return;
  NSString *safeName = name.length ? name : @"DockLaunchers-update.dmg";
  NSString *dest = [NSHomeDirectory() stringByAppendingPathComponent:[@"Downloads" stringByAppendingPathComponent:safeName]];
  [[NSFileManager defaultManager] removeItemAtPath:dest error:NULL];
  [self showToast:@"正在下载更新…"];
  NSURLSessionDownloadTask *task = [[NSURLSession sharedSession] downloadTaskWithURL:[NSURL URLWithString:urlString] completionHandler:^(NSURL *location, NSURLResponse *response, NSError *error) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (error || !location) {
        NSAlert *a = [[NSAlert alloc] init]; a.messageText = @"下载更新失败"; a.informativeText = error.localizedDescription ?: @"请稍后重试"; [a addButtonWithTitle:@"好"]; [a runModal]; return;
      }
      NSError *moveErr = nil;
      BOOL ok = [[NSFileManager defaultManager] moveItemAtURL:location toURL:[NSURL fileURLWithPath:dest] error:&moveErr];
      if (!ok) { [self showToast:@"更新文件保存失败"]; return; }
      if ([[NSUserDefaults standardUserDefaults] boolForKey:@"centerAutoInstallUpdates"]) {
        [self installUpdateDMG:dest];
        return;
      }
      NSAlert *a = [[NSAlert alloc] init];
      a.messageText = @"更新已下载";
      a.informativeText = [NSString stringWithFormat:@"已保存到：\n%@\n\n可以直接安装，或手动打开 DMG。", dest];
      [a addButtonWithTitle:@"立即安装"];
      [a addButtonWithTitle:@"打开 DMG"];
      [a addButtonWithTitle:@"稍后"];
      NSButton *autoInstall = [NSButton checkboxWithTitle:@"下载后自动安装" target:nil action:nil];
      autoInstall.frame = NSMakeRect(0,0,240,22);
      a.accessoryView = autoInstall;
      NSModalResponse r = [a runModal];
      if (autoInstall.state == NSControlStateValueOn) {
        [[NSUserDefaults standardUserDefaults] setBool:YES forKey:@"centerAutoInstallUpdates"];
        [[NSUserDefaults standardUserDefaults] synchronize];
      }
      if (r == NSAlertFirstButtonReturn) [self installUpdateDMG:dest];
      else if (r == NSAlertSecondButtonReturn) [[NSWorkspace sharedWorkspace] openURL:[NSURL fileURLWithPath:dest]];
    });
  }];
  [task resume];
}

- (void)checkForUpdates:(id)sender {
  NSString *current = [[NSBundle mainBundle] objectForInfoDictionaryKey:@"CFBundleShortVersionString"] ?: @"0";
  NSURL *url = [NSURL URLWithString:@"https://api.github.com/repos/Andre-xue/dock-launchers/releases/latest"];
  NSMutableURLRequest *req = [NSMutableURLRequest requestWithURL:url];
  [req setValue:@"DockLaunchers-UpdateCheck" forHTTPHeaderField:@"User-Agent"];
  [req setTimeoutInterval:12];
  NSURLSessionDataTask *task = [[NSURLSession sharedSession] dataTaskWithRequest:req completionHandler:^(NSData *data, NSURLResponse *resp, NSError *err) {
    dispatch_async(dispatch_get_main_queue(), ^{
      if (err || !data.length) {
        NSAlert *a = [[NSAlert alloc] init];
        a.messageText = @"检查更新失败";
        a.informativeText = [NSString stringWithFormat:@"当前版本 %@\n无法连接 GitHub，请稍后重试。", current];
        [a addButtonWithTitle:@"好"];
        [a runModal];
        return;
      }
      id obj = [NSJSONSerialization JSONObjectWithData:data options:0 error:NULL];
      if (![obj isKindOfClass:[NSDictionary class]] || !obj[@"tag_name"]) {
        NSAlert *a = [[NSAlert alloc] init];
        a.messageText = @"暂无发布版本";
        a.informativeText = [NSString stringWithFormat:@"当前版本 %@\n仓库还没有可用的 Release。", current];
        [a addButtonWithTitle:@"好"];
        [a runModal];
        return;
      }
      NSString *latest = [obj[@"tag_name"] stringByReplacingOccurrencesOfString:@"v" withString:@""];
      NSString *page = obj[@"html_url"] ?: @"https://github.com/Andre-xue/dock-launchers/releases";
      NSComparisonResult cmp = [latest compare:current options:NSNumericSearch];
      NSAlert *a = [[NSAlert alloc] init];
      if (cmp == NSOrderedDescending) {
        NSDictionary *dmg = nil;
        NSArray *assets = obj[@"assets"];
        if ([assets isKindOfClass:[NSArray class]]) {
          for (NSDictionary *asset in assets) {
            NSString *an = asset[@"name"] ?: @"";
            if ([an.lowercaseString hasSuffix:@".dmg"]) { dmg = asset; break; }
          }
        }
        if (!dmg) {
          a.messageText = [NSString stringWithFormat:@"发现新版本 %@", latest];
          a.informativeText = [NSString stringWithFormat:@"当前版本：%@\n最新版本：%@\n\n这个版本没有 DMG，是否打开下载页面？", current, latest];
          [a addButtonWithTitle:@"打开下载页"];
          [a addButtonWithTitle:@"稍后"];
          if ([a runModal] == NSAlertFirstButtonReturn) [[NSWorkspace sharedWorkspace] openURL:[NSURL URLWithString:page]];
          return;
        }
        NSString *assetURL = dmg[@"browser_download_url"] ?: @"";
        NSString *assetName = dmg[@"name"] ?: [NSString stringWithFormat:@"DockLaunchers控制台-%@.dmg", latest];
        BOOL autoDownload = [[NSUserDefaults standardUserDefaults] boolForKey:@"centerAutoDownloadUpdates"];
        if (autoDownload && assetURL.length) { [self downloadUpdateAsset:assetURL name:assetName]; return; }
        a.messageText = [NSString stringWithFormat:@"发现新版本 %@", latest];
        a.informativeText = [NSString stringWithFormat:@"当前版本：%@\n最新版本：%@\n\n是否下载更新？", current, latest];
        [a addButtonWithTitle:@"下载并打开"];
        [a addButtonWithTitle:@"稍后"];
        NSButton *autoCheck = [NSButton checkboxWithTitle:@"以后自动下载更新" target:nil action:nil];
        autoCheck.frame = NSMakeRect(0,0,260,22);
        a.accessoryView = autoCheck;
        NSModalResponse r = [a runModal];
        if (autoCheck.state == NSControlStateValueOn) {
          [[NSUserDefaults standardUserDefaults] setBool:YES forKey:@"centerAutoDownloadUpdates"];
          [[NSUserDefaults standardUserDefaults] synchronize];
        }
        if (r == NSAlertFirstButtonReturn && assetURL.length) [self downloadUpdateAsset:assetURL name:assetName];
      } else {
        a.messageText = @"已是最新版本";
        a.informativeText = [NSString stringWithFormat:@"当前版本：%@\n最新版本：%@", current, latest];
        [a addButtonWithTitle:@"好"];
        [a runModal];
      }
    });
  }];
  [task resume];
}

